#!/usr/bin/env python
# -*- coding: utf-8 -*-
r"""
UI1 - the whole credit-and-committee front end, in one patch.

WHY ONE INSTEAD OF SIX. Replaying the frontend patchers against the pilot's
tree in order produced seven aborts, most of them "looks applied" on a file
nothing had touched yet. The cause: each carried a WHOLE FILE captured after
the previous one had been applied, so an earlier patch already contained a
later patch's work, and the later one then found its own marker and stopped.

They were never independent. Pretending otherwise cost a rebuild every time.
This is the final state of every frontend file the credit work touches,
verified as a whole.

WHAT IS IN IT

  THE BRANCH COMMITTEE
    a queue in Manager Queues and the Daily Log, showing only cases at or past
    the committee stage; Review opens the case; the row says what YOU decided
    and the tab counts what still awaits you.

  THE DEPARTMENT ANALYST
    Credit Analysis narrowed to My cases and the Pool; the pool offers Pick
    rather than a request; tabs run Case Journey, Department Review, Department
    Credit Committee, then the rest; the verdict panel sits with the papers it
    judges; recommending asks once whether a document is still to be attached.

  THE DEPARTMENT COMMITTEE
    its own tab that says why it is empty rather than rendering blank, and its
    own sidebar section for the head-office members who vote.

  THE PIPELINE
    the funnel and the headline cards follow the business-line selection; the
    selector moved into the funnel's empty side; Total Assured removed; large
    figures stop overflowing their cards; A2Z replaces the hardcoded EKE
    labels.

WHAT IT WILL NOT DO. It refuses if any file already carries this work, and it
checks that nothing present in the pilot's copies would be dropped - including
the Deals Warehouse menu entry, which a whole-file sidebar patch once carried
to the pilot by accident and must never carry again.

Verified: tsc --noEmit clean, vite build clean, against the full backend stack.

Usage (from project root, .venv active):
    python scripts\\patch_ui1_credit_frontend.py            # dry run
    python scripts\\patch_ui1_credit_frontend.py --apply
"""
import json
import os
import shutil
import sys

BACKUP_SUFFIX = ".pre_ui1"


def _p(rel):
    """A stored forward-slash key as a path this OS can open."""
    return os.path.join(*rel.split("/"))


FILES = json.loads(r'''{
 "frontend/web/src/pages/LmsApplicationDetail.tsx": "// v10.520 Phase 4 Batch \u03b25 \u2014 LMS application detail page.\n//\n// Single-application view at /lms/:appId. Shows full application info\n// plus per-action inline panels gated by the \u03b18 permissions object:\n//   - Assign Analyst panel       (when can_assign)\n//   - Edit Application panel     (when can_update)\n//   - Record Decision panel      (when can_record_decision)\n//\n// Pattern mirrors PipelineDealDetail.tsx (\u03b22): inline panels rather than\n// modal dialogs, page-local fetch (not Provider), refetch after each\n// successful mutation so the permissions object reflects new state.\n//\n// Routing: on success of any mutation, stays on the page and refetches.\n// The panel that was used closes itself because its permission flag\n// flipped (e.g. after assign, can_assign becomes false because status\n// is now 'assigned').\n\nimport { displayName } from \"../lib/names\";\nimport { FacilitiesTable, facilitiesToPrintHtml } from '@/components/FacilitiesTable';\nimport { useState, useEffect } from 'react';\nimport type { ElementType } from 'react';\nimport { AffordabilityAppraisal } from '@/components/AffordabilityAppraisal';\nimport { getApplicationWorkbench, refreshWorkbench, addWorkbenchNote, pickLmsApplication, submitLmsToDcc, listLmsDocuments, downloadLmsDocument, uploadLmsDocument, requestLmsDocument, getDccRoster, recordDccVote, resolveDcc, handToCreditAnalyst, uploadCallbackMemo, resubmitAfterRework, type WorkbenchView, type LmsDocumentsResponse, type DccRosterResponse } from '@/lib/api';\nimport { DocumentViewerModal } from '@/components/DocumentViewerModal';\nimport { useNavigate, useParams } from 'react-router-dom';\nimport { useBranding } from '@/hooks/useBranding';\nimport { useLmsApplication } from '@/hooks/useLmsApplication';\nimport { useLmsMutations } from '@/hooks/useLmsMutations';\nimport { useToast } from '@/components/Toast';\nimport { useRole } from '@/hooks/useRole';\nimport { WorkbenchShell } from '@/components/WorkbenchShell';\nimport {\n  getLmsCr, saveLmsCr, getCommitteeCharter, getCommitteeTiers, fetchCommitteeRouting, getLmsCommitteeRecords, fetchMyAnalysts, setCommitteeReadiness, fetchReworkReasons, appealDecline, decideAppeal, recordCommitteePreRead, fetchCommitteePreReads, type CommitteePreReadsResponse, type LmsCommitteeRecordsResponse, type AssignableAnalyst,\n  type CrView, type CrField, type CommitteeMember, type CommitteeTier,\n} from '@/lib/api';  // attachment imports trimmed with AttachmentsBccCard\nimport { Card, EmbeddedShell, EmbeddedHeader, EmbeddedBody } from '@/components/Card';\nimport { printDocument, escapeHtml } from '@/lib/print';\nimport { Badge } from '@/components/Badge';\nimport { Button } from '@/components/Button';\nimport { Input } from '@/components/Input';\nimport { Skeleton } from '@/components/Skeleton';\nimport { Timeline, eventLabel } from '@/components/Timeline';\nimport {\n  DECISION_VERDICTS,\n  COMMON_AUTHORITIES,\n  type DecisionVerdict,\n  type LoanApplication,\n} from '@/types/lms';\n\n\n// \u2500\u2500 Format helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction formatAmount(v: number | undefined, symbol: string): string {\n  const n = Number(v);\n  if (!Number.isFinite(n) || n === 0) return '\u2014';\n  return `${symbol} ${n.toLocaleString()}`;\n}\n\nfunction formatDate(s: string | undefined | null): string {\n  if (!s) return '\u2014';\n  return s.slice(0, 10);\n}\n\n\n// \u2500\u2500 Page component \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport function LmsApplicationDetail() {\n  const { appId } = useParams<{ appId: string }>();\n  const navigate = useNavigate();\n  const { branding } = useBranding();\n  const { toast } = useToast();\n  const { user } = useRole();\n\n  const { application, permissions, loading, error, refetch } =\n    useLmsApplication(appId);\n  const mutations = useLmsMutations();\n\n\n  // Panel toggles\n  const [assignOpen,   setAssignOpen]   = useState(false);\n  const [updateOpen,   setUpdateOpen]   = useState(false);\n  // The rework button lives on the Department Review tab, which renders inside\n  // THIS component - so its state belongs here, above every early return.\n  const [reworkBusy, setReworkBusy] = useState(false);\n  const [decisionOpen, setDecisionOpen] = useState(false);\n\n  const currencySymbol = branding?.currency_symbol ?? 'KES';\n\n\n  // \u2500\u2500 Loading state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  if (loading) {\n    return (\n      <div className=\"min-h-screen bg-gray-50\">\n        <header className=\"text-white shadow\" style={{ background: 'var(--brand-secondary)' }}>\n          <div className=\"max-w-6xl mx-auto px-6 py-5\">\n            <Skeleton className=\"h-7 w-72 bg-white/20\" />\n          </div>\n        </header>\n        <main className=\"max-w-6xl mx-auto px-6 py-6 space-y-4\">\n          <Skeleton className=\"h-32 w-full\" />\n          <Skeleton className=\"h-48 w-full\" />\n        </main>\n      </div>\n    );\n  }\n\n  // \u2500\u2500 Error / not-found \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  if (error || !application || !permissions) {\n    return (\n      <div className=\"min-h-screen bg-gray-50\">\n        <header className=\"text-white shadow\" style={{ background: 'var(--brand-secondary)' }}>\n          <div className=\"max-w-5xl mx-auto px-6 py-5\">\n            <h1 className=\"text-xl font-semibold\">Application not found</h1>\n          </div>\n        </header>\n        <main className=\"max-w-5xl mx-auto px-6 py-6\">\n          <Card >\n            <Card.Body>\n              <div className=\"text-sm text-red-800 mb-3\">\n                <div className=\"font-semibold\">Could not load application</div>\n                <div className=\"text-xs\">{error || `No application with id ${appId} found.`}</div>\n              </div>\n              <Button variant=\"ghost\" size=\"sm\" onClick={() => navigate('/lms')}>\n                \u2190 Back to applications\n              </Button>\n            </Card.Body>\n          </Card>\n        </main>\n      </div>\n    );\n  }\n\n\n  // IA Phase 3: the VIEW gate (which panel layout to show) keys purely on\n  // \"is the viewer the assigned analyst\" \u2014 independent of assignment_purpose,\n  // so legacy assignments (no purpose recorded) still get the analyst layout.\n  // Editing on the credit page is credit-only (permissions.can_update), which\n  // excludes the RM/originator by design.\n  const _viewerIsAnalyst = Boolean(application.analyst?.code) && String(application.analyst?.code ?? '') === String(user?.staff_code ?? '');\n\n  // IA Phase 3: the Assessment card is rendered in one of two positions \u2014\n  // directly under the customer strip for the assigned analyst, or in its\n  // regular place in the origination flow for everyone else. Defined once\n  // here and placed conditionally in the JSX below to avoid duplication.\n  const printJourney = () => {\n    const evs = [...(application.journey ?? application.history ?? [])];\n    const rows = evs.map((e) => {\n      const when = e.at ? new Date(e.at).toLocaleString() : '';\n      const who = e.by_name || e.by || '';\n      const role = e.by_role ? ` <span class=\"muted\">(${escapeHtml(e.by_role)})</span>` : '';\n      return `<tr><td>${escapeHtml(when)}</td><td>${escapeHtml(eventLabel(e.event))}</td><td>${escapeHtml(who)}${role}</td><td>${escapeHtml(e.note || '')}</td></tr>`;\n    }).join('');\n    const head = `<div class=\"head\"><h1>Case Journey \u2014 ${escapeHtml(application.id)}</h1><span class=\"muted\">${escapeHtml(application.client_name || '')} \u00b7 printed ${escapeHtml(new Date().toLocaleString())}</span></div>`;\n    const table = `<table><thead><tr><th style=\"width:20%\">When</th><th style=\"width:22%\">Event</th><th style=\"width:22%\">By</th><th>Note</th></tr></thead><tbody>${rows || '<tr><td colspan=\"4\" class=\"muted\">No events recorded.</td></tr>'}</tbody></table>`;\n    printDocument(`Case Journey ${application.id}`, head + table);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-gray-50\">\n      <main className=\"max-w-7xl 2xl:max-w-[1680px] mx-auto px-6 py-6\">\n        <WorkbenchShell\n          title={application.client_name}\n          stage={application.status}\n          badges={[\n            ...(application.sla?.state === 'breached' ? [{ label: 'SLA breached' }] : []),\n            ...(application.sla?.state === 'due_soon' ? [{ label: 'SLA due soon' }] : []),\n          ]}\n          idLabel={application.id}\n          onBack={() => navigate('/lms')}\n          onRefresh={() => void refetch()}\n          details={(\n            <div className=\"flex flex-wrap items-center gap-x-6 gap-y-2 text-sm\">\n              <div className=\"flex items-center gap-2\">\n                <span className=\"text-xs uppercase tracking-wide text-gray-400\">CIF</span>\n                <span className=\"font-mono font-medium text-gray-900\">{application.client_cif || '\u2014'}</span>\n              </div>\n              <div className=\"flex items-center gap-2\">\n                <span className=\"text-xs uppercase tracking-wide text-gray-400\">Product</span>\n                <span className=\"text-gray-900\">{application.product || '\u2014'}</span>\n              </div>\n              <div className=\"flex items-center gap-2\">\n                <span className=\"text-xs uppercase tracking-wide text-gray-400\">Amount</span>\n                <span className=\"font-medium text-gray-900\">{formatAmount(application.amount, currencySymbol)}</span>\n              </div>\n              <div className=\"flex items-center gap-2\">\n                <span className=\"text-xs uppercase tracking-wide text-gray-400\">RM</span>\n                <span className=\"text-gray-900\">{application.rm_name || application.rm_code || '\u2014'}</span>\n              </div>\n              {application.analyst?.name && (\n                <div className=\"flex items-center gap-2\">\n                  <span className=\"text-xs uppercase tracking-wide text-gray-400\">Analyst</span>\n                  <span className=\"text-gray-900\">{displayName(application.analyst.name)}</span>\n                </div>\n              )}\n            </div>\n          )}\n        defaultTabId=\"journey\"\n        tabs={[\n          { id: 'journey', label: 'Case Journey', color: '#0082BB', content: (\n            <>\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 Case Journey (prominent, always shown) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {(\n          <Card stripe=\"primary\">\n            <Card.Header>\n              <div className=\"flex items-center justify-between\">\n                <h3 className=\"text-sm font-semibold text-gray-900\">Case Journey</h3>\n                <div className=\"flex items-center gap-3\">\n                  <span className=\"text-xs text-gray-400\">{(application.journey ?? application.history)?.length ?? 0} events \u00b7 who did what, when</span>\n                  <button onClick={printJourney} className=\"text-xs font-medium text-brand-primary hover:underline\">Print</button>\n                </div>\n              </div>\n            </Card.Header>\n            <Card.Body>\n              {/* Executive summary \u2014 compact reference facts folded in from the\n                  former standalone Reference card, to reduce box count. Key\n                  facts (client/CIF/product/amount/RM/analyst) live in the strip. */}\n              <div className=\"mb-4 flex flex-wrap gap-x-6 gap-y-1.5 border-b border-gray-100 pb-3 text-xs\">\n                {([\n                  ['Currency', application.currency || 'KES', false],\n                  ['Applied', formatDate(application.application_date), false],\n                  ['Updated', formatDate(application.last_updated), false],\n                  ['Pipeline deal', application.pipeline_deal_id || '\u2014', true],\n                  ['RM code', application.rm_code || '\u2014', true],\n                  ['RM unit', application.rm_unit || '\u2014', false],\n                ] as const).map(([label, value, mono]) => (\n                  <span key={label} className=\"flex items-center gap-1.5\">\n                    <span className=\"uppercase tracking-wide text-gray-400\">{label}</span>\n                    <span className={mono ? 'font-mono text-gray-800' : 'text-gray-800'}>{value}</span>\n                  </span>\n                ))}\n              </div>\n              <Timeline events={[...(application.journey ?? application.history ?? [])]} emptyHint=\"No activity recorded on this application yet. Actions taken here (assignment, decisions) will appear in this journey.\" />\n            </Card.Body>\n          </Card>\n        )}\n\n\n            </>\n          ) },\n          { id: 'documents', label: 'Department Review', color: '#0097A7', content: (\n            <>\n              {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 The rework is done \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n            RULING (2026-08-14): \"it is extremely important to have the rework\n            submit, and it should send it right back. The rework submit should\n            also be on the department analyst side.\"\n\n            RB1 sends a case back to the branch with what needs fixing, and\n            nothing sent it on again - so a returned case could only move by\n            API. That is the half of a loop that makes the other half useless.\n\n            SHOWN TO WHOEVER OPENS A RETURNED CASE. The owner at the branch\n            does the work; the analyst may also send it back once they can see\n            it is done. Both need the same button, because a case waiting on\n            \"who is allowed to press this\" is a case not moving.\n\n            THE SERVER DECIDES WHERE IT GOES - back to the analyst who returned\n            it, or to the pool if that person cannot be identified. */}\n        {String(application.status || '') === 'returned' && (\n          <Card stripe=\"accent\">\n            <Card.Header>\n              <h3 className=\"text-sm font-semibold text-gray-900\">Returned for rework</h3>\n            </Card.Header>\n            <Card.Body>\n              <p className=\"mb-2 text-sm text-gray-800\">\n                {String((application as unknown as Record<string, unknown>).rework_reasons ?? '')\n                  || 'This case was returned for correction.'}\n              </p>\n              {(() => {\n                const back = String((application as unknown as\n                  { returned_by_name?: string }).returned_by_name ?? '');\n                return back ? (\n                  <p className=\"mb-2 text-xs text-gray-500\">\n                    Returned by {back} \u2014 it goes back to them when you send it.\n                  </p>\n                ) : null;\n              })()}\n              <div className=\"flex justify-end\">\n                <Button\n                  size=\"sm\"\n                  disabled={reworkBusy}\n                  onClick={() => {\n                    void (async () => {\n                      setReworkBusy(true);\n                      try {\n                        const r = await resubmitAfterRework(appId ?? '', {});\n                        const to = (r as unknown as { back_to?: string }).back_to;\n                        toast({ tone: 'success',\n                          message: `Sent back to ${to || 'credit'}.` });\n                        await refetch();\n                      } catch (e) {\n                        toast({ tone: 'danger',\n                          message: e instanceof Error ? e.message : 'Could not send it back' });\n                      } finally { setReworkBusy(false); }\n                    })();\n                  }}\n                >\n                  {reworkBusy ? 'Sending\u2026' : 'Rework done \u2014 send it back'}\n                </Button>\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n        {/* PICKING BELONGS WHERE THE WORK IS (ruling 2026-08-14):\n                  \"this should not have come on the Actions but on the\n                  analysis.\" An analyst opening a case to work it should not\n                  have to find another tab to claim it first - and Actions said\n                  only \"no actions available for your role\", which reads as a\n                  dead end rather than a case waiting to be picked up. */}\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 ACTION: Self-pick (if can_self_pick) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {permissions.can_self_pick && (\n          <div className=\"mt-4 rounded-md border border-blue-200 bg-blue-50 px-4 py-3\">\n            <div className=\"flex items-center justify-between gap-3\">\n              <div className=\"text-sm text-blue-900\">\n                This case is unallocated and in your segment. Pick it to start working it.\n              </div>\n              <Button onClick={async () => {\n                try {\n                  await pickLmsApplication(application.id);\n                  await refetch();\n                  toast({ tone: 'success', message: 'Case picked \u2014 assigned to you.' });\n                } catch (e) {\n                  toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Pick failed.' });\n                }\n              }}>Pick this case</Button>\n            </div>\n          </div>\n        )}\n\n        {/* THE DOCUMENTATION HEADER CARD IS GONE (ruling 2026-08-14): \"we can\n                  remove entirely the top part written Documentation and the\n                  contents.\"\n\n                  A completeness percentage that reads 0%, \"Nothing\n                  outstanding\", and three underwriting flags all reading \"no\"\n                  told the analyst nothing they could act on - and pushed the\n                  papers and the decision below the fold. What is left is the\n                  documents themselves and the verdict. */}\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 The analyst's verdict \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n            RULING (2026-08-14): \"it is here that we need to see the\n            recommendation from the consumer analyst ... if it returns for\n            reworks with specifics, or recommend for department credit review\n            which we defined as should be able to auto advance including\n            stage.\"\n\n            CorrectnessPanel already carries both - a reason list for a rework\n            and a \"ready for committee\" verdict. It was on another tab, so the\n            analyst read the papers on one screen and recorded the verdict on\n            another. It belongs with the evidence it is a verdict about. */}\n        {/* THE ASSIGNED ANALYST RECORDS IT, not anybody who can edit the\n            case. This is the gate the panel already had on the Actions tab and\n            it is the right one - a verdict carries a name, so the person\n            giving it must be the person the case is with. */}\n        {String(application.analyst?.code ?? '') === String(user?.staff_code ?? '')\n          && !!application.analyst?.code && (\n          <CorrectnessPanel appId={application.id} onDone={refetch} toast={toast} />\n        )}\n\n        <LmsTravelledDocuments appId={application.id} canDownload={!!permissions.can_update}\n          // Whoever is WORKING the case may attach: the analyst who can send it\n          // to the DCC, anyone who can update it, and the credit analyst it was\n          // handed to. Not a committee member merely reading it.\n          // WIDER THAN THE FIRST ATTEMPT. can_submit_to_dcc is only true while\n          // a case sits at 'assigned' - so the moment it moved to credit_admin,\n          // Catherine lost the ability to attach to a case she is still working.\n          // can_view is the honest test here: the credit surface is already\n          // scoped, and somebody who can open the case can add a paper to it.\n          canAttach={!!(permissions.can_view ?? true)}\n          onAttached={refetch} />\n\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 Credit Report moved into the Assessment tabs below \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        <BranchCommitteeDecisionsCard appId={application.id} />\n        {application.status === 'referred_to_committee' && (\n          <CommitteePreReadPanel appId={application.id} toast={toast} />\n        )}\n\n\n            </>\n          ) },\n          // \u2500\u2500 DEPARTMENT CREDIT COMMITTEE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n          // RULING (2026-08-14): \"we embed a Department Credit Committee where\n          // we will have a similar page like that of the branch credit\n          // committee ... the same flow as the branch manager clicking on\n          // review and getting to that page to vote should be the same for the\n          // department committee.\"\n          //\n          // THE PANELS ALREADY EXISTED - DccVotePanel and SubmitToDccPanel -\n          // buried inside the journey and actions tabs, several screens apart.\n          // A member arriving to vote had to know where to look. They are the\n          // same two panels; what was missing was somewhere obvious to put\n          // them.\n          //\n          // Sits directly after Department Analysis, because that is the order\n          // the work happens: read the case, analyse it, take it to committee.\n          { id: 'dcc', label: 'Department Credit Committee', color: '#005B82', content: (\n            <div className=\"space-y-4\">\n              <DccVotePanel appId={application.id} toast={toast} onDone={refetch} />\n              {permissions.can_submit_to_dcc && (\n                <SubmitToDccPanel appId={application.id} onDone={refetch} toast={toast} />\n              )}\n              {/* The branch committee's decision stays on the journey tab,\n                  where it is context for the whole case rather than only for\n                  voting - so it is not repeated here. */}\n            </div>\n          ) },\n          { id: 'cr', label: 'Transaction Memo', color: '#7E57C2', content: (\n            <CreditReportCard appId={application.id} canEdit={!!permissions.can_update && !_viewerIsAnalyst} toast={toast} embedded />\n          ) },\n          { id: 'affordability', label: 'Affordability', color: '#00A65A', content: (\n            <AffordabilityAppraisal defaultCif={application.client_cif} appId={application.id} embedded canEdit={!!permissions.can_update} />\n          ) },\n          ...(permissions.can_update ? [{ id: 'engines', label: 'Engines & Conflicts', color: '#C62828', content: (\n            <CreditWorkbenchPanel appId={application.id} toast={toast} embedded canEdit={!!permissions.can_update} />\n          ) }] : []),\n          { id: 'actions', label: 'Actions', color: '#EF6C00', content: (\n            <div className=\"space-y-4\">\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 Decision card (only if recorded) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {application.decision?.verdict && (\n          <Card stripe=\"accent\">\n            <Card.Header>\n              <h2 className=\"text-base font-semibold text-gray-900\">\n                Decision: {application.decision.verdict}\n              </h2>\n            </Card.Header>\n            <Card.Body>\n              <div className=\"grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-3 text-sm\">\n                <Field label=\"Authority\" value={application.decision.authority} />\n                <Field label=\"Date\" value={formatDate(application.decision.date)} />\n                {application.decision.reason && (\n                  <Field label=\"Reason\" value={application.decision.reason} fullWidth />\n                )}\n                {application.decision.comments && (\n                  <Field label=\"Comments\" value={application.decision.comments} fullWidth />\n                )}\n                {application.decision.conditions && application.decision.conditions.length > 0 && (\n                  <div className=\"col-span-2\">\n                    <div className=\"text-xs text-gray-500 uppercase tracking-wide mb-1\">\n                      Conditions\n                    </div>\n                    <ul className=\"text-sm text-gray-700 list-disc pl-5 space-y-1\">\n                      {application.decision.conditions.map((c, i) => (\n                        <li key={i}>{c}</li>\n                      ))}\n                    </ul>\n                  </div>\n                )}\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 ACTION: Hand to Credit Analyst (if can_hand_to_credit_analyst) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {permissions.can_hand_to_credit_analyst && (\n          <HandToCreditAnalystPanel appId={application.id} onDone={refetch} toast={toast} />\n        )}\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 ACTION: Assign Analyst (if can_assign) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {permissions.can_assign && (\n          <ActionPanelAssign\n            appId={application.id}\n            open={assignOpen}\n            setOpen={setAssignOpen}\n            mutations={mutations}\n            onSuccess={async () => {\n              await refetch();\n              setAssignOpen(false);\n              toast({ tone: 'success', message: 'Analyst assigned.' });\n            }}\n            toast={toast}\n          />\n        )}\n\n        {/* C2: assignment purpose banner + correctness action set */}\n        {application.assignment_purpose && (\n          <div className={`mt-4 rounded-md px-4 py-2 text-sm ${\n            application.assignment_purpose === 'correctness'\n              ? 'bg-amber-50 text-amber-800' : 'bg-blue-50 text-blue-800'}`}>\n            {application.assignment_purpose === 'correctness'\n              ? 'Read the papers, then either recommend the case to the department committee or return it to the branch with what needs fixing.'\n              : 'Assigned for decisioning \u2014 analyse the case and record the credit decision.'}\n          </div>\n        )}\n        {application.committee_readiness && (\n          <div className={`mt-2 rounded-md px-4 py-2 text-xs ${\n            application.committee_readiness.state === 'ready_for_committee'\n              ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>\n            {application.committee_readiness.state === 'ready_for_committee'\n              ? `Recommended to committee by ${application.committee_readiness.by_name}`\n              : `Returned for rework \u2014 by ${application.committee_readiness.by_name}`}\n            {application.committee_readiness.opinion\n              && <div className=\"mt-1 italic\">Opinion: {application.committee_readiness.opinion}</div>}\n          </div>\n        )}\n        {/* CorrectnessPanel moved to Department Review, where the papers\n            it judges are. Removed here so it does not render twice. */}\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 ACTION: Edit Application (if can_update) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {permissions.can_update && (\n          <ActionPanelUpdate\n            application={application}\n            open={updateOpen}\n            setOpen={setUpdateOpen}\n            mutations={mutations}\n            onSuccess={async () => {\n              await refetch();\n              setUpdateOpen(false);\n              toast({ tone: 'success', message: 'Application updated.' });\n            }}\n            toast={toast}\n          />\n        )}\n\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 ACTION: Record Decision (if can_record_decision) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {permissions.can_record_decision && (\n          <ActionPanelDecision\n            appId={application.id}\n            open={decisionOpen}\n            setOpen={setDecisionOpen}\n            mutations={mutations}\n            onSuccess={async (verdict) => {\n              await refetch();\n              setDecisionOpen(false);\n              toast({\n                tone: verdict === 'approved' ? 'success' : verdict === 'declined' ? 'danger' : 'warning',\n                message: `Decision recorded: ${verdict}`,\n              });\n            }}\n            toast={toast}\n          />\n        )}\n\n        <AppealPanel app={application} canReview={!!permissions.can_record_decision} onDone={refetch} toast={toast} />\n\n\n        {/* \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 Credit workflow actions (v10.587) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {permissions.can_request_info && (\n          <WfRequestInfo appId={application.id} mutations={mutations} toast={toast} onDone={refetch} />\n        )}\n        {permissions.can_escalate && (\n          <WfSimple appId={application.id} mutations={mutations} toast={toast} onDone={refetch}\n            stripe=\"warning\" title=\"Escalate / seek guidance\"\n            desc=\"If you cannot decide this case alone, escalate it to your line manager for input. Give a brief reason.\"\n            cta=\"Escalate to line manager\"\n            run={(id, note) => mutations.escalate(id, { reason: note })}\n            okMsg=\"Escalated to your line manager.\" requireNote />\n        )}\n        {application.escalation?.escalated && !application.escalation?.resolved && (permissions.can_record_decision) && (\n          <WfSimple appId={application.id} mutations={mutations} toast={toast} onDone={refetch}\n            stripe=\"primary\" title=\"Add your view (line manager)\"\n            desc={`Escalated by ${application.escalation?.by || 'the analyst'}: ${application.escalation?.reason || ''}`}\n            cta=\"Record manager view\"\n            run={(id, note) => mutations.managerView(id, { view: note })}\n            okMsg=\"Your view was recorded.\" requireNote />\n        )}\n        {permissions.can_provide_info && (\n          <WfSimple appId={application.id} mutations={mutations} toast={toast} onDone={refetch}\n            stripe=\"accent\" title=\"Provide requested information\"\n            desc={application.info_request?.note || 'The analyst requested additional documentation.'}\n            cta=\"Mark information provided\"\n            run={(id, note) => mutations.provideInfo(id, { note })} okMsg=\"Information provided.\" />\n        )}\n        {permissions.can_sign_offer && (\n          <WfSignOffer appId={application.id} mutations={mutations} toast={toast} onDone={refetch} />\n        )}\n        {permissions.can_validate_offer && (\n          <WfValidateOffer appId={application.id} mutations={mutations} toast={toast} onDone={refetch} />\n        )}\n        {permissions.can_confirm_to_credit_admin && (\n          <WfSimple appId={application.id} mutations={mutations} toast={toast} onDone={refetch}\n            stripe=\"primary\" title=\"Confirm to Credit Admin\"\n            desc=\"Confirm the signed, validated offer to Credit Admin to open the disbursement case.\"\n            cta=\"Confirm to Credit Admin\"\n            run={(id, note) => mutations.confirmToCreditAdmin(id, { note })} okMsg=\"Confirmed to Credit Admin.\" />\n        )}\n        {permissions.can_refer_committee && (\n          <WfReferCommittee appId={application.id} mutations={mutations} toast={toast} onDone={refetch} />\n        )}\n        {(permissions.can_vote_committee || permissions.can_resolve_committee) && (\n          <WfCommittee application={application} mutations={mutations} toast={toast} onDone={refetch}\n            canVote={!!permissions.can_vote_committee} canResolve={!!permissions.can_resolve_committee} />\n        )}\n\n        {/* If no actions available, show why */}\n        {!permissions.can_assign && !permissions.can_update && !permissions.can_record_decision &&\n         !permissions.can_request_info && !permissions.can_provide_info && !permissions.can_sign_offer &&\n         !permissions.can_validate_offer && !permissions.can_confirm_to_credit_admin &&\n         !permissions.can_refer_committee && !permissions.can_vote_committee && !permissions.can_resolve_committee && (\n          <Card>\n            <Card.Body>\n              <div className=\"text-xs text-gray-500 italic\">\n                No actions available for this application from your role at its current status (\n                <span className=\"font-mono\">{application.status}</span>).\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n            </div>\n          ) },\n        ]}\n      />\n      </main>\n    </div>\n  );\n}\n\n\n// \u2500\u2500 Field display helper \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface FieldProps {\n  label:      string;\n  value:     string | number | null | undefined;\n  mono?:     boolean;\n  fullWidth?: boolean;\n}\n\nfunction Field({ label, value, mono, fullWidth }: FieldProps) {\n  const display = value === null || value === undefined || value === '' ? '\u2014' : String(value);\n  return (\n    <div className={fullWidth ? 'col-span-2' : ''}>\n      <div className=\"text-xs text-gray-500 uppercase tracking-wide\">{label}</div>\n      <div className={`text-sm text-gray-900 mt-0.5 ${mono ? 'font-mono' : ''}`}>{display}</div>\n    </div>\n  );\n}\n\n\n// \u2500\u2500 ACTION PANEL: Assign Analyst \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface ActionPanelProps {\n  appId:       string;\n  open:        boolean;\n  setOpen:     (v: boolean) => void;\n  mutations:   ReturnType<typeof useLmsMutations>;\n  onSuccess:   (...args: unknown[]) => void | Promise<void>;\n  toast:       ReturnType<typeof useToast>['toast'];\n}\n\nfunction ActionPanelAssign({ appId, open, setOpen, mutations, onSuccess, toast }: ActionPanelProps) {\n  const [analystCode, setAnalystCode] = useState('');\n  const [analystName, setAnalystName] = useState('');\n  const [error, setError] = useState<string | null>(null);\n  const [analysts, setAnalysts] = useState<AssignableAnalyst[]>([]);\n  useEffect(() => {\n    fetchMyAnalysts().then((r) => setAnalysts(r.analysts)).catch(() => setAnalysts([]));\n  }, []);\n\n  if (!open) {\n    return (\n      <Card stripe=\"accent\">\n        <Card.Body>\n          <div className=\"flex items-center justify-between\">\n            <div>\n              <h3 className=\"text-sm font-semibold text-gray-900\">Assign credit analyst</h3>\n              <p className=\"text-xs text-gray-500 mt-0.5\">\n                Assign a credit analyst to review this submitted application.\n              </p>\n            </div>\n            <Button variant=\"primary\" size=\"sm\" onClick={() => setOpen(true)}>\n              Assign analyst\n            </Button>\n          </div>\n        </Card.Body>\n      </Card>\n    );\n  }\n\n  const onSubmit = async () => {\n    setError(null);\n    if (!analystCode.trim()) { setError('Analyst code is required.'); return; }\n    if (!analystName.trim()) { setError('Analyst name is required.'); return; }\n\n    const result = await mutations.assign(appId, {\n      analyst_code: analystCode.trim(),\n      analyst_name: analystName.trim(),\n    });\n    if (result.ok) {\n      await onSuccess();\n    } else {\n      setError(result.error);\n      toast({ tone: 'danger', message: result.error });\n    }\n  };\n\n  return (\n    <Card stripe=\"accent\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">Assign credit analyst</h3>\n      </Card.Header>\n      <Card.Body>\n        {analysts.length > 0 ? (\n          <div>\n            <label className=\"block text-xs font-medium text-gray-600 mb-1\">Credit analyst *</label>\n            <select\n              className=\"w-full px-3 py-1.5 rounded-md border border-gray-300 text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n              value={analystCode}\n              disabled={mutations.loading}\n              onChange={(e) => {\n                const a = analysts.find((x) => x.staff_code === e.target.value);\n                setAnalystCode(a?.staff_code ?? '');\n                setAnalystName(a?.name ?? '');\n              }}\n            >\n              <option value=\"\">\u2014 select an analyst \u2014</option>\n              {analysts.map((a) => (\n                <option key={a.staff_code} value={a.staff_code}>\n                  {a.name} ({a.staff_code}){a.unit ? ` \u2014 ${a.unit}` : ''}\n                </option>\n              ))}\n            </select>\n            <p className=\"mt-1 text-xs text-gray-400\">{analysts.length} analyst(s) in your team.</p>\n          </div>\n        ) : (\n          <div className=\"grid grid-cols-1 md:grid-cols-2 gap-3\">\n            <Input\n              label=\"Analyst staff code *\"\n              placeholder=\"e.g. 300080\"\n              value={analystCode}\n              onChange={(e) => setAnalystCode(e.target.value)}\n              disabled={mutations.loading}\n            />\n            <Input\n              label=\"Analyst name *\"\n              placeholder=\"e.g. Zainab Okello\"\n              value={analystName}\n              onChange={(e) => setAnalystName(e.target.value)}\n              disabled={mutations.loading}\n            />\n          </div>\n        )}\n        {error && (\n          <div className=\"mt-3 px-3 py-2 rounded-md bg-red-50 border border-red-200 text-sm text-red-800\">\n            {error}\n          </div>\n        )}\n      </Card.Body>\n      <Card.Footer>\n        <div className=\"flex items-center gap-2\">\n          <Button variant=\"primary\" onClick={onSubmit} disabled={mutations.loading}>\n            {mutations.loading ? 'Assigning\u2026' : 'Confirm assignment'}\n          </Button>\n          <Button variant=\"ghost\" onClick={() => { setOpen(false); setError(null); }} disabled={mutations.loading}>\n            Cancel\n          </Button>\n        </div>\n      </Card.Footer>\n    </Card>\n  );\n}\n\n\n// \u2500\u2500 ACTION PANEL: Update Application \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n//\n// Has its own props interface (not extending ActionPanelProps) because\n// Update uses application.id internally rather than receiving appId as\n// a separate prop \u2014 the form needs the application object anyway to\n// pre-fill fields.\n\ninterface ActionPanelUpdateProps {\n  application:   LoanApplication;\n  open:          boolean;\n  setOpen:       (v: boolean) => void;\n  mutations:     ReturnType<typeof useLmsMutations>;\n  onSuccess:     () => void | Promise<void>;\n  toast:         ReturnType<typeof useToast>['toast'];\n}\n\nfunction ActionPanelUpdate({\n  application, open, setOpen, mutations, onSuccess, toast,\n}: ActionPanelUpdateProps) {\n  const [completenessScore, setCompletenessScore] = useState<string>(\n    application.completeness_score !== undefined ? String(application.completeness_score) : ''\n  );\n  const [appraisalNotes, setAppraisalNotes] = useState<string>(application.appraisal_notes || '');\n  const [complianceFlag, setComplianceFlag] = useState<boolean>(application.compliance_flag || false);\n  const [complianceType, setComplianceType] = useState<string>(application.compliance_type || '');\n  const [error, setError] = useState<string | null>(null);\n\n  if (!open) {\n    return (\n      <Card stripe=\"accent\">\n        <Card.Body>\n          <div className=\"flex items-center justify-between\">\n            <div>\n              <h3 className=\"text-sm font-semibold text-gray-900\">Update application</h3>\n              <p className=\"text-xs text-gray-500 mt-0.5\">\n                Edit completeness score, compliance flags, appraisal notes.\n              </p>\n            </div>\n            <Button variant=\"primary\" size=\"sm\" onClick={() => setOpen(true)}>\n              Update fields\n            </Button>\n          </div>\n        </Card.Body>\n      </Card>\n    );\n  }\n\n  const onSubmit = async () => {\n    setError(null);\n    const body: Record<string, unknown> = {};\n\n    if (completenessScore.trim()) {\n      const n = Number(completenessScore);\n      if (!Number.isFinite(n) || n < 0 || n > 100) {\n        setError('Completeness score must be a number 0\u2013100.');\n        return;\n      }\n      body.completeness_score = n;\n    }\n    if (appraisalNotes !== (application.appraisal_notes || '')) {\n      body.appraisal_notes = appraisalNotes;\n    }\n    if (complianceFlag !== (application.compliance_flag || false)) {\n      body.compliance_flag = complianceFlag;\n    }\n    if (complianceType !== (application.compliance_type || '')) {\n      body.compliance_type = complianceType || undefined;\n    }\n\n    if (Object.keys(body).length === 0) {\n      setError('No changes to save.');\n      return;\n    }\n\n    const result = await mutations.update(application.id, body);\n    if (result.ok) {\n      await onSuccess();\n    } else {\n      setError(result.error);\n      toast({ tone: 'danger', message: result.error });\n    }\n  };\n\n  return (\n    <Card stripe=\"accent\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">Update application fields</h3>\n      </Card.Header>\n      <Card.Body>\n        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-3\">\n          <Input\n            label=\"Completeness score (0-100)\"\n            type=\"number\"\n            value={completenessScore}\n            onChange={(e) => setCompletenessScore(e.target.value)}\n            disabled={mutations.loading}\n            placeholder=\"e.g. 75\"\n          />\n          <div>\n            <label className=\"text-sm font-medium text-gray-700\">Compliance flag</label>\n            <div className=\"mt-1 flex items-center gap-3 h-10\">\n              <label className=\"flex items-center gap-2 text-sm\">\n                <input\n                  type=\"checkbox\"\n                  checked={complianceFlag}\n                  onChange={(e) => setComplianceFlag(e.target.checked)}\n                  disabled={mutations.loading}\n                />\n                Flagged\n              </label>\n              {complianceFlag && (\n                <input\n                  type=\"text\"\n                  value={complianceType}\n                  onChange={(e) => setComplianceType(e.target.value)}\n                  disabled={mutations.loading}\n                  placeholder=\"e.g. AML review\"\n                  className=\"flex-1 h-8 px-2 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary\"\n                />\n              )}\n            </div>\n          </div>\n        </div>\n        <div className=\"mt-3\">\n          <label className=\"text-sm font-medium text-gray-700\">Appraisal notes</label>\n          <textarea\n            value={appraisalNotes}\n            onChange={(e) => setAppraisalNotes(e.target.value)}\n            disabled={mutations.loading}\n            rows={3}\n            className=\"mt-1 w-full px-3 py-2 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20 resize-y\"\n          />\n        </div>\n        {error && (\n          <div className=\"mt-3 px-3 py-2 rounded-md bg-red-50 border border-red-200 text-sm text-red-800\">\n            {error}\n          </div>\n        )}\n      </Card.Body>\n      <Card.Footer>\n        <div className=\"flex items-center gap-2\">\n          <Button variant=\"primary\" onClick={onSubmit} disabled={mutations.loading}>\n            {mutations.loading ? 'Saving\u2026' : 'Save changes'}\n          </Button>\n          <Button variant=\"ghost\" onClick={() => { setOpen(false); setError(null); }} disabled={mutations.loading}>\n            Cancel\n          </Button>\n        </div>\n      </Card.Footer>\n    </Card>\n  );\n}\n\n\n// \u2500\u2500 ACTION PANEL: Record Decision \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction ActionPanelDecision({ appId, open, setOpen, mutations, onSuccess, toast }: ActionPanelProps) {\n  const [verdict, setVerdict] = useState<DecisionVerdict>('approved');\n  const [authority, setAuthority] = useState<string>(COMMON_AUTHORITIES[0]);\n  const [reason, setReason]       = useState<string>('');\n  const [conditions, setConditions] = useState<string>('');\n  const [comments, setComments]   = useState<string>('');\n  const [error, setError]         = useState<string | null>(null);\n\n  if (!open) {\n    return (\n      <Card stripe=\"accent\">\n        <Card.Body>\n          <div className=\"flex items-center justify-between\">\n            <div>\n              <h3 className=\"text-sm font-semibold text-gray-900\">Record decision</h3>\n              <p className=\"text-xs text-gray-500 mt-0.5\">\n                Approve, decline, or return this application.\n              </p>\n            </div>\n            <Button variant=\"primary\" size=\"sm\" onClick={() => setOpen(true)}>\n              Record decision\n            </Button>\n          </div>\n        </Card.Body>\n      </Card>\n    );\n  }\n\n  const onSubmit = async () => {\n    setError(null);\n    if (!authority.trim()) { setError('Authority is required.'); return; }\n\n    const conditionsList = conditions\n      .split('\\n')\n      .map((c) => c.trim())\n      .filter((c) => c.length > 0);\n\n    const result = await mutations.recordDecision(appId, {\n      verdict,\n      authority: authority.trim(),\n      reason: reason.trim() || undefined,\n      conditions: conditionsList.length > 0 ? conditionsList : undefined,\n      comments: comments.trim() || undefined,\n    });\n\n    if (result.ok) {\n      await (onSuccess as (verdict: DecisionVerdict) => Promise<void>)(verdict);\n    } else {\n      setError(result.error);\n      toast({ tone: 'danger', message: result.error });\n    }\n  };\n\n  return (\n    <Card stripe=\"accent\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">Record decision</h3>\n      </Card.Header>\n      <Card.Body>\n        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-3\">\n          <div>\n            <label className=\"text-sm font-medium text-gray-700\">Verdict *</label>\n            <select\n              value={verdict}\n              onChange={(e) => setVerdict(e.target.value as DecisionVerdict)}\n              disabled={mutations.loading}\n              className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n            >\n              {DECISION_VERDICTS.map((v) => (\n                <option key={v} value={v}>{v}</option>\n              ))}\n            </select>\n          </div>\n          <div>\n            <label className=\"text-sm font-medium text-gray-700\">Authority *</label>\n            <input\n              type=\"text\"\n              value={authority}\n              onChange={(e) => setAuthority(e.target.value)}\n              disabled={mutations.loading}\n              list=\"authority-options\"\n              className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n            />\n            <datalist id=\"authority-options\">\n              {COMMON_AUTHORITIES.map((a) => (\n                <option key={a} value={a} />\n              ))}\n            </datalist>\n          </div>\n        </div>\n        <div className=\"mt-3\">\n          <label className=\"text-sm font-medium text-gray-700\">\n            Reason {verdict !== 'approved' && <span className=\"text-gray-500\">(recommended for {verdict})</span>}\n          </label>\n          <input\n            type=\"text\"\n            value={reason}\n            onChange={(e) => setReason(e.target.value)}\n            disabled={mutations.loading}\n            className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n          />\n        </div>\n        {verdict === 'approved' && (\n          <div className=\"mt-3\">\n            <label className=\"text-sm font-medium text-gray-700\">Conditions (one per line)</label>\n            <textarea\n              value={conditions}\n              onChange={(e) => setConditions(e.target.value)}\n              disabled={mutations.loading}\n              rows={3}\n              placeholder=\"Board resolution&#10;Debenture&#10;Insurance certificate\"\n              className=\"mt-1 w-full px-3 py-2 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20 resize-y\"\n            />\n            <p className=\"text-xs text-gray-500 mt-1\">\n              For conditional approvals. Each line becomes one condition on the credit-admin case.\n            </p>\n          </div>\n        )}\n        <div className=\"mt-3\">\n          <label className=\"text-sm font-medium text-gray-700\">Comments</label>\n          <textarea\n            value={comments}\n            onChange={(e) => setComments(e.target.value)}\n            disabled={mutations.loading}\n            rows={2}\n            className=\"mt-1 w-full px-3 py-2 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20 resize-y\"\n          />\n        </div>\n        {error && (\n          <div className=\"mt-3 px-3 py-2 rounded-md bg-red-50 border border-red-200 text-sm text-red-800\">\n            {error}\n          </div>\n        )}\n      </Card.Body>\n      <Card.Footer>\n        <div className=\"flex items-center gap-2\">\n          <Button\n            variant={verdict === 'declined' ? 'danger' : verdict === 'returned' ? 'secondary' : 'primary'}\n            onClick={onSubmit}\n            disabled={mutations.loading}\n          >\n            {mutations.loading ? 'Recording\u2026' : `Confirm ${verdict}`}\n          </Button>\n          <Button variant=\"ghost\" onClick={() => { setOpen(false); setError(null); }} disabled={mutations.loading}>\n            Cancel\n          </Button>\n        </div>\n      </Card.Footer>\n    </Card>\n  );\n}\n\n\n// \u2500\u2500 Credit workflow panels (v10.587) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type { MutationResult } from '@/hooks/useLmsMutations';\nimport type { LoanAppMutationResponse } from '@/types/lms';\n\ntype WfMutations = ReturnType<typeof useLmsMutations>;\ntype WfToast = ReturnType<typeof useToast>['toast'];\ntype WfRun = (id: string, note: string) => Promise<MutationResult<LoanAppMutationResponse>>;\n\ninterface WfSimpleProps {\n  appId: string;\n  mutations: WfMutations;\n  toast: WfToast;\n  onDone: () => Promise<unknown> | unknown;\n  stripe: 'primary' | 'secondary' | 'accent' | 'brand' | 'warning';\n  title: string;\n  desc: string;\n  cta: string;\n  run: WfRun;\n  okMsg: string;\n  requireNote?: boolean;\n}\n\nfunction WfSimple({ appId, toast, onDone, stripe, title, desc, cta, run, okMsg, mutations, requireNote }: WfSimpleProps) {\n  const [note, setNote] = useState('');\n  const [error, setError] = useState<string | null>(null);\n  const onClick = async () => {\n    setError(null);\n    if (requireNote && note.trim().length < 3) {\n      setError('Please enter a reason (at least a few characters).');\n      return;\n    }\n    const res = await run(appId, note.trim());\n    if (res.ok) {\n      await onDone();\n      toast({ tone: 'success', message: okMsg });\n      setNote('');\n    } else {\n      setError(res.error);\n    }\n  };\n  const cardStripe = stripe === 'brand' ? 'primary' : stripe === 'warning' ? 'accent' : stripe;\n  return (\n    <Card className=\"mt-6\" stripe={cardStripe}>\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">{title}</h3></Card.Header>\n      <Card.Body>\n        <p className=\"text-sm text-gray-600 mb-3\">{desc}</p>\n        <Input label=\"Note (optional)\" value={note}\n               onChange={(e) => setNote(e.target.value)} disabled={mutations.loading} />\n        {error && <p className=\"text-xs text-red-600 mt-2\">{error}</p>}\n        <div className=\"mt-3\">\n          <Button variant=\"primary\" onClick={onClick} disabled={mutations.loading}>\n            {mutations.loading ? 'Working\u2026' : cta}\n          </Button>\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction WfRequestInfo({ appId, mutations, toast, onDone }: {\n  appId: string; mutations: WfMutations; toast: WfToast; onDone: () => Promise<unknown> | unknown;\n}) {\n  const [docs, setDocs] = useState('');\n  const [note, setNote] = useState('');\n  const [error, setError] = useState<string | null>(null);\n  const onClick = async () => {\n    setError(null);\n    const documents = docs.split(',').map((d) => d.trim()).filter(Boolean);\n    const res = await mutations.requestInfo(appId, { documents, note: note.trim() });\n    if (res.ok) { await onDone(); toast({ tone: 'success', message: 'Information requested.' }); setDocs(''); setNote(''); }\n    else setError(res.error);\n  };\n  return (\n    <Card className=\"mt-6\" stripe=\"accent\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Request more information</h3></Card.Header>\n      <Card.Body>\n        <p className=\"text-sm text-gray-600 mb-3\">Park the case and ask the deal owner for additional documents (pre-decision).</p>\n        <Input label=\"Documents (comma-separated)\" value={docs}\n               onChange={(e) => setDocs(e.target.value)} disabled={mutations.loading}\n               placeholder=\"Audited accounts, CRB report\" />\n        <div className=\"mt-2\">\n          <Input label=\"Note (optional)\" value={note}\n                 onChange={(e) => setNote(e.target.value)} disabled={mutations.loading} />\n        </div>\n        {error && <p className=\"text-xs text-red-600 mt-2\">{error}</p>}\n        <div className=\"mt-3\">\n          <Button variant=\"primary\" onClick={onClick} disabled={mutations.loading}>\n            {mutations.loading ? 'Working\u2026' : 'Request information'}\n          </Button>\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction WfSignOffer({ appId, mutations, toast, onDone }: {\n  appId: string; mutations: WfMutations; toast: WfToast; onDone: () => Promise<unknown> | unknown;\n}) {\n  const [filename, setFilename] = useState('');\n  const [note, setNote] = useState('');\n  const [error, setError] = useState<string | null>(null);\n  const onClick = async () => {\n    setError(null);\n    const res = await mutations.signOffer(appId, {\n      attachment_filename: filename.trim() || undefined, note: note.trim(),\n    });\n    if (res.ok) { await onDone(); toast({ tone: 'success', message: 'Offer signed.' }); }\n    else setError(res.error);\n  };\n  return (\n    <Card className=\"mt-6\" stripe=\"primary\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Sign letter of offer</h3></Card.Header>\n      <Card.Body>\n        <p className=\"text-sm text-gray-600 mb-3\">Mark the letter of offer signed by the customer and attach the signed copy.</p>\n        <Input label=\"Signed copy filename\" value={filename}\n               onChange={(e) => setFilename(e.target.value)} disabled={mutations.loading}\n               placeholder=\"signed_offer_ECO123.pdf\" />\n        <div className=\"mt-2\">\n          <Input label=\"Note (optional)\" value={note}\n                 onChange={(e) => setNote(e.target.value)} disabled={mutations.loading} />\n        </div>\n        {error && <p className=\"text-xs text-red-600 mt-2\">{error}</p>}\n        <div className=\"mt-3\">\n          <Button variant=\"primary\" onClick={onClick} disabled={mutations.loading}>\n            {mutations.loading ? 'Working\u2026' : 'Mark signed + attach'}\n          </Button>\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction WfValidateOffer({ appId, mutations, toast, onDone }: {\n  appId: string; mutations: WfMutations; toast: WfToast; onDone: () => Promise<unknown> | unknown;\n}) {\n  const [note, setNote] = useState('');\n  const [error, setError] = useState<string | null>(null);\n  const act = async (approve: boolean) => {\n    setError(null);\n    const res = await mutations.validateOffer(appId, { approve, note: note.trim() });\n    if (res.ok) { await onDone(); toast({ tone: approve ? 'success' : 'warning', message: approve ? 'Offer validated.' : 'Sent back for re-handling.' }); }\n    else setError(res.error);\n  };\n  return (\n    <Card className=\"mt-6\" stripe=\"secondary\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Validate signed offer</h3></Card.Header>\n      <Card.Body>\n        <p className=\"text-sm text-gray-600 mb-3\">Line-manager checks &amp; balances on the signed offer before it proceeds.</p>\n        <Input label=\"Note (optional)\" value={note}\n               onChange={(e) => setNote(e.target.value)} disabled={mutations.loading} />\n        {error && <p className=\"text-xs text-red-600 mt-2\">{error}</p>}\n        <div className=\"mt-3 flex gap-2\">\n          <Button variant=\"primary\" onClick={() => act(true)} disabled={mutations.loading}>Validate</Button>\n          <Button variant=\"ghost\" onClick={() => act(false)} disabled={mutations.loading}>Send back</Button>\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction WfReferCommittee({ appId, mutations, toast, onDone }: {\n  appId: string; mutations: WfMutations; toast: WfToast; onDone: () => Promise<unknown> | unknown;\n}) {\n  const [tiers, setTiers] = useState<CommitteeTier[]>([]);\n  const [entryTier, setEntryTier] = useState<number | ''>('');\n  const [error, setError] = useState<string | null>(null);\n  const [suggested, setSuggested] = useState<{ tier: number | null; name: string | null; amount: number; finalName?: string | null; mustClimb?: boolean } | null>(null);\n\n  useEffect(() => {\n    let live = true;\n    getCommitteeTiers().then((r) => { if (live) setTiers(r.tiers || []); }).catch(() => {});\n    fetchCommitteeRouting(appId).then((r) => {\n      if (!live) return;\n      setSuggested({ tier: r.entry_tier ?? r.suggested_tier, name: r.entry_name ?? r.suggested_name, amount: r.amount, finalName: r.final_name, mustClimb: r.must_climb });\n      const preselect = r.entry_tier ?? r.suggested_tier;\n      if (preselect != null) setEntryTier(preselect);\n    }).catch(() => {});\n    return () => { live = false; };\n  }, [appId]);\n\n  const refer = async () => {\n    setError(null);\n    const res = await mutations.referCommittee(appId, entryTier === '' ? undefined : Number(entryTier));\n    if (res.ok) { await onDone(); toast({ tone: 'success', message: 'Referred to committee.' }); }\n    else setError(res.error);\n  };\n\n  return (\n    <Card className=\"mt-6\" stripe=\"primary\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Refer to credit committee</h3></Card.Header>\n      <Card.Body>\n        <p className=\"text-xs text-gray-500 mb-3\">\n          This facility is committee-tier under the bank's policy. Most cases enter at the Branch\n          Credit Committee; CIB / head-office cases may enter a higher tier directly.\n        </p>\n        {suggested?.name && (\n          <div className=\"mb-3 rounded bg-blue-50 px-3 py-2 text-xs text-blue-800\">\n            {suggested.mustClimb ? (\n              <>By limit, KES {suggested.amount.toLocaleString()} enters at <span className=\"font-semibold\">{suggested.name}</span> and climbs to <span className=\"font-semibold\">{suggested.finalName}</span> \u2014 each committee's verdict is captured before the next.</>\n            ) : (\n              <>By limit, KES {suggested.amount.toLocaleString()} is decided by <span className=\"font-semibold\">{suggested.name}</span> (pre-selected). You can override below.</>\n            )}\n          </div>\n        )}\n        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-2 items-end\">\n          <div>\n            <label className=\"text-sm font-medium text-gray-700\">Entry tier</label>\n            <select value={entryTier} onChange={(e) => setEntryTier(e.target.value === '' ? '' : Number(e.target.value))}\n              disabled={mutations.loading}\n              className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-base text-gray-900\">\n              <option value=\"\">Default (Branch Credit Committee)</option>\n              {tiers.filter((t) => t.can_be_entry).map((t) => (\n                <option key={t.tier} value={t.tier}>Tier {t.tier}: {t.name}</option>\n              ))}\n            </select>\n          </div>\n          <div>\n            <Button variant=\"primary\" onClick={refer} disabled={mutations.loading}>Refer to committee</Button>\n          </div>\n        </div>\n        {error && <p className=\"text-xs text-red-600 mt-2\">{error}</p>}\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction WfCommittee({ application, mutations, toast, onDone, canVote, canResolve }: {\n  application: LoanApplication; mutations: WfMutations; toast: WfToast;\n  onDone: () => Promise<unknown> | unknown; canVote: boolean; canResolve: boolean;\n}) {\n  const [memberId, setMemberId] = useState('');\n  const [vote, setVote] = useState('YES');\n  const [rationale, setRationale] = useState('');\n  const [error, setError] = useState<string | null>(null);\n  const [members, setMembers] = useState<CommitteeMember[]>([]);\n  const votes = application.committee?.votes ?? [];\n\n  useEffect(() => {\n    let live = true;\n    getCommitteeCharter()\n      .then((ch) => { if (live) setMembers(ch.members || []); })\n      .catch(() => { /* dropdown falls back to manual entry */ });\n    return () => { live = false; };\n  }, []);\n\n  const castVote = async () => {\n    setError(null);\n    if (!memberId.trim()) { setError('Member id required.'); return; }\n    const res = await mutations.voteCommittee(application.id, { member_id: memberId.trim(), vote, rationale: rationale.trim() });\n    if (res.ok) { await onDone(); toast({ tone: 'success', message: `Vote recorded: ${memberId} ${vote}` }); setRationale(''); }\n    else setError(res.error);\n  };\n  const resolve = async () => {\n    setError(null);\n    const res = await mutations.resolveCommittee(application.id, {});\n    if (res.ok) { await onDone(); toast({ tone: 'info', message: 'Committee resolved.' }); }\n    else setError(res.error);\n  };\n  return (\n    <Card className=\"mt-6\" stripe=\"primary\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Credit committee</h3></Card.Header>\n      <Card.Body>\n        {application.committee?.current_tier_name && (\n          <div className=\"mb-3 flex items-center gap-2\">\n            <Badge tone=\"brand\">Tier {application.committee.current_tier}: {application.committee.current_tier_name}</Badge>\n            {(application.committee.tier_history?.length ?? 0) > 0 && (\n              <span className=\"text-xs text-gray-500\">\n                escalated from {application.committee.tier_history!.map((h) => h.tier_name || `Tier ${h.tier}`).join(' \u2192 ')}\n              </span>\n            )}\n          </div>\n        )}\n        {votes.length > 0 && (\n          <div className=\"mb-3 text-xs text-gray-600\">\n            Votes recorded: {votes.map((v) => `${v.member_id}:${v.vote}`).join(', ')}\n          </div>\n        )}\n        {canVote && (\n          <div className=\"grid grid-cols-1 md:grid-cols-3 gap-2 items-end\">\n            <div>\n              <label className=\"text-sm font-medium text-gray-700\">Committee member</label>\n              {members.length > 0 ? (\n                <select value={memberId} onChange={(e) => setMemberId(e.target.value)} disabled={mutations.loading}\n                  className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-base text-gray-900\">\n                  <option value=\"\">Select member\u2026</option>\n                  {members.map((m) => (\n                    <option key={m.member_id} value={m.member_id}>\n                      {m.name} \u2014 {m.role.replace(/_/g, ' ').toLowerCase()}{m.is_independent ? ' (independent)' : ''}\n                    </option>\n                  ))}\n                </select>\n              ) : (\n                <Input label=\"\" value={memberId}\n                       onChange={(e) => setMemberId(e.target.value)} disabled={mutations.loading}\n                       placeholder=\"m1\" />\n              )}\n            </div>\n            <div>\n              <label className=\"text-sm font-medium text-gray-700\">Vote</label>\n              <select value={vote} onChange={(e) => setVote(e.target.value)} disabled={mutations.loading}\n                className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-base text-gray-900\">\n                {['YES', 'NO', 'ABSTAIN', 'RECUSED'].map((v) => <option key={v} value={v}>{v}</option>)}\n              </select>\n            </div>\n            <Input label=\"Rationale (optional)\" value={rationale}\n                   onChange={(e) => setRationale(e.target.value)} disabled={mutations.loading} />\n          </div>\n        )}\n        {error && <p className=\"text-xs text-red-600 mt-2\">{error}</p>}\n        <div className=\"mt-3 flex gap-2\">\n          {canVote && <Button variant=\"ghost\" onClick={castVote} disabled={mutations.loading}>Record vote</Button>}\n          {canResolve && <Button variant=\"primary\" onClick={resolve} disabled={mutations.loading}>Resolve committee</Button>}\n          {canResolve && (\n            <Button variant=\"secondary\" onClick={async () => {\n              setError(null);\n              const res = await mutations.submitUpward(application.id, '');\n              if (res.ok) { await onDone(); toast({ tone: 'info', message: 'Submitted to the next tier.' }); }\n              else setError(res.error);\n            }} disabled={mutations.loading}>Submit to next tier \u2191</Button>\n          )}\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\n\n\n// (Attachments & BCC card removed from the credit surface \u2014 the RM's documents\n// live on the pipeline workbench; committee outcomes on the deal's committee card.)\n\n// \u2500\u2500\u2500 Credit Report (CR) \u2014 hybrid auto-populated appraisal memo \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Template-driven: renders sections/fields from the server. auto/cbs fields\n// show prefilled (editable but tinted to signal provenance); rm fields are\n// blank for the relationship owner. Save draft or mark complete (required\n// fields enforced server-side).\nfunction DccVotePanel({ appId, toast, onDone }: {\n  appId: string;\n  toast: ReturnType<typeof useToast>['toast'];\n  onDone: () => Promise<void> | void;\n}) {\n  const [roster, setRoster] = useState<DccRosterResponse | null>(null);\n  const [memberId, setMemberId] = useState('');\n  const [vote, setVote] = useState('YES');\n  const [rationale, setRationale] = useState('');\n  const [busy, setBusy] = useState(false);\n  const load = () => { getDccRoster(appId).then(setRoster).catch(() => { /* none */ }); };\n  useEffect(() => { load(); /* eslint-disable-next-line */ }, [appId]);\n  // \u2500\u2500 SAY WHY, RATHER THAN NOTHING \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // This returned null whenever the case was not yet before the committee, so\n  // the Department Credit Committee tab rendered BLANK - which reads as broken\n  // rather than as \"not yet\". A member opening it to vote had no way to tell\n  // the difference.\n  //\n  // Returning null is right where the panel is one card among many on another\n  // tab. It is wrong when the panel IS the tab.\n  if (!roster) {\n    return (\n      <Card>\n        <Card.Body>\n          <p className=\"py-6 text-center text-sm text-gray-400\">Loading the committee\u2026</p>\n        </Card.Body>\n      </Card>\n    );\n  }\n  if (!roster.enabled) {\n    return (\n      <Card>\n        <Card.Header>\n          <h3 className=\"text-sm font-semibold text-gray-900\">Department Credit Committee</h3>\n        </Card.Header>\n        <Card.Body>\n          <p className=\"text-sm text-gray-600\">\n            The department committee is not switched on for this bank. An\n            administrator enables it under Administration \u2192 Credit Committees.\n          </p>\n        </Card.Body>\n      </Card>\n    );\n  }\n  if (!roster.is_dcc_case && !roster.outcome) {\n    return (\n      <Card>\n        <Card.Header>\n          <h3 className=\"text-sm font-semibold text-gray-900\">Department Credit Committee</h3>\n        </Card.Header>\n        <Card.Body>\n          <p className=\"text-sm text-gray-600\">\n            This case has not been submitted to the department committee yet.\n          </p>\n          <p className=\"mt-1 text-xs text-gray-500\">\n            It arrives here once the analyst marks it ready on the Department\n            Review tab \u2014 then the committee's members vote, and the case moves\n            on by itself when they have.\n          </p>\n        </Card.Body>\n      </Card>\n    );\n  }\n  const votesByMember = new Map(roster.votes.map((v) => [v.member_id, v]));\n  const resolve = async () => {\n    setBusy(true);\n    try {\n      await resolveDcc(appId, {});\n      toast({ tone: 'success', message: 'DCC closed \u2014 case returned to the Department Analyst.' });\n      await onDone();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not close the DCC.' });\n    } finally { setBusy(false); }\n  };\n  const cast = async () => {\n    if (!memberId) return;\n    setBusy(true);\n    try {\n      await recordDccVote(appId, { member_id: memberId, vote, rationale: rationale.trim() });\n      toast({ tone: 'success', message: 'DCC vote recorded.' });\n      setRationale(''); load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Vote failed.' });\n    } finally { setBusy(false); }\n  };\n  return (\n    <Card className=\"mt-4\" stripe=\"primary\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">{roster.name}</h3>\n        <span className=\"text-xs text-gray-500\">{roster.votes.length}/{roster.members.length} voted</span>\n      </Card.Header>\n      <Card.Body>\n        {roster.outcome ? (\n          <div className=\"rounded-md border border-gray-200 bg-gray-50 p-3 text-sm\">\n            <div>DCC recommendation:{' '}\n              <span className={roster.outcome.recommendation === 'support' ? 'font-semibold text-green-700'\n                : roster.outcome.recommendation === 'oppose' ? 'font-semibold text-red-600'\n                : 'font-semibold text-gray-600'}>\n                {roster.outcome.recommendation}\n              </span>\n            </div>\n            <div className=\"mt-1 text-xs text-gray-500\">\n              Tally: {roster.outcome.tally.yes} yes \u00b7 {roster.outcome.tally.no} no \u00b7 {roster.outcome.tally.abstain} abstain\n              {roster.outcome.by_name ? ` \u00b7 closed by ${roster.outcome.by_name}` : ''}\n            </div>\n            <p className=\"mt-2 text-xs text-gray-500\">Advisory only \u2014 the Credit Analyst makes the final decision.</p>\n          </div>\n        ) : roster.members.length === 0 ? (\n          <p className=\"text-xs text-gray-400\">No DCC members configured yet (set them in the credit-workflow config).</p>\n        ) : (\n          <>\n            <div className=\"mb-3 space-y-1\">\n              {roster.members.map((m) => {\n                const id = m.id || m.member_id || '';\n                const v = votesByMember.get(id);\n                return (\n                  <div key={id} className=\"flex items-center justify-between text-sm\">\n                    <span className=\"text-gray-800\">\n                      {m.name || id}{m.role ? <span className=\"text-xs text-gray-500\"> \u2014 {m.role}</span> : null}\n                    </span>\n                    <span className={v ? (v.vote === 'YES' ? 'text-green-700' : v.vote === 'NO' ? 'text-red-600' : 'text-gray-500') : 'text-gray-300'}>\n                      {v ? v.vote : 'not voted'}\n                    </span>\n                  </div>\n                );\n              })}\n            </div>\n            <div className=\"grid grid-cols-1 items-end gap-2 border-t pt-3 md:grid-cols-3\">\n              <div>\n                <label className=\"text-xs font-medium text-gray-700\">Member</label>\n                <select value={memberId} onChange={(e) => setMemberId(e.target.value)} disabled={busy}\n                  className=\"mt-1 h-9 w-full rounded-md border border-gray-300 bg-white px-2 text-sm\">\n                  <option value=\"\">Select\u2026</option>\n                  {roster.members.map((m) => {\n                    const id = m.id || m.member_id || '';\n                    return <option key={id} value={id}>{m.name || id}</option>;\n                  })}\n                </select>\n              </div>\n              <div>\n                <label className=\"text-xs font-medium text-gray-700\">Vote</label>\n                <select value={vote} onChange={(e) => setVote(e.target.value)} disabled={busy}\n                  className=\"mt-1 h-9 w-full rounded-md border border-gray-300 bg-white px-2 text-sm\">\n                  <option>YES</option><option>NO</option><option>ABSTAIN</option>\n                </select>\n              </div>\n              <Button onClick={cast} disabled={busy || !memberId}>Record vote</Button>\n            </div>\n            <input value={rationale} onChange={(e) => setRationale(e.target.value)} disabled={busy}\n              placeholder=\"Rationale (optional)\"\n              className=\"mt-2 w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm\" />\n            {roster.votes.length > 0 && (\n              <div className=\"mt-3 flex items-center justify-end gap-2 border-t pt-3\">\n                <span className=\"text-xs text-gray-500\">Advisory \u2014 closing returns the case to the Department Analyst.</span>\n                <Button variant=\"ghost\" onClick={resolve} disabled={busy}>Close &amp; return to analyst</Button>\n              </div>\n            )}\n          </>\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n\n\n// WHAT THE ANALYST ATTACHES (ruling 2026-08-12: \"in the pilot she is\n// particularly supposed to attach the CRB and the Call Back Memo\").\n//\n// Offered as named buttons rather than a free-text box: a document called\n// \"CRB\" on one case and \"CRB Report\" on another cannot be checked off a\n// required list, and the analyst should not have to know the exact string.\n// \"Other\" stays for the paper nobody anticipated.\nconst ANALYST_DOCS = ['CRB Report', 'Call Back Memo', 'Other'];\n\nfunction LmsTravelledDocuments({ appId, canDownload, canAttach, onAttached }: {\n  appId: string; canDownload: boolean; canAttach?: boolean; onAttached?: () => void;\n}) {\n  const [files, setFiles] = useState<LmsDocumentsResponse['files']>({});\n  const [viewing, setViewing] = useState<{ docName: string; filename: string } | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState('');\n\n  const [requested, setRequested] = useState<{ name: string; note?: string }[]>([]);\n\n  const reload = () => {\n    listLmsDocuments(appId).then((d) => {\n      setFiles(d.files || {});\n      setRequested(d.requested || []);\n    }).catch(() => { /* none on file */ });\n  };\n\n  async function requestDoc() {\n    const name = (window.prompt('What document do you need?') || '').trim();\n    if (!name) return;\n    const note = (window.prompt('Why, or any detail for whoever supplies it? (optional)') || '').trim();\n    setBusy(true);\n    setErr('');\n    try {\n      await requestLmsDocument(appId, name, note);\n      reload();\n      onAttached?.();\n    } catch (e) {\n      setErr(e instanceof Error ? e.message : 'Could not record that request.');\n    } finally {\n      setBusy(false);\n    }\n  }\n  useEffect(reload, [appId]);\n\n  async function attach(docName: string, file: File) {\n    setBusy(true);\n    setErr('');\n    try {\n      const b64 = await new Promise<string>((res, rej) => {\n        const r = new FileReader();\n        r.onload = () => res(String(r.result).split(',')[1] ?? '');\n        r.onerror = () => rej(new Error('Could not read that file.'));\n        r.readAsDataURL(file);\n      });\n      await uploadLmsDocument(appId, docName, file.name, b64);\n      reload();\n      onAttached?.();\n    } catch (e) {\n      setErr(e instanceof Error ? e.message : 'Could not attach that file.');\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const entries = Object.entries(files);\n  // The panel must render even with nothing on file - otherwise the analyst\n  // has nowhere to attach the first document.\n  if (entries.length === 0 && !canAttach) return null;\n  return (\n    <Card className=\"mt-4\">\n      <Card.Header>\n        <h2 className=\"text-base font-semibold text-gray-900\">Documents on file</h2>\n        <span className=\"text-xs text-gray-500\">\n          {entries.length} document{entries.length === 1 ? '' : 's'} travelled with the case\n        </span>\n      </Card.Header>\n      <Card.Body>\n        <div className=\"space-y-2\">\n          {entries.map(([doc, meta]) => (\n            <div key={doc} className=\"flex items-center justify-between gap-2 rounded border p-2 text-sm\">\n              <span className=\"text-gray-800\">\n                <span className=\"text-gray-400\">\ud83d\udcc4</span> {doc}\n                {meta?.filename && <span className=\"ml-2 text-xs text-gray-500\">{meta.filename}</span>}\n              </span>\n              <button type=\"button\" className=\"text-brand-primary hover:underline text-xs\"\n                onClick={() => setViewing({ docName: doc, filename: meta?.filename || doc })}>View</button>\n            </div>\n          ))}\n        </div>\n        {entries.length === 0 && (\n          <p className=\"py-3 text-center text-xs text-gray-400\">\n            Nothing on file yet.\n          </p>\n        )}\n\n        {canAttach && (\n          <div className=\"mt-3 rounded-lg border border-gray-200 bg-gray-50/60 p-3\">\n            <p className=\"mb-2 text-xs font-medium text-gray-700\">Attach a document</p>\n            <div className=\"flex flex-wrap items-center gap-2\">\n              {[...ANALYST_DOCS, ...requested.map((r) => r.name)\n                .filter((n) => !ANALYST_DOCS.includes(n))].map((d) => (\n                <label key={d}\n                       className={'cursor-pointer rounded-md border px-3 py-1.5 text-xs '\n                         + (files[d]\n                           ? 'border-[#BED600] bg-[#F4F8E6] text-[#3B6D11]'\n                           : 'border-gray-300 bg-white text-gray-700 hover:border-brand-primary')}>\n                  {files[d] ? `\u2713 ${d}` : d}\n                  <input type=\"file\" className=\"hidden\" disabled={busy}\n                         onChange={(e) => {\n                           const f = e.target.files?.[0];\n                           if (!f) return;\n                           const name = d === 'Other'\n                             ? (window.prompt('What is this document called?') || '').trim()\n                             : d;\n                           if (!name) return;\n                           void attach(name, f);\n                           e.target.value = '';\n                         }} />\n                </label>\n              ))}\n              {busy && <span className=\"text-xs text-gray-500\">Attaching\u2026</span>}\n            </div>\n            {err && <p className=\"mt-2 text-xs text-rose-600\">{err}</p>}\n\n            {/* ASK FOR SOMETHING NOT ON THE LIST. The required list is per\n                PRODUCT and set by an admin - it says what every case of this\n                kind needs. What one analyst wants on ONE case is a different\n                thing, and writing it into the product config would quietly\n                change the rules for every future deal. So it is recorded on\n                the case, with who asked. */}\n            <div className=\"mt-2 flex items-center gap-2\">\n              <button type=\"button\" disabled={busy}\n                      onClick={() => void requestDoc()}\n                      className=\"rounded-md border border-gray-300 bg-white px-3 py-1.5 text-xs text-gray-700 hover:border-brand-primary\">\n                Request a document\n              </button>\n              {requested.length > 0 && (\n                <span className=\"text-[11px] text-gray-500\">\n                  {requested.length} requested:{' '}\n                  {requested.map((r) => r.name).join(', ')}\n                </span>\n              )}\n            </div>\n            <p className=\"mt-2 text-[11px] text-gray-500\">\n              Attached against this case and recorded under your name and role,\n              so it is clear later which papers came from credit rather than\n              from the branch.\n            </p>\n          </div>\n        )}\n\n        {!canDownload && (\n          <p className=\"mt-2 text-xs text-gray-400\">Read-only \u2014 download is not permitted for your role.</p>\n        )}\n      </Card.Body>\n      {viewing && (\n        <DocumentViewerModal\n          dealId=\"\" docName={viewing.docName} filename={viewing.filename}\n          canDownload={canDownload}\n          fetchBlob={() => downloadLmsDocument(appId, viewing.docName)}\n          onClose={() => setViewing(null)}\n        />\n      )}\n    </Card>\n  );\n}\n\n\nfunction HandToCreditAnalystPanel({ appId, onDone, toast }: {\n  appId: string;\n  onDone: () => Promise<void> | void;\n  toast: ReturnType<typeof useToast>['toast'];\n}) {\n  const [busy, setBusy] = useState(false);\n  const hand = async () => {\n    setBusy(true);\n    try {\n      await handToCreditAnalyst(appId);\n      toast({ tone: 'success', message: 'Handed to the Credit Analyst pool for decisioning.' });\n      await onDone();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Handoff failed.' });\n    } finally { setBusy(false); }\n  };\n  return (\n    <div className=\"mt-4 rounded-md border border-blue-200 bg-blue-50 px-4 py-3\">\n      <div className=\"text-sm font-semibold text-blue-900\">Hand to Credit Analyst</div>\n      <p className=\"mt-1 text-xs text-blue-800\">\n        The DCC has advised. Release this case to the Credit Analyst pool \u2014 a Credit Analyst\n        picks it up and, seeing both the Branch Committee and DCC inputs, makes the final\n        credit decision that issues the offer. You do not decide the case.\n      </p>\n      <div className=\"mt-3\">\n        <Button onClick={hand} disabled={busy}>{busy ? 'Handing over\u2026' : 'Hand to Credit Analyst'}</Button>\n      </div>\n    </div>\n  );\n}\n\n\nfunction SubmitToDccPanel({ appId, onDone, toast }: {\n  appId: string;\n  onDone: () => Promise<void> | void;\n  toast: ReturnType<typeof useToast>['toast'];\n}) {\n  const [opinion, setOpinion] = useState('');\n  const [pep, setPep] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [memoBusy, setMemoBusy] = useState(false);\n  const attachMemo = () => {\n    const inp = document.createElement('input');\n    inp.type = 'file';\n    inp.onchange = async () => {\n      const f = inp.files?.[0];\n      if (!f) return;\n      setMemoBusy(true);\n      try {\n        const buf = await f.arrayBuffer();\n        const bytes = new Uint8Array(buf);\n        let bin = '';\n        for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);\n        await uploadCallbackMemo(appId, { filename: f.name, content_b64: btoa(bin) });\n        toast({ tone: 'success', message: 'Call-Back Memo attached.' });\n        await onDone();\n      } catch (e) {\n        toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Upload failed.' });\n      } finally { setMemoBusy(false); }\n    };\n    inp.click();\n  };\n  const submit = async () => {\n    setBusy(true);\n    try {\n      await submitLmsToDcc(appId, { opinion: opinion.trim(), pep_confirmed: pep });\n      toast({ tone: 'success', message: 'Submitted to the Department Credit Committee.' });\n      await onDone();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Submit failed.' });\n    } finally { setBusy(false); }\n  };\n  return (\n    <div className=\"mt-4 rounded-md border border-amber-200 bg-amber-50 px-4 py-3\">\n      <div className=\"text-sm font-semibold text-amber-900\">Submit to Department Credit Committee</div>\n      <p className=\"mt-1 text-xs text-amber-800\">\n        Check completeness and voice your support. You do not make the credit decision \u2014\n        this refers the case to the DCC. As the checker, complete the call-back and\n        <strong> attach the Call-Back Memo</strong> below, and confirm PEP compliance.\n      </p>\n      <div className=\"mt-3 flex items-center gap-2\">\n        <Button variant=\"ghost\" size=\"sm\" onClick={attachMemo} disabled={memoBusy || busy}>\n          {memoBusy ? 'Attaching\u2026' : 'Attach Call-Back Memo'}\n        </Button>\n        <span className=\"text-xs text-amber-700\">Stored with the case + readable by the committee.</span>\n      </div>\n      <label className=\"mt-3 block text-xs font-medium text-amber-900\">Support opinion</label>\n      <textarea\n        value={opinion} disabled={busy} rows={3}\n        onChange={(e) => setOpinion(e.target.value)}\n        placeholder=\"Why you support this facility (completeness, key strengths)\u2026\"\n        className=\"mt-1 w-full rounded-md border border-amber-300 px-2 py-1.5 text-sm\"\n      />\n      <label className=\"mt-3 flex items-center gap-2 text-sm text-amber-900\">\n        <input type=\"checkbox\" checked={pep} disabled={busy} onChange={(e) => setPep(e.target.checked)} />\n        I confirm the client is not a PEP and has no compliance issues.\n      </label>\n      <div className=\"mt-3\">\n        <Button onClick={submit} disabled={busy || !pep}>\n          {busy ? 'Submitting\u2026' : 'Submit to DCC'}\n        </Button>\n      </div>\n    </div>\n  );\n}\n\n\nfunction CreditReportCard({ appId, canEdit, toast, embedded = false }: {\n  appId: string; canEdit: boolean; toast: ReturnType<typeof useToast>['toast'];\n  embedded?: boolean;\n}) {\n  const [cr, setCr] = useState<CrView | null>(null);\n  const [edits, setEdits] = useState<Record<string, string>>({});\n  const [busy, setBusy] = useState(false);\n\n  const load = async () => {\n    try {\n      const r = await getLmsCr(appId);\n      setCr(r.cr);\n    } catch { /* page-local, non-fatal */ }\n  };\n  useEffect(() => { void load(); /* eslint-disable-next-line */ }, [appId]);\n\n  const valueFor = (key: string): string => {\n    if (key in edits) return edits[key];\n    const v = cr?.values?.[key];\n    return v === undefined || v === null ? '' : String(v);\n  };\n\n  const save = async (completed: boolean) => {\n    setBusy(true);\n    try {\n      // Send only RM-edited fields; server re-derives auto/cbs on read.\n      await saveLmsCr(appId, { values: edits, completed });\n      setEdits({});\n      toast({ tone: 'success', message: completed ? 'Transaction Memo marked complete.' : 'Transaction Memo saved.' });\n      await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Save failed.' });\n    } finally { setBusy(false); }\n  };\n\n  if (!cr) return null;\n\n  const sourceTint = (f: CrField, hasValue: boolean) => {\n    if (f.source === 'cbs') return hasValue ? 'bg-blue-50/50' : '';\n    if (f.source === 'auto') return hasValue ? 'bg-gray-50' : '';\n    return '';\n  };\n\n  const printCr = () => {\n    const secs = (cr.template?.sections ?? []).map((sec) => {\n      const tableField = (sec.fields ?? []).find((f) => f.type === 'table');\n      if (tableField) {\n        return `<h2>${escapeHtml(sec.title)}</h2>${facilitiesToPrintHtml(valueFor(tableField.key))}`;\n      }\n      const rows = (sec.fields ?? []).map((f) =>\n        `<tr><th style=\"width:42%\">${escapeHtml(f.label)}</th><td>${escapeHtml(valueFor(f.key)) || '\u2014'}</td></tr>`).join('');\n      return `<h2>${escapeHtml(sec.title)}</h2><table>${rows}</table>`;\n    }).join('');\n    const head = `<div class=\"head\"><h1>Transaction Memo \u2014 ${escapeHtml(appId)}</h1><span class=\"muted\">${cr.completed ? 'Complete' : 'Draft'} \u00b7 printed ${escapeHtml(new Date().toLocaleString())}</span></div>`;\n    printDocument(`Transaction Memo ${appId}`, head + secs);\n  };\n\n  const Shell:   ElementType = embedded ? EmbeddedShell  : Card;\n  const SHeader: ElementType = embedded ? EmbeddedHeader : Card.Header;\n  const SBody:   ElementType = embedded ? EmbeddedBody   : Card.Body;\n\n  return (\n    <Shell className=\"mt-6\">\n      <SHeader>\n        <h2 className=\"text-base font-semibold text-gray-900\">Transaction Memo (TM)</h2>\n        <div className=\"flex items-center gap-2\">\n          {cr.completed && <Badge tone=\"success\">Complete</Badge>}\n          {!cr.cbs_available && <span className=\"text-xs text-gray-400\">CBS data unavailable \u2014 fill manually</span>}\n          <button className=\"text-sm text-brand-primary\" onClick={printCr}>Print</button>\n        </div>\n      </SHeader>\n      <SBody>\n          <p className=\"text-xs text-gray-500 mb-4\">\n            Fields tinted blue come from CBS; grey from the application. Both are editable.\n            Plain fields are for the relationship owner to complete.\n          </p>\n          <div className=\"space-y-6\">\n            {cr.template.sections.map((sec) => (\n              <div key={sec.key}>\n                <div className=\"text-sm font-semibold text-gray-800 mb-2 pb-1 border-b border-gray-100\">\n                  {sec.title}\n                </div>\n                <div className=\"grid grid-cols-1 md:grid-cols-2 gap-3\">\n                  {sec.fields.map((f) => {\n                    const val = valueFor(f.key);\n                    if (f.type === 'table') {\n                      return (\n                        <div key={f.key} className=\"md:col-span-2\">\n                          <label className=\"mb-1 block text-xs text-gray-600\">{f.label}</label>\n                          <FacilitiesTable value={val} onChange={(v) => setEdits((p) => ({ ...p, [f.key]: v }))} disabled={!canEdit || busy} />\n                        </div>\n                      );\n                    }\n                    const isLong = ['strengths', 'weaknesses', 'mitigants', 'rm_recommendation', 'conditions', 'purpose', 'background', 'statements', 'crb_arrears', 'risk_summary', 'other_bank_facilities', 'other_bank_securities', 'dsr_computation', 'policy_exception', 'account_conduct', 'repayment_source'].includes(f.key);\n                    return (\n                      <div key={f.key} className={isLong ? 'md:col-span-2' : ''}>\n                        <label className=\"block text-xs text-gray-600 mb-1\">\n                          {f.label}{f.required && <span className=\"text-red-500\"> *</span>}\n                          {f.source !== 'rm' && <span className=\"ml-1 text-[10px] uppercase text-gray-400\">({f.source})</span>}\n                        </label>\n                        {isLong ? (\n                          <textarea\n                            value={val} disabled={!canEdit || busy} rows={2}\n                            onChange={(e) => setEdits((p) => ({ ...p, [f.key]: e.target.value }))}\n                            className={`w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm ${sourceTint(f, !!val)}`}\n                          />\n                        ) : (\n                          <input\n                            value={val} disabled={!canEdit || busy}\n                            onChange={(e) => setEdits((p) => ({ ...p, [f.key]: e.target.value }))}\n                            className={`w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm ${sourceTint(f, !!val)}`}\n                          />\n                        )}\n                      </div>\n                    );\n                  })}\n                </div>\n              </div>\n            ))}\n          </div>\n          {canEdit && (\n            <div className=\"mt-4 flex gap-2\">\n              <Button onClick={() => save(false)} disabled={busy}>{busy ? 'Working\u2026' : 'Save draft'}</Button>\n              <Button variant=\"secondary\" onClick={() => save(true)} disabled={busy}>Mark complete</Button>\n            </div>\n          )}\n          {cr.updated_by && (\n            <div className=\"mt-2 text-xs text-gray-400\">Last saved by {cr.updated_by}</div>\n          )}\n        </SBody>\n    </Shell>\n  );\n}\n\n// \u2500\u2500 Branch committee decisions (4b-7b): read-only, carried from the deal \u2500\u2500\nfunction BranchCommitteeDecisionsCard({ appId }: { appId: string }) {\n  const [data, setData] = useState<LmsCommitteeRecordsResponse | null>(null);\n  useEffect(() => {\n    getLmsCommitteeRecords(appId).then(setData).catch(() => setData(null));\n  }, [appId]);\n  if (!data) return null;\n  const codes = Object.keys(data.committee_records || {});\n  if (codes.length === 0) return null;\n  const tone = (o: string) => (o === 'APPROVED' ? 'success' : o === 'REJECTED' ? 'danger' : 'warning');\n  return (\n    <Card className=\"mt-6\">\n      <Card.Header>\n        <h2 className=\"text-base font-semibold text-gray-900\">Branch Committee Decisions</h2>\n        <Badge tone=\"info\" size=\"sm\">from branch</Badge>\n      </Card.Header>\n      <Card.Body>\n        <p className=\"mb-3 text-xs text-gray-500\">Recorded at the branch before submission (read-only).</p>\n        <div className=\"space-y-3\">\n          {codes.map((code) => {\n            const r = data.committee_records[code];\n            return (\n              <div key={code} className=\"rounded border p-2\">\n                <div className=\"flex items-center justify-between\">\n                  <span className=\"text-sm font-medium\">{code}</span>\n                  <Badge tone={tone(r.outcome)} size=\"sm\">{r.outcome}</Badge>\n                </div>\n                <p className=\"text-xs text-gray-500\">Recorded by {r.recorded_by} on {r.recorded_at}.</p>\n                {r.mode === 'voting' && r.votes.length > 0 && (\n                  <ul className=\"mt-1 list-disc pl-5 text-xs text-gray-600\">\n                    {r.votes.map((v, i) => <li key={i}>{v.name} ({v.role}): {v.vote}</li>)}\n                  </ul>\n                )}\n              </div>\n            );\n          })}\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\n\n// C2: correctness-check action set \u2014 mark ready for committee or return for rework,\n// with an optional opinion for the Chief.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 Credit Analyst Workbench panel (P3) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst WB_NOTE_CATEGORIES = ['OBSERVATION', 'CONCERN', 'FOLLOW_UP', 'RECOMMENDATION', 'DECISION_RATIONALE'];\n\nfunction CreditWorkbenchPanel({ appId, toast, embedded = false, canEdit = false }: {\n  appId: string; toast: (t: { tone: 'success' | 'danger'; message: string }) => void;\n  embedded?: boolean; canEdit?: boolean;\n}) {\n  const { user } = useRole();\n  const [wb, setWb] = useState<WorkbenchView | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [noteCat, setNoteCat] = useState('OBSERVATION');\n  const [noteBody, setNoteBody] = useState('');\n\n  const load = async () => {\n    try { setWb(await getApplicationWorkbench(appId)); }\n    catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Failed to load workbench' }); }\n  };\n  useEffect(() => { void load(); /* eslint-disable-next-line */ }, [appId]);\n\n  const refresh = async () => {\n    setBusy(true);\n    try {\n      const r = await refreshWorkbench(appId);\n      setWb((prev) => prev ? { ...prev, summary: r.summary, conflict_report: r.conflict_report } : prev);\n      toast({ tone: 'success', message: 'Engines refreshed.' });\n      await load();\n    } catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Refresh failed' }); }\n    finally { setBusy(false); }\n  };\n\n  const addNote = async () => {\n    if (!noteBody.trim()) return;\n    setBusy(true);\n    try {\n      await addWorkbenchNote(appId, noteCat, noteBody.trim());\n      setNoteBody('');\n      toast({ tone: 'success', message: 'Note recorded.' });\n      await load();\n    } catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Note failed' }); }\n    finally { setBusy(false); }\n  };\n\n  if (!wb) return null;\n  const cr = wb.conflict_report;\n  const s = wb.summary;\n\n  const Shell:   ElementType = embedded ? EmbeddedShell  : Card;\n  const SHeader: ElementType = embedded ? EmbeddedHeader : Card.Header;\n  const SBody:   ElementType = embedded ? EmbeddedBody   : Card.Body;\n\n  return (\n    <Shell className=\"mt-4\" stripe=\"accent\">\n      <SHeader>\n        <div className=\"flex items-center justify-between\">\n          <h3 className=\"text-sm font-semibold text-gray-900\">Credit Analyst Workbench</h3>\n          <span className=\"text-xs text-gray-500\">Session {s.state ?? '\u2014'}</span>\n        </div>\n      </SHeader>\n      <SBody>\n        <p className=\"mb-3 text-xs text-gray-500\">\n          What each credit engine currently says for this customer, and where they conflict.\n        </p>\n\n        {/* Conflict report \u2014 front and centre */}\n        <div className={`mb-3 rounded border p-3 text-sm ${cr.conflict_count > 0 ? 'border-amber-300 bg-amber-50' : 'border-green-200 bg-green-50'}`}>\n          {cr.conflict_count > 0 ? (\n            <div>\n              <span className=\"font-medium text-amber-800\">{cr.conflict_count} conflict{cr.conflict_count === 1 ? '' : 's'} across engines</span>\n              <div className=\"mt-2 space-y-1\">\n                {cr.conflicts.map((c, i) => (\n                  <div key={i} className=\"text-xs text-amber-900\">\n                    <span className=\"font-medium\">{c.decision}</span> \u2014 {c.sources.join(', ')}\n                  </div>\n                ))}\n              </div>\n            </div>\n          ) : (\n            <span className=\"text-green-800\">No conflicts across the engines pulled ({cr.total_pulls} pull{cr.total_pulls === 1 ? '' : 's'}).</span>\n          )}\n        </div>\n\n        {/* WB role lens (P4): role-shaped read-side signals */}\n        {wb.role_lens && (() => {\n          const r = String(user?.role ?? '').toLowerCase();\n          const ca = wb.role_lens.credit_admin;\n          const isAdminOrTrops = r.includes('admin') || r.includes('trops') || r.includes('operations') || r.includes('disburs');\n          const isRm = r.includes('relationship') || r.includes('personal banker') || r.includes(' ro ') || r.includes('officer');\n          const roleLabel = isAdminOrTrops ? 'Credit Admin / Trops' : (r.includes('analyst') ? 'Analyst' : (isRm ? 'Relationship Manager' : 'Credit'));\n          return (\n            <div className=\"mb-3 rounded border border-gray-200 bg-gray-50 p-3 text-xs\">\n              <div className=\"mb-1 flex items-center justify-between\">\n                <span className=\"font-medium text-gray-700\">Your view: {roleLabel}</span>\n              </div>\n              <div className=\"flex flex-wrap gap-x-4 gap-y-1 text-gray-600\">\n                <span>Appraisal (CR): {wb.role_lens.cr.completed === null ? 'n/a' : (wb.role_lens.cr.completed ? 'complete \u2713' : 'incomplete')}</span>\n                {ca.linked ? (\n                  <>\n                    <span>Conditions: {ca.conditions_met}/{ca.conditions_total} met</span>\n                    <span>All met: {ca.all_conditions_met ? 'yes \u2713' : 'no'}</span>\n                    <span>Cleared: {ca.cleared ? 'yes \u2713' : 'no'}</span>\n                    <span>Disbursed: {ca.disbursed ? 'yes \u2713' : 'no'}</span>\n                  </>\n                ) : <span className=\"text-gray-400\">No credit-admin case yet</span>}\n              </div>\n            </div>\n          );\n        })()}\n\n        {/* Engine sources */}\n        <div className=\"mb-3 grid grid-cols-2 gap-2 text-xs\">\n          <div>\n            <p className=\"font-medium text-gray-600\">Engines pulled ({(s.sources_pulled ?? []).length})</p>\n            {(s.sources_pulled ?? []).map((src) => <div key={src} className=\"text-green-700\">\u2713 {src}</div>)}\n          </div>\n          <div>\n            <p className=\"font-medium text-gray-600\">Not yet pulled ({(s.sources_missing ?? []).length})</p>\n            {(s.sources_missing ?? []).map((src) => <div key={src} className=\"text-gray-400\">\u2022 {src}</div>)}\n          </div>\n        </div>\n\n        {canEdit ? (\n        <div className=\"mb-4\">\n          <Button variant=\"primary\" onClick={() => void refresh()} disabled={busy}>\n            {busy ? 'Refreshing\u2026' : 'Refresh engines'}\n          </Button>\n        </div>\n        ) : (\n          <p className=\"mb-4 text-xs text-gray-400\">Read-only \u2014 you can view the credit analysis but not change it.</p>\n        )}\n\n        {/* Analyst notes */}\n        <div className=\"border-t pt-3\">\n          <p className=\"mb-2 text-xs font-medium text-gray-600\">\n            Analyst notes {s.notes_count ? `(${s.notes_count})` : ''}\n          </p>\n          {canEdit && (\n          <div className=\"flex flex-col gap-2 sm:flex-row\">\n            <select value={noteCat} onChange={(e) => setNoteCat(e.target.value)}\n              className=\"rounded border border-gray-300 px-2 py-1.5 text-sm\">\n              {WB_NOTE_CATEGORIES.map((c) => <option key={c} value={c}>{c.replace(/_/g, ' ')}</option>)}\n            </select>\n            <input value={noteBody} onChange={(e) => setNoteBody(e.target.value)}\n              placeholder=\"Record an observation, concern, or rationale\u2026\"\n              className=\"flex-1 rounded border border-gray-300 px-3 py-1.5 text-sm\" />\n            <Button variant=\"ghost\" onClick={() => void addNote()} disabled={busy || !noteBody.trim()}>Add note</Button>\n          </div>\n          )}\n          {s.notes_by_category && Object.keys(s.notes_by_category).length > 0 && (\n            <div className=\"mt-2 flex flex-wrap gap-2 text-xs text-gray-500\">\n              {Object.entries(s.notes_by_category).map(([cat, n]) => (\n                <span key={cat} className=\"rounded bg-gray-100 px-2 py-0.5\">{cat.replace(/_/g, ' ')}: {n}</span>\n              ))}\n            </div>\n          )}\n        </div>\n      </SBody>\n    </Shell>\n  );\n}\n\nfunction AppealPanel({ app, canReview, onDone, toast }: {\n  app: LoanApplication; canReview: boolean;\n  onDone: () => Promise<unknown> | unknown; toast: (t: { tone: 'success' | 'danger'; message: string }) => void;\n}) {\n  const [reason, setReason] = useState('');\n  const [note, setNote] = useState('');\n  const [busy, setBusy] = useState(false);\n  const pending = !!app.appeal_pending;\n  const isDeclined = String(app.status).toLowerCase() === 'declined';\n  const appeals = app.appeals ?? [];\n  if (!isDeclined && !pending && appeals.length === 0) return null;\n\n  const file = async () => {\n    if (!reason.trim()) { toast({ tone: 'danger', message: 'An appeal reason is required.' }); return; }\n    setBusy(true);\n    try {\n      await appealDecline(app.id, reason.trim());\n      toast({ tone: 'success', message: 'Appeal filed \u2014 pending manager review.' });\n      await onDone();\n    } catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Failed' }); }\n    finally { setBusy(false); }\n  };\n  const review = async (outcome: 'grant' | 'uphold') => {\n    setBusy(true);\n    try {\n      const r = await decideAppeal(app.id, outcome, note.trim() || undefined);\n      toast({ tone: 'success', message: r.reopened ? 'Appeal granted \u2014 case reopened for a fresh decision.' : 'Appeal upheld \u2014 the decline stands.' });\n      await onDone();\n    } catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Failed' }); }\n    finally { setBusy(false); }\n  };\n\n  return (\n    <Card className=\"mt-4\" stripe=\"accent\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Decline appeal</h3></Card.Header>\n      <Card.Body>\n        {appeals.length > 0 && (\n          <div className=\"mb-3 space-y-2\">\n            {appeals.map((a, i) => (\n              <div key={i} className=\"rounded border border-gray-200 bg-gray-50 p-2 text-xs\">\n                <div><span className=\"font-medium\">Reason:</span> {a.reason}</div>\n                <div className=\"text-gray-500\">\n                  Filed{a.by_name ? ` by ${a.by_name}` : ''}{a.at ? ` \u00b7 ${a.at}` : ''} \u2014 <span className=\"font-medium\">{a.outcome}</span>{a.reviewed_by_name ? ` by ${a.reviewed_by_name}` : ''}\n                </div>\n                {a.review_note && <div className=\"italic text-gray-500\">Note: {a.review_note}</div>}\n              </div>\n            ))}\n          </div>\n        )}\n        {isDeclined && !pending && (\n          <div>\n            <p className=\"mb-2 text-xs text-gray-500\">This application was declined. File an appeal for reconsideration \u2014 a manager will review it.</p>\n            <textarea value={reason} onChange={(e) => setReason(e.target.value)} placeholder=\"Grounds for appeal\u2026\" rows={3} className=\"mb-2 w-full rounded border border-gray-300 px-3 py-2 text-sm\" />\n            <Button variant=\"primary\" onClick={() => void file()} disabled={busy}>File appeal</Button>\n          </div>\n        )}\n        {pending && canReview && (\n          <div>\n            <p className=\"mb-2 text-xs text-gray-500\">An appeal is pending. Grant it (reopens the case for a fresh decision) or uphold the decline.</p>\n            <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder=\"Review note (optional)\u2026\" rows={2} className=\"mb-2 w-full rounded border border-gray-300 px-3 py-2 text-sm\" />\n            <div className=\"flex gap-2\">\n              <Button variant=\"primary\" onClick={() => void review('grant')} disabled={busy}>Grant (reopen)</Button>\n              <Button variant=\"ghost\" onClick={() => void review('uphold')} disabled={busy}>Uphold decline</Button>\n            </div>\n          </div>\n        )}\n        {pending && !canReview && (\n          <p className=\"text-xs text-gray-500\">Appeal filed \u2014 pending manager review.</p>\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction CorrectnessPanel({ appId, onDone, toast }: {\n  appId: string; onDone: () => Promise<unknown> | unknown; toast: (t: { tone: 'success' | 'danger'; message: string }) => void;\n}) {\n  const [opinion, setOpinion] = useState('');\n  const [reasons, setReasons] = useState<string[]>([]);\n  const [reasonOptions, setReasonOptions] = useState<string[]>([]);\n  const [busy, setBusy] = useState(false);\n  useEffect(() => {\n    fetchReworkReasons().then(setReasonOptions).catch(() => setReasonOptions([]));\n  }, []);\n  const toggleReason = (r: string) =>\n    setReasons((p) => (p.includes(r) ? p.filter((x) => x !== r) : [...p, r]));\n  // \u2500\u2500 ASK BEFORE SUBMITTING \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // RULING (2026-08-14): \"it submitted without asking if there are documents\n  // required for her to attach ... it can allow without, but the question\n  // where she selects Yes or No should come up for confirmation on her side.\"\n  //\n  // Recommending now SENDS the case, and a click that sends something should\n  // ask once. The question is the useful one - is anything still to attach -\n  // rather than a bare \"are you sure\", which people learn to click through.\n  //\n  // ANSWERING \"yes, something is missing\" does not block: it closes the\n  // dialogue and leaves her on the page with the attach control, because the\n  // remedy for a missing paper is to attach it, not to be told off.\n  const [confirmReady, setConfirmReady] = useState(false);\n\n  const act = async (decision: 'ready' | 'rework') => {\n    if (decision === 'rework' && reasons.length === 0) {\n      toast({ tone: 'danger', message: 'Select at least one rework reason before returning the case.' });\n      return;\n    }\n    setBusy(true);\n    try {\n      await setCommitteeReadiness(appId, decision, opinion.trim() || undefined,\n        decision === 'rework' ? reasons : undefined);\n      toast({ tone: 'success', message: decision === 'ready'\n        ? 'Recommended \u2014 the case is now with the department committee.'\n        : 'Returned to the branch for rework.' });\n      await onDone();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Action failed' });\n    } finally { setBusy(false); }\n  };\n  return (\n    <Card className=\"mt-4\" stripe=\"accent\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Correctness check</h3></Card.Header>\n      <Card.Body>\n        <p className=\"mb-2 text-xs text-gray-500\">Confirm the case is well-packaged for committee, or return it for rework. When returning for rework, select the specific reason(s) so the branch knows exactly what to fix; you may also add an opinion for the Chief.</p>\n        {reasonOptions.length > 0 && (\n          <div className=\"mb-3 rounded-md border border-gray-200 bg-gray-50 p-3\">\n            <div className=\"mb-1.5 text-xs font-medium text-gray-600\">Rework reasons <span className=\"text-gray-400\">(required if returning for rework)</span></div>\n            <div className=\"grid grid-cols-1 gap-1 sm:grid-cols-2\">\n              {reasonOptions.map((r) => (\n                <label key={r} className=\"flex items-center gap-2 text-xs text-gray-700\">\n                  <input type=\"checkbox\" checked={reasons.includes(r)} onChange={() => toggleReason(r)} disabled={busy} />\n                  {r}\n                </label>\n              ))}\n            </div>\n          </div>\n        )}\n        <textarea\n          value={opinion}\n          onChange={(e) => setOpinion(e.target.value)}\n          placeholder=\"Optional opinion / notes for the Chief\u2026\"\n          className=\"mb-3 w-full rounded border border-gray-300 px-3 py-2 text-sm\"\n          rows={3}\n        />\n        <div className=\"flex gap-2\">\n          {/* \"MAYBE READY RECOMMENDED\" (ruling 2026-08-14). \"Mark ready\" reads\n              like a housekeeping flag; what the analyst is doing is\n              RECOMMENDING the case, and that recommendation now sends it to\n              the committee in the same act. The label should say so, because\n              somebody who thinks they are ticking a box will press it more\n              casually than somebody who knows they are submitting. */}\n          {confirmReady && (\n            <div className=\"mb-3 w-full rounded-md border border-amber-300 bg-amber-50 px-3 py-2.5\">\n              <p className=\"text-sm font-medium text-amber-900\">\n                Is there any document still to be attached to this case?\n              </p>\n              <p className=\"mt-1 text-xs text-amber-800\">\n                Recommending sends it straight to the department committee \u2014 they\n                will vote on the papers as they stand.\n              </p>\n              <div className=\"mt-2 flex items-center gap-2\">\n                <Button size=\"sm\" variant=\"secondary\"\n                  onClick={() => setConfirmReady(false)}>\n                  Yes \u2014 let me attach it first\n                </Button>\n                <Button size=\"sm\" disabled={busy}\n                  onClick={() => { setConfirmReady(false); void act('ready'); }}>\n                  No \u2014 recommend it now\n                </Button>\n              </div>\n            </div>\n          )}\n          <Button variant=\"primary\" onClick={() => setConfirmReady(true)} disabled={busy}>Recommend to committee</Button>\n          <Button variant=\"ghost\" onClick={() => void act('rework')} disabled={busy}>Return for rework</Button>\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\n\n// C3b: committee pre-read \u2014 members record a non-binding view; everyone sees leanings.\nfunction CommitteePreReadPanel({ appId, toast }: {\n  appId: string; toast: (t: { tone: 'success' | 'danger'; message: string }) => void;\n}) {\n  const [data, setData] = useState<CommitteePreReadsResponse | null>(null);\n  const [note, setNote] = useState('');\n  const [busy, setBusy] = useState(false);\n  const load = async () => {\n    try { setData(await fetchCommitteePreReads(appId)); } catch { /* non-fatal */ }\n  };\n  useEffect(() => { void load(); /* eslint-disable-next-line */ }, [appId]);\n  const record = async (view: 'leaning_approve' | 'leaning_decline' | 'questions') => {\n    setBusy(true);\n    try {\n      await recordCommitteePreRead(appId, view, note.trim() || undefined);\n      toast({ tone: 'success', message: 'Pre-read recorded.' });\n      setNote(''); await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not record' });\n    } finally { setBusy(false); }\n  };\n  const label: Record<string, string> = {\n    leaning_approve: 'Leaning approve', leaning_decline: 'Leaning decline', questions: 'Questions',\n  };\n  return (\n    <Card className=\"mt-4\" stripe=\"accent\">\n      <Card.Header><h3 className=\"text-sm font-semibold text-gray-900\">Committee pre-read (non-binding)</h3></Card.Header>\n      <Card.Body>\n        <p className=\"mb-2 text-xs text-gray-500\">Members review independently ahead of the convened meeting. This is a non-binding leaning, not the vote.</p>\n        {data && (\n          <div className=\"mb-3 flex gap-3 text-xs\">\n            <span className=\"rounded bg-green-50 px-2 py-1 text-green-700\">Approve: {data.tally.leaning_approve ?? 0}</span>\n            <span className=\"rounded bg-red-50 px-2 py-1 text-red-700\">Decline: {data.tally.leaning_decline ?? 0}</span>\n            <span className=\"rounded bg-amber-50 px-2 py-1 text-amber-700\">Questions: {data.tally.questions ?? 0}</span>\n          </div>\n        )}\n        <textarea value={note} onChange={(e) => setNote(e.target.value)}\n          placeholder=\"Optional note with your leaning\u2026\"\n          className=\"mb-2 w-full rounded border border-gray-300 px-3 py-2 text-sm\" rows={2} />\n        <div className=\"flex gap-2\">\n          <Button variant=\"primary\" size=\"sm\" onClick={() => void record('leaning_approve')} disabled={busy}>Leaning approve</Button>\n          <Button variant=\"ghost\" size=\"sm\" onClick={() => void record('leaning_decline')} disabled={busy}>Leaning decline</Button>\n          <Button variant=\"ghost\" size=\"sm\" onClick={() => void record('questions')} disabled={busy}>Questions</Button>\n        </div>\n        {data && data.pre_reads.length > 0 && (\n          <div className=\"mt-3 space-y-1\">\n            {data.pre_reads.map((r) => (\n              <div key={r.by_code} className=\"rounded bg-gray-50 px-2 py-1 text-xs\">\n                <span className=\"font-medium\">{r.by_name}</span>: {label[r.view] ?? r.view}\n                {r.note && <span className=\"text-gray-500\"> \u2014 {r.note}</span>}\n              </div>\n            ))}\n          </div>\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n",
 "frontend/web/src/pages/Lms.tsx": "// v10.520 Phase 4 Batch \u03b25 \u2014 LMS application list page.\n//\n// First consumer of GET /api/lms/applications (\u03b18). Cascade-scoped\n// table with status filters. Clicking a row navigates to detail.\n//\n// Layout mirrors Pipeline.tsx: header strip + filter chips + Card-based\n// table + empty/loading/error states.\n\nimport { displayName } from \"../lib/names\";\nimport { useState, useMemo, useEffect } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { useBranding } from '@/hooks/useBranding';\nimport { useRole } from '@/hooks/useRole';\nimport { useLmsApplications } from '@/hooks/useLmsApplications';\nimport { useToast } from '@/components/Toast';\nimport { fetchAssignmentRequests, assignLmsAnalyst, fetchMyAnalysts, type AssignmentRequestCase, type AssignableAnalyst, pickLmsApplication } from '@/lib/api';\nimport { Card } from '@/components/Card';\nimport { PageHeader } from '@/components/PageHeader';\nimport { Badge } from '@/components/Badge';\nimport { Button } from '@/components/Button';\nimport { Skeleton } from '@/components/Skeleton';\nimport {\n  statusTone,\n  type LoanApplication,\n} from '@/types/lms';\n\n\n// \u2500\u2500 Helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction formatAmount(v: number | undefined, symbol: string): string {\n  const n = Number(v);\n  if (!Number.isFinite(n) || n === 0) return '\u2014';\n  return `${symbol} ${n.toLocaleString()}`;\n}\n\nfunction formatDate(s: string | undefined): string {\n  if (!s) return '\u2014';\n  return s.slice(0, 10);\n}\n\n\n// \u2500\u2500 Page component \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport function Lms() {\n  const navigate = useNavigate();\n  const { branding } = useBranding();\n  const { user, isAdmin } = useRole();\n  const { applications, loading, error, refetch } = useLmsApplications();\n\n  // \u2500\u2500 Filter state (client-side; server always returns all in-scope) \u2500\u2500\n  const [statusFilter, setStatusFilter] = useState<string | 'all'>('all');\n  const [searchTerm,   setSearchTerm]   = useState<string>('');\n  // B1: workload tabs. Analysts default to their own cases; managers to All.\n  const myCode = String(user?.staff_code ?? '');\n  const roleLc = String(user?.role ?? '').toLowerCase();\n  const isPureAnalyst = roleLc.includes('analyst') && !isAdmin\n    && !/chief|head|manager|officer|director|managing/.test(roleLc);\n  const [tab, setTab] = useState<'mine' | 'pool' | 'all'>('all');\n  const [page, setPage] = useState(0);\n  const PAGE_SIZE = 25;\n  const { toast } = useToast();\n  const [requestBusy, setRequestBusy] = useState<string | null>(null);\n  const isManagerRole = isAdmin || /chief|head|manager|officer|director|managing/.test(roleLc);\n  // PICKING IS IMMEDIATE. doRequest below asks a manager to allocate the case\n  // and is kept for the roles that still work that way; a department analyst\n  // takes their own segment's work without asking.\n  const doPick = async (appId: string) => {\n    setRequestBusy(appId);\n    try {\n      await pickLmsApplication(appId);\n      toast({ tone: 'success', message: 'Picked \u2014 it is in My cases now.' });\n      await refetch();\n    } catch (e) {\n      toast({ tone: 'danger',\n        message: e instanceof Error ? e.message : 'Could not pick this case' });\n    } finally {\n      setRequestBusy(null);\n    }\n  };\n\n  // doRequest removed with the button it served: a department analyst picks\n  // rather than requests. If a role that still needs manager allocation\n  // appears, request-assignment is untouched on the server.\n  const [requestsCases, setRequestsCases] = useState<AssignmentRequestCase[]>([]);\n  const [analystPool, setAnalystPool] = useState<AssignableAnalyst[]>([]);\n  const [assignBusy, setAssignBusy] = useState<string | null>(null);\n  const [assignMenuFor, setAssignMenuFor] = useState<string | null>(null);\n  const [assignPurpose, setAssignPurpose] = useState<'decisioning' | 'correctness'>('decisioning');\n  const loadRequests = async () => {\n    if (!isManagerRole) return;\n    try { const r = await fetchAssignmentRequests(); setRequestsCases(r.cases); } catch { /* non-fatal */ }\n    try { const a = await fetchMyAnalysts(); setAnalystPool(a.analysts); } catch { /* non-fatal */ }\n  };\n  useEffect(() => { void loadRequests(); /* eslint-disable-next-line */ }, [isManagerRole, applications]);\n  const doAssign = async (appId: string, code: string, name: string, purpose: 'decisioning' | 'correctness' = 'decisioning') => {\n    setAssignBusy(appId + code);\n    try {\n      await assignLmsAnalyst(appId, { analyst_code: code, analyst_name: name, purpose });\n      toast({ tone: 'success', message: purpose === 'correctness' ? `Assigned to ${name} for correctness check.` : `Assigned to ${name} for decisioning.` });\n      await refetch();\n      await loadRequests();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Assign failed' });\n    } finally { setAssignBusy(null); }\n  };\n  useEffect(() => { setTab(isPureAnalyst ? 'mine' : 'all'); }, [isPureAnalyst]);\n\n  // \u2500\u2500 Filtered apps \u2500\u2500\n  const filteredApps = useMemo<LoanApplication[]>(() => {\n    let result = applications;\n    if (statusFilter !== 'all') {\n      result = result.filter((a) => (a.status || '').toLowerCase() === statusFilter);\n    }\n    if (searchTerm.trim()) {\n      const t = searchTerm.trim().toLowerCase();\n      result = result.filter((a) =>\n        (a.client_name || '').toLowerCase().includes(t) ||\n        (a.id || '').toLowerCase().includes(t) ||\n        (a.product || '').toLowerCase().includes(t) ||\n        (a.rm_name || '').toLowerCase().includes(t)\n      );\n    }\n    // B1: workload tab filter.\n    if (tab === 'mine') {\n      result = result.filter((a) => String(a.analyst?.code ?? '') === myCode);\n    } else if (tab === 'pool') {\n      result = result.filter((a) => !a.analyst?.code\n        && ['submitted'].includes((a.status || '').toLowerCase()));\n    }\n    return result;\n  }, [applications, statusFilter, searchTerm, tab, myCode]);\n  // Keep the current page in range when the filtered set shrinks.\n  const pageCount = Math.max(1, Math.ceil(filteredApps.length / PAGE_SIZE));\n  const safePage = Math.min(page, pageCount - 1);\n  const pagedApps = filteredApps.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);\n\n  // \u2500\u2500 Status counts for the filter chips \u2500\u2500\n  // statusCounts is gone with the filter row it fed. statusFilter itself\n  // stays and remains 'all' - it is the mechanism the search box and the tabs\n  // narrow through, and removing it would mean rewriting a working filter to\n  // delete a row of buttons.\n\n  const tabCounts = useMemo(() => ({\n    mine: applications.filter((a) => String(a.analyst?.code ?? '') === myCode).length,\n    pool: applications.filter((a) => !a.analyst?.code && (a.status || '').toLowerCase() === 'submitted').length,\n    all: applications.length,\n  }), [applications, myCode]);\n\n  const currencySymbol = branding?.currency_symbol ?? 'KES';\n\n\n  return (\n    <div className=\"min-h-screen bg-gray-50\">\n      {/* Header strip \u2014 same brand-navy as Pipeline pages */}\n      <PageHeader\n        ribbon\n        breadcrumbs={[{ label: 'A2Z Credit Intelligence System (CIS)' }, { label: 'Credit Analysis' }]}\n        title=\"Credit Analysis\"\n        subtitle=\"Submitted, assigned, and decided applications in your cascade.\"\n      />\n\n      <main className=\"max-w-7xl 2xl:max-w-[1680px] mx-auto px-6 py-6\">\n\n        {/* \u2500\u2500 Summary strip \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {!loading && !error && applications.length > 0 && (\n          <div className=\"grid grid-cols-2 md:grid-cols-4 gap-3 mb-4\">\n            {(() => {\n              const total = applications.length;\n              const inAnalysis = applications.filter((a) =>\n                ['submitted', 'assigned', 'info_requested'].includes((a.status || '').toLowerCase())).length;\n              const decided = applications.filter((a) =>\n                ['approved', 'declined', 'disbursed'].includes((a.status || '').toLowerCase())).length;\n              const totalValue = applications.reduce((s, a) => s + (Number(a.amount) || 0), 0);\n              const stat = (label: string, value: string, accent: string) => (\n                <Card>\n                  <Card.Body className=\"py-3\">\n                    <div className=\"text-xs text-gray-500\">{label}</div>\n                    <div className={`text-xl font-semibold mt-0.5 ${accent}`}>{value}</div>\n                  </Card.Body>\n                </Card>\n              );\n              return (\n                <>\n                  {stat('In queue', String(total), 'text-gray-900')}\n                  {stat('In analysis', String(inAnalysis), 'text-brand-primary')}\n                  {stat('Decided', String(decided), 'text-gray-900')}\n                  {stat('Total value', formatAmount(totalValue, currencySymbol), 'text-gray-900')}\n                </>\n              );\n            })()}\n          </div>\n        )}\n\n        {/* B2: assignment requests (manager) */}\n        {isManagerRole && requestsCases.length > 0 && (\n          <Card className=\"mb-4\" stripe=\"accent\">\n            <Card.Header>\n              <h2 className=\"text-base font-semibold text-gray-900\">Assignment requests</h2>\n              <Badge tone=\"warning\" size=\"sm\">{requestsCases.length}</Badge>\n            </Card.Header>\n            <Card.Body>\n              <div className=\"space-y-3\">\n                {requestsCases.map((c) => (\n                  <div key={c.id} className=\"rounded border p-3\">\n                    <div className=\"mb-2 flex items-center justify-between\">\n                      <div>\n                        <span className=\"font-mono text-xs text-gray-500\">{c.id}</span>\n                        <span className=\"ml-2 text-sm font-medium\">{c.client_name}</span>\n                        <span className=\"ml-2 text-xs text-gray-400\">{c.product}</span>\n                      </div>\n                    </div>\n                    <div className=\"space-y-1\">\n                      {c.requests.map((r) => (\n                        <div key={r.by_code} className=\"flex items-center justify-between rounded bg-gray-50 px-2 py-1 text-sm\">\n                          <span>Requested by <span className=\"font-medium\">{r.by_name}</span> ({r.by_code})</span>\n                          <Button size=\"sm\" onClick={() => void doAssign(c.id, r.by_code, r.by_name)}\n                            disabled={assignBusy === c.id + r.by_code}>\n                            {assignBusy === c.id + r.by_code ? 'Assigning\u2026' : `Assign to ${r.by_name.split(' ')[0]}`}\n                          </Button>\n                        </div>\n                      ))}\n                    </div>\n                    <div className=\"mt-2 flex items-center gap-2\">\n                      <span className=\"text-xs text-gray-500\">or assign someone else:</span>\n                      <select\n                        className=\"rounded border px-2 py-1 text-xs\"\n                        defaultValue=\"\"\n                        onChange={(e) => {\n                          const a = analystPool.find((x) => x.staff_code === e.target.value);\n                          if (a) void doAssign(c.id, a.staff_code, a.name);\n                          e.target.value = '';\n                        }}\n                      >\n                        <option value=\"\">\u2014 pick analyst \u2014</option>\n                        {analystPool.map((a) => (\n                          <option key={a.staff_code} value={a.staff_code}>{displayName(a.name)} ({a.staff_code})</option>\n                        ))}\n                      </select>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n        {/* \u2500\u2500 Filter bar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        <Card className=\"mb-4\">\n          <Card.Body>\n            {/* B1: workload tabs */}\n            <div className=\"flex items-center gap-2 mb-3 border-b border-gray-100 pb-3\">\n              {/* TWO TABS (ruling 2026-08-14): \"this should be My cases and\n                  the Pool. It is the pool that will contain all the cases\n                  submitted from the branch, and from here is where they select\n                  and it comes to My cases - once selected it moves out of the\n                  pool. This is for a department especially with 2 analysts to\n                  all pick from the pool.\"\n\n                  \"All\" was a third view of the same cases that answered no\n                  question an analyst asks. What is waiting for anyone, and\n                  what is mine - those are the two. */}\n              {([['mine', 'My cases'], ['pool', 'Pool']] as const).map(([key, label]) => (\n                <button\n                  key={key}\n                  onClick={() => setTab(key)}\n                  className={`px-3 py-1.5 rounded-md text-sm font-medium transition ${\n                    tab === key ? 'bg-brand-primary text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'\n                  }`}\n                >\n                  {label} ({tabCounts[key]})\n                </button>\n              ))}\n              {tab === 'pool' && (\n                <span className=\"ml-2 text-xs text-gray-500\">Everything waiting for this department. Open a case and pick it \u2014 it moves to My cases and out of the pool.</span>\n              )}\n            </div>\n            {/* THE STATUS FILTER ROW IS GONE (ruling 2026-08-14): \"we can\n                remove the rest of the items since they can still view that\n                from the Sales Pro.\"\n\n                Thirteen status buttons - approved, declined, offer_signed,\n                analyst_confirmed - are the shape of the workflow, not a\n                question anybody opens this page to ask. My cases and the Pool\n                are. The full picture is a click away in Sales Pro. */}\n            <div className=\"flex items-center gap-2\">\n              <input\n                type=\"text\"\n                placeholder=\"Search by client name, app id, product, or RM...\"\n                value={searchTerm}\n                onChange={(e) => setSearchTerm(e.target.value)}\n                className=\"flex-1 h-9 px-3 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n              />\n              {searchTerm && (\n                <Button variant=\"ghost\" size=\"sm\" onClick={() => setSearchTerm('')}>\n                  Clear\n                </Button>\n              )}\n              <Button variant=\"ghost\" size=\"sm\" onClick={() => refetch()}>\n                Refresh\n              </Button>\n            </div>\n          </Card.Body>\n        </Card>\n\n\n        {/* \u2500\u2500 Error state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {error && (\n          <Card className=\"mb-4\">\n            <Card.Body>\n              <div className=\"text-sm text-red-800\">\n                <div className=\"font-semibold mb-1\">Failed to load applications</div>\n                <div>{error}</div>\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n\n        {/* \u2500\u2500 Loading state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {loading && !error && (\n          <Card>\n            <Card.Body>\n              <div className=\"space-y-2\">\n                <Skeleton className=\"h-6 w-full\" />\n                <Skeleton className=\"h-6 w-full\" />\n                <Skeleton className=\"h-6 w-full\" />\n                <Skeleton className=\"h-6 w-3/4\" />\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n\n        {/* \u2500\u2500 Empty state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {!loading && !error && filteredApps.length === 0 && (\n          <Card>\n            <Card.Body>\n              <div className=\"text-center py-10\">\n                {applications.length === 0 ? (\n                  <>\n                    <div className=\"text-sm font-medium text-gray-800 mb-1\">\n                      No applications in your queue yet\n                    </div>\n                    <div className=\"text-xs text-gray-500 max-w-md mx-auto\">\n                      Applications submitted to credit{user?.full_name ? ` for ${user.full_name}` : ''} will\n                      appear here once a relationship manager submits a deal and it is assigned for analysis.\n                    </div>\n                  </>\n                ) : (\n                  <>\n                    <div className=\"text-sm font-medium text-gray-800 mb-1\">\n                      Nothing matches this filter\n                    </div>\n                    <div className=\"text-xs text-gray-500 mb-3\">\n                      {applications.length} application{applications.length === 1 ? '' : 's'} in your queue,\n                      none in {statusFilter !== 'all' ? `\u201c${statusFilter}\u201d` : 'this view'}\n                      {searchTerm ? ` matching \u201c${searchTerm}\u201d` : ''}.\n                    </div>\n                    <Button\n                      variant=\"ghost\"\n                      size=\"sm\"\n                      onClick={() => { setStatusFilter('all'); setSearchTerm(''); }}\n                    >\n                      Clear filters\n                    </Button>\n                  </>\n                )}\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n\n        {/* \u2500\u2500 List table \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n        {!loading && !error && filteredApps.length > 0 && (\n          <Card>\n            <Card.Body className=\"p-0\">\n              <div className=\"overflow-x-auto\">\n                <table className=\"min-w-full text-sm\">\n                  <thead className=\"bg-gray-50 border-b border-gray-200\">\n                    <tr className=\"text-left text-xs font-medium text-gray-500 uppercase tracking-wide\">\n                      <th className=\"px-4 py-3\">ID</th>\n                      <th className=\"px-4 py-3\">Client</th>\n                      <th className=\"px-4 py-3\">Product</th>\n                      <th className=\"px-4 py-3 text-right\">Amount</th>\n                      <th className=\"px-4 py-3\">Status</th>\n                      <th className=\"px-4 py-3\">RM</th>\n                      <th className=\"px-4 py-3\">Analyst</th>\n                      <th className=\"px-4 py-3\">SLA</th>\n                      <th className=\"px-4 py-3\">Review</th>\n                      {isManagerRole && <th className=\"px-4 py-3\">Assign</th>}\n                    </tr>\n                  </thead>\n                  <tbody className=\"divide-y divide-gray-100\">\n                    {pagedApps.map((app) => (\n                      <tr\n                        key={app.id}\n                        onClick={() => navigate(`/lms/${encodeURIComponent(app.id)}`)}\n                        className=\"hover:bg-gray-50 cursor-pointer transition\"\n                      >\n                        <td className=\"px-4 py-3 font-mono text-xs text-gray-500 whitespace-nowrap\">\n                          {app.id}\n                        </td>\n                        <td className=\"px-4 py-3\">\n                          <div className=\"font-medium text-gray-900\">{app.client_name}</div>\n                        </td>\n                        <td className=\"px-4 py-3 text-gray-700\">\n                          {app.product || '\u2014'}\n                        </td>\n                        <td className=\"px-4 py-3 text-right font-mono text-gray-700\">\n                          {formatAmount(app.amount, currencySymbol)}\n                        </td>\n                        <td className=\"px-4 py-3\">\n                          <Badge tone={statusTone(app.status)} size=\"sm\">\n                            {app.status}\n                          </Badge>\n                        </td>\n                        <td className=\"px-4 py-3 text-gray-700 text-xs\">\n                          {app.rm_name || '\u2014'}\n                        </td>\n                        <td className=\"px-4 py-3 text-gray-700 text-xs\">\n                          {app.analyst?.name\n                            ? app.analyst.name\n                            : (tab === 'pool' && isPureAnalyst ? (\n                              /* PICK, NOT REQUEST (ruling 2026-08-14): \"this\n                                 page should now have pick and not request\n                                 assignment.\"\n\n                                 Requesting belongs where a manager allocates\n                                 work. A department analyst owns their\n                                 segment's cases already, so asking permission\n                                 to take one adds a person to the chain for no\n                                 decision - and leaves the case sitting in the\n                                 pool while everybody waits. */\n                              <button\n                                onClick={(e) => { e.stopPropagation(); void doPick(app.id); }}\n                                disabled={requestBusy === app.id}\n                                className=\"rounded border border-brand-primary px-2 py-0.5 text-xs font-medium text-brand-primary hover:bg-brand-primary/5 disabled:opacity-50\"\n                              >\n                                {requestBusy === app.id ? 'Picking\u2026' : 'Pick'}\n                              </button>\n                            ) : <span className=\"text-gray-400\">unassigned</span>)}\n                        </td>\n                        <td className=\"px-4 py-3 text-xs\">\n                          {app.sla ? (\n                            <div className=\"flex flex-col gap-0.5\">\n                              {app.sla.stage && (\n                                <span className={`inline-flex w-fit items-center gap-1 rounded px-1.5 py-0.5 font-medium ${\n                                  app.sla.stage.state === 'breached' ? 'bg-red-100 text-red-700'\n                                  : app.sla.stage.state === 'due_soon' ? 'bg-amber-100 text-amber-700'\n                                  : 'bg-green-100 text-green-700'}`}>\n                                  My: {app.sla.stage.state === 'breached'\n                                    ? `${app.sla.stage.overdue_business_days}d over`\n                                    : `${app.sla.stage.remaining_business_days}d left`}\n                                </span>\n                              )}\n                              <span className={`inline-flex w-fit items-center gap-1 rounded px-1.5 py-0.5 ${\n                                app.sla.state === 'breached' ? 'text-red-600'\n                                : app.sla.state === 'due_soon' ? 'text-amber-600'\n                                : 'text-green-600'}`}>\n                                Case: {app.sla.state === 'breached'\n                                  ? `${app.sla.overdue_business_days}d over`\n                                  : app.sla.state === 'due_soon'\n                                  ? `${app.sla.remaining_business_days}d left`\n                                  : 'on track'}\n                              </span>\n                            </div>\n                          ) : <span className=\"text-gray-300\">\u2014</span>}\n                        </td>\n                        {/* WHAT THE REVIEW SAYS, not when it was applied for\n                            (ruling 2026-08-14): \"once the analyst recommends or\n                            returns it records here as reviewed and returned.\"\n\n                            The application date was the same for every DRYRUN\n                            case and told nobody whether their queue had moved.\n                            What an analyst scanning this list wants is which\n                            cases they have dealt with. The date is still on\n                            the case itself. */}\n                        <td className=\"px-4 py-3 text-xs\">\n                          {(() => {\n                            const r = (app as unknown as {\n                              committee_readiness?: { state?: string; by_name?: string };\n                            }).committee_readiness;\n                            const st = String(app.status || '').toLowerCase();\n                            if (r?.state === 'ready_for_committee') {\n                              return <span className=\"font-medium text-[#005B82]\">Reviewed \u00b7 recommended</span>;\n                            }\n                            if (r?.state === 'returned_for_rework' || st === 'returned') {\n                              return <span className=\"font-medium text-amber-700\">Reviewed \u00b7 returned</span>;\n                            }\n                            if (st === 'assigned') {\n                              return <span className=\"text-gray-500\">In review</span>;\n                            }\n                            return <span className=\"text-gray-400\">{formatDate(app.application_date)}</span>;\n                          })()}\n                        </td>\n                        {isManagerRole && (\n                          <td className=\"px-4 py-3 text-xs relative\" onClick={(e) => e.stopPropagation()}>\n                            {!app.analyst?.code && (app.status || '').toLowerCase() === 'submitted' ? (\n                              <>\n                                <button\n                                  onClick={() => setAssignMenuFor(assignMenuFor === app.id ? null : app.id)}\n                                  className=\"rounded border border-brand-primary px-2 py-0.5 text-xs text-brand-primary hover:bg-brand-primary/5\"\n                                >\n                                  Assign \u25be\n                                </button>\n                                {assignMenuFor === app.id && (\n                                  <div className=\"absolute right-0 z-10 mt-1 w-64 rounded-md border border-gray-200 bg-white p-2 shadow-lg\">\n                                    <div className=\"mb-1 text-xs font-medium text-gray-500\">Purpose</div>\n                                    <div className=\"mb-2 flex gap-1\">\n                                      {(['decisioning', 'correctness'] as const).map((pp) => (\n                                        <button key={pp}\n                                          onClick={() => setAssignPurpose(pp)}\n                                          className={`flex-1 rounded px-2 py-1 text-xs ${\n                                            assignPurpose === pp ? 'bg-brand-primary text-white' : 'bg-gray-100 text-gray-700'}`}>\n                                          {pp === 'decisioning' ? 'Decisioning' : 'Correctness check'}\n                                        </button>\n                                      ))}\n                                    </div>\n                                    <div className=\"mb-1 text-xs font-medium text-gray-500\">To</div>\n                                    <select\n                                      className=\"mb-2 w-full rounded border px-2 py-1 text-xs\"\n                                      defaultValue=\"\"\n                                      onChange={(e) => {\n                                        const a = analystPool.find((x) => x.staff_code === e.target.value);\n                                        if (a) { void doAssign(app.id, a.staff_code, a.name, assignPurpose); setAssignMenuFor(null); }\n                                      }}\n                                    >\n                                      <option value=\"\">\u2014 pick person \u2014</option>\n                                      {analystPool.map((a) => (\n                                        <option key={a.staff_code} value={a.staff_code}>{a.name}</option>\n                                      ))}\n                                    </select>\n                                    <div className=\"border-t border-gray-100 pt-2\">\n                                      <button\n                                        onClick={() => { setAssignMenuFor(null); navigate(`/lms/${encodeURIComponent(app.id)}`); }}\n                                        className=\"w-full rounded bg-gray-50 px-2 py-1 text-left text-xs text-gray-700 hover:bg-gray-100\"\n                                      >\n                                        Route to committee \u2192\n                                      </button>\n                                    </div>\n                                  </div>\n                                )}\n                              </>\n                            ) : (\n                              <span className=\"text-gray-300\">\u2014</span>\n                            )}\n                          </td>\n                        )}\n                      </tr>\n                    ))}\n                  </tbody>\n                </table>\n              </div>\n              <div className=\"flex items-center justify-between px-4 py-3 border-t border-gray-100 text-xs text-gray-500\">\n                <span>\n                  {filteredApps.length === 0 ? 'No applications' :\n                    `${safePage * PAGE_SIZE + 1}\u2013${Math.min((safePage + 1) * PAGE_SIZE, filteredApps.length)} of ${filteredApps.length}`}\n                  {statusFilter !== 'all' && ` (status: ${statusFilter})`}\n                  {searchTerm && ` (search: \"${searchTerm}\")`}\n                </span>\n                {pageCount > 1 && (\n                  <span className=\"inline-flex items-center gap-2\">\n                    <button type=\"button\" onClick={() => setPage(Math.max(0, safePage - 1))}\n                      disabled={safePage === 0}\n                      className=\"rounded border px-2 py-1 text-brand-primary disabled:opacity-40 hover:bg-gray-50\">Prev</button>\n                    <span>Page {safePage + 1} / {pageCount}</span>\n                    <button type=\"button\" onClick={() => setPage(Math.min(pageCount - 1, safePage + 1))}\n                      disabled={safePage >= pageCount - 1}\n                      className=\"rounded border px-2 py-1 text-brand-primary disabled:opacity-40 hover:bg-gray-50\">Next</button>\n                  </span>\n                )}\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n      </main>\n    </div>\n  );\n}\n",
 "frontend/web/src/pages/PipelineDealDetail.tsx": "// v10.511 Phase 4 Batch \u03b22 \u2014 PipelineDealDetail page.\n//\n// The single-deal view at /pipeline/:dealId. Shows full deal info plus\n// per-action inline panels gated by the \u03b17 permissions object:\n//   - Advance Stage panel    (when can_advance_stage)\n//   - Request Cancellation panel (when can_request_cancel)\n//\n// Future \u03b2-batches will add panels for Edit (\u03b23-or-later), Validate\n// (\u03b24), Approve Cancel (\u03b24). The pattern established here \u2014 one panel\n// per action, conditionally rendered by permission flag, inline form\n// rather than modal dialog \u2014 should scale to all of them.\n//\n// Why inline panels and not modal dialogs:\n//   - The v10.496 primitive set has no Dialog component\n//   - Inline panels are simpler and work on mobile without overlay logic\n//   - Two consumers is too few to know what a Dialog primitive should do\n//   - When a third consumer appears (\u03b23 Create with \u03b15 conflict UX),\n//     we'll see the pattern and can decide whether Dialog earns its keep\n//\n// Data fetching:\n//   This page is the FIRST consumer of GET /api/pipeline/deals/{id}.\n//   It fetches independently (not via PipelineProvider, which is the\n//   list provider). The fetch happens on mount and after each\n//   successful mutation. No Context Provider \u2014 the data is page-local.\n//\n// Routing back to list:\n//   On success of any mutation, we DON'T navigate away. The user\n//   sees the updated deal state on the same page, with the relevant\n//   action panel now closed (because the permission changed: e.g.\n//   after request_cancel, can_request_cancel becomes false). They\n//   navigate back to /pipeline when they want.\n\nimport { displayName } from \"../lib/names\";\nimport { useCallback, useEffect, useState } from 'react';\nimport { FacilitiesTable, facilitiesToPrintHtml } from '@/components/FacilitiesTable';\nimport { printDocument, escapeHtml } from '@/lib/print';\nimport { useNavigate, useParams, Link } from 'react-router-dom';\nimport { useBranding } from '@/hooks/useBranding';\nimport { usePipelineDealMutations } from '@/hooks/usePipelineDealMutations';\nimport { useToast } from '@/components/Toast';\nimport { fetchPipelineDealDetail, fetchCreditChecklist, fetchNextStep, type NextStep, getDealCr, saveDealCr, getDealCommitteeRecords, recordDealCommitteeDecision, castCommitteeVote, appealCommitteeDecision, closeDealAsLost, type CommitteeGate, type CommitteeRecordsResponse, type CrView, type CrField, submitDealToCredit, referExistingDeal, fetchDealSla, ApiValidationError, AuthExpiredError, listDealDocuments, uploadDealDocument, deleteDealDocument, createValidationRequest, resolveValidationRequest, liftDealHold, fetchDealJourney, type ValidationRequest, type StaffMember, type SlaViolation, type DealDocumentsResponse } from '@/lib/api';\nimport { Timeline } from '@/components/Timeline';\nimport type { LoanAppHistoryEvent } from '@/types/lms';\nimport { useRole } from '@/hooks/useRole';\nimport { Card } from '@/components/Card';\nimport { Badge } from '@/components/Badge';\nimport { Button } from '@/components/Button';\nimport { DocumentViewerModal } from '@/components/DocumentViewerModal';\nimport { Input } from '@/components/Input';\nimport { Skeleton } from '@/components/Skeleton';\nimport { WorkbenchShell } from '@/components/WorkbenchShell';\nimport { StaffPicker } from '@/components/StaffPicker';\nimport {\n  ADVANCE_TARGET_STAGES,\n  type PipelineDeal,\n  type DealPermissions,\n  type CreditChecklistResponse,\n} from '@/types/pipeline';\n\n\n// \u2500\u2500 Format helpers (mirroring Pipeline.tsx) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction formatValue(v: number | undefined, symbol: string): string {\n  const n = Number(v);\n  if (!Number.isFinite(n) || n === 0) return '\u2014';\n  return `${symbol} ${n.toLocaleString()}`;\n}\n\nfunction formatDate(s: string | undefined): string {\n  if (!s) return '\u2014';\n  // Backend sometimes returns ISO datetime, sometimes just date.\n  // Take the first 10 chars (YYYY-MM-DD) which works for either.\n  return s.slice(0, 10);\n}\n\n\n// \u2500\u2500 Detail page component \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport { AffordabilityAppraisal } from '@/components/AffordabilityAppraisal';\n\nexport function PipelineDealDetail() {\n  const { dealId } = useParams<{ dealId: string }>();\n  const navigate = useNavigate();\n  const { branding } = useBranding();\n  const { toast } = useToast();\n  const mutations = usePipelineDealMutations();\n\n  const [deal, setDeal] = useState<PipelineDeal | null>(null);\n  const [permissions, setPermissions] = useState<DealPermissions | null>(null);\n  const [sla, setSla] = useState<SlaViolation | null>(null);\n  const [stageFlow, setStageFlow] = useState<string[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [loadError, setLoadError] = useState<string | null>(null);\n  const { user: viewer } = useRole();\n\n  // \u2500\u2500 Fetch routine \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // Called on mount and after each successful mutation. Refreshes the\n  // deal + its permissions object (which may have shifted state).\n\n  const reloadDeal = useCallback(async () => {\n    if (!dealId) return;\n    setLoading(true);\n    setLoadError(null);\n    try {\n      const response = await fetchPipelineDealDetail(dealId);\n      setDeal(response.deal);\n      setPermissions(response.permissions);\n      setStageFlow(response.stage_flow ?? []);\n      // Per-deal SLA \u2014 non-blocking; failure leaves the panel hidden, not the page.\n      fetchDealSla(dealId).then((r) => setSla(r.sla)).catch(() => setSla(null));\n    } catch (e) {\n      if (e instanceof AuthExpiredError) {\n        // AuthProvider's 401 callback already flipped state; the route\n        // guard will redirect. Don't show our own error.\n        return;\n      }\n      const msg = e instanceof Error ? e.message : 'Failed to load deal';\n      setLoadError(msg);\n      setDeal(null);\n      setPermissions(null);\n    } finally {\n      setLoading(false);\n    }\n  }, [dealId]);\n\n  // Initial load + re-fetch when dealId changes\n  useEffect(() => {\n    void reloadDeal();\n  }, [reloadDeal]);\n\n  // \u2500\u2500 Render guard: deal id missing or 404 \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  if (!dealId) {\n    return (\n      <DetailFrame title=\"Deal\">\n        <Card className=\"mt-8\">\n          <Card.Body>\n            <Badge tone=\"danger\">Missing deal ID</Badge>\n            <p className=\"mt-2 text-sm text-gray-700\">\n              No deal ID in URL. <Link to=\"/pipeline\" className=\"text-brand-primary underline\">Back to pipeline</Link>.\n            </p>\n          </Card.Body>\n        </Card>\n      </DetailFrame>\n    );\n  }\n\n  if (loading && !deal) {\n    return (\n      <DetailFrame title={`Deal ${dealId}`}>\n        <Card className=\"mt-8\">\n          <Card.Body>\n            <Skeleton shape=\"line\" className=\"w-1/2\" />\n            <div className=\"mt-4\">\n              <Skeleton shape=\"block\" className=\"h-6 w-full\" />\n            </div>\n            <div className=\"mt-2\">\n              <Skeleton shape=\"block\" className=\"h-6 w-full\" />\n            </div>\n          </Card.Body>\n        </Card>\n      </DetailFrame>\n    );\n  }\n\n  if (loadError || !deal) {\n    return (\n      <DetailFrame title={`Deal ${dealId}`}>\n        <Card className=\"mt-8\">\n          <Card.Header>\n            <div className=\"flex items-center gap-3\">\n              <Badge tone=\"danger\">Not found</Badge>\n              <h2 className=\"text-base font-semibold text-gray-900\">\n                Deal {dealId} unavailable\n              </h2>\n            </div>\n            <Button variant=\"ghost\" size=\"sm\" onClick={() => navigate('/pipeline')}>\n              Back to pipeline\n            </Button>\n          </Card.Header>\n          <Card.Body>\n            <p className=\"text-sm text-gray-700\">\n              {loadError ?? 'This deal could not be loaded. It may be outside your cascade scope, or the deal ID may not exist.'}\n            </p>\n            <p className=\"text-xs text-gray-400 mt-3\">\n              The server returns 404 (not 403) for out-of-scope deals to avoid leaking deal existence \u2014 this is \u03b17 design.\n            </p>\n          </Card.Body>\n        </Card>\n      </DetailFrame>\n    );\n  }\n\n  // \u2500\u2500 Main render \u2014 deal + action panels \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // Document/credit-review edit rights: the deal OWNER always; admins/executives retain\n  // override rights, but every edit they make is audit-logged server-side (upload/CR/committee\n  // all call _audit with the actor). Everyone else is view-only.\n  // Edit override is restricted to the literal system Admin role (granted via config /\n  // role-capability), NOT senior bankers like Heads/Directors \u2014 they view-only on deals\n  // they don't own. Admin edits remain audit-logged server-side.\n  const _viewerIsAdmin = String(viewer?.role ?? '').trim().toLowerCase() === 'admin';\n  const canEditDocs = (!!viewer?.staff_code && String(viewer.staff_code) === String(deal.staff_code)) || _viewerIsAdmin;\n\n\n  return (\n    <DetailFrame title={`Deal ${deal.id}`}>\n      {/* Phase L: origination lock banner \u2014 the deal is with Credit and edits/\n          stage moves are disabled until it's returned or info is requested. */}\n      {deal.locked && (\n        <div className=\"mb-4 rounded-lg border border-amber-300 bg-amber-50 px-4 py-3\">\n          <div className=\"flex items-start gap-2\">\n            <span className=\"text-amber-600\" aria-hidden>\ud83d\udd12</span>\n            <div className=\"text-sm text-amber-800\">\n              <span className=\"font-semibold\">Locked \u2014 with Credit.</span>{' '}\n              {deal.lock_reason || 'Editing and stage changes are disabled until the case is returned for rework or information is requested.'}\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Cancellation-pending notice */}\n      {deal.cancel_requested && !deal.cancel_approved && (\n        <Card className=\"mb-4\" stripe=\"accent\">\n          <Card.Body>\n            <div className=\"flex items-start gap-3\">\n              <Badge tone=\"warning\" size=\"md\">Pending manager approval</Badge>\n              <div className=\"flex-1\">\n                <div className=\"text-sm text-gray-800\">\n                  This deal has a cancellation request awaiting manager review.\n                </div>\n                <div className=\"text-xs text-gray-600 mt-1\">\n                  <span className=\"font-medium\">Requested by:</span> {deal.cancel_requested_by || '\u2014'}\n                  {deal.cancel_reason && (\n                    <>\n                      {' \u00b7 '}\n                      <span className=\"font-medium\">Reason:</span> {deal.cancel_reason}\n                    </>\n                  )}\n                </div>\n              </div>\n            </div>\n          </Card.Body>\n        </Card>\n      )}\n\n      <WorkbenchShell\n        title={deal.client_name || '\u2014'}\n        stage={deal.stage}\n        badges={[\n          ...(deal.locked ? [{ label: '\ud83d\udd12 Locked' }] : []),\n          ...(deal.manager_validated ? [{ label: deal.validated_by_name ? `\u2713 Validated by ${deal.validated_by_name}` : '\u2713 Validated' }] : []),\n          ...(deal.draft ? [{ label: 'Draft' }] : []),\n        ]}\n        idLabel={deal.id}\n        onBack={() => navigate('/pipeline')}\n        onRefresh={() => void reloadDeal()}\n        details={sla && sla.state ? (\n          <Card stripe={sla.state === 'breached' ? 'accent' : 'primary'}>\n            <Card.Header>\n              <div className=\"flex items-center gap-3 flex-wrap\">\n                <h3 className=\"text-sm font-semibold text-gray-900\">SLA status</h3>\n                <Badge\n                  tone={sla.state === 'breached' ? 'danger' : sla.state === 'due_soon' ? 'warning' : 'success'}\n                  size=\"sm\"\n                >\n                  {sla.state === 'breached' ? 'Breached' : sla.state === 'due_soon' ? 'Due soon' : 'On track'}\n                </Badge>\n                <Badge tone={sla.clock === 'step' ? 'info' : 'neutral'} size=\"sm\">\n                  {sla.clock === 'step' ? (sla.step || 'step').replace(/_/g, ' ') : 'age clock'}\n                </Badge>\n                {sla.commitment_status === 'active' && (\n                  <Badge tone=\"info\" size=\"sm\">committed {sla.commitment?.committed_date}</Badge>\n                )}\n                {sla.commitment_status === 'unfulfilled' && (\n                  <Badge tone=\"danger\" size=\"sm\">commitment overdue</Badge>\n                )}\n              </div>\n            </Card.Header>\n            <Card.Body>\n              <div className=\"grid grid-cols-2 md:grid-cols-4 gap-4 text-sm\">\n                <DetailField label=\"Elapsed\" value={`${sla.elapsed_business_days} bd`} />\n                <DetailField label=\"Target\" value={`${sla.target_days} bd`} />\n                <DetailField\n                  label={sla.breached ? 'Overdue' : 'Remaining'}\n                  value={sla.breached ? `+${sla.overdue_business_days} bd` : `${sla.remaining_business_days ?? '\u2014'} bd`}\n                />\n                <DetailField label=\"Escalation\" value={(sla.escalate_to || '\u2014').replace(/_/g, ' ')} />\n              </div>\n              {sla.commitment && (\n                <p className=\"text-xs text-gray-500 mt-3\">\n                  <span className=\"font-medium\">Commitment:</span> {sla.commitment.reason}\n                  {' \u00b7 by '}{sla.commitment.committed_date}\n                  {sla.commitment.recorded_by_name ? ` (${sla.commitment.recorded_by_name})` : ''}\n                </p>\n              )}\n            </Card.Body>\n          </Card>\n        ) : undefined}\n        defaultTabId=\"journey\"\n        tabs={[\n          { id: 'journey', label: 'Case Journey', color: '#0082BB', content: <CaseJourneyTab deal={deal} /> },\n          { id: 'documents', label: 'Documentation and Credit Review', color: '#0097A7', content: <CreditSubmissionPanel deal={deal} onChanged={() => void reloadDeal()} stageFlow={stageFlow} canEdit={canEditDocs} /> },\n          { id: 'affordability', label: 'Affordability', color: '#00A65A', content: <AffordabilityAppraisal dealId={deal.id} /> },\n          { id: 'cr', label: 'Transaction Memo', color: '#7E57C2', content: <DealCreditReportCard dealId={deal.id} canEdit={canEditDocs} /> },\n          { id: 'committee', label: 'Branch Credit Committee', color: '#EF6C00', content: <CommitteeJourneyCard dealId={deal.id} canEdit={canEditDocs} /> },\n          { id: 'forwarding', label: 'Forwarding Memo', color: '#5C6BC0', content: <ForwardingMemoCard dealId={deal.id} canEdit={canEditDocs} /> },\n          { id: 'actions', label: 'Actions', color: '#C62828', content: (\n            <div className=\"space-y-6\">\n              {permissions?.can_advance_stage && (\n                <AdvancePanel\n                  deal={deal}\n                  mutations={mutations}\n                  stageFlow={stageFlow}\n                  onSuccess={() => {\n                    toast({ tone: 'success', message: 'Deal advanced.' });\n                    void reloadDeal();\n                  }}\n                />\n              )}\n              <ValidationPanel deal={deal} onChanged={() => void reloadDeal()} />\n              {!deal.draft && deal.referral_status !== 'pending' && (\n                <ReferPanel deal={deal} onSuccess={() => void reloadDeal()} />\n              )}\n              {permissions?.can_request_cancel && (\n                <RequestCancelPanel\n                  deal={deal}\n                  mutations={mutations}\n                  onSuccess={() => {\n                    toast({\n                      tone: 'success',\n                      message: 'Cancellation requested. A manager will review it.',\n                    });\n                    void reloadDeal();\n                  }}\n                />\n              )}\n            </div>\n          ) },\n        ]}\n      />\n\n      {/* Footer */}\n      <footer className=\"mt-12 pb-6 text-center text-[11px] text-gray-400 leading-relaxed\">\n        {branding?.ip_notice}\n      </footer>\n    </DetailFrame>\n  );\n}\n\n\n// \u2500\u2500 Frame component (shared header + main wrap) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface DetailFrameProps {\n  title:    string;\n  children: React.ReactNode;\n}\n\nfunction DetailFrame({ title, children }: DetailFrameProps) {\n  useEffect(() => { document.title = title; }, [title]);\n  return (\n    <div className=\"min-h-screen bg-gray-50\">\n      <main className=\"max-w-7xl 2xl:max-w-[1680px] mx-auto px-6 pt-3 pb-6\">\n        {children}\n      </main>\n    </div>\n  );\n}\n\n\n// \u2500\u2500 Detail field (label + value cell) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction DetailField({\n  label, value, sub,\n}: { label: string; value: React.ReactNode; sub?: React.ReactNode }) {\n  return (\n    <div>\n      <div className=\"text-[11px] font-semibold uppercase tracking-wider text-gray-500\">\n        {label}\n      </div>\n      <div className=\"mt-1 text-sm text-gray-900\">\n        {value ?? '\u2014'}\n      </div>\n      {sub && (\n        <div className=\"text-[11px] text-gray-400 mt-0.5 font-mono\">{sub}</div>\n      )}\n    </div>\n  );\n}\n\n\n// \u2500\u2500 Action panel: Submit to Credit Analysis (v10.574 Batch B10) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface CreditPanelProps {\n  deal:      PipelineDeal;\n  onChanged: () => void;\n}\n\n// Phase V/R: line-manager validation. Shows validation requests; lets the deal\n// owner request a reopen of a declined case; lets the resolved line manager\n// (or admin) approve/reject. Approval of a reopen returns the case for rework.\nfunction CaseJourneyTab({ deal }: { deal: PipelineDeal }) {\n  const [events, setEvents] = useState<LoanAppHistoryEvent[]>([]);\n  const [loading, setLoading] = useState(true);\n  const dealId = deal.id;\n  const load = useCallback(() => {\n    setLoading(true);\n    return fetchDealJourney(dealId)\n      .then((r) => setEvents(r.journey || []))\n      .catch(() => setEvents([]))\n      .finally(() => setLoading(false));\n  }, [dealId]);\n  // Re-fetch on deal change (parent reloadDeal after any action) so the journey\n  // stays live as the case travels \u2014 validation, votes, stage moves, submission.\n  useEffect(() => {\n    let alive = true;\n    setLoading(true);\n    fetchDealJourney(dealId)\n      .then((r) => { if (alive) setEvents(r.journey || []); })\n      .catch(() => { if (alive) setEvents([]); })\n      .finally(() => { if (alive) setLoading(false); });\n    return () => { alive = false; };\n  }, [dealId, deal.updated_at]);\n\n  const facts: [string, string, boolean][] = [\n    ['Product', String(deal.product_type ?? deal.product ?? '\u2014'), false],\n    ['Category', String(deal.pipeline_category ?? deal.deal_category ?? '\u2014'), false],\n    ['Client type', String(deal.client_type ?? '\u2014'), false],\n    ['Value', formatValue(deal.amount_kes ?? deal.deal_value, deal.currency ?? 'KES'), false],\n    ['Currency', String(deal.currency ?? 'KES'), false],\n    ['Stage', String(deal.stage ?? '\u2014'), false],\n    ['Expected close', deal.expected_close ? formatDate(deal.expected_close) : '\u2014', false],\n    ['Owner', deal.staff_name ? displayName(deal.staff_name) : '\u2014', false],\n    ['Deal', String(deal.id), true],\n  ];\n\n  return (\n    <Card stripe=\"primary\">\n      <Card.Header>\n        <div className=\"flex w-full items-center justify-between\">\n          <h3 className=\"text-sm font-semibold text-gray-900\">Case Journey</h3>\n          <div className=\"flex items-center gap-3\">\n            <span className=\"text-xs text-gray-400\">{events.length} events \u00b7 who did what, when</span>\n            <button onClick={() => void load()} className=\"text-xs font-medium text-brand-primary hover:underline\">Refresh</button>\n          </div>\n        </div>\n      </Card.Header>\n      <Card.Body>\n        {/* Executive summary \u2014 key deal facts folded into the journey, mirroring\n            the LMS analysis Case Journey. One place to read the case: the facts,\n            then the travelling history. */}\n        <div className=\"mb-4 flex flex-wrap gap-x-6 gap-y-1.5 border-b border-gray-100 pb-3 text-xs\">\n          {facts.map(([label, value, mono]) => (\n            <span key={label} className=\"flex items-center gap-1.5\">\n              <span className=\"uppercase tracking-wide text-gray-400\">{label}</span>\n              <span className={mono ? 'font-mono text-gray-800' : 'text-gray-800'}>{value}</span>\n            </span>\n          ))}\n        </div>\n        {loading ? (\n          <p className=\"text-sm text-gray-400\">Loading\u2026</p>\n        ) : (\n          <Timeline events={events} emptyHint=\"No activity recorded yet. Creation, manager validation, stage moves, committee votes, and submission appear here as the case travels.\" />\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n\n\nfunction ValidationPanel({ deal, onChanged }: CreditPanelProps) {\n  const { toast } = useToast();\n  const { user } = useRole();\n  const [reason, setReason] = useState('');\n  const [holdReason, setHoldReason] = useState('');\n  const [notes, setNotes] = useState<Record<string, string>>({});\n  const [busy, setBusy] = useState(false);\n  const requests = deal.validation_requests ?? [];\n  const pending = requests.filter((r) => r.status === 'pending');\n  const myCode = String(user?.staff_code ?? '');\n  const isAdmin = Boolean(user?.role && /admin/i.test(user.role));\n  const iAmDealValidator = !!myCode && myCode === String(deal.validator?.code ?? '');\n\n  const request = async () => {\n    if (!reason.trim()) { toast({ tone: 'danger', message: 'A reason is required.' }); return; }\n    setBusy(true);\n    try {\n      await createValidationRequest(deal.id, 'reopen', reason.trim());\n      toast({ tone: 'success', message: 'Reopen request sent to the line manager for validation.' });\n      setReason(''); onChanged();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not send request.' });\n    } finally { setBusy(false); }\n  };\n\n  const requestHold = async () => {\n    if (!holdReason.trim()) { toast({ tone: 'danger', message: 'A reason is required.' }); return; }\n    setBusy(true);\n    try {\n      await createValidationRequest(deal.id, 'hold', holdReason.trim());\n      toast({ tone: 'success', message: 'Hold request sent to the line manager for validation.' });\n      setHoldReason(''); onChanged();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not send request.' });\n    } finally { setBusy(false); }\n  };\n\n  const liftHold = async () => {\n    setBusy(true);\n    try {\n      await liftDealHold(deal.id, 'Hold lifted; clocks resumed.');\n      toast({ tone: 'success', message: 'Hold lifted \u2014 clocks resumed.' });\n      onChanged();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not lift hold.' });\n    } finally { setBusy(false); }\n  };\n\n  const resolve = async (req: ValidationRequest, decision: 'approved' | 'rejected') => {\n    setBusy(true);\n    try {\n      await resolveValidationRequest(deal.id, req.id, decision, (notes[req.id] ?? '').trim());\n      toast({ tone: 'success', message: decision === 'approved' ? 'Request approved.' : 'Request rejected.' });\n      onChanged();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not resolve request.' });\n    } finally { setBusy(false); }\n  };\n\n  // Nothing to show unless a reopen/hold can be requested, it's on hold, or there are requests.\n  if (!deal.reopen_available && !deal.hold_available && !deal.on_hold && requests.length === 0) return null;\n\n  return (\n    <Card>\n      <Card.Header>\n        <h2 className=\"text-base font-semibold text-gray-900\">Line-manager validation</h2>\n      </Card.Header>\n      <Card.Body>\n        {deal.on_hold && (\n          <div className=\"mb-4 rounded-lg border border-orange-300 bg-orange-50 p-3\">\n            <div className=\"flex items-center justify-between gap-2\">\n              <span className=\"text-sm font-semibold text-orange-900\">\u23f8 On hold \u2014 SLA clocks frozen</span>\n              {(iAmDealValidator || isAdmin) && (\n                <Button variant=\"primary\" onClick={() => void liftHold()} disabled={busy}>Lift hold</Button>\n              )}\n            </div>\n            {deal.hold_reason ? <p className=\"mt-1 text-sm text-gray-700\">{deal.hold_reason}</p> : null}\n            {!(iAmDealValidator || isAdmin) && (\n              <p className=\"mt-1 text-xs text-orange-700\">Only the line manager can lift this hold.</p>\n            )}\n          </div>\n        )}\n\n        {deal.hold_available && (\n          <div className=\"mb-4 rounded-lg border border-gray-200 p-3\">\n            <p className=\"mb-2 text-sm text-gray-700\">\n              Put this case on hold \u2014 this freezes all SLA clocks until lifted. Your line\n              manager{deal.validator?.name ? ` (${displayName(deal.validator.name)})` : ''} must validate the request.\n            </p>\n            <Input value={holdReason} onChange={(e) => setHoldReason(e.target.value)}\n              placeholder=\"Reason for placing on hold (required)\" />\n            <div className=\"mt-2\">\n              <Button variant=\"ghost\" onClick={() => void requestHold()} disabled={busy || !holdReason.trim()}>\n                Request hold\n              </Button>\n            </div>\n          </div>\n        )}\n\n        {deal.reopen_available && (\n          <div className=\"mb-4 rounded-lg border border-gray-200 p-3\">\n            <p className=\"mb-2 text-sm text-gray-700\">\n              This case was declined. You can request to reopen it for rework \u2014 your{' '}\n              line manager{deal.validator?.name ? ` (${displayName(deal.validator.name)})` : ''} must validate the request.\n            </p>\n            <Input value={reason} onChange={(e) => setReason(e.target.value)}\n              placeholder=\"Reason for reopening (required)\" />\n            <div className=\"mt-2\">\n              <Button variant=\"primary\" onClick={() => void request()} disabled={busy || !reason.trim()}>\n                Request reopen\n              </Button>\n            </div>\n          </div>\n        )}\n\n        {pending.length > 0 && (\n          <div className=\"space-y-3\">\n            {pending.map((r) => {\n              const iAmValidator = !!myCode && myCode === String(r.validator_code ?? '');\n              return (\n                <div key={r.id} className=\"rounded-lg border border-amber-200 bg-amber-50 p-3\">\n                  <div className=\"flex items-center justify-between gap-2\">\n                    <span className=\"text-sm font-medium text-amber-900 capitalize\">{r.kind} request \u2014 pending</span>\n                    <span className=\"text-xs text-amber-700\">\n                      to validate: {r.validator_name || '\u2014'}{r.admin_fallback ? ' (admin fallback)' : ''}\n                    </span>\n                  </div>\n                  <p className=\"mt-1 text-sm text-gray-700\">\n                    <span className=\"text-gray-500\">Reason:</span> {r.reason || '\u2014'}\n                    {r.requested_by_name ? <span className=\"text-gray-500\"> \u00b7 by {r.requested_by_name}</span> : null}\n                  </p>\n                  {(iAmValidator || isAdmin) ? (\n                    <div className=\"mt-2\">\n                      <Input value={notes[r.id] ?? ''} onChange={(e) => setNotes({ ...notes, [r.id]: e.target.value })}\n                        placeholder=\"Validation note (optional)\" />\n                      <div className=\"mt-2 flex gap-2\">\n                        <Button variant=\"primary\" onClick={() => void resolve(r, 'approved')} disabled={busy}>Approve</Button>\n                        <Button variant=\"ghost\" onClick={() => void resolve(r, 'rejected')} disabled={busy}>Reject</Button>\n                      </div>\n                    </div>\n                  ) : (\n                    <p className=\"mt-2 text-xs text-gray-400\">Awaiting validation by the line manager.</p>\n                  )}\n                </div>\n              );\n            })}\n          </div>\n        )}\n\n        {requests.filter((r) => r.status !== 'pending').length > 0 && (\n          <div className=\"mt-4 space-y-1\">\n            <p className=\"text-xs font-medium text-gray-500\">History</p>\n            {requests.filter((r) => r.status !== 'pending').map((r) => (\n              <p key={r.id} className=\"text-xs text-gray-500\">\n                <span className=\"capitalize\">{r.kind}</span> \u00b7 {r.status}\n                {r.validated_by_name ? ` by ${r.validated_by_name}` : ''}\n                {r.note ? ` \u2014 ${r.note}` : ''}\n              </p>\n            ))}\n          </div>\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n\n// \u2500\u2500 Credit Journey stepper: the credit stages in order, active one highlighted,\n// future ones greyed. Reads checklist state (backend already enforces the sequence). \u2500\u2500\nfunction creditSubmitLabel(checklist: CreditChecklistResponse, stageFlow?: string[]): string {\n  const current = String(checklist.current_stage ?? '');\n  // Only name CREDIT-JOURNEY stages (Documentation..Credit Analysis), never sales stages\n  // like Negotiation. Slice the deal's flow to its credit portion first.\n  const full = (stageFlow && stageFlow.length) ? stageFlow : CREDIT_JOURNEY_STAGES;\n  const d = full.findIndex((st) => /documentation/i.test(st));\n  const c = full.findIndex((st) => /^credit analysis$/i.test(st.trim()));\n  const journey = (d >= 0 && c >= 0 && c >= d) ? full.slice(d, c + 1) : CREDIT_JOURNEY_STAGES;\n  const idx = journey.findIndex((st) => st.toLowerCase() === current.toLowerCase());\n  // If current is before/at the doc gate, submit enters the first gate after Documentation.\n  const next =\n    idx >= 0 && idx + 1 < journey.length ? journey[idx + 1]\n    : idx < 0 && journey.length > 1 ? journey[1]\n    : 'Credit Analysis';\n  return `Submit to ${next}`;\n}\n\nconst CREDIT_JOURNEY_STAGES = [\n  'Documentation',\n  'Branch Credit Committee Review',\n  'Consumer Credit Analysis',\n  'Department Credit Committee Review',\n  'Credit Analysis',\n];\n\nfunction CreditJourneyStepper({ checklist, stageFlow }: { checklist: CreditChecklistResponse; stageFlow?: string[] }) {\n  const current = String(checklist.current_stage ?? '');\n  const submitted = Boolean(checklist.already_submitted);\n  const journeyStages = (() => {\n    const f = stageFlow ?? [];\n    const d = f.findIndex((st) => /documentation/i.test(st));\n    const c = f.findIndex((st) => /^credit analysis$/i.test(st.trim()));\n    return (d >= 0 && c >= 0 && c >= d) ? f.slice(d, c + 1) : CREDIT_JOURNEY_STAGES;\n  })();\n  const currentIdx = journeyStages.findIndex(\n    (st) => st.toLowerCase() === current.toLowerCase(),\n  );\n  const activeIdx = currentIdx >= 0 ? currentIdx : 0;\n\n  return (\n    <div className=\"mb-4 rounded-md border border-gray-200 bg-gray-50 px-3 py-3\">\n      <div className=\"mb-3 text-xs font-semibold uppercase tracking-wide text-gray-500\">\n        Credit journey\n      </div>\n      <div className=\"flex items-start\">\n        {journeyStages.map((stage, i) => {\n          const isDone = i < activeIdx;\n          const isActive = i === activeIdx;\n          const isAwaiting = isActive && submitted;\n          let markCls = 'border-gray-300 text-gray-400 bg-white';\n          let labelCls = 'text-gray-400';\n          let mark = String(i + 1);\n          if (isDone) { markCls = 'border-[#669438] bg-[#669438] text-white'; labelCls = 'text-[#669438]'; mark = '\u2713'; }\n          else if (isAwaiting) { markCls = 'border-amber-500 text-amber-600 bg-white'; labelCls = 'text-amber-600 font-medium'; }\n          else if (isActive) { markCls = 'border-[#0082BB] bg-[#0082BB] text-white'; labelCls = 'text-[#0082BB] font-semibold'; }\n          return (\n            <div key={stage} className=\"flex flex-1 flex-col items-center text-center\">\n              <div className=\"flex w-full items-center\">\n                <div className={`h-0.5 flex-1 ${i === 0 ? 'bg-transparent' : isDone || isActive ? 'bg-[#0082BB]' : 'bg-gray-200'}`} />\n                <div className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border text-xs ${markCls}`}>\n                  {mark}\n                </div>\n                <div className={`h-0.5 flex-1 ${i === journeyStages.length - 1 ? 'bg-transparent' : isDone ? 'bg-[#0082BB]' : 'bg-gray-200'}`} />\n              </div>\n              <div className={`mt-1 px-1 text-[11px] leading-tight ${labelCls}`}>\n                {stage}\n                {isActive && !submitted && <div className=\"text-[10px] text-gray-400\">current step</div>}\n                {isAwaiting && <div className=\"text-[10px] text-amber-500\">awaiting decision</div>}\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n\nfunction CreditSubmissionPanel({ deal, onChanged, stageFlow, canEdit = true }: CreditPanelProps & { stageFlow?: string[]; canEdit?: boolean }) {\n  const { toast } = useToast();\n  const [checklist,  setChecklist]  = useState<CreditChecklistResponse | null>(null);\n  // What the next stage actually is, and who owes which document. Fetched\n  // rather than assumed - the flow is config-driven and per product, so the\n  // page cannot know it without asking.\n  const [nextStep, setNextStep] = useState<NextStep | null>(null);\n  const [submitting, setSubmitting] = useState(false);\n  const [error,      setError]      = useState<string | null>(null);\n  const [docFiles,   setDocFiles]   = useState<Record<string, DealDocumentsResponse['files'][string]>>({});\n  const [busyDoc,    setBusyDoc]    = useState<string | null>(null);\n  const [otherLabel, setOtherLabel] = useState('');\n  const [viewing,    setViewing]    = useState<{ docName: string; filename: string } | null>(null);\n  const OTHER_PREFIX = 'Other: ';\n\n  const reloadDocs = () => {\n    listDealDocuments(deal.id)\n      .then((d) => setDocFiles(d.files || {}))\n      .catch(() => { /* leave as-is */ });\n  };\n  useEffect(() => { reloadDocs(); /* eslint-disable-next-line */ }, [deal.id]);\n\n  const uploadFor = (doc: string) => {\n    const inp = document.createElement('input');\n    inp.type = 'file';\n    inp.onchange = async () => {\n      const f = inp.files?.[0];\n      if (!f) return;\n      setBusyDoc(doc); setError(null);\n      try {\n        const buf = await f.arrayBuffer();\n        let bin = '';\n        const bytes = new Uint8Array(buf);\n        for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);\n        await uploadDealDocument(deal.id, doc, f.name, btoa(bin));\n        reloadDocs();\n      } catch (e) {\n        setError(e instanceof Error ? e.message : 'Upload failed');\n      } finally {\n        setBusyDoc(null);\n      }\n    };\n    inp.click();\n  };\n\n  const viewDoc = (doc: string) => {\n    const meta = docFiles[doc];\n    setViewing({ docName: doc, filename: meta?.filename || doc });\n  };\n\n  const removeDoc = async (doc: string) => {\n    setBusyDoc(doc);\n    try {\n      await deleteDealDocument(deal.id, doc);\n      reloadDocs();\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Remove failed');\n    } finally {\n      setBusyDoc(null);\n    }\n  };\n\n  useEffect(() => {\n    let alive = true;\n    void fetchNextStep(deal.id).then((n) => { if (alive) setNextStep(n); })\n      .catch(() => { /* label falls back to \"Submit to next stage\" */ });\n    fetchCreditChecklist(deal.id)\n      .then((c) => {\n        if (!alive) return;\n        setChecklist(c);\n      })\n      .catch(() => { /* checklist unavailable \u2014 panel stays hidden */ });\n    return () => { alive = false; };\n  }, [deal.id]);\n\n  if (!checklist) return null;\n\n  // Credit can return a deal (returned / info_requested). Phase L unlocks the\n  // deal on those, so `already_submitted && !locked` means it's back with the\n  // RM for more documents. Keep the upload form available so they can supply\n  // documents until credit has everything, then resubmit.\n  const reopenedForDocs = Boolean(checklist.already_submitted) && !deal.locked;\n\n  // Already submitted and still locked \u2014 show the cross-link, no form.\n  if (checklist.already_submitted && !reopenedForDocs) {\n    return (\n      <Card className=\"mt-6\" stripe=\"accent\">\n        <Card.Header>\n          <h3 className=\"text-sm font-semibold text-gray-900\">Credit analysis</h3>\n          <Badge tone=\"success\" size=\"sm\">Submitted</Badge>\n        </Card.Header>\n        <Card.Body>\n          <CreditJourneyStepper checklist={checklist} stageFlow={stageFlow} />\n          <p className=\"text-sm text-gray-700\">\n            This deal has been submitted to credit analysis. The case is now with\n            Credit; you can follow its progress in the Case Journey.\n          </p>\n        </Card.Body>\n      </Card>\n    );\n  }\n\n  // Gate reasons that block the FINAL submit. Shown as a soft banner in the\n  // upload UI below \u2014 they no longer hide the document upload. The CR\n  // prerequisite is intentionally NOT listed here: the RM completes the CR on\n  // its own tab, so surfacing it on the Documents tab is noise.\n  const gateReasons: string[] = [];\n  if (checklist.manager_validated === false) {\n    gateReasons.push('This deal has not been validated by a manager. A manager must validate it (from their Manager Queue) before it can be submitted to credit.');\n  }\n  if (checklist.stage_ok === false && checklist.stage_required) {\n    gateReasons.push(`Deal must be at stage \"${checklist.stage_required}\"${checklist.current_stage ? ` (currently \"${checklist.current_stage}\")` : ''}.`);\n  }\n  if ((checklist.committee_rejected ?? []).length > 0) {\n    gateReasons.push(`Committee rejected: ${(checklist.committee_rejected ?? []).join(', ')}. The deal returns to the owner (appeal or close).`);\n  }\n  if ((checklist.committee_pending ?? []).length > 0) {\n    gateReasons.push(`Committee decision outstanding: ${(checklist.committee_pending ?? []).join(', ')}.`);\n  }\n\n  // Hide the panel only when there is genuinely nothing for this viewer to do:\n  // can't submit, no gates, no required documents and no CR path (e.g. a\n  // non-owner, or a deal with no credit journey). Otherwise fall through and\n  // show the upload UI so the owner can attach documents even before the deal\n  // is submit-ready.\n  if (!checklist.can_submit && gateReasons.length === 0\n      && checklist.required.length === 0 && !checklist.cr_required) {\n    return null;\n  }\n\n  const missing = checklist.required.filter((d) => !docFiles[d]);\n\n  const onSubmit = async () => {\n    setSubmitting(true);\n    setError(null);\n    try {\n      const res = await submitDealToCredit(deal.id, checklist.required.filter((d) => docFiles[d]));\n      toast({\n        tone: 'success',\n        message: `\u2713 Submitted to credit \u2014 application ${res.application_id}.`,\n      });\n      onChanged();\n    } catch (e) {\n      if (e instanceof ApiValidationError) setError(e.detail);\n      else if (e instanceof AuthExpiredError) { /* handled globally */ }\n      else setError('Submission failed. Please try again.');\n    } finally {\n      setSubmitting(false);\n    }\n  };\n\n  return (\n    <Card className=\"mt-6\" stripe=\"accent\">\n      <Card.Header>\n        <CreditJourneyStepper checklist={checklist} stageFlow={stageFlow} />\n        <h3 className=\"text-sm font-semibold text-gray-900\">{creditSubmitLabel(checklist, stageFlow)}</h3>\n        <Badge tone=\"info\" size=\"sm\">document gate</Badge>\n      </Card.Header>\n      <Card.Body>\n        {reopenedForDocs && (\n          <div className=\"mb-3 rounded border border-amber-200 bg-amber-50 p-2 text-sm text-amber-800\">\n            Credit returned this deal for more information. Supply the outstanding documents below, then resubmit.\n          </div>\n        )}\n        {gateReasons.length > 0 && (\n          <div className=\"mb-3 rounded border border-amber-200 bg-amber-50 p-2 text-sm text-amber-800\">\n            <div className=\"font-medium\">Submission is blocked until:</div>\n            <ul className=\"list-disc pl-5\">\n              {gateReasons.map((r, i) => <li key={i}>{r}</li>)}\n            </ul>\n          </div>\n        )}\n        <p className=\"text-xs text-gray-500 mb-3\">\n          {canEdit\n            ? 'Upload each required document. All required documents must be attached before the deal can be submitted to credit analysis.'\n            : 'Documents for this deal (managed by the owner). You have view access \u2014 open any attached document below.'}\n        </p>\n        <div className=\"space-y-2\">\n          {checklist.required.map((doc) => {\n            const attached = docFiles[doc];\n            return (\n              <div key={doc} className=\"flex items-center justify-between gap-2 rounded border p-2 text-sm\">\n                <div className=\"flex items-center gap-2\">\n                  <span className={attached ? 'text-green-700' : 'text-gray-800'}>\n                    {attached ? '\u2713' : '\u25cb'} {doc}\n                  </span>\n                  {attached && (\n                    <span className=\"text-xs text-gray-500\">{attached.filename}</span>\n                  )}\n                </div>\n                <div className=\"flex items-center gap-2\">\n                  {attached && (\n                    <button type=\"button\" className=\"text-brand-primary hover:underline text-xs\"\n                      onClick={() => void viewDoc(doc)}>View</button>\n                  )}\n                  {canEdit && (\n                    <button type=\"button\" className=\"text-brand-primary hover:underline text-xs\"\n                      onClick={() => uploadFor(doc)} disabled={busyDoc === doc}>\n                      {busyDoc === doc ? 'Uploading\u2026' : attached ? 'Replace' : 'Upload'}\n                    </button>\n                  )}\n                  {canEdit && attached && (\n                    <button type=\"button\" className=\"text-red-600 hover:underline text-xs\"\n                      onClick={() => void removeDoc(doc)} disabled={busyDoc === doc}>Remove</button>\n                  )}\n                </div>\n              </div>\n            );\n          })}\n        </div>\n        {/* BO1: attached ad-hoc \"Other\" documents */}\n        {Object.keys(docFiles).filter((k) => k.startsWith(OTHER_PREFIX)).length > 0 && (\n          <div className=\"mt-3 space-y-2\">\n            <p className=\"text-xs font-medium text-gray-600\">Other documents</p>\n            {Object.keys(docFiles).filter((k) => k.startsWith(OTHER_PREFIX)).map((k) => (\n              <div key={k} className=\"flex items-center justify-between gap-2 rounded border p-2 text-sm\">\n                <span className=\"text-green-700\">\u2713 {k.slice(OTHER_PREFIX.length)}</span>\n                <div className=\"flex items-center gap-2\">\n                  <button type=\"button\" className=\"text-brand-primary hover:underline text-xs\"\n                    onClick={() => void viewDoc(k)}>View</button>\n                  {canEdit && (\n                    <button type=\"button\" className=\"text-red-600 hover:underline text-xs\"\n                      onClick={() => void removeDoc(k)} disabled={busyDoc === k}>Remove</button>\n                  )}\n                </div>\n              </div>\n            ))}\n          </div>\n        )}\n        {/* BO1: add an ad-hoc \"Other\" document */}\n        {canEdit && <div className=\"mt-3 flex items-center gap-2\">\n          <input\n            type=\"text\"\n            className=\"flex-1 rounded border px-2 py-1.5 text-sm\"\n            placeholder=\"Other (describe) \u2014 e.g. board resolution, extra KYC\u2026\"\n            value={otherLabel}\n            onChange={(e) => setOtherLabel(e.target.value)}\n          />\n          <button\n            type=\"button\"\n            className=\"rounded border px-3 py-1.5 text-sm text-brand-primary hover:bg-gray-50 disabled:opacity-50\"\n            disabled={!otherLabel.trim() || busyDoc !== null}\n            onClick={() => { const label = otherLabel.trim(); if (label) { uploadFor(OTHER_PREFIX + label); setOtherLabel(''); } }}\n          >\n            Attach other\n          </button>\n        </div>}\n        {error && <div className=\"mt-3 text-sm text-red-600\">{error}</div>}\n        {!error && missing.length > 0 && (\n          <div className=\"mt-3 text-xs text-amber-600\">\n            {missing.length} document{missing.length === 1 ? '' : 's'} still required.\n          </div>\n        )}\n        {canEdit ? (\n          <div className=\"mt-4 flex items-center justify-end gap-3\">\n            {!checklist.can_submit && (\n              <span className=\"text-xs text-gray-500\">Submission opens once all prerequisites are complete.</span>\n            )}\n            {/* THE BUTTON NAMES THE REAL DESTINATION (ruling 2026-08-12). The\n                advance was always right - one stage, config-driven - but the\n                label named a step three transitions away, which teaches people\n                the wrong shape of their own process.\n\n                And it is no longer disabled by outstanding paperwork: only\n                MANDATORY documents block now, so the deal can move while the\n                rest is still being gathered. */}\n            <Button\n              onClick={() => void onSubmit()}\n              loading={submitting}\n              disabled={(nextStep?.blocking?.length ?? 0) > 0 || !checklist.can_submit}\n            >\n              {nextStep?.submit_label ?? 'Submit to next stage'}\n            </Button>\n          </div>\n        ) : (\n          <div className=\"mt-4 text-xs text-gray-400\">Submission is managed by the deal owner.</div>\n        )}\n        {viewing && (\n          <DocumentViewerModal\n            dealId={deal.id}\n            docName={viewing.docName}\n            filename={viewing.filename}\n            canDownload\n            onClose={() => setViewing(null)}\n          />\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n\n\n// \u2500\u2500 Action panel: Advance Stage \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n/**\n * Shared props for action panels (Advance + RequestCancel).\n *\n * \u03b41 (2026-06-12): onSuccess accepts an optional meta arg. Advance\n * passes { targetStage } so the parent can render a stage-aware toast\n * (e.g. \"Loan application created\" when targetStage was 'Compliance').\n * RequestCancelPanel calls onSuccess() with no args \u2014 backward-compatible\n * because the meta arg is optional.\n */\ninterface ActionPanelProps {\n  deal:      PipelineDeal;\n  mutations: ReturnType<typeof usePipelineDealMutations>;\n  onSuccess: (meta?: { targetStage?: string }) => void;\n  /** This deal's product-class stage flow (B17). When present, the advance\n   *  dropdown follows it instead of the flat ADVANCE_TARGET_STAGES list. */\n  stageFlow?: string[];\n}\n\nfunction AdvancePanel({ deal, mutations, onSuccess, stageFlow }: ActionPanelProps) {\n  // B17: follow this deal's product-class flow (loan vs deposit vs \u2026) from the\n  // detail response; fall back to the flat list only if config didn't load.\n  const stages = stageFlow && stageFlow.length > 0 ? stageFlow : ADVANCE_TARGET_STAGES;\n  // Default to the next plausible stage if current is in the flow.\n  const currentIndex = stages.indexOf(deal.stage);\n  const defaultTarget = currentIndex >= 0 && currentIndex < stages.length - 1\n    ? stages[currentIndex + 1]\n    : stages[0];\n\n  const [targetStage, setTargetStage] = useState<string>(defaultTarget);\n  const [note,        setNote]        = useState('');\n  const [error,       setError]       = useState<string | null>(null);\n\n  const onSubmit = async () => {\n    setError(null);\n    const result = await mutations.advance(deal.id, {\n      target_stage: targetStage,\n      note: note.trim() || undefined,\n    });\n    if (result.ok) {\n      onSuccess({ targetStage });\n      setNote('');\n    } else {\n      setError(result.error);\n    }\n  };\n\n  // v10.588: lock manual advance at the credit-assessment gate. The stage only\n  // progresses via the document-gated \"Submit to Credit Analysis\" panel below\n  // (which the backend blocks until every required document is attached). Once\n  // submitted (the deal carries an lms_application_id), this unlocks.\n  const isCreditGate = /credit/i.test(deal.stage) && /(assess|analys)/i.test(deal.stage);\n  const submittedToCredit = !!deal.lms_application_id;\n  if (isCreditGate && !submittedToCredit) {\n    return (\n      <Card className=\"mt-6\" stripe=\"secondary\">\n        <Card.Header>\n          <h3 className=\"text-sm font-semibold text-gray-900\">Advance stage</h3>\n          <Badge tone=\"warning\" size=\"sm\">locked at Credit Assessment</Badge>\n        </Card.Header>\n        <Card.Body>\n          <p className=\"text-sm text-gray-600\">\n            This deal is at <span className=\"font-medium\">{deal.stage}</span>. The stage can&apos;t be\n            advanced manually from here \u2014 complete the document checklist and use the{' '}\n            <span className=\"font-medium\">Submit to Credit Analysis</span> panel below. Submission is\n            blocked until every required document is attached, and it moves the deal forward\n            automatically once it succeeds.\n          </p>\n        </Card.Body>\n      </Card>\n    );\n  }\n\n  return (\n    <Card className=\"mt-6\" stripe=\"primary\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">Advance stage</h3>\n        <Badge tone=\"info\" size=\"sm\">can_advance_stage</Badge>\n      </Card.Header>\n      <Card.Body>\n        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n          <div>\n            <label className=\"text-sm font-medium text-gray-700\">\n              Target stage\n            </label>\n            <select\n              value={targetStage}\n              onChange={(e) => setTargetStage(e.target.value)}\n              disabled={mutations.loading}\n              className=\"mt-1 w-full h-10 px-3 rounded-md border border-gray-300 bg-white text-base text-gray-900 focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n            >\n              {stages.map((s) => (\n                <option key={s} value={s} disabled={s === deal.stage}>\n                  {s}{s === deal.stage ? ' (current)' : ''}\n                </option>\n              ))}\n            </select>\n            <p className=\"text-xs text-gray-500 mt-1\">\n              Current: {deal.stage}. Server validates the transition.\n            </p>\n          </div>\n          <Input\n            label=\"Note (optional)\"\n            placeholder=\"Context for the change\"\n            value={note}\n            onChange={(e) => setNote(e.target.value)}\n            disabled={mutations.loading}\n            helper=\"Recorded on the deal's audit trail.\"\n          />\n        </div>\n        {error && (\n          <div className=\"mt-4 px-3 py-2 rounded-md bg-red-50 border border-red-200 text-sm text-red-800\">\n            {error}\n          </div>\n        )}\n      </Card.Body>\n      <Card.Footer>\n        <Button\n          variant=\"primary\"\n          size=\"md\"\n          onClick={() => void onSubmit()}\n          loading={mutations.loading}\n          disabled={!targetStage || targetStage === deal.stage}\n        >\n          Advance to {targetStage}\n        </Button>\n      </Card.Footer>\n    </Card>\n  );\n}\n\n\n// \u2500\u2500 Action panel: Request Cancellation \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction RequestCancelPanel({ deal, mutations, onSuccess }: ActionPanelProps) {\n  const [reason, setReason] = useState('');\n  const [error,  setError]  = useState<string | null>(null);\n\n  const MIN_REASON_LEN = 5;\n  const tooShort = reason.trim().length < MIN_REASON_LEN;\n\n  const onSubmit = async () => {\n    setError(null);\n    const result = await mutations.requestCancel(deal.id, {\n      reason: reason.trim(),\n    });\n    if (result.ok) {\n      onSuccess();\n      setReason('');\n    } else {\n      setError(result.error);\n    }\n  };\n\n  return (\n    <Card className=\"mt-6\" stripe=\"accent\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">Request cancellation</h3>\n        <Badge tone=\"warning\" size=\"sm\">can_request_cancel</Badge>\n      </Card.Header>\n      <Card.Body>\n        <Input\n          label={`Reason (min ${MIN_REASON_LEN} chars)`}\n          placeholder=\"e.g. duplicate of D0042, lost to NCBA\"\n          value={reason}\n          onChange={(e) => setReason(e.target.value)}\n          disabled={mutations.loading}\n          helper={`A manager will see this reason when deciding whether to approve.`}\n          error={\n            reason.length > 0 && tooShort\n              ? `Reason is ${reason.trim().length} character${reason.trim().length === 1 ? '' : 's'} \u2014 need at least ${MIN_REASON_LEN}.`\n              : undefined\n          }\n        />\n        {error && (\n          <div className=\"mt-4 px-3 py-2 rounded-md bg-red-50 border border-red-200 text-sm text-red-800\">\n            {error}\n          </div>\n        )}\n        <p className=\"text-xs text-gray-500 mt-3\">\n          This sends the request to your manager's queue. The deal stays\n          active until they approve or reject. You can't request again\n          while one is pending.\n        </p>\n      </Card.Body>\n      <Card.Footer>\n        <Button\n          variant=\"danger\"\n          size=\"md\"\n          onClick={() => void onSubmit()}\n          loading={mutations.loading}\n          disabled={tooShort}\n        >\n          Submit cancellation request\n        </Button>\n      </Card.Footer>\n    </Card>\n  );\n}\n\n\n/**\n * ReferPanel \u2014 refer this existing deal to a chosen recipient (A1).\n * Self-contained: uses the StaffPicker (segment \u2192 person) + a note, posts to\n * /api/pipeline/deals/{id}/refer, then asks the parent to reload the deal so the\n * new \"Referral: pending\" badge appears.\n */\nfunction ReferPanel({ deal, onSuccess }: { deal: PipelineDeal; onSuccess: () => void }) {\n  const { toast } = useToast();\n  const [open, setOpen] = useState(false);\n  const [picked, setPicked] = useState<StaffMember | null>(null);\n  const [note, setNote] = useState('');\n  const [busy, setBusy] = useState(false);\n\n  async function onSubmit() {\n    if (!picked) {\n      toast({ tone: 'warning', message: 'Select a recipient first.' });\n      return;\n    }\n    setBusy(true);\n    try {\n      await referExistingDeal(deal.id, {\n        referred_to_code: picked.staff_code,\n        referred_to_name: picked.name,\n        referral_note: note.trim(),\n      });\n      toast({ tone: 'success', message: `Referred to ${displayName(picked.name)}. They'll need to accept it.` });\n      setOpen(false); setPicked(null); setNote('');\n      onSuccess();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Referral failed.' });\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <Card className=\"mt-6\" stripe=\"primary\">\n      <Card.Header>\n        <h3 className=\"text-sm font-semibold text-gray-900\">Refer deal</h3>\n        {deal.referral_status === 'declined' && (\n          <Badge tone=\"warning\" size=\"sm\">previously returned</Badge>\n        )}\n      </Card.Header>\n      <Card.Body>\n        {!open ? (\n          <div className=\"flex items-center justify-between gap-4\">\n            <p className=\"text-sm text-gray-600\">\n              Hand this deal to a colleague \u2014 pick their segment, then the person. They\n              progress it once they accept; you keep following it.\n            </p>\n            <Button variant=\"secondary\" size=\"sm\" onClick={() => setOpen(true)}>\n              Refer to someone\u2026\n            </Button>\n          </div>\n        ) : (\n          <div className=\"space-y-3\">\n            <StaffPicker value={picked} onChange={setPicked} />\n            <Input\n              label=\"Note (optional)\"\n              placeholder=\"Why you're referring this deal\"\n              value={note}\n              onChange={(e) => setNote(e.target.value)}\n              disabled={busy}\n            />\n            <div className=\"flex gap-2\">\n              <Button variant=\"primary\" size=\"sm\" onClick={() => void onSubmit()}\n                loading={busy} disabled={!picked}>\n                Refer deal\n              </Button>\n              <Button variant=\"ghost\" size=\"sm\" disabled={busy}\n                onClick={() => { setOpen(false); setPicked(null); setNote(''); }}>\n                Cancel\n              </Button>\n            </div>\n          </div>\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n\n// \u2500\u2500 Deal Credit Report (4b-3): CR originates at the branch, on the deal \u2500\u2500\nfunction ForwardingMemoCard({ dealId, canEdit }: { dealId: string; canEdit: boolean }) {\n  const { toast } = useToast();\n  const [to, setTo] = useState('Bank Credit Committee');\n  const [recommendation, setRecommendation] = useState('');\n  const [roName, setRoName] = useState('');\n  const [bmName, setBmName] = useState('');\n  const [busy, setBusy] = useState(false);\n\n  const printMemo = () => {\n    const esc = escapeHtml;\n    const body = `\n      <table>\n        <tr><th style=\"width:32%\">To</th><td>${esc(to)}</td></tr>\n        <tr><th>Re</th><td>Deal ${esc(dealId)}</td></tr>\n        <tr><th>Forwarding recommendation</th><td>${esc(recommendation) || '\\u2014'}</td></tr>\n      </table>\n      <h2>Sign-off</h2>\n      <table>\n        <tr><th style=\"width:32%\">Relationship Officer</th><td>${esc(roName) || '________________'}&nbsp;&nbsp;Signature: ____________&nbsp;&nbsp;Date: __________</td></tr>\n        <tr><th>Branch Manager</th><td>${esc(bmName) || '________________'}&nbsp;&nbsp;Signature: ____________&nbsp;&nbsp;Date: __________</td></tr>\n      </table>\n      <h2>Branch Credit Committee</h2>\n      <table>\n        <tr><td>Name: ________________&nbsp;&nbsp;Signature: ____________&nbsp;&nbsp;Date: __________</td></tr>\n        <tr><td>Name: ________________&nbsp;&nbsp;Signature: ____________&nbsp;&nbsp;Date: __________</td></tr>\n      </table>\n      <h2>Bank Credit Committee \\u2014 Approver&apos;s Comments</h2>\n      <table><tr><td style=\"height:80px\">&nbsp;</td></tr></table>\n    `;\n    const head = `<div class=\"head\"><h1>Forwarding Memo \\u2014 ${esc(dealId)}</h1><span class=\"muted\">printed ${esc(new Date().toLocaleString())}</span></div>`;\n    printDocument(`Forwarding Memo ${dealId}`, head + body);\n  };\n\n  const uploadSigned = () => {\n    const inp = document.createElement('input');\n    inp.type = 'file';\n    inp.onchange = async () => {\n      const f = inp.files?.[0];\n      if (!f) return;\n      setBusy(true);\n      try {\n        const buf = await f.arrayBuffer();\n        const bytes = new Uint8Array(buf);\n        let bin = '';\n        for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);\n        await uploadDealDocument(dealId, 'Forwarding Memo', f.name, btoa(bin));\n        toast({ tone: 'success', message: 'Signed Forwarding Memo uploaded.' });\n      } catch (e) {\n        toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Upload failed.' });\n      } finally { setBusy(false); }\n    };\n    inp.click();\n  };\n\n  return (\n    <Card className=\"mt-6\">\n      <Card.Header>\n        <h2 className=\"text-base font-semibold text-gray-900\">Forwarding Memo</h2>\n        <div className=\"flex items-center gap-2\">\n          <button className=\"text-sm text-brand-primary\" onClick={printMemo}>Print</button>\n          {canEdit && (\n            <button className=\"text-sm text-brand-primary disabled:opacity-50\" onClick={uploadSigned} disabled={busy}>Upload signed</button>\n          )}\n        </div>\n      </Card.Header>\n      <Card.Body>\n        <p className=\"mb-4 text-xs text-gray-500\">\n          Complete after the Branch Credit Committee gives its input, then Print for wet\n          signatures and Upload the signed copy. The signed copy travels with the case.\n        </p>\n        <div className=\"grid grid-cols-1 gap-3 md:grid-cols-2\">\n          <div>\n            <label className=\"mb-1 block text-xs text-gray-600\">To</label>\n            <input value={to} onChange={(e) => setTo(e.target.value)} className=\"w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm\" />\n          </div>\n          <div>\n            <label className=\"mb-1 block text-xs text-gray-600\">Relationship Officer</label>\n            <input value={roName} onChange={(e) => setRoName(e.target.value)} className=\"w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm\" />\n          </div>\n          <div className=\"md:col-span-2\">\n            <label className=\"mb-1 block text-xs text-gray-600\">Forwarding recommendation</label>\n            <textarea value={recommendation} onChange={(e) => setRecommendation(e.target.value)} rows={3} className=\"w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm\" />\n          </div>\n          <div>\n            <label className=\"mb-1 block text-xs text-gray-600\">Branch Manager</label>\n            <input value={bmName} onChange={(e) => setBmName(e.target.value)} className=\"w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm\" />\n          </div>\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction DealCreditReportCard({ dealId, canEdit }: { dealId: string; canEdit: boolean }) {\n  const { toast } = useToast();\n  const [cr, setCr] = useState<CrView | null>(null);\n  const [edits, setEdits] = useState<Record<string, string>>({});\n  const [busy, setBusy] = useState(false);\n\n  const load = async () => {\n    try { setCr(await getDealCr(dealId)); } catch { /* non-fatal */ }\n  };\n  useEffect(() => { void load(); /* eslint-disable-next-line */ }, [dealId]);\n\n  const valueFor = (key: string): string => {\n    if (key in edits) return edits[key];\n    const v = cr?.values?.[key];\n    return v === undefined || v === null ? '' : String(v);\n  };\n\n  const save = async (completed: boolean) => {\n    setBusy(true);\n    try {\n      await saveDealCr(dealId, { values: edits, completed });\n      setEdits({});\n      toast({ tone: 'success', message: completed ? 'Transaction Memo marked complete.' : 'Transaction Memo saved.' });\n      await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Save failed.' });\n    } finally { setBusy(false); }\n  };\n\n  if (!cr) return null;\n\n  const sourceTint = (f: CrField, hasValue: boolean) => {\n    if (f.source === 'cbs') return hasValue ? 'bg-blue-50/50' : '';\n    if (f.source === 'auto') return hasValue ? 'bg-gray-50' : '';\n    return '';\n  };\n\n  const printTm = () => {\n    const secs = (cr.template?.sections ?? []).map((sec) => {\n      const tableField = (sec.fields ?? []).find((f) => f.type === 'table');\n      if (tableField) {\n        return `<h2>${escapeHtml(sec.title)}</h2>${facilitiesToPrintHtml(valueFor(tableField.key))}`;\n      }\n      const rows = (sec.fields ?? []).map((f) =>\n        `<tr><th style=\"width:42%\">${escapeHtml(f.label)}</th><td>${escapeHtml(valueFor(f.key)) || '\u2014'}</td></tr>`).join('');\n      return `<h2>${escapeHtml(sec.title)}</h2><table>${rows}</table>`;\n    }).join('');\n    const head = `<div class=\"head\"><h1>Transaction Memo \u2014 ${escapeHtml(dealId)}</h1><span class=\"muted\">${cr.completed ? 'Complete' : 'Draft'} \u00b7 printed ${escapeHtml(new Date().toLocaleString())}</span></div>`;\n    printDocument(`Transaction Memo ${dealId}`, head + secs);\n  };\n\n  const uploadSignedTm = () => {\n    const inp = document.createElement('input');\n    inp.type = 'file';\n    inp.onchange = async () => {\n      const f = inp.files?.[0];\n      if (!f) return;\n      setBusy(true);\n      try {\n        const buf = await f.arrayBuffer();\n        const bytes = new Uint8Array(buf);\n        let bin = '';\n        for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);\n        await uploadDealDocument(dealId, 'Transaction Memo', f.name, btoa(bin));\n        toast({ tone: 'success', message: 'Signed Transaction Memo uploaded.' });\n      } catch (e) {\n        toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Upload failed.' });\n      } finally { setBusy(false); }\n    };\n    inp.click();\n  };\n\n  return (\n    <Card className=\"mt-6\">\n      <Card.Header>\n        <h2 className=\"text-base font-semibold text-gray-900\">Transaction Memo (TM)</h2>\n        <div className=\"flex items-center gap-2\">\n          {cr.completed && <Badge tone=\"success\">Complete</Badge>}\n          {!cr.cbs_available && <span className=\"text-xs text-gray-400\">CBS data unavailable \u2014 fill manually</span>}\n          <button className=\"text-sm text-brand-primary\" onClick={printTm}>Print</button>\n          {canEdit && (\n            <button className=\"text-sm text-brand-primary disabled:opacity-50\" onClick={uploadSignedTm} disabled={busy}>Upload signed</button>\n          )}\n        </div>\n      </Card.Header>\n      <Card.Body>\n          <p className=\"text-xs text-gray-500 mb-4\">\n            Complete the Transaction Memo at the branch (after documents). Blue = CBS, grey = deal;\n            both editable. Plain fields are for the deal owner.\n          </p>\n          <div className=\"space-y-6\">\n            {cr.template.sections.map((sec) => (\n              <div key={sec.key}>\n                <div className=\"text-sm font-semibold text-gray-800 mb-2 pb-1 border-b border-gray-100\">\n                  {sec.title}\n                </div>\n                <div className=\"grid grid-cols-1 md:grid-cols-2 gap-3\">\n                  {sec.fields.map((f) => {\n                    const val = valueFor(f.key);\n                    if (f.type === 'table') {\n                      return (\n                        <div key={f.key} className=\"md:col-span-2\">\n                          <label className=\"mb-1 block text-xs text-gray-600\">{f.label}</label>\n                          <FacilitiesTable value={val} onChange={(v) => setEdits((p) => ({ ...p, [f.key]: v }))} disabled={!canEdit || busy} />\n                        </div>\n                      );\n                    }\n                    const isLong = ['strengths', 'weaknesses', 'mitigants', 'rm_recommendation', 'conditions', 'purpose', 'background', 'statements', 'crb_arrears', 'risk_summary', 'other_bank_facilities', 'other_bank_securities', 'dsr_computation', 'policy_exception', 'account_conduct', 'repayment_source'].includes(f.key);\n                    return (\n                      <div key={f.key} className={isLong ? 'md:col-span-2' : ''}>\n                        <label className=\"block text-xs text-gray-600 mb-1\">\n                          {f.label}{f.required && <span className=\"text-red-500\"> *</span>}\n                          {f.source !== 'rm' && <span className=\"ml-1 text-[10px] uppercase text-gray-400\">({f.source})</span>}\n                        </label>\n                        {isLong ? (\n                          <textarea\n                            value={val} disabled={!canEdit || busy} rows={2}\n                            onChange={(e) => setEdits((p) => ({ ...p, [f.key]: e.target.value }))}\n                            className={`w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm ${sourceTint(f, !!val)}`}\n                          />\n                        ) : (\n                          <input\n                            value={val} disabled={!canEdit || busy}\n                            onChange={(e) => setEdits((p) => ({ ...p, [f.key]: e.target.value }))}\n                            className={`w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm ${sourceTint(f, !!val)}`}\n                          />\n                        )}\n                      </div>\n                    );\n                  })}\n                </div>\n              </div>\n            ))}\n          </div>\n          {canEdit && (\n            <div className=\"mt-5 flex justify-end gap-2\">\n              <Button variant=\"ghost\" onClick={() => void save(false)} disabled={busy}>Save draft</Button>\n              <Button onClick={() => void save(true)} disabled={busy}>Mark complete</Button>\n            </div>\n          )}\n        </Card.Body>\n    </Card>\n  );\n}\n\n// \u2500\u2500 Committee Journey capture (4b-4): record each gate's decision on the deal \u2500\u2500\nfunction CommitteeJourneyCard({ dealId, canEdit }: { dealId: string; canEdit: boolean }) {\n  const { toast } = useToast();\n  const [data, setData] = useState<CommitteeRecordsResponse | null>(null);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [outcomeDraft, setOutcomeDraft] = useState<Record<string, string>>({});\n  const [appealReason, setAppealReason] = useState<Record<string, string>>({});\n  const doAppeal = async (code: string) => {\n    const reason = (appealReason[code] ?? '').trim();\n    if (!reason) { toast({ tone: 'danger', message: 'Enter an appeal reason.' }); return; }\n    setBusy(code);\n    try {\n      const r = await appealCommitteeDecision(dealId, code, reason);\n      toast({ tone: 'success', message: r.message });\n      setAppealReason((p) => ({ ...p, [code]: '' }));\n      await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Appeal failed' });\n    } finally { setBusy(null); }\n  };\n  const doCloseLost = async (code: string) => {\n    setBusy(code);\n    try {\n      await closeDealAsLost(dealId, `Committee ${code} rejected`);\n      toast({ tone: 'success', message: 'Deal closed as Lost.' });\n      await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Close failed' });\n    } finally { setBusy(null); }\n  };\n\n  const load = async () => {\n    try { setData(await getDealCommitteeRecords(dealId)); } catch { /* non-fatal */ }\n  };\n  useEffect(() => { void load(); /* eslint-disable-next-line */ }, [dealId]);\n\n  // ---- HOOKS BEFORE THE EARLY RETURN ------------------------------------\n  // These three were declared AFTER `if (!data ...) return null` - so on a\n  // render where data was absent React saw six hooks and on the next it saw\n  // nine. That is the Rules of Hooks violation, and it does not fail quietly:\n  // it throws, and the page renders blank.\n  //\n  //     Warning: React has detected a change in the order of Hooks called by\n  //     CommitteeJourneyCard ... 7. undefined -> useState\n  //\n  // Every hook must run on every render, so they belong above any return.\n  const [myVote, setMyVote] = useState<Record<string, string>>({});\n  const [myDocs, setMyDocs] = useState<Record<string, boolean>>({});\n  const [myComment, setMyComment] = useState<Record<string, string>>({});\n\n  if (!data || data.cr_only) return null;\n\n\n\n  // \u2500\u2500 YOUR OWN VOTE, NOT THE WHOLE COMMITTEE'S \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // This used to post every member's row at once, so one member pressing the\n  // button submitted a committee's worth of votes - one vote, below quorum,\n  // DEFERRED, case closed before anybody else had seen it. Each member now\n  // records their own view from their own login and the case stays open until\n  // enough of them have.\n\n  const castMyVote = async (gate: CommitteeGate) => {\n    const vote = myVote[gate.code];\n    if (!vote) { toast({ tone: 'danger', message: 'Pick your vote.' }); return; }\n    if (vote === 'YES' && !myDocs[gate.code]) {\n      toast({ tone: 'danger', message: 'Confirm the documentation was checked before voting YES.' });\n      return;\n    }\n    setBusy(gate.code);\n    try {\n      const r = await castCommitteeVote(dealId, gate.code, {\n        vote,\n        documents_validated: !!myDocs[gate.code],\n        comment: myComment[gate.code] ?? '',\n      });\n      // THE MESSAGE SAYS WHAT ACTUALLY HAPPENED. \"Decision recorded\" after one\n      // vote is what made people think the case had been decided.\n      toast({\n        tone: 'success',\n        message: r.decided\n          ? `Committee decided: ${r.outcome === 'APPROVED' ? 'recommended'\n              : r.outcome === 'REJECTED' ? 'not recommended' : 'deferred'}.`\n          : `Your vote is in \u2014 ${r.votes_cast} of ${r.quorum}.`\n            + (r.awaiting.length ? ` Awaiting ${r.awaiting.join(', ')}.` : ''),\n      });\n      await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Failed' });\n    } finally { setBusy(null); }\n  };\n\n  const recordSingle = async (gate: CommitteeGate) => {\n    const outcome = outcomeDraft[gate.code];\n    if (!outcome) { toast({ tone: 'danger', message: 'Pick an outcome.' }); return; }\n    setBusy(gate.code);\n    try {\n      await recordDealCommitteeDecision(dealId, { code: gate.code, outcome });\n      toast({ tone: 'success', message: `${gate.code} decision recorded.` });\n      await load();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Failed' });\n    } finally { setBusy(null); }\n  };\n\n  const outcomeTone = (o: string) => (o === 'APPROVED' ? 'success' : o === 'REJECTED' ? 'danger' : 'warning');\n  // The same stored values, read back as what the committee actually did.\n  const outcomeLabel = (o: string) => (\n    o === 'APPROVED' ? 'Recommended'\n      : o === 'REJECTED' ? 'Not recommended'\n        : o === 'DEFERRED' ? 'Deferred' : o);\n\n  return (\n    <Card className=\"mt-6\">\n      <Card.Header>\n        <h2 className=\"text-base font-semibold text-gray-900\">Credit Committee Journey</h2>\n        <div className=\"flex items-center gap-2\">\n          {/* THE PAPERS, ONE CLICK AWAY (ruling 2026-08-13: \"they need to be\n              able to view documentation, otherwise how do they know what they\n              are approving\"). A committee member reaching this card from their\n              queue has no reason to know the documents live under another tab\n              further up the page - so it is named here, where the decision is\n              actually made. */}\n          <button\n            type=\"button\"\n            onClick={() => window.dispatchEvent(\n              new CustomEvent('workbench:open-tab', { detail: 'documents' }))}\n            className=\"rounded-md border border-gray-300 px-2.5 py-1 text-xs font-medium text-gray-700 hover:bg-gray-50\"\n          >\n            View documentation\n          </button>\n          <Badge tone=\"info\" size=\"sm\">{data.gates.length} gate{data.gates.length === 1 ? '' : 's'}</Badge>\n        </div>\n      </Card.Header>\n      <Card.Body>\n        <div className=\"space-y-4\">\n          {data.gates.map((gate) => (\n            <div key={gate.code} className=\"rounded border p-3\">\n              <div className=\"mb-2 flex items-center justify-between\">\n                <div>\n                  <span className=\"text-sm font-semibold\">{gate.code} \u2014 {gate.name}</span>\n                  <span className=\"ml-2 text-xs text-gray-400\">\n                    {gate.recording_mode === 'voting' ? `voting \u00b7 ${gate.voting_rule}` : 'single record'}\n                  </span>\n                </div>\n                {gate.record && <Badge tone={outcomeTone(gate.record.outcome)} size=\"sm\">{outcomeLabel(gate.record.outcome)}</Badge>}\n              </div>\n\n              {gate.record ? (\n                <div className=\"text-xs text-gray-600\">\n                  Recorded by {gate.record.recorded_by} on {gate.record.recorded_at}.\n                  {gate.record.mode === 'voting' && gate.record.votes.length > 0 && (\n                    <ul className=\"mt-1 list-disc pl-5\">\n                      {gate.record.votes.map((v, i) => (\n                        <li key={i}>\n                          {v.name} ({v.role}): {v.vote}\n                          {v.documents_validated ? ' \u00b7 \u2713 docs validated' : ''}\n                          {v.comment ? ` \u2014 ${v.comment}` : ''}\n                        </li>\n                      ))}\n                    </ul>\n                  )}\n                  {gate.record.outcome === 'REJECTED' && canEdit && (\n                    <div className=\"mt-3 rounded bg-red-50 p-2\">\n                      <p className=\"mb-2 font-medium text-red-700\">Rejected \u2014 appeal or close as lost.</p>\n                      <textarea className=\"mb-2 w-full rounded border px-2 py-1 text-xs\" rows={2}\n                        placeholder=\"Appeal reason / justification\"\n                        value={appealReason[gate.code] ?? ''}\n                        onChange={(e) => setAppealReason((p) => ({ ...p, [gate.code]: e.target.value }))} />\n                      <div className=\"flex gap-2\">\n                        <Button size=\"sm\" onClick={() => void doAppeal(gate.code)} disabled={busy === gate.code}>\n                          {busy === gate.code ? 'Working\u2026' : 'Appeal (re-open)'}\n                        </Button>\n                        <Button size=\"sm\" variant=\"ghost\" onClick={() => void doCloseLost(gate.code)} disabled={busy === gate.code}>\n                          Close as Lost\n                        </Button>\n                      </div>\n                    </div>\n                  )}\n                </div>\n              ) : (gate.can_vote ?? canEdit) ? (\n                /* CAN THIS PERSON VOTE, not can they edit the deal. canEdit\n                   means owner or admin; a committee member is neither, so the\n                   voting bench never rendered for the one person who needed\n                   it. The server answers from the roster, and falls back to\n                   canEdit for a build where the gate does not carry it. */\n                gate.recording_mode === 'voting' ? (\n                  <div>\n                    {(gate.members ?? []).length === 0 && (\n                      <p className=\"mb-2 text-xs text-amber-600\">No members configured for this committee \u2014 add them in Credit Committees admin.</p>\n                    )}\n\n                    {/* \u2500\u2500 YOUR VOTE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n                        One member, one vote, from their own login. This used\n                        to be a row per member with a single \"Record votes\"\n                        button, so whoever pressed it submitted the whole\n                        committee - and one vote below quorum closed the case\n                        as DEFERRED before anybody else had seen it.\n\n                        Who is voting comes from the session, not a name typed\n                        here, so it cannot be misattributed. */}\n                    <div className=\"rounded-md border border-gray-200 p-3\">\n                      <div className=\"mb-2 text-xs font-semibold text-gray-700\">\n                        Your vote\n                      </div>\n                      <div className=\"flex flex-wrap items-center gap-2\">\n                        <select\n                          className=\"rounded border px-2 py-1 text-xs\"\n                          value={myVote[gate.code] ?? ''}\n                          onChange={(e) => setMyVote((m) => ({ ...m, [gate.code]: e.target.value }))}\n                        >\n                          <option value=\"\">\u2014 your view \u2014</option>\n                          <option value=\"YES\">Recommend</option>\n                          <option value=\"NO\">Do not recommend</option>\n                          <option value=\"ABSTAIN\">Abstain</option>\n                          <option value=\"RECUSED\">Recuse myself</option>\n                        </select>\n                        <label className=\"flex items-center gap-1.5 text-xs text-gray-700\">\n                          <input\n                            type=\"checkbox\"\n                            checked={!!myDocs[gate.code]}\n                            onChange={(e) => setMyDocs((m) => ({ ...m, [gate.code]: e.target.checked }))}\n                          />\n                          Documentation checked\n                        </label>\n                      </div>\n                      <input\n                        className=\"mt-2 w-full rounded border px-2 py-1 text-xs\"\n                        placeholder=\"Comment (optional)\"\n                        value={myComment[gate.code] ?? ''}\n                        onChange={(e) => setMyComment((m) => ({ ...m, [gate.code]: e.target.value }))}\n                      />\n                      <div className=\"mt-2 flex items-center justify-between gap-2\">\n                        {/* WHO HAS ALREADY VOTED, so a member can see whether\n                            the committee is waiting on them or on somebody\n                            else. */}\n                        <span className=\"text-[11px] text-gray-500\">\n                          {(gate.votes_cast ?? 0) > 0\n                            ? `${gate.votes_cast} of ${gate.quorum ?? 2} voted`\n                            : 'No votes yet'}\n                          {(gate.awaiting ?? []).length > 0\n                            ? ` \u00b7 awaiting ${(gate.awaiting ?? []).join(', ')}`\n                            : ''}\n                        </span>\n                        <Button size=\"sm\" onClick={() => void castMyVote(gate)} disabled={busy === gate.code}>\n                          {busy === gate.code ? 'Submitting\u2026' : 'Submit my vote'}\n                        </Button>\n                      </div>\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"flex items-center gap-2\">\n                    <select className=\"rounded border px-2 py-1.5 text-sm\"\n                      value={outcomeDraft[gate.code] ?? ''}\n                      onChange={(e) => setOutcomeDraft((p) => ({ ...p, [gate.code]: e.target.value }))}>\n                      {/* A COMMITTEE RECOMMENDS; the approval comes from\n                          credit (ruling 2026-08-13). The stored values stay\n                          APPROVED / REJECTED / DEFERRED because the gate, the\n                          journey and the reports all read them - renaming the\n                          data would break those for a wording change. What a\n                          person reads now matches what they are actually\n                          doing. */}\n                      <option value=\"\">\u2014 recommendation \u2014</option>\n                      <option value=\"APPROVED\">Recommend</option>\n                      <option value=\"REJECTED\">Do not recommend</option>\n                      <option value=\"DEFERRED\">Defer \u2014 more information needed</option>\n                    </select>\n                    <Button size=\"sm\" onClick={() => void recordSingle(gate)} disabled={busy === gate.code}>\n                      {busy === gate.code ? 'Recording\u2026' : 'Record recommendation'}\n                    </Button>\n                  </div>\n                )\n              ) : (\n                <p className=\"text-xs text-gray-400\">Not yet decided.</p>\n              )}\n            </div>\n          ))}\n        </div>\n      </Card.Body>\n    </Card>\n  );\n}\n\n",
 "frontend/web/src/pages/PipelineManagerQueues.tsx": "// v10.513 Phase 4 Batch \u03b24 \u2014 PipelineManagerQueues page.\n//\n// Manager-only page at /pipeline/queues with two tabs:\n//\n//   1. Validation queue \u2014 deals past Lead awaiting manager validation.\n//      Each deal has Validate (approved:true) / Query (approved:false)\n//      action panel.\n//\n//   2. Cancellation queue \u2014 deals with pending cancellation requests\n//      awaiting manager decision. Each deal has Approve / Reject\n//      action panel.\n//\n// Authorization layers (defense in depth):\n//   1. Sidebar hides the \"Manager Queues\" link from non-managers (UX)\n//   2. This page renders \"Not authorized\" guard when isManager(user)\n//      is false, before even attempting the fetch (UX)\n//   3. Server returns 403 to non-managers on the queue endpoints\n//      (the real security boundary)\n//\n// Pattern reuse:\n//   - Tab strip + count badges: bespoke (no Tab primitive)\n//   - Per-deal action panels: same shape as \u03b22 detail page panels\n//   - Same Toast pattern for success / error\n//   - Same mutation hook pattern\n\nimport { displayName } from \"../lib/names\";\nimport { useCallback, useEffect, useState } from 'react';\nimport { useNavigate, Link } from 'react-router-dom';\nimport { useBranding } from '@/hooks/useBranding';\nimport { useRole } from '@/hooks/useRole';\nimport { useToast } from '@/components/Toast';\nimport { usePipelineDealMutations } from '@/hooks/usePipelineDealMutations';\nimport { isManager } from '@/lib/role';\nimport {\n  fetchValidationQueue, AuthExpiredError,\n} from '@/lib/api';\nimport { Card } from '@/components/Card';\nimport { Badge } from '@/components/Badge';\nimport { Button } from '@/components/Button';\nimport { Skeleton } from '@/components/Skeleton';\nimport { PageHeader } from '@/components/PageHeader';\nimport { CommitteeQueue } from '@/components/CommitteeQueue';\nimport { fetchCommitteeQueue } from '@/lib/api';\nimport DailyLogValidation from '@/components/DailyLogValidation';\nimport BranchCountersign from '@/components/BranchCountersign';\nimport UnitRollup from '@/components/UnitRollup';\nimport Leaderboard from '@/components/Leaderboard';\nimport DailyLogAnalytics from '@/components/DailyLogAnalytics';\nimport PipelineLeaderboard from '@/components/PipelineLeaderboard';\nimport PipelineDayCountersign from '@/components/PipelineDayCountersign';\nimport PipelineBranchDay from '@/components/PipelineBranchDay';\nimport { fetchUnitDays } from '@/lib/api';\nimport {\n  stageTone, type PipelineDeal,\n} from '@/types/pipeline';\n\n\ntype TabKey = 'validation' | 'committee' | 'dailylog' | 'ranking' | 'analytics';\n\n\n// \u2500\u2500 Page component \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport function PipelineManagerQueues() {\n  const { branding } = useBranding();\n  const { user } = useRole();\n  const { toast } = useToast();\n  const navigate = useNavigate();\n\n  const userIsManager = isManager(user);\n\n  // \u2500\u2500 Page-local state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  const [activeTab, setActiveTab] = useState<TabKey>('validation');\n  // Fetched once for the badge; the panel loads its own copy when opened.\n  const [committeeCount, setCommitteeCount] = useState(0);\n  useEffect(() => {\n    void (async () => {\n      try {\n        // COUNT WHAT IS WAITING ON YOU, not what the committee has not\n        // finished. Three cases with your vote already on two of them is one\n        // outstanding task, not three - and a badge that will not go down as\n        // you work is a badge people stop reading.\n        const q = await fetchCommitteeQueue();\n        setCommitteeCount(q.cases.filter((c) => !c.you_voted).length);\n      } catch {\n        setCommitteeCount(0);\n      }\n    })();\n  }, []);\n  const [validationDeals, setValidationDeals] = useState<PipelineDeal[]>([]);\n  const [loadingV, setLoadingV] = useState(false);\n  const [errorV,   setErrorV]   = useState<string | null>(null);\n  // Daily-log queue owns its own fetching; the page only tracks the count\n  // for the tab badge.\n  const [dailyLogPending, setDailyLogPending] = useState(0);\n  // Tier 2 (Head of Branches, MD) countersigns BRANCHES; everyone else\n  // validates individuals. Decided by asking the server what this caller\n  // oversees rather than by inspecting their role string here.\n  // 'staff' = validates individuals, 'branch' = countersigns branches,\n  // 'rollup' = MD / Business Manager, observes and may return.\n  const [tier, setTier] = useState<'staff' | 'branch' | 'rollup' | null>(null);\n  const [rankView, setRankView] = useState<'index' | 'pipeline'>('index');\n\n  // \u2500\u2500 Fetchers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  const loadValidation = useCallback(async () => {\n    if (!userIsManager) return;\n    setLoadingV(true);\n    setErrorV(null);\n    try {\n      const res = await fetchValidationQueue();\n      setValidationDeals(res.deals);\n    } catch (e) {\n      if (e instanceof AuthExpiredError) return;\n      const msg = e instanceof Error ? e.message : 'Failed to load validation queue';\n      setErrorV(msg);\n      setValidationDeals([]);\n    } finally {\n      setLoadingV(false);\n    }\n  }, [userIsManager]);\n\n  useEffect(() => {\n    let alive = true;\n    void (async () => {\n      try {\n        // One probe. /unit-days answers both questions: top_of_house marks the\n        // observation tier, and a Branches node means this caller countersigns\n        // branches. Asking the server beats inspecting a role string here.\n        const r = await fetchUnitDays();\n        if (!alive) return;\n        if (r.top_of_house) setTier('rollup');\n        else if ((r.branches?.children?.length ?? 0) > 0) setTier('branch');\n        else setTier('staff');\n      } catch {\n        if (alive) setTier('staff');\n      }\n    })();\n    return () => { alive = false; };\n  }, []);\n\n  // Initial load + reload on tab focus to keep queues fresh\n  useEffect(() => {\n    void loadValidation();\n  }, [loadValidation]);\n\n  // \u2500\u2500 Render guards \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  if (!userIsManager) {\n    return (\n      <div className=\"min-h-screen bg-gray-50\">\n        <PageHeader\n          title=\"Manager Queues\"\n          breadcrumbs={[{ label: 'A2Z Pipeline Intelligence System (PIS)' }, { label: 'Manager Queues' }]}\n        />\n        <div className=\"max-w-7xl 2xl:max-w-[1680px] mx-auto px-6 py-6\">\n        <Card>\n          <Card.Header>\n            <div className=\"flex items-center gap-3\">\n              <Badge tone=\"warning\">Not authorized</Badge>\n              <h2 className=\"text-base font-semibold text-gray-900\">\n                Manager queues\n              </h2>\n            </div>\n          </Card.Header>\n          <Card.Body>\n            <p className=\"text-sm text-gray-700\">\n              These queues are only visible to staff with manager authority\n              (Branch Manager, Regional Head, Director, MD, etc.).\n            </p>\n            <p className=\"text-sm text-gray-500 mt-3\">\n              If you believe this is wrong, contact your administrator.\n              Your current role is{' '}\n              <span className=\"font-mono text-gray-700\">\n                {user?.role ?? '(unknown)'}\n              </span>.\n            </p>\n            <div className=\"mt-4\">\n              <Link\n                to=\"/pipeline\"\n                className=\"text-sm text-brand-primary underline\"\n              >\n                \u2190 Back to pipeline\n              </Link>\n            </div>\n          </Card.Body>\n        </Card>\n        </div>\n      </div>\n    );\n  }\n\n  // \u2500\u2500 Active tab data \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  // Cancellation was removed from this page (ruling 2026-08-09); the deal list\n  // here is now only ever the pipeline validation queue.\n  const activeDeals    = validationDeals;\n  const activeLoading  = loadingV;\n  const activeError    = errorV;\n  const activeReload   = loadValidation;\n\n  // \u2500\u2500 Main render \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  return (\n    <div className=\"min-h-screen bg-gray-50\">\n      <PageHeader\n        title=\"Manager Queues\"\n        breadcrumbs={[{ label: 'A2Z Pipeline Intelligence System (PIS)' }, { label: 'Manager Queues' }]}\n      />\n      <div className=\"max-w-7xl 2xl:max-w-[1680px] mx-auto px-6 py-6\">\n\n      {/* Tab strip */}\n      <div className=\"flex items-center gap-2 border-b border-gray-200\">\n        <TabBtn\n          active={activeTab === 'validation'}\n          onClick={() => setActiveTab('validation')}\n          label=\"Pipeline validation\"\n          count={validationDeals.length}\n          loading={loadingV}\n        />\n        {/* Committee sits beside validation because it is the same kind of\n            work - a queue of things waiting on this person's decision. No new\n            sidebar entry (ruling 2026-08-12). */}\n        <TabBtn\n          active={activeTab === 'committee'}\n          onClick={() => setActiveTab('committee')}\n          label=\"Committee\"\n          // The real number, not a hardcoded zero. A tab that always reads 0\n          // tells somebody there is nothing to do, which is the opposite of\n          // what this queue exists to say.\n          count={committeeCount}\n          loading={false}\n        />\n        <TabBtn\n          active={activeTab === 'dailylog'}\n          onClick={() => setActiveTab('dailylog')}\n          label=\"Daily log validation\"\n          count={dailyLogPending}\n          loading={false}\n        />\n        <TabBtn\n          active={activeTab === 'ranking'}\n          onClick={() => setActiveTab('ranking')}\n          label=\"Ranking\"\n          count={0}\n          loading={false}\n        />\n        <TabBtn\n          active={activeTab === 'analytics'}\n          onClick={() => setActiveTab('analytics')}\n          label=\"Index analytics\"\n          count={0}\n          loading={false}\n        />\n        <div className=\"flex-1\" />\n        <Button\n          variant=\"ghost\"\n          size=\"sm\"\n          onClick={() => void activeReload()}\n          loading={activeLoading}\n        >\n          Refresh\n        </Button>\n      </div>\n\n      {/* Daily-log validation owns its own loading, empty and error states. */}\n      {activeTab === 'committee' && <CommitteeQueue />}\n\n      {activeTab === 'dailylog' && tier === null && (\n        <Card className=\"mt-4\"><Card.Body>\n          <div className=\"text-sm text-gray-400\">Loading\u2026</div>\n        </Card.Body></Card>\n      )}\n      {activeTab === 'dailylog' && tier === 'rollup' && (\n        <UnitRollup onCount={setDailyLogPending} />\n      )}\n      {activeTab === 'dailylog' && tier === 'branch' && (\n        <BranchCountersign onCount={setDailyLogPending} />\n      )}\n      {activeTab === 'dailylog' && tier === 'staff' && (\n        <DailyLogValidation onCount={setDailyLogPending} />\n      )}\n\n      {/* Ranking and analytics live here too: a manager works out of this page,\n          and making them navigate elsewhere to see how their team is doing\n          splits one job across two screens. Both components are scope-aware\n          server-side, so each manager sees their own population. */}\n      {/* Pipeline validation follows the daily log's tier routing: a branch or\n          roll-up caller countersigns days; everyone else works the deal queue\n          below. Same shape, so a manager learns one screen and knows both. */}\n      {activeTab === 'validation' && (tier === 'branch' || tier === 'rollup') && (\n        <PipelineDayCountersign onCount={() => { /* count shown on the tab */ }} />\n      )}\n\n      {/* Tier 1 \u2014 the branch triad. This was the old per-deal card list; the\n          pilot reported that it did not match the daily log, so it now uses the\n          same shape: rows, a branch line, and a gate on closing the day. */}\n      {activeTab === 'validation' && tier === 'staff' && <PipelineBranchDay />}\n\n      {/* Two rankings, one tab: the productivity INDEX and the PIPELINE. They\n          measure different things over the same people, so they sit side by\n          side rather than being blended into a single misleading number. */}\n      {activeTab === 'ranking' && (\n        <div className=\"mt-4 space-y-4\">\n          <div className=\"flex gap-1.5 text-xs\">\n            {(['index', 'pipeline'] as const).map((k) => (\n              <button key={k} type=\"button\" onClick={() => setRankView(k)}\n                className={'rounded-full px-3 py-1 font-medium '\n                  + (rankView === k ? 'bg-[#005B82] text-white'\n                                    : 'bg-gray-100 text-gray-600 hover:bg-[#0082BB]/10')}>\n                {k === 'index' ? 'Index ranking' : 'Pipeline ranking'}\n              </button>\n            ))}\n          </div>\n          {rankView === 'index' ? <Leaderboard /> : <PipelineLeaderboard />}\n        </div>\n      )}\n      {activeTab === 'analytics' && <DailyLogAnalytics />}\n\n      {/* Error panel */}\n      {!['dailylog', 'ranking', 'analytics', 'committee'].includes(activeTab)\n        && !(activeTab === 'validation' && (tier === 'branch' || tier === 'rollup' || tier === 'staff'))\n        && activeError && (\n        <Card className=\"mt-4\">\n          <Card.Body>\n            <div className=\"flex items-center gap-3\">\n              <Badge tone=\"danger\">Error</Badge>\n              <div className=\"flex-1 text-sm text-gray-700\">{activeError}</div>\n              <Button variant=\"ghost\" size=\"sm\" onClick={() => void activeReload()}>\n                Retry\n              </Button>\n            </div>\n          </Card.Body>\n        </Card>\n      )}\n\n      {/* Empty / loading / content */}\n      {['dailylog', 'ranking', 'analytics', 'committee'].includes(activeTab)\n        || (activeTab === 'validation' && (tier === 'branch' || tier === 'rollup' || tier === 'staff'))\n        ? null : activeLoading && activeDeals.length === 0 ? (\n        <Card className=\"mt-4\">\n          <Card.Body>\n            <Skeleton shape=\"line\" className=\"w-1/3\" />\n            <div className=\"mt-3\"><Skeleton shape=\"block\" className=\"h-12\" /></div>\n            <div className=\"mt-2\"><Skeleton shape=\"block\" className=\"h-12\" /></div>\n          </Card.Body>\n        </Card>\n      ) : activeDeals.length === 0 && !activeError ? (\n        <Card className=\"mt-4\">\n          <Card.Body>\n            <div className=\"text-sm text-gray-700 font-medium\">\n              No deals in this queue.\n            </div>\n            <div className=\"text-xs text-gray-500 mt-1\">\n              {activeTab === 'validation'\n                ? 'New deals past Lead stage will appear here for your validation.'\n                : 'Cancellation requests from your team will appear here for your decision.'}\n            </div>\n          </Card.Body>\n        </Card>\n      ) : (\n        <div className=\"mt-4 space-y-3\">\n          {activeDeals.map((deal) => (\n            activeTab === 'validation' ? (\n              <ValidationCard\n                key={deal.id}\n                deal={deal}\n                onNavigate={() => navigate(`/pipeline/${encodeURIComponent(deal.id)}`)}\n                onResolved={() => {\n                  toast({ tone: 'success', message: 'Validation decision recorded.' });\n                  void loadValidation();\n                }}\n                onErrorToast={(msg) => toast({ tone: 'danger', message: msg })}\n              />\n            ) : (\n              <CancellationCard\n                key={deal.id}\n                deal={deal}\n                onNavigate={() => navigate(`/pipeline/${encodeURIComponent(deal.id)}`)}\n                onResolved={() => {\n                  toast({ tone: 'success', message: 'Decision recorded.' });\n                  void loadValidation();\n                }}\n                onErrorToast={(msg) => toast({ tone: 'danger', message: msg })}\n              />\n            )\n          ))}\n        </div>\n      )}\n\n      {/* Footer */}\n      <footer className=\"mt-12 pb-6 text-center text-[11px] text-gray-400 leading-relaxed\">\n        {branding?.ip_notice}\n      </footer>\n      </div>\n    </div>\n  );\n}\n\n\n// \u2500\u2500 Tab button \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface TabBtnProps {\n  active:   boolean;\n  onClick:  () => void;\n  label:    string;\n  count:    number;\n  loading:  boolean;\n}\n\nfunction TabBtn({ active, onClick, label, count, loading }: TabBtnProps) {\n  return (\n    <button\n      type=\"button\"\n      onClick={onClick}\n      className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${\n        active\n          ? 'border-brand-primary text-brand-primary'\n          : 'border-transparent text-gray-600 hover:text-gray-900'\n      }`}\n    >\n      {label}\n      {' '}\n      <span className={`ml-1 px-2 py-0.5 text-[11px] rounded-full ${\n        active ? 'bg-brand-primary text-white' : 'bg-gray-200 text-gray-700'\n      }`}>\n        {loading ? '\u2026' : count}\n      </span>\n    </button>\n  );\n}\n\n\n// \u2500\u2500 Common queue card scaffolding \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface QueueCardCommonProps {\n  deal:         PipelineDeal;\n  onNavigate:   () => void;\n  children:     React.ReactNode;\n}\n\nfunction QueueCard({ deal, onNavigate, children }: QueueCardCommonProps) {\n  const { branding } = useBranding();\n  const sym = branding?.currency_symbol ?? '';\n  return (\n    <Card>\n      <Card.Header>\n        <div className=\"flex items-center gap-3 flex-wrap\">\n          <button\n            type=\"button\"\n            onClick={onNavigate}\n            className=\"font-mono text-xs text-brand-primary hover:underline\"\n          >\n            {deal.id}\n          </button>\n          <h3 className=\"text-sm font-semibold text-gray-900\">\n            {deal.client_name || '\u2014'}\n          </h3>\n          <Badge tone={stageTone(deal.stage)} size=\"sm\">{deal.stage}</Badge>\n        </div>\n        <div className=\"text-xs text-gray-500 text-right\">\n          <div>{deal.product_type ?? deal.product ?? '\u2014'}</div>\n          <div className=\"font-medium text-gray-900 mt-0.5\">\n            {sym} {Number(deal.amount_kes ?? deal.deal_value ?? 0).toLocaleString()}\n          </div>\n        </div>\n      </Card.Header>\n      <Card.Body>\n        <div className=\"grid grid-cols-2 md:grid-cols-4 gap-3 text-xs mb-3\">\n          <Field label=\"Owner\" value={deal.staff_name ? displayName(deal.staff_name) : undefined} sub={deal.staff_code} />\n          <Field label=\"Probability\" value={\n            typeof deal.probability === 'number'\n              ? `${Math.round(deal.probability * 100)}%`\n              : '\u2014'\n          } />\n          <Field label=\"Next action\" value={deal.next_action} />\n          <Field label=\"Expected close\" value={(deal.expected_close ?? '').slice(0, 10) || '\u2014'} />\n        </div>\n        {children}\n      </Card.Body>\n    </Card>\n  );\n}\n\nfunction Field({ label, value, sub }: {\n  label: string;\n  value: React.ReactNode;\n  sub?: React.ReactNode;\n}) {\n  return (\n    <div>\n      <div className=\"text-[10px] font-semibold uppercase tracking-wider text-gray-500\">\n        {label}\n      </div>\n      <div className=\"text-sm text-gray-900 mt-0.5\">{value ?? '\u2014'}</div>\n      {sub && (\n        <div className=\"text-[10px] text-gray-400 font-mono\">{sub}</div>\n      )}\n    </div>\n  );\n}\n\n\n// \u2500\u2500 Validation card (Validate / Query buttons + note) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninterface ResolvedCallbacks {\n  onResolved:    () => void;\n  onErrorToast:  (msg: string) => void;\n}\n\nfunction ValidationCard({ deal, onNavigate, onResolved, onErrorToast }: {\n  deal: PipelineDeal;\n  onNavigate: () => void;\n} & ResolvedCallbacks) {\n  const mutations = usePipelineDealMutations();\n  const [note, setNote] = useState('');\n\n  const submit = async (approved: boolean) => {\n    const result = await mutations.validate(deal.id, {\n      approved,\n      note: note.trim() || undefined,\n    });\n    if (result.ok) {\n      setNote('');\n      onResolved();\n    } else {\n      onErrorToast(result.error);\n    }\n  };\n\n  return (\n    <QueueCard deal={deal} onNavigate={onNavigate}>\n      <div className=\"border-t border-gray-100 pt-3\">\n        <label className=\"text-xs font-medium text-gray-700\">\n          Manager note (optional)\n        </label>\n        <input\n          type=\"text\"\n          value={note}\n          onChange={(e) => setNote(e.target.value)}\n          disabled={mutations.loading}\n          placeholder=\"Context for the owner if querying\"\n          className=\"mt-1 w-full h-9 px-3 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n        />\n        <div className=\"mt-3 flex items-center justify-end gap-2\">\n          <Button\n            variant=\"ghost\"\n            size=\"sm\"\n            onClick={() => void submit(false)}\n            loading={mutations.loading}\n          >\n            Query (return to owner)\n          </Button>\n          <Button\n            variant=\"primary\"\n            size=\"sm\"\n            onClick={() => void submit(true)}\n            loading={mutations.loading}\n          >\n            Validate \u2014 include in forecast\n          </Button>\n        </div>\n      </div>\n    </QueueCard>\n  );\n}\n\n\n// \u2500\u2500 Cancellation card (Approve / Reject buttons + reason context) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction CancellationCard({ deal, onNavigate, onResolved, onErrorToast }: {\n  deal: PipelineDeal;\n  onNavigate: () => void;\n} & ResolvedCallbacks) {\n  const mutations = usePipelineDealMutations();\n  const [note, setNote] = useState('');\n\n  const submit = async (approve: boolean) => {\n    const result = await mutations.approveCancel(deal.id, {\n      approve,\n      note: note.trim() || undefined,\n    });\n    if (result.ok) {\n      setNote('');\n      onResolved();\n    } else {\n      onErrorToast(result.error);\n    }\n  };\n\n  return (\n    <QueueCard deal={deal} onNavigate={onNavigate}>\n      {/* Requested-by + reason context */}\n      <div className=\"px-3 py-2 rounded-md bg-amber-50 border border-amber-200 text-xs\">\n        <div className=\"font-semibold text-amber-900\">\n          Cancellation requested\n          {deal.cancel_requested_by && ` by ${deal.cancel_requested_by}`}\n        </div>\n        {deal.cancel_reason && (\n          <div className=\"text-amber-800 mt-1\">\n            <span className=\"font-medium\">Reason:</span> {deal.cancel_reason}\n          </div>\n        )}\n      </div>\n      <div className=\"border-t border-gray-100 pt-3 mt-3\">\n        <label className=\"text-xs font-medium text-gray-700\">\n          Your decision note (optional)\n        </label>\n        <input\n          type=\"text\"\n          value={note}\n          onChange={(e) => setNote(e.target.value)}\n          disabled={mutations.loading}\n          placeholder=\"Recorded on the deal for audit\"\n          className=\"mt-1 w-full h-9 px-3 rounded-md border border-gray-300 bg-white text-sm focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n        />\n        <div className=\"mt-3 flex items-center justify-end gap-2\">\n          <Button\n            variant=\"ghost\"\n            size=\"sm\"\n            onClick={() => void submit(false)}\n            loading={mutations.loading}\n          >\n            Decline cancellation \u2014 deal continues\n          </Button>\n          <Button\n            variant=\"danger\"\n            size=\"sm\"\n            onClick={() => void submit(true)}\n            loading={mutations.loading}\n          >\n            Approve cancellation \u2014 close as Lost\n          </Button>\n        </div>\n      </div>\n    </QueueCard>\n  );\n}\n",
 "frontend/web/src/pages/Pipeline.tsx": "// v10.510 Phase 4 Batch \u03b21 \u2014 Pipeline page.\n//\n// First read-only consumer of the \u03b11-\u03b17 pipeline API surface. Shows\n// the caller's cascade-scoped deal list with per-deal permission\n// indicators (\u03b17) visible inline. The mutation surface (create, edit,\n// advance, refer, validate, cancel/request, cancel/approve) lands in\n// subsequent \u03b2-batches.\n//\n// What this proves end-to-end:\n//   1. \u03b11's pipeline list endpoint returns data \u2192 React renders it\n//   2. \u03b12's cascade scope filters \u2192 caller sees only own/scope deals\n//   3. \u03b13's CRUD endpoint Pydantic typing \u2192 matches our TypeScript shape\n//   4. \u03b17's permissions object \u2192 React reads it without recomputing auth\n//   5. The Bearer-header JWT lifecycle from Phase 1 \u2192 carries through\n//      to a brand-new authenticated endpoint\n//   6. The Provider pattern from Batch 2d \u2192 extends cleanly to a new domain\n//\n// Layout pattern matches Dashboard.tsx:\n//   - Header strip with brand.secondary background (deep navy)\n//   - max-w-7xl content column\n//   - Stat strip at top for at-a-glance metrics\n//   - Card-wrapped Table for the deal list\n//   - Footer with branding ip_notice\n//\n// Composition: 100% bespoke v10.496 primitives. No new visual atoms.\n\nimport { displayName } from \"../lib/names\";\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport { useNavigate, useSearchParams } from 'react-router-dom';\nimport { useBranding } from '@/hooks/useBranding';\nimport { usePipelineDeals } from '@/hooks/usePipelineDeals';\nimport { useRole } from '@/hooks/useRole';\nimport { fetchPipelineConfig, fetchPipelineAnalytics, fetchFunnelDrill, downloadFile } from '@/lib/api';\nimport { Card } from '@/components/Card';\nimport DefinedFunnel from '@/components/DefinedFunnel';\nimport { PageHeader } from '@/components/PageHeader';\nimport { Stat } from '@/components/Stat';\nimport { Badge, type BadgeTone } from '@/components/Badge';\nimport { Button } from '@/components/Button';\nimport { Table, type Column } from '@/components/Table';\nimport { PermissionBadges } from '@/components/PermissionBadges';\nimport { parseTs } from '@/lib/datetime';\nimport {\n  stageTone,\n  type PipelineDeal,\n  type PipelineConfig,\n  type PipelineAnalyticsResponse,\n  type FunnelDrillResponse,\n} from '@/types/pipeline';\n\n\n// \u2500\u2500 Display helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n/** Format a deal_value in the tenant's currency. Compact format for table cells. */\nfunction formatValue(v: number, symbol: string): string {\n  if (!Number.isFinite(v) || v === 0) return '\u2014';\n  // COMPACT ABOVE A MILLION. \"KES 632,907,965.8\" is eighteen characters and\n  // overflowed the card at text-3xl; nobody reads the last six digits of a\n  // pipeline total anyway. The exact figure stays in the tooltip.\n  const abs = Math.abs(v);\n  if (abs >= 1_000_000_000) return `${symbol} ${(v / 1_000_000_000).toFixed(2)}B`;\n  if (abs >= 1_000_000) return `${symbol} ${(v / 1_000_000).toFixed(1)}M`;\n  return `${symbol} ${Math.round(v).toLocaleString()}`;\n}\n\n/** The exact figure, for a title attribute - compact display should never be\n *  the only place a number exists. */\nfunction exactValue(v: number, symbol: string): string {\n  if (!Number.isFinite(v)) return '\u2014';\n  return `${symbol} ${v.toLocaleString(undefined, { maximumFractionDigits: 2 })}`;\n}\n\n/** Days a deal has been open, from its earliest available timestamp. */\nfunction daysOpen(deal: PipelineDeal): number | null {\n  const raw = deal.created_at || deal.open_date || deal.updated_at;\n  if (!raw) return null;\n  // parseTs, not new Date: a date-only open_date must anchor to LOCAL midnight,\n  // otherwise the age is measured from 03:00 and can round down a whole day.\n  const parsed = parseTs(raw);\n  if (!parsed) return null;\n  const start = parsed.getTime();\n  if (!Number.isFinite(start)) return null;\n  const diff = Date.now() - start;\n  if (diff < 0) return 0;\n  return Math.floor(diff / 86_400_000);\n}\n\n/** Traffic-light cell for a deal's attached SLA status. Null when no SLA applies\n *  (closed / no timestamp). */\nfunction slaCell(deal: PipelineDeal): { tone: BadgeTone; label: string; title: string } | null {\n  const s = deal.sla;\n  if (!s || !s.state) return null;\n  const clock = s.clock === 'step' ? (s.step || 'step').replace(/_/g, ' ') : 'age';\n  if (s.state === 'breached') {\n    return {\n      tone: 'danger',\n      label: `breached +${s.overdue_business_days ?? 0}`,\n      title: `${clock}: ${s.elapsed_business_days ?? '?'}/${s.target_days ?? '?'} bd \u2014 escalate to ${(s.escalate_to || '').replace(/_/g, ' ') || 'step owner'}`,\n    };\n  }\n  if (s.state === 'due_soon') {\n    return { tone: 'warning', label: 'due soon', title: `${clock}: ${s.remaining_business_days ?? '?'} bd to target` };\n  }\n  return { tone: 'success', label: 'on track', title: `${clock}: ${s.remaining_business_days ?? '?'} bd to target` };\n}\n\n\n// \u2500\u2500 Page component \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport function Pipeline() {\n  const { branding } = useBranding();\n  const { user } = useRole();\n  const { deals, count, loading, error, refetch } = usePipelineDeals();\n\n  // SLA traffic-light filter, driven by ?sla=on_track|due_soon|breached (e.g. from the\n  // Analytics SLA summary card). Filters the already-loaded deals client-side on sla.state.\n  const [searchParams, setSearchParams] = useSearchParams();\n  const slaFilter = searchParams.get('sla');\n  // Win-probability band filter (?winprob=high|medium|low). high \u226575, medium 40\u201374,\n  // low <40 \u2014 derived per-deal from the current stage's product flow. Combines with sla.\n  const winprobFilter = searchParams.get('winprob');\n  const winprobBand = (wp: number | null | undefined): 'high' | 'medium' | 'low' | null => {\n    if (typeof wp !== 'number') return null;\n    return wp >= 75 ? 'high' : wp >= 40 ? 'medium' : 'low';\n  };\n  const [config, setConfig] = useState<PipelineConfig | null>(null);\n  const [segmentFilter, setSegmentFilter] = useState('');\n  // Two-level segment model, sourced from the configurable business units (customer_segments):\n  //   Business unit (Consumer/Commercial/CIB/Treasury) -> its sub-segments (Premier/SME/...).\n  // Each visible deal's sub-segment is resolved to its business unit via a reverse map, then\n  // grouped by unit. A single-unit viewer (e.g. Consumer) therefore sees ONLY that unit's\n  // sub-segments; a leaked cross-unit value groups under its OWN unit, never polluting another.\n  const segmentGroups = useMemo(() => {\n    const cfgSegs = config?.customer_segments ?? {};\n    // reverse map: sub-segment -> business unit\n    const subToUnit = new Map<string, string>();\n    for (const [unit, subs] of Object.entries(cfgSegs)) {\n      for (const sub of subs) subToUnit.set(sub, unit);\n    }\n    // tally sub-segment counts present in visible deals\n    const counts = new Map<string, number>();\n    for (const d of deals) {\n      const k = (d.segment && String(d.segment).trim()) || 'Unclassified';\n      counts.set(k, (counts.get(k) ?? 0) + 1);\n    }\n    // build ordered groups: business unit -> [{key, count}] in config order\n    const groups: { unit: string; subs: { key: string; count: number }[] }[] = [];\n    for (const [unit, subs] of Object.entries(cfgSegs)) {\n      const present = subs\n        .filter((sub) => counts.has(sub))\n        .map((sub) => ({ key: sub, count: counts.get(sub) ?? 0 }));\n      if (present.length) groups.push({ unit, subs: present });\n    }\n    // any present sub-segment that IS a bare business-unit name (mis-tagged) or unknown:\n    // collect under an 'Other' group so it's visible but not mixed into a real unit.\n    const known = new Set<string>();\n    for (const g of groups) for (const s of g.subs) known.add(s.key);\n    const other: { key: string; count: number }[] = [];\n    for (const [k, c] of counts.entries()) {\n      if (k === 'Unclassified') continue;\n      if (!known.has(k) && !subToUnit.has(k)) other.push({ key: k, count: c });\n    }\n    if (other.length) groups.push({ unit: 'Other', subs: other });\n    if (counts.has('Unclassified')) {\n      groups.push({ unit: 'Unclassified', subs: [{ key: 'Unclassified', count: counts.get('Unclassified') ?? 0 }] });\n    }\n    return groups;\n  }, [deals, config]);\n\n  // \u2500\u2500 THE BUSINESS-LINE SELECTOR, BESIDE THE FUNNEL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // It used to sit above the deal list as a row of chips that wrapped, with\n  // sub-segments inline beside their line - so \"Consumer Premier Direct\n  // Advantage Commercial SME...\" ran together and the shape of the hierarchy\n  // was lost. Vertical, it reads as what it is: three lines, each with its own\n  // sub-segments underneath.\n  //\n  // It lives in the funnel's empty right-hand side, which puts the thing you\n  // filter BY next to the thing it filters - and the funnel now follows the\n  // selection, so the two panels always describe the same book.\n  const segmentAside = segmentGroups.length === 0 ? null : (\n    <div role=\"tablist\" aria-label=\"Filter by segment\" className=\"text-sm\">\n      <div className=\"mb-2 text-[11px] font-semibold uppercase tracking-wide text-gray-600\">\n        Business line\n      </div>\n      <button\n        type=\"button\"\n        onClick={() => setSegmentFilter('')}\n        className={[\n          'mb-1 w-full rounded-md px-2.5 py-1.5 text-left text-xs font-semibold transition-colors',\n          segmentFilter === '' ? 'bg-[#005B82] text-white'\n                               : 'text-gray-900 hover:bg-[#0082BB]/10 hover:text-[#005B82]',\n        ].join(' ')}\n      >\n        All\n      </button>\n      {segmentGroups.map((g) => {\n        const unitKey = `unit:${g.unit}`;\n        const unitOn = segmentFilter === unitKey;\n        const total = g.subs.reduce((a, x) => a + x.count, 0);\n        return (\n          <div key={g.unit} className=\"mb-1\">\n            <button\n              type=\"button\"\n              onClick={() => setSegmentFilter(unitOn ? '' : unitKey)}\n              title={`All ${g.unit} deals`}\n              className={[\n                'flex w-full items-center justify-between rounded-md px-2.5 py-1.5',\n                'text-xs font-semibold transition-colors',\n                unitOn ? 'bg-[#005B82] text-white'\n                       : 'text-gray-900 hover:bg-[#0082BB]/10 hover:text-[#005B82]',\n              ].join(' ')}\n            >\n              <span>{g.unit}</span>\n              <span className={unitOn ? 'text-white/80'\n                                      : 'font-semibold text-[#005B82]'}>{total}</span>\n            </button>\n            {/* Sub-segments sit UNDER their line, indented, so the hierarchy\n                is visible rather than implied by ordering. */}\n            <div className=\"ml-2 border-l-2 border-[#0082BB]/25 pl-2\">\n              {g.subs.map((sg) => {\n                const on = segmentFilter === sg.key;\n                return (\n                  <button\n                    key={sg.key}\n                    type=\"button\"\n                    onClick={() => setSegmentFilter(on ? '' : sg.key)}\n                    className={[\n                      'flex w-full items-center justify-between rounded-md px-2 py-1',\n                      'text-[11px] transition-colors',\n                      on ? 'bg-[#0082BB]/15 font-semibold text-[#005B82]'\n                         : 'text-gray-700 hover:bg-[#0082BB]/10 hover:text-[#005B82]',\n                    ].join(' ')}\n                  >\n                    <span className=\"truncate\">{sg.key}</span>\n                    <span className=\"ml-2 shrink-0 font-medium text-gray-600\">{sg.count}</span>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n        );\n      })}\n    </div>\n  );\n\n  const visibleDeals = useMemo(\n    () => deals.filter((d) =>\n      (!slaFilter || d.sla?.state === slaFilter)\n      && (!winprobFilter || winprobBand(d.win_probability) === winprobFilter)\n      // A filter of `unit:Consumer` matches every sub-segment configured under\n      // Consumer, so the line can be read as one. Anything else is the exact\n      // sub-segment, as before.\n      && (!segmentFilter\n          || (segmentFilter.startsWith('unit:')\n              ? (segmentGroups.find((g) => `unit:${g.unit}` === segmentFilter)?.subs ?? [])\n                  .some((sg) => sg.key === (d.segment || 'Unclassified'))\n              : (d.segment || 'Unclassified') === segmentFilter))),\n    [deals, slaFilter, winprobFilter, segmentFilter, segmentGroups],\n  );\n  const clearSlaFilter = () => {\n    const next = new URLSearchParams(searchParams);\n    next.delete('sla');\n    setSearchParams(next, { replace: true });\n  };\n  const setWinprobFilter = (band: string) => {\n    const next = new URLSearchParams(searchParams);\n    if (band) next.set('winprob', band); else next.delete('winprob');\n    setSearchParams(next, { replace: true });\n  };\n\n  // Batch A: admin-configured category/stage filters (from /api/pipeline/stages)\n  const [catFilter, setCatFilter] = useState('');\n  const [stageFilter, setStageFilter] = useState('');\n\n  // Funnel stage-drill: click a band \u2192 fetch deals at that class+stage,\n  // broken down by product and segment.\n  const [drill, setDrill] = useState<FunnelDrillResponse | null>(null);\n  const [drillLoading, setDrillLoading] = useState(false);\n  const [drillVisible, setDrillVisible] = useState(50);\n  const [exporting, setExporting] = useState(false);\n  const drillRef = useRef<HTMLDivElement | null>(null);\n  const onStageDrill = (cls: string, stage: string): void => {\n    setDrillLoading(true);\n    setDrill(null);\n    setDrillVisible(50);\n    fetchFunnelDrill(cls, stage)\n      .then((d) => setDrill(d))\n      .catch(() => setDrill(null))\n      .finally(() => setDrillLoading(false));\n  };\n  // When the drill opens, bring the panel into view (the funnel can be tall,\n  // so the panel would otherwise open below the fold).\n  useEffect(() => {\n    if (drill && drillRef.current) {\n      drillRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    }\n  }, [drill]);\n\n  useEffect(() => {\n    let active = true;\n    fetchPipelineConfig()\n      .then((c) => { if (active) setConfig(c); })\n      .catch(() => { /* dropdowns stay empty if config can't load */ });\n    return () => { active = false; };\n  }, []);\n\n  // Analytics: validated/pending split, per-class buckets, the validated\n  // funnel, and the scope-aware pending-validation count. Refetched whenever\n  // the deal list settles (after create/validate/advance/refresh).\n  const [analytics, setAnalytics] = useState<PipelineAnalyticsResponse | null>(null);\n  useEffect(() => {\n    if (loading) return;\n    let active = true;\n    // THE HEADLINE FIGURES FOLLOW THE BUSINESS LINE, like the funnel below\n    // them. Without this the top of the page described the whole book while\n    // everything under it described one line.\n    fetchPipelineAnalytics({\n      unit: segmentFilter.startsWith('unit:') ? segmentFilter.slice(5) : undefined,\n      segment: segmentFilter && !segmentFilter.startsWith('unit:') ? segmentFilter : undefined,\n    })\n      .then((a) => { if (active) setAnalytics(a); })\n      .catch(() => { /* tiles fall back to local sums if analytics fails */ });\n    return () => { active = false; };\n  }, [loading, count, segmentFilter]);\n\n  // Stage options narrow to the selected category's flow; else all stages.\n  const stageOptions = useMemo(() => {\n    if (!config) return [] as string[];\n    if (catFilter) {\n      const cat = config.deal_categories.find((c) => c.category === catFilter);\n      if (cat) return cat.stages;\n    }\n    return config.stages.map((s) => s.stage);\n  }, [config, catFilter]);\n\n  const onCategoryChange = (value: string) => {\n    setCatFilter(value);\n    setStageFilter('');\n    void refetch({ category: value || undefined });\n  };\n  const onStageChange = (value: string) => {\n    setStageFilter(value);\n    void refetch({ category: catFilter || undefined, stage: value || undefined });\n  };\n  const navigate = useNavigate();\n\n  const sym = branding?.currency_symbol ?? '';\n\n  // Table column config \u2014 typed against PipelineDeal so render functions\n  // get full intellisense on row data.\n  const columns: Column<PipelineDeal>[] = useMemo(() => [\n    {\n      key: 'id',\n      header: 'Deal ID',\n      width: 110,\n      sortable: true,\n      exportValue: (row) => row.id,\n      render: (row) => (\n        <span className=\"font-mono text-xs text-gray-600\">{row.id}</span>\n      ),\n    },\n    {\n      key: 'client_name',\n      header: 'Client',\n      sortable: true,\n      exportValue: (row) => row.client_name || '',\n      render: (row) => (\n        <div>\n          <div className=\"font-medium text-gray-900\">{row.client_name || '\u2014'}</div>\n          {row.product_type && (\n            <div className=\"text-xs text-gray-500 mt-0.5\">{row.product_type}</div>\n          )}\n        </div>\n      ),\n    },\n    {\n      key: 'stage',\n      header: 'Stage',\n      sortable: true,\n      exportValue: (row) => row.stage,\n      render: (row) => (\n        <Badge tone={stageTone(row.stage)} size=\"sm\">{row.stage}</Badge>\n      ),\n    },\n    {\n      key: 'deal_value',\n      header: 'Value',\n      align: 'right',\n      sortable: true,\n      sortAccessor: (row) => Number(row.amount_kes ?? row.deal_value) || 0,\n      exportValue: (row) => String(row.amount_kes ?? row.deal_value ?? ''),\n      render: (row) => (\n        <span className=\"font-medium text-gray-900\">\n          {formatValue(Number(row.amount_kes ?? row.deal_value), branding?.currency_symbol ?? '')}\n        </span>\n      ),\n    },\n    {\n      key: 'aging',\n      header: 'Age',\n      align: 'right',\n      sortable: true,\n      sortAccessor: (row) => daysOpen(row) ?? -1,\n      exportValue: (row) => { const d = daysOpen(row); return d == null ? '' : String(d); },\n      render: (row) => {\n        const d = daysOpen(row);\n        if (d == null) return <span className=\"text-xs text-gray-400\">\u2014</span>;\n        const stale = d > 14;\n        return (\n          <span className={`text-xs font-medium ${stale ? 'text-red-600' : 'text-gray-600'}`}>\n            {d}d{stale ? ' \u00b7 stale' : ''}\n          </span>\n        );\n      },\n    },\n    {\n      key: 'sla',\n      header: 'SLA',\n      exportValue: (row) => row.sla?.state || '',\n      render: (row) => {\n        const c = slaCell(row);\n        if (!c) return <span className=\"text-xs text-gray-300\">\u2014</span>;\n        return <span title={c.title}><Badge tone={c.tone} size=\"sm\">{c.label}</Badge></span>;\n      },\n    },\n    {\n      key: 'win_probability',\n      header: 'Win %',\n      align: 'right',\n      sortable: true,\n      sortAccessor: (row) => (typeof row.win_probability === 'number' ? row.win_probability : -1),\n      exportValue: (row) => (typeof row.win_probability === 'number' ? String(row.win_probability) : ''),\n      render: (row) => {\n        const wp = row.win_probability;\n        if (typeof wp !== 'number') return <span className=\"text-xs text-gray-300\">\u2014</span>;\n        const tone: BadgeTone = wp >= 75 ? 'success' : wp >= 40 ? 'info' : 'neutral';\n        return (\n          <span title=\"Likelihood of closing, from the current stage's product flow\">\n            <Badge tone={tone} size=\"sm\">{Math.round(wp)}%</Badge>\n          </span>\n        );\n      },\n    },\n    {\n      key: 'staff_name',\n      header: 'Owner',\n      sortable: true,\n      exportValue: (row) => row.staff_name || '',\n      render: (row) => (\n        <div>\n          <div className=\"text-sm text-gray-800\">{row.staff_name ? displayName(row.staff_name) : '\u2014'}</div>\n          {row.staff_code && (\n            <div className=\"text-xs text-gray-400 mt-0.5 font-mono\">\n              {row.staff_code}\n            </div>\n          )}\n        </div>\n      ),\n    },\n    {\n      key: 'permissions',\n      header: 'You can',\n      render: (row) => <PermissionBadges permissions={row.permissions} />,\n    },\n  // intentionally not depending on the dynamic data; column config is stable\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  ], [branding?.currency_symbol]);\n\n  // \u2500\u2500 Render \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  return (\n    <div className=\"min-h-screen bg-gray-50\">\n      <PageHeader\n        ribbon\n        // STICKY: the ribbon carries Export and New Deal, and it scrolled away\n        // the moment somebody moved down the deal list - so the two things they\n        // most often want were only reachable by scrolling back up.\n        sticky\n        // The breadcrumb repeated what the bar above already says. One trail is\n        // a trail; two is noise. The subtitle carries the only line that was\n        // adding anything.\n        title=\"A2Z Sales Pro\"\n        subtitle=\"Your pipeline\"\n        actions={\n          <>\n            <Button\n              variant=\"secondary\"\n              onClick={() => {\n                setExporting(true);\n                downloadFile('/pipeline/export/xlsx', 'EKE_Pipeline.xlsx')\n                  .catch(() => { /* surfaced via button state only */ })\n                  .finally(() => setExporting(false));\n              }}\n              disabled={exporting}\n            >\n              {exporting ? 'Exporting\u2026' : 'Export Excel'}\n            </Button>\n            <Button variant=\"primary\" onClick={() => navigate('/pipeline/new')}>\n              + New Deal\n            </Button>\n          </>\n        }\n      />\n\n      {/* Main content */}\n      <main className=\"max-w-7xl 2xl:max-w-[1680px] mx-auto px-6 py-8\">\n        {/* Assured pipeline by product class \u2014 validated value headline,\n            pending-assurance beneath. Sourced from /api/pipeline/analytics. */}\n        {/* FOUR ACROSS, and now exactly four cards. With five children the fifth\n            wrapped onto a row of its own and the block looked broken. */}\n        <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <Stat\n            label=\"Asset Pipeline\"\n            value={analytics ? formatValue(analytics.pipelines.asset.value, sym) : '\u2014'}\n            titleText={analytics ? exactValue(analytics.pipelines.asset.value, sym) : undefined}\n            sub={analytics && analytics.pipelines.asset.pending_value > 0\n              ? `${formatValue(analytics.pipelines.asset.pending_value, sym)} pending assurance`\n              : 'Assured'}\n            loading={loading}\n            stripe={false}\n            tone=\"primary\"\n            onClick={() => navigate('/analytics')}\n          />\n          <Stat\n            label=\"Liability Pipeline\"\n            value={analytics ? formatValue(analytics.pipelines.liability.value, sym) : '\u2014'}\n            titleText={analytics ? exactValue(analytics.pipelines.liability.value, sym) : undefined}\n            sub={analytics && analytics.pipelines.liability.pending_value > 0\n              ? `${formatValue(analytics.pipelines.liability.pending_value, sym)} pending assurance`\n              : 'Assured'}\n            loading={loading}\n            stripe={false}\n            tone=\"success\"\n            onClick={() => navigate('/analytics')}\n          />\n          <Stat\n            label=\"Insurance\"\n            value={analytics ? formatValue(analytics.pipelines.insurance.value, sym) : '\u2014'}\n            sub={analytics && analytics.pipelines.insurance.pending_value > 0\n              ? `${formatValue(analytics.pipelines.insurance.pending_value, sym)} pending assurance`\n              : 'Assured'}\n            loading={loading}\n            stripe={false}\n            tone=\"lime\"\n            onClick={() => navigate('/analytics')}\n          />\n          <Stat\n            label=\"Other\"\n            value={analytics ? formatValue(analytics.pipelines.other.value, sym) : '\u2014'}\n            sub={analytics && analytics.pipelines.other.pending_value > 0\n              ? `${formatValue(analytics.pipelines.other.pending_value, sym)} pending assurance`\n              : 'Assured'}\n            loading={loading}\n            stripe={false}\n            tone=\"violet\"\n            onClick={() => navigate('/analytics')}\n          />\n        </div>\n\n        {/* Scope summary row */}\n        <div className=\"grid grid-cols-1 md:grid-cols-3 gap-4 mt-4\">\n          <Stat\n            label=\"Deals Visible\"\n            value={loading ? '\u2014' : count}\n            sub=\"In your cascade scope\"\n            loading={loading}\n            stripe={false}\n            tone=\"teal\"\n            onClick={() => navigate('/analytics')}\n          />\n          <Stat\n            label=\"Pending Validation\"\n            value={analytics ? analytics.totals.pending_validation : (loading ? '\u2014' : 0)}\n            sub={analytics && analytics.totals.pending_validation > 0\n              ? 'Awaiting your sign-off'\n              : 'Nothing to validate'}\n            loading={loading}\n            stripe={false}\n            tone={analytics && analytics.totals.pending_validation > 0 ? 'accent' : 'neutral'}\n            onClick={() => navigate('/pipeline/queues')}\n          />\n          {/* \"Total Assured\" REMOVED (ruling 2026-08-13): it added the asset\n              and liability books together, which is not a number anybody uses -\n              a loan and a deposit do not sum to anything meaningful. The two\n              books are already shown separately above. */}\n        </div>\n\n        {/* Validated pipeline funnel */}\n        <DefinedFunnel\n          onStageClick={onStageDrill}\n          unit={segmentFilter.startsWith('unit:') ? segmentFilter.slice(5) : undefined}\n          segment={segmentFilter && !segmentFilter.startsWith('unit:')\n            ? segmentFilter : undefined}\n          aside={segmentAside}\n        />\n\n        {/* Funnel stage-drill panel */}\n        {(drillLoading || drill) && (\n          <div ref={drillRef} className=\"scroll-mt-24\">\n          <Card className=\"mt-4 ring-2 ring-[var(--brand-primary)]/30\">\n            <Card.Header>\n              <h2 className=\"text-base font-semibold text-gray-900\">\n                {drill ? `${drill.cls === 'all' ? 'All' : drill.cls[0].toUpperCase() + drill.cls.slice(1)} \u00b7 ${drill.stage}` : 'Loading\u2026'}\n              </h2>\n              <button\n                type=\"button\"\n                onClick={() => setDrill(null)}\n                className=\"text-xs text-gray-400 hover:text-gray-700\"\n              >\n                Close \u2715\n              </button>\n            </Card.Header>\n            <Card.Body>\n              {drillLoading && <div className=\"h-24 animate-pulse rounded bg-gray-100\" />}\n              {drill && (\n                <div>\n                  <div className=\"mb-4 text-sm text-gray-500\">\n                    <span className=\"font-semibold text-gray-800\">{drill.totals.count}</span> assured deals \u00b7{' '}\n                    <span className=\"font-semibold text-gray-800\">{formatValue(drill.totals.value, sym)}</span>\n                  </div>\n                  <div className=\"grid gap-6 md:grid-cols-3\">\n                    <DrillBreakdown title=\"By segment\" rows={drill.by_segment.map((s) => ({ label: s.segment, value: s.value, count: s.count }))} sym={sym} />\n                    <DrillBreakdown title=\"By sector\" rows={drill.by_sector.map((s) => ({ label: s.sector, value: s.value, count: s.count }))} sym={sym} />\n                    <DrillBreakdown title=\"By product\" rows={drill.by_product.map((p) => ({ label: p.product, value: p.value, count: p.count }))} sym={sym} />\n                  </div>\n                  {drill.deals.length > 0 && (\n                    <div className=\"mt-6 overflow-x-auto\">\n                      <table className=\"w-full text-sm\">\n                        <thead>\n                          <tr className=\"border-b border-gray-200 text-left text-xs text-gray-500\">\n                            <th className=\"py-2 pr-3\">Deal</th>\n                            <th className=\"py-2 pr-3\">Client</th>\n                            <th className=\"py-2 pr-3\">Product</th>\n                            <th className=\"py-2 pr-3\">Segment</th>\n                            <th className=\"py-2 pr-3 text-right\">Value</th>\n                            <th className=\"py-2 pr-3\">Owner</th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          {drill.deals.slice(0, drillVisible).map((d) => (\n                            <tr key={d.id} className=\"border-b border-gray-100\">\n                              <td className=\"py-1.5 pr-3 font-mono text-xs text-gray-500\">{d.id}</td>\n                              <td className=\"py-1.5 pr-3 text-gray-800\">{d.client_name}</td>\n                              <td className=\"py-1.5 pr-3 text-gray-600\">{d.product_type}</td>\n                              <td className=\"py-1.5 pr-3 text-gray-600\">{d.segment}</td>\n                              <td className=\"py-1.5 pr-3 text-right tabular-nums text-gray-800\">{formatValue(d.amount_kes, sym)}</td>\n                              <td className=\"py-1.5 pr-3 text-gray-600\">{displayName(d.staff_name)}</td>\n                            </tr>\n                          ))}\n                        </tbody>\n                      </table>\n                      {drill.deals.length > drillVisible ? (\n                        <div className=\"mt-2 flex items-center gap-3\">\n                          <Button variant=\"ghost\" size=\"sm\" onClick={() => setDrillVisible((n) => n + 50)}>\n                            Show more ({drill.deals.length - drillVisible} more)\n                          </Button>\n                          <span className=\"text-xs text-gray-400\">Showing {drillVisible} of {drill.deals.length}</span>\n                        </div>\n                      ) : drill.deals.length > 50 ? (\n                        <div className=\"mt-2 text-xs text-gray-400\">Showing all {drill.deals.length} deals.</div>\n                      ) : null}\n                    </div>\n                  )}\n                </div>\n              )}\n            </Card.Body>\n          </Card>\n          </div>\n        )}\n\n        {/* Error panel \u2014 only renders on error */}\n        {error && (\n          <Card className=\"mt-6\">\n            <Card.Body>\n              <div className=\"flex items-center gap-3\">\n                <Badge tone=\"danger\">Error</Badge>\n                <div className=\"flex-1 text-sm text-gray-700\">{error}</div>\n                <Button variant=\"ghost\" size=\"sm\" onClick={() => void refetch()}>\n                  Retry\n                </Button>\n              </div>\n            </Card.Body>\n          </Card>\n        )}\n\n        {/* Deal table */}\n        <Card className=\"mt-8\" padding=\"none\">\n          <Card.Header>\n            <div className=\"flex items-center gap-3\">\n              <h2 className=\"text-base font-semibold text-gray-900\">\n                Pipeline Deals\n              </h2>\n                </div>\n            <div className=\"flex items-center gap-2\">\n              <select\n                value={catFilter}\n                onChange={(e) => onCategoryChange(e.target.value)}\n                aria-label=\"Filter by deal category\"\n                className=\"h-9 px-2 rounded-md border border-gray-300 bg-white text-sm text-gray-900 focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n              >\n                <option value=\"\">All categories</option>\n                {config?.deal_categories.map((c) => (\n                  <option key={c.category} value={c.category}>{c.category}</option>\n                ))}\n              </select>\n              <select\n                value={stageFilter}\n                onChange={(e) => onStageChange(e.target.value)}\n                aria-label=\"Filter by stage\"\n                className=\"h-9 px-2 rounded-md border border-gray-300 bg-white text-sm text-gray-900 focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n              >\n                <option value=\"\">All stages</option>\n                {stageOptions.map((s) => (\n                  <option key={s} value={s}>{s}</option>\n                ))}\n              </select>\n              <select\n                value={winprobFilter ?? ''}\n                onChange={(e) => setWinprobFilter(e.target.value)}\n                aria-label=\"Filter by win probability\"\n                className=\"h-9 px-2 rounded-md border border-gray-300 bg-white text-sm text-gray-900 focus:outline-none focus:border-brand-primary focus:ring-2 focus:ring-brand-primary/20\"\n              >\n                <option value=\"\">All win %</option>\n                <option value=\"high\">High (\u226575%)</option>\n                <option value=\"medium\">Medium (40\u201374%)</option>\n                <option value=\"low\">Low (&lt;40%)</option>\n              </select>\n              <Button\n                variant=\"ghost\"\n                size=\"sm\"\n                onClick={() => void refetch()}\n                loading={loading}\n              >\n                Refresh\n              </Button>\n            </div>\n          </Card.Header>\n          <Card.Body className=\"p-4\">\n            {slaFilter && (\n              <div className=\"mb-3 flex items-center gap-2 text-sm\">\n                <span className=\"text-gray-500\">SLA filter:</span>\n                <Badge\n                  tone={slaFilter === 'breached' ? 'danger' : slaFilter === 'due_soon' ? 'warning' : 'success'}\n                  size=\"sm\"\n                >\n                  {slaFilter.replace(/_/g, ' ')}\n                </Badge>\n                <span className=\"text-xs text-gray-400\">{visibleDeals.length} of {deals.length}</span>\n                <button onClick={clearSlaFilter} className=\"text-xs text-brand-primary hover:underline\">clear</button>\n              </div>\n            )}\n            {winprobFilter && (\n              <div className=\"mb-3 flex items-center gap-2 text-sm\">\n                <span className=\"text-gray-500\">Win probability:</span>\n                <Badge\n                  tone={winprobFilter === 'high' ? 'success' : winprobFilter === 'medium' ? 'info' : 'neutral'}\n                  size=\"sm\"\n                >\n                  {winprobFilter === 'high' ? 'High (\u226575%)' : winprobFilter === 'medium' ? 'Medium (40\u201374%)' : 'Low (<40%)'}\n                </Badge>\n                <span className=\"text-xs text-gray-400\">{visibleDeals.length} of {deals.length}</span>\n                <button onClick={() => setWinprobFilter('')} className=\"text-xs text-brand-primary hover:underline\">clear</button>\n              </div>\n            )}\n            <Table<PipelineDeal>\n              columns={columns}\n              rows={visibleDeals}\n              rowKey=\"id\"\n              loading={loading}\n              searchable\n              searchPlaceholder=\"Search deals by client, stage, owner\u2026\"\n              paginated\n              pageSize={25}\n              onRowClick={(row) => navigate(`/pipeline/${encodeURIComponent(row.id)}`)}\n              empty={\n                <div className=\"py-8\">\n                  <div className=\"text-base text-gray-700 font-medium\">\n                    No deals in your scope.\n                  </div>\n                  <div className=\"text-sm text-gray-500 mt-1\">\n                    {user?.role && `As ${user.role}, you see deals from your cascade.`}\n                  </div>\n                </div>\n              }\n            />\n          </Card.Body>\n        </Card>\n\n        {/* IP notice footer \u2014 verbatim from /api/branding */}\n        <footer className=\"mt-12 pb-6 text-center text-[11px] text-gray-400 leading-relaxed\">\n          {branding?.ip_notice}\n        </footer>\n      </main>\n    </div>\n  );\n}\n\n// \u2500\u2500 Drill breakdown: a compact value-ranked bar list (segment / product) \u2500\u2500\nfunction DrillBreakdown({\n  title, rows, sym,\n}: {\n  title: string;\n  rows: { label: string; value: number; count: number }[];\n  sym: string;\n}) {\n  const max = Math.max(...rows.map((r) => r.value), 1);\n  const PALETTE = ['#06b6d4', '#3b82f6', '#6366f1', '#a855f7', '#ec4899', '#f59e0b', '#10b981', '#14b8a6'];\n  return (\n    <div>\n      <div className=\"mb-2 text-xs font-semibold uppercase tracking-wide text-gray-400\">{title}</div>\n      {rows.length === 0 ? (\n        <div className=\"text-sm text-gray-400\">No data.</div>\n      ) : (\n        <div className=\"space-y-2\">\n          {rows.slice(0, 8).map((r, i) => (\n            <div key={r.label} className=\"flex items-center gap-3\">\n              <div className=\"w-28 shrink-0 truncate text-xs text-gray-600\" title={r.label}>{r.label}</div>\n              <div className=\"h-4 flex-1 rounded bg-gray-100\">\n                <div\n                  className=\"h-4 rounded\"\n                  style={{ width: `${Math.max(4, Math.round((r.value / max) * 100))}%`, background: PALETTE[i % PALETTE.length] }}\n                />\n              </div>\n              <div className=\"w-32 shrink-0 text-right text-xs text-gray-500\">\n                {formatValue(r.value, sym)} <span className=\"text-gray-400\">\u00b7 {r.count}</span>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
 "frontend/web/src/components/CommitteeQueue.tsx": "// Cases waiting on a committee this person sits on.\n//\n// RULING (2026-08-12): the branch managers were gathered and nothing moved.\n// Once the committees existed, the reason it still would not have moved is\n// that MEMBERS HAD NOWHERE TO LOOK - a decision could only be recorded by\n// knowing a deal id and opening it. A committee that cannot find its own cases\n// is not a committee.\n//\n// NO NEW SIDEBAR ENTRY (ruling: \"I am avoiding too many side bars\"). This\n// mounts inside Manager Queues for managers and inside the Daily Log for\n// everybody else, so a committee member meets it where they already work.\n//\n// Review takes them to the deal, where the committee panel already lives -\n// rather than building a second decision surface that could drift from it.\nimport { useCallback, useEffect, useState } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { fetchCommitteeQueue, type CommitteeQueueResponse } from '@/lib/api';\n\nexport function CommitteeQueue({ compact = false }: { compact?: boolean }) {\n  const nav = useNavigate();\n  const [data, setData] = useState<CommitteeQueueResponse | null>(null);\n  const [loading, setLoading] = useState(false);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    try {\n      setData(await fetchCommitteeQueue());\n    } catch {\n      setData(null);\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n  useEffect(() => { void load(); }, [load]);\n\n  // Somebody on no committee sees nothing at all - an empty panel headed\n  // \"Committee\" would only make them wonder what they were missing.\n  if (!loading && (!data || data.committees.length === 0)) return null;\n\n  const kes = (n?: number) => (n == null ? \"\\u2014\" : n.toLocaleString());\n\n  return (\n    <div className={compact ? 'mt-4' : ''}>\n      <div className=\"mb-2 flex flex-wrap items-baseline justify-between gap-2\">\n        <div>\n          <h2 className=\"text-base font-semibold text-gray-900\">\n            Awaiting your committee\n          </h2>\n          <p className=\"text-xs text-gray-500\">\n            {(data?.committees ?? []).map((c) => c.name).join(' \\u00b7 ')}\n          </p>\n        </div>\n        <button type=\"button\" onClick={() => void load()}\n                className=\"text-xs text-gray-500 hover:text-gray-800\">\n          Refresh\n        </button>\n      </div>\n\n      {loading && (\n        <p className=\"py-6 text-center text-sm text-gray-400\">Loading\\u2026</p>\n      )}\n\n      {!loading && (data?.cases.length ?? 0) === 0 && (\n        <p className=\"rounded-lg border border-gray-200 bg-gray-50/60 py-6 text-center text-sm text-gray-500\">\n          Nothing waiting on your committee.\n        </p>\n      )}\n\n      {!loading && (data?.cases.length ?? 0) > 0 && (\n        <div className=\"overflow-hidden rounded-lg border border-gray-200\">\n          <table className=\"w-full text-sm\">\n            <thead className=\"bg-gray-50 text-left text-[11px] uppercase tracking-wide text-gray-500\">\n              <tr>\n                <th className=\"px-3 py-2\">Client</th>\n                <th className=\"px-3 py-2\">Product</th>\n                <th className=\"px-3 py-2 text-right\">Value</th>\n                <th className=\"px-3 py-2\">Owner</th>\n                <th className=\"px-3 py-2\">Committee</th>\n                <th className=\"px-3 py-2\" />\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-gray-100\">\n              {(data?.cases ?? []).map((c) => (\n                <tr key={c.deal_id} className=\"hover:bg-gray-50/60\">\n                  <td className=\"px-3 py-2 font-medium text-gray-900\">\n                    {c.client_name}\n                    <span className=\"ml-2 text-[11px] text-gray-400\">{c.deal_id}</span>\n                  </td>\n                  <td className=\"px-3 py-2 text-gray-700\">{c.product}</td>\n                  <td className=\"px-3 py-2 text-right tabular-nums text-gray-700\">\n                    {c.currency} {kes(c.deal_value)}\n                  </td>\n                  <td className=\"px-3 py-2 text-gray-600\">{c.owner}</td>\n                  <td className=\"px-3 py-2 text-[11px] text-gray-500\">\n                    {(c.awaiting_names ?? []).join(', ')}\n                  </td>\n                  <td className=\"px-3 py-2 text-right\">\n                    {/* SAY WHAT YOU DID, rather than \"Review\" for ever. A case\n                        stays listed because the COMMITTEE has not finished,\n                        which is a different thing from waiting on YOU. */}\n                    {c.you_voted && (\n                      <span className=\"mr-2 text-[11px] font-medium text-[#005B82]\">\n                        You: {c.your_vote === 'YES' ? 'recommended'\n                          : c.your_vote === 'NO' ? 'not recommended'\n                          : c.your_vote === 'ABSTAIN' ? 'abstained'\n                          : c.your_vote === 'RECUSED' ? 'recused' : 'voted'}\n                      </span>\n                    )}\n                    <button\n                      type=\"button\"\n                      // THE ROUTE IS /pipeline/{id}, not /pipeline/deals/{id}. The wrong path\n                      // matched no route at all, so React Router rendered nothing and\n                      // Review opened a blank page:\n                      //     No routes matched location \"/pipeline/deals/SIMBCC_FORTIS_03\"\n                      // Every other page in the app links this way; this one invented\n                      // a path that reads more logically and does not exist.\n                      onClick={() => nav(`/pipeline/${encodeURIComponent(c.deal_id)}`)}\n                      className={[\n                        'rounded-md px-3 py-1.5 text-xs font-semibold',\n                        c.you_voted\n                          ? 'border border-gray-300 text-gray-700 hover:bg-gray-50'\n                          : 'bg-brand-primary text-white hover:opacity-90',\n                      ].join(' ')}\n                    >\n                      {c.you_voted ? 'View' : 'Review'}\n                    </button>\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      )}\n    </div>\n  );\n}\n",
 "frontend/web/src/components/DefinedFunnel.tsx": "// DefinedFunnel \u2014 the pipeline centrepiece, drawn from ADMIN CONFIG.\n//\n// Ruling 2026-08-09: stages are never hardcoded. Every band here is a stage the\n// bank configured in that product's flow, in the order it configured them, with\n// the win probability it set for that stage WITHIN THAT FLOW.\n//\n// EMPTY STAGES ARE DRAWN. A funnel that hides the steps holding nothing is a bar\n// chart of whatever happened to be busy \u2014 and the empty step is usually the\n// finding: it is where deals stop arriving.\n//\n// THE CREDIT LAYER IS A SECOND AXIS, not a stage. Documentation / Branch Credit /\n// Department / Credit Analysis / Credit Administration / TROPS say where a deal\n// probably sits inside the bank, inferred from its probability. It sits beneath\n// the journey and never filters it.\n\nimport { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';\nimport { Card } from '@/components/Card';\nimport { useToast } from '@/components/Toast';\nimport { fetchPipelineDefinedFunnel, type DefinedFunnel as FunnelData, type DefinedFlow } from '@/lib/api';\n\n// Cool\u2192warm sweep: early stages cool, closing stages warm. Depth comes from a\n// vertical gradient plus a soft inner highlight, so a band reads as a solid\n// object rather than a coloured rectangle.\nconst PALETTE = ['#0082BB', '#0C7BC0', '#3F6FC4', '#6A61C0', '#9455B0', '#BE4E93', '#D75A72', '#E0A02B', '#669438'];\n\nfunction bandColour(i: number, n: number): string {\n  if (n <= 1) return PALETTE[0];\n  const seg = (i / (n - 1)) * (PALETTE.length - 1);\n  const idx = Math.min(Math.floor(seg), PALETTE.length - 2);\n  const t = seg - idx;\n  const hex = (h: string) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];\n  const [r1, g1, b1] = hex(PALETTE[idx]);\n  const [r2, g2, b2] = hex(PALETTE[idx + 1]);\n  const m = (a: number, b: number) => Math.round(a + (b - a) * t);\n  return `rgb(${m(r1, r2)}, ${m(g1, g2)}, ${m(b1, b2)})`;\n}\n\nfunction kes(n: number): string {\n  if (!n) return '\u2014';\n  return Math.round(n).toLocaleString();\n}\n\nexport interface DefinedFunnelProps {\n  /** Clicking a non-empty band drills into that flow + stage. Preserved from the\n   *  previous funnel: dropping it would have removed a working feature quietly. */\n  onStageClick?: (flow: string, stage: string) => void;\n  /** THE JOURNEY FOLLOWS THE SELECTION. Without this the funnel showed the\n   *  whole book while the list beneath it showed one line - two panels on one\n   *  screen describing different things. `unit` is a whole line (Consumer),\n   *  `segment` one sub-segment (Premier). */\n  unit?: string;\n  segment?: string;\n  /** Rendered beside the bands, where the funnel leaves space. */\n  aside?: ReactNode;\n}\n\nexport default function DefinedFunnel({ onStageClick, unit, segment, aside }: DefinedFunnelProps = {}) {\n  const { toast } = useToast();\n  const [data, setData] = useState<FunnelData | null>(null);\n  const [loading, setLoading] = useState(false);\n  // Distinct from `loading`: a REFRESH keeps the bands on screen and dims them;\n  // a load has nothing to show yet.\n  const [refreshing, setRefreshing] = useState(false);\n  const loadedOnce = useRef(false);\n  const [flowKey, setFlowKey] = useState('');\n  const [hover, setHover] = useState('');\n\n  useEffect(() => {\n    let alive = true;\n    // KEEP THE OLD NUMBERS ON SCREEN WHILE FETCHING THE NEW ONES. Selecting a\n    // business line blanked the whole card to \"Loading the journey...\" and\n    // then redrew it - a flash on every click, and a moment where the screen\n    // said nothing at all. The previous figures stay until the new ones\n    // arrive, dimmed so nobody reads a stale number as current.\n    // A REF, NOT `data`. Reading `data` here would be a stale closure, and\n    // adding it to the dependency list would loop: the effect sets data, which\n    // re-runs the effect. A ref answers \"has this ever loaded\" without taking\n    // part in the dependency graph.\n    setLoading(!loadedOnce.current);\n    setRefreshing(true);\n    void (async () => {\n      try {\n        const r = await fetchPipelineDefinedFunnel({ unit, segment });\n        if (!alive) return;\n        setData(r);\n        setFlowKey((k) => k || (r.flows[0]?.flow ?? ''));\n      } catch (e) {\n        if (alive) toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not load the funnel.' });\n      } finally {\n        if (alive) { loadedOnce.current = true; setLoading(false); setRefreshing(false); }\n      }\n    })();\n    return () => { alive = false; };\n  }, [toast, unit, segment]);\n\n  const flow: DefinedFlow | undefined = useMemo(\n    () => data?.flows.find((f) => f.flow === flowKey) ?? data?.flows[0],\n    [data, flowKey]);\n\n  const buckets = flow?.buckets ?? [];\n  // Micro-steps open on demand: management reads the six buckets, an officer\n  // opens the one they work in.\n  const [openBucket, setOpenBucket] = useState('');\n\n  return (\n    <Card>\n      <Card.Header>\n        <div className=\"flex flex-wrap items-center justify-between gap-3\">\n          <div>\n            <h2 className=\"text-base font-semibold text-gray-900\">Pipeline journey</h2>\n          </div>\n        </div>\n      </Card.Header>\n\n      <Card.Body>\n        {loading && <p className=\"py-10 text-center text-sm text-gray-400\">Loading the journey\u2026</p>}\n\n        {!loading && data && data.flows.length === 0 && (\n          <p className=\"py-10 text-center text-sm text-gray-400\">\n            No product flows configured. Define them in Administration.\n          </p>\n        )}\n\n        {/* THE BANDS AND THE SELECTOR SIDE BY SIDE. The funnel is a narrowing\n            shape, so the right-hand side of the card was empty space while the\n            business-line selector sat above the deal list in a wrapped row of\n            chips. Putting the selector where the space already is reads better\n            and, more importantly, puts the thing you are filtering BY next to\n            the thing it filters. On a narrow screen it stacks. */}\n        {!loading && data && data.flows.length > 0 && (\n          <div className={aside ? 'lg:flex lg:items-start lg:gap-6' : ''}>\n          <div className={[\n            aside ? 'min-w-0 lg:flex-1' : '',\n            refreshing ? 'opacity-50 transition-opacity' : 'transition-opacity',\n          ].join(' ')}>\n            <div className=\"mb-3 flex flex-wrap gap-1.5\">\n              {data.flows.map((f) => (\n                <button key={f.flow} type=\"button\" onClick={() => setFlowKey(f.flow)}\n                  className={'rounded-full px-3 py-1 text-xs font-medium capitalize transition-colors '\n                    + (flow?.flow === f.flow ? 'bg-[#005B82] text-white'\n                                             : 'bg-gray-100 text-gray-600 hover:bg-[#0082BB]/10')}>\n                  {f.flow}\n                  <span className=\"ml-1.5 opacity-70\">{f.deals}</span>\n                </button>\n              ))}\n            </div>\n\n            {/* A TRUE FUNNEL: each band is a trapezoid whose top edge matches\n                the band above, so the silhouette is continuous from Initiation\n                to disbursement rather than a stack of separate bars. Width\n                follows the ideal taper \u2014 what a healthy pipeline SHOULD look\n                like \u2014 while the RAG rail on the left reports what it is\n                actually doing. Shape shows the plan; colour shows the truth. */}\n            <div className=\"mx-auto\" style={{ maxWidth: 760 }}>\n              {buckets.map((b, i) => {\n                const wTop = 100 - (i / Math.max(buckets.length, 1)) * 62;\n                const wBot = 100 - ((i + 1) / Math.max(buckets.length, 1)) * 62;\n                const colour = bandColour(i, buckets.length);\n                const empty = b.count === 0;\n                const on = hover === b.key;\n                const open = openBucket === b.key;\n                const h = b.health;\n                const rag = h.status === 'red' ? '#C4536F'\n                  : h.status === 'amber' ? '#E0A02B'\n                  : h.status === 'green' ? '#669438' : '#D8DBDF';\n                return (\n                  <div key={b.key}>\n                    <div\n                      onMouseEnter={() => setHover(b.key)}\n                      onMouseLeave={() => setHover('')}\n                      onClick={() => setOpenBucket(open ? '' : b.key)}\n                      className=\"relative flex cursor-pointer items-stretch gap-2\"\n                    >\n                      {/* the health rail \u2014 red/amber/green, per stage */}\n                      <div className=\"w-1.5 shrink-0 rounded-full transition-all\"\n                           style={{ background: rag, opacity: on ? 1 : 0.85 }}\n                           title={h.status === 'idle'\n                             ? 'No deals at this stage'\n                             : `${h.avg_days} working days on average against a ${h.target_days}-day target`} />\n\n                      <div className=\"relative flex-1\" style={{ height: 58 }}>\n                        {/* the trapezoid */}\n                        <div\n                          className=\"absolute inset-0 transition-transform duration-200\"\n                          style={{\n                            clipPath: `polygon(${(100 - wTop) / 2}% 0%, ${100 - (100 - wTop) / 2}% 0%, ${100 - (100 - wBot) / 2}% 100%, ${(100 - wBot) / 2}% 100%)`,\n                            background: empty\n                              ? 'repeating-linear-gradient(45deg,#F4F5F7,#F4F5F7 7px,#E9EBEE 7px,#E9EBEE 14px)'\n                              : `linear-gradient(180deg, rgba(255,255,255,0.30) 0%, ${colour} 34%, ${colour} 62%, rgba(0,0,0,0.26) 100%), ${colour}`,\n                            transform: on ? 'scaleY(1.04)' : 'none',\n                            filter: on ? 'brightness(1.06)' : 'none',\n                          }}\n                        />\n                        {/* fill: how much of this band the deals occupy */}\n                        {!empty && (\n                          <div className=\"absolute inset-y-0 left-0 flex items-center justify-center\"\n                               style={{ width: '100%' }}>\n                            <div className=\"flex items-baseline gap-2 text-white drop-shadow\">\n                              <span className=\"text-lg font-semibold tabular-nums\">{b.count}</span>\n                              <span className=\"text-[11px] opacity-90\">KES {kes(b.value)}</span>\n                            </div>\n                          </div>\n                        )}\n                        {empty && (\n                          <div className=\"absolute inset-0 flex items-center justify-center\">\n                            <span className=\"text-[11px] text-gray-400\">nothing here</span>\n                          </div>\n                        )}\n                      </div>\n\n                      <div className=\"w-52 shrink-0 self-center\">\n                        <div className={'truncate text-xs font-semibold ' + (empty ? 'text-gray-400' : 'text-gray-800')}\n                             title={b.label}>\n                          <span className=\"mr-1 text-gray-400\">{open ? '\u25be' : '\u25b8'}</span>\n                          {b.label}\n                        </div>\n                        <div className=\"text-[10px] text-gray-400\">\n                          {b.weight}% \u00b7 {Math.round(b.probability * 100)}% at exit\n                        </div>\n                        <div className=\"text-[10px]\" style={{ color: rag }}>\n                          {h.status === 'idle'\n                            ? 'no deals'\n                            : `${h.avg_days}d avg / ${h.target_days}d target`\n                              + (h.at_risk ? ` \u00b7 ${h.at_risk} over` : '')}\n                        </div>\n                      </div>\n                    </div>\n\n                    {open && (\n                      <div className=\"mb-1 ml-4 space-y-1 border-l-2 border-gray-200 pl-3\">\n                        {b.steps.map((st) => (\n                          <div key={st.stage}\n                               onClick={(e) => {\n                                 e.stopPropagation();\n                                 if (st.count && onStageClick && flow) onStageClick(flow.flow, st.stage);\n                               }}\n                               className={'flex items-center gap-3 text-xs '\n                                 + (st.count && onStageClick ? 'cursor-pointer hover:bg-gray-50' : '')}>\n                            <span className=\"w-56 truncate text-gray-600\" title={st.stage}>{st.stage}</span>\n                            <span className=\"w-14 text-right tabular-nums text-gray-400\">\n                              {Math.round(st.probability * 100)}%\n                            </span>\n                            <div className=\"h-2 flex-1 overflow-hidden rounded-full bg-gray-100\">\n                              <div className=\"h-full rounded-full\"\n                                   style={{ width: `${b.count ? (st.count / Math.max(b.count, 1)) * 100 : 0}%`,\n                                            background: colour }} />\n                            </div>\n                            <span className=\"w-10 text-right tabular-nums text-gray-700\">{st.count}</span>\n                            <span className=\"w-28 text-right tabular-nums text-gray-500\">KES {kes(st.value)}</span>\n                          </div>\n                        ))}\n                      </div>\n                    )}\n                  </div>\n                );\n              })}\n            </div>\n\n            {/* What the colours mean \u2014 three words, not a paragraph. */}\n            <div className=\"mt-3 flex items-center justify-center gap-4 text-[10px] text-gray-500\">\n              {[['#669438', 'within target'], ['#E0A02B', 'slipping'],\n                ['#C4536F', 'stalled'], ['#D8DBDF', 'no deals']].map(([c, l]) => (\n                <span key={l} className=\"flex items-center gap-1\">\n                  <span className=\"inline-block h-2 w-2 rounded-full\" style={{ background: c }} />\n                  {l}\n                </span>\n              ))}\n            </div>\n\n            <div className=\"mt-3 flex flex-wrap items-center justify-between gap-2 border-t border-gray-100 pt-3 text-xs\">\n              <span className=\"text-gray-500\">\n                {flow?.deals ?? 0} deals \u00b7 KES {kes(flow?.value ?? 0)} \u00b7{' '}\n                <span className=\"font-semibold text-gray-800\">\n                  KES {kes(flow?.weighted ?? 0)} weighted\n                </span>\n              </span>\n            </div>\n          </div>\n\n          {aside && (\n            /* The selector column. Fixed width so the bands keep a sensible\n               shape - a funnel that reflows as the sidebar grows stops looking\n               like a funnel. Sticky so it stays put while somebody reads down\n               a long journey. */\n            <div className=\"mt-6 shrink-0 lg:mt-0 lg:w-64 lg:self-start lg:sticky lg:top-4\">\n              {aside}\n            </div>\n          )}\n          </div>\n        )}\n      </Card.Body>\n    </Card>\n  );\n}\n",
 "frontend/web/src/components/Sidebar.tsx": "import { displayName } from \"../lib/names\";\nimport { Link, useLocation } from 'react-router-dom';\nimport { useBranding } from '@/hooks/useBranding';\nimport { useAuth } from '@/hooks/useAuth';\nimport { useRole } from '@/hooks/useRole';\nimport { isManager } from '@/lib/role';\n\ninterface NavItem {\n  path: string;\n  label: string;\n  matchActive: (pathname: string) => boolean;\n  visibleFor?: (isMgr: boolean, isAdmin: boolean, isCfgAdmin: boolean, isAdminOrMd: boolean, isCreditStaff: boolean) => boolean;\n}\ninterface NavGroup { label: string; items: NavItem[]; }\n\n// A hardcoded hide list already existed and was empty. Rather than add a second\n// mechanism beside it, the same filter now also reads `hidden_modules` from\n// BRANDING - which comes from org_config.json, a file each deployment owns.\n//\n// So the pilot hides a module by listing its route in ITS config, and this side\n// keeps it, with no divergent code and nothing to remember at release time.\n// Keyed on ROUTE, not label: \"EKE Sales Pro\" and \"A2Z Sales Pro\" are the same\n// module, and a list keyed on the words would stop matching after a rebrand.\nconst DEMO_HIDE = new Set<string>([]);\n\nconst NAV_GROUPS: NavGroup[] = [\n  {\n    label: 'Executive Intelligence',\n    items: [\n      { path: '/',              label: 'Dashboard',        matchActive: (p) => p === '/' },\n      { path: '/perform',       label: 'Balanced Scorecard', matchActive: (p) => p === '/perform' },\n      { path: '/cascade',       label: 'Target Cascade',   matchActive: (p) => p === '/cascade' || p.startsWith('/cascade/'), visibleFor: (_m, _a, _c, md) => md },\n      { path: '/initiatives',   label: 'Initiatives',      matchActive: (p) => p === '/initiatives' || p.startsWith('/initiatives/') },\n      { path: '/profitability', label: 'Profitability',    matchActive: (p) => p === '/profitability' },\n      { path: '/sla',           label: 'SLA Monitor',      matchActive: (p) => p.startsWith('/sla'), visibleFor: (m, a) => m || a },\n    ],\n  },\n  {\n    label: 'Pipeline Intelligence (PIS)',\n    items: [\n      { path: '/pipeline',        label: 'A2Z Sales Pro',        matchActive: (p) => p === '/pipeline' || (p.startsWith('/pipeline/') && !p.startsWith('/pipeline/queues') && !p.startsWith('/pipeline/events') && !p.startsWith('/pipeline/channels') && !p.startsWith('/pipeline/warehouse')) },\n      { path: '/analytics',       label: 'Sales Pro Analytics',  matchActive: (p) => p.startsWith('/analytics') },\n      { path: '/pipeline/queues', label: 'Manager Queues',       matchActive: (p) => p.startsWith('/pipeline/queues'), visibleFor: (m) => m },\n      { path: '/pipeline/channels', label: 'Origin Channels',    matchActive: (p) => p.startsWith('/pipeline/channels') || p.startsWith('/pipeline/events') },\n      // Standalone, NOT a channel: a shelf with claim mechanics and no budget,\n      // so grouping it with the invested channels would imply a return question\n      // it cannot answer.\n      { path: '/referrals',       label: 'A2Z Sales Referral Analytics', matchActive: (p) => p.startsWith('/referrals') },\n      { path: '/branch-log',      label: 'Daily Log',     matchActive: (p) => p.startsWith('/branch-log') },\n      { path: '/portfolio',       label: 'Portfolio',            matchActive: (p) => p.startsWith('/portfolio') },\n    ],\n  },\n  {\n    // \u2500\u2500 DEPARTMENT REVIEW, ITS OWN SECTION (ruling 2026-08-14) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    // \"For the department gate we have a sidebar dedicated to the department\n    // which we could name Department Review ... this can also be the place\n    // where the head-office team, especially those voting, can get in and see\n    // the committee as can also vote, but it be restricted to selected voters\n    // only.\"\n    //\n    // Credit Analysis is the BANK credit analyst's module - Julius Korir's\n    // work. The department analyst and the committee members were borrowing it\n    // and seeing a screen built for somebody else's job. They now have their\n    // own way in.\n    //\n    // RESTRICTED TO CREDIT STAFF, which is the same gate Credit Analysis uses.\n    // A tighter one - only named committee members - belongs on the SERVER,\n    // where it already is: the vote endpoint refuses a non-member with a 403.\n    // Hiding a menu entry is not a permission, and treating it as one is how\n    // people end up believing a screen is safe because it is hard to find.\n    label: 'Department Review',\n    items: [\n      { path: '/lms',                 label: 'Department Review',   matchActive: (p) => p === '/lms' || p.startsWith('/lms/'), visibleFor: (_m, _a, _c, _md, credit) => credit },\n    ],\n  },\n  {\n    label: 'Credit Intelligence (CIS)',\n    items: [\n      { path: '/lms',                 label: 'Credit Analysis',     matchActive: (p) => p === '/lms' || p.startsWith('/lms/'), visibleFor: (_m, _a, _c, _md, credit) => credit },\n      { path: '/committee/convening', label: 'Committee Convening', matchActive: (p) => p.startsWith('/committee/convening'), visibleFor: (_m, _a, _c, md) => md },\n      { path: '/credit-admin',        label: 'Credit Admin',        matchActive: (p) => p === '/credit-admin' || p.startsWith('/credit-admin/'), visibleFor: (_m, _a, _c, _md, credit) => credit },\n      { path: '/troops',              label: 'Trops Disbursement',  matchActive: (p) => p.startsWith('/troops'), visibleFor: (_m, _a, _c, _md, credit) => credit },\n      { path: '/credit-analytics',    label: 'Credit Analytics',    matchActive: (p) => p.startsWith('/credit-analytics'), visibleFor: (_m, _a, _c, _md, credit) => credit },\n    ],\n  },\n  {\n    label: 'Reference & Admin',\n    items: [\n      { path: '/cbs',              label: 'Customer Lookup',     matchActive: (p) => p === '/cbs' || p.startsWith('/cbs/'), visibleFor: (_m, _a, _c, md) => md },\n      { path: '/admin/config',     label: 'Administration',      matchActive: (p) => (p.startsWith('/admin/') && !p.startsWith('/admin/cbs-debug')) || p.startsWith('/fx-rates'), visibleFor: (_m, _a, _c, md) => md },\n      { path: '/admin/cbs-debug', label: 'CBS / FlexCube Debug', matchActive: (p) => p.startsWith('/admin/cbs-debug'), visibleFor: (_m, isA) => isA },\n    ],\n  },\n];\n\nfunction initials(name?: string) {\n  return (name ?? '?').trim().split(/\\s+/).slice(0, 2).map((s) => s[0]?.toUpperCase() ?? '').join('');\n}\n\ninterface SidebarProps { onNavigate?: () => void; }\n\nexport function Sidebar({ onNavigate }: SidebarProps) {\n  const { pathname } = useLocation();\n  const { branding } = useBranding();\n  // Absent config hides nothing, so this cannot take a module away from\n  // somebody who never asked for it.\n  const hidden = new Set<string>(branding?.hidden_modules ?? []);\n  const { user } = useRole();\n  const { logout } = useAuth();\n\n  const isMgr      = isManager(user);\n  const isAdmin    = user?.is_admin ?? false;\n  const isCfgAdmin = isAdmin || ['admin', 'director', 'chief', 'managing'].some((t) => (user?.role ?? '').toLowerCase().includes(t));\n  // First-rollout gate: admin or the MD/CEO only.\n  const isAdminOrMd = isAdmin || ['managing director', 'chief executive'].some((t) => (user?.role ?? '').toLowerCase().includes(t));\n  // Credit Intelligence modules belong to credit staff (analysts, credit admin,\n  // treasury/disbursement, recovery) + admin/MD. Front-line RMs/branch see the\n  // pipeline instead, and track their own cases there.\n  const isCreditStaff = isAdminOrMd || /credit|analys|underwrit|recover|collection|treasur|disburs/i.test(user?.role ?? '');\n\n  return (\n    <aside className=\"sidebar\">\n      <div className=\"sb-brand\">\n        <img src=\"/img/ecobank-light.svg\" alt=\"Ecobank\" className=\"sb-logo\" />\n        <div className=\"sb-brand-text\">\n          <div className=\"sb-brand-name\">{branding?.app_name ?? 'A2Z Blueprint'}</div>\n          <div className=\"sb-brand-tag\">MIS 360</div>\n        </div>\n      </div>\n\n      <nav className=\"sb-nav\">\n        {NAV_GROUPS.map((group) => {\n          const items = group.items.filter(\n            (item) => !DEMO_HIDE.has(item.path)\n              && !hidden.has(item.path)\n              && (!item.visibleFor || item.visibleFor(isMgr, isAdmin, isCfgAdmin, isAdminOrMd, isCreditStaff)),\n          );\n          if (!items.length) return null;\n          return (\n            <div key={group.label}>\n              <div className=\"sb-section-lbl\">{group.label}</div>\n              {items.map((item) => {\n                const active = item.matchActive(pathname);\n                return (\n                  <Link\n                    key={item.path}\n                    to={item.path}\n                    onClick={onNavigate}\n                    className={`sb-item${active ? ' active' : ''}`}\n                  >\n                    {item.label}\n                  </Link>\n                );\n              })}\n            </div>\n          );\n        })}\n      </nav>\n\n      <div className=\"sb-foot\">\n        <div className=\"sb-user\">\n          <div className=\"sb-av\">{initials(user?.full_name ?? user?.username)}</div>\n          <div className=\"sb-user-info\">\n            <div className=\"sb-user-name\">{user?.full_name ? displayName(user.full_name, (user as any).display_name) : (user?.username ?? '\u2014')}</div>\n            <div className=\"sb-user-role\">{user?.role ?? ''}</div>\n          </div>\n        </div>\n        <button\n          type=\"button\"\n          className=\"sb-logout\"\n          onClick={() => { logout(); onNavigate?.(); }}\n        >\n          Sign out\n        </button>\n        <Link to=\"/about\" onClick={() => onNavigate?.()}\n          className=\"mt-2 block text-center text-[11px] text-white/40 hover:text-white/70\">\n          \u00a9 2026 A2Z \u00b7 About\n        </Link>\n      </div>\n    </aside>\n  );\n}\n",
 "frontend/web/src/components/Stat.tsx": "// v10.496 \u2014 Stat primitive.\n//\n// The reusable KPI tile. v10.495's Dashboard.tsx inlined this layout;\n// v10.496 extracts it as a real component so every page that shows\n// numeric metrics (MD Cockpit, RM dashboards, branch ops, etc.) uses\n// the same visual + accessibility contract.\n//\n// API:\n//   <Stat label=\"Total Deposits\" value=\"KES 1.42T\" />\n//   <Stat label=\"NPL Ratio\" value=\"11.1%\" delta={-0.4} />\n//   <Stat label=\"Active RMs\" value={232} sub=\"Target: 250\" />\n//   <Stat label=\"Pipeline\" value=\"...\" loading />\n//\n// `delta` is interpreted as a percentage-point change; positive shows\n// in green (with up arrow), negative in red (with down arrow). To\n// invert the polarity (e.g. NPL going DOWN is good), pass\n// `invertDelta`.\n\nimport type { ReactNode } from 'react';\nimport { Card } from './Card';\nimport { cn } from '@/lib/cn';\n\nexport interface StatProps {\n  label: ReactNode;\n  value: ReactNode;\n  /** The exact figure, shown on hover. A compact headline must never be the\n   *  only place a number exists. */\n  titleText?: string;\n  sub?: ReactNode;\n  delta?: number;\n  invertDelta?: boolean;\n  loading?: boolean;\n  stripe?: boolean | 'primary' | 'secondary' | 'accent';\n  /** Subtle tinted background + coloured left accent \u2014 colour-codes the tile. */\n  tone?: 'primary' | 'secondary' | 'accent' | 'neutral' | 'success' | 'lime' | 'teal' | 'violet';\n  /** When set, the tile becomes a clickable drill-through. */\n  onClick?: () => void;\n  className?: string;\n}\n\nconst TONE_BG: Record<string, string> = {\n  primary:   'bg-sky-50 border-l-[3px] border-l-[#0082BB]',\n  secondary: 'bg-slate-50 border-l-[3px] border-l-[#005B82]',\n  accent:    'bg-amber-50 border-l-[3px] border-l-amber-400',\n  success:   'bg-emerald-50 border-l-[3px] border-l-[#669438]',\n  lime:      'bg-lime-50 border-l-[3px] border-l-[#8ba700]',\n  teal:      'bg-teal-50 border-l-[3px] border-l-teal-500',\n  violet:    'bg-violet-50 border-l-[3px] border-l-violet-400',\n  neutral:   '',\n};\n\nfunction formatDelta(delta: number): string {\n  const sign = delta > 0 ? '+' : '';\n  return `${sign}${delta.toFixed(1)}`;\n}\n\nexport function Stat({\n  label, value, sub, delta, invertDelta = false, titleText,\n  loading = false, stripe = 'primary', tone, onClick, className,\n}: StatProps) {\n  // When invertDelta is true (e.g. NPL ratio), down is good.\n  const isGood = delta === undefined\n    ? null\n    : invertDelta ? delta < 0 : delta > 0;\n\n  const isBad = delta === undefined\n    ? null\n    : invertDelta ? delta > 0 : delta < 0;\n\n  const clickable = typeof onClick === 'function';\n\n  return (\n    <Card\n      stripe={stripe}\n      padding=\"md\"\n      onClick={onClick}\n      className={cn(\n        'relative',\n        tone && TONE_BG[tone],\n        clickable && 'cursor-pointer hover:shadow-md hover:border-gray-300 transition-all',\n        className,\n      )}\n    >\n      <div className=\"text-xs font-semibold uppercase tracking-wider\n                       text-gray-500\">\n        {label}\n      </div>\n      <div className=\"mt-2 flex items-baseline gap-3\">\n        {loading ? (\n          <span className=\"inline-block h-9 w-24 rounded\n                            bg-gray-100 animate-pulse\" />\n        ) : (\n          // min-w-0 + truncate: without both, a long figure pushes the card\n          // wider than its grid cell and the row stops lining up. The exact\n          // number is on hover.\n          <span title={titleText}\n                className=\"block min-w-0 truncate text-3xl font-bold text-brand-secondary\">\n            {value}\n          </span>\n        )}\n        {!loading && delta !== undefined && (\n          <span className={cn(\n            'inline-flex items-center text-sm font-medium',\n            isGood && 'text-green-600',\n            isBad && 'text-red-600',\n            !isGood && !isBad && 'text-gray-500',\n          )}>\n            {isGood && <span aria-hidden=\"true\">\u2191</span>}\n            {isBad && <span aria-hidden=\"true\">\u2193</span>}\n            {formatDelta(delta)}%\n          </span>\n        )}\n      </div>\n      {sub && (\n        <div className=\"mt-2 text-xs text-gray-400\">{sub}</div>\n      )}\n      {clickable && (\n        <span className=\"absolute top-3 right-3 text-gray-300 text-sm\" aria-hidden=\"true\">\u2192</span>\n      )}\n    </Card>\n  );\n}\n",
 "frontend/web/src/components/WorkbenchShell.tsx": "// WorkbenchShell \u2014 the shared workbench chrome (Phase 2e).\n//\n// One reusable header standard for every workbench: a coloured Ecobank-blue\n// ribbon (back \u00b7 title \u00b7 stage \u00b7 badges \u00b7 cross-link \u00b7 id \u00b7 refresh \u00b7 details\n// toggle), a collapsible \"Details\" slot, and a colour-coded tab strip. Extracted\n// from the deal workbench so LMS/Credit Analysis, Credit Admin, Trops, and\n// Credit Analytics can all adopt the identical look with one component.\n\nimport { useEffect, useState, type ReactNode } from 'react';\n\nexport interface WorkbenchTab {\n  id: string;\n  label: string;\n  /** Accent colour (hex) for the tab \u2014 active text + top border. */\n  color: string;\n  content: ReactNode;\n}\n\nexport interface WorkbenchBadge {\n  label: string;\n}\n\nexport interface WorkbenchShellProps {\n  title: string;\n  /** Primary status pill shown next to the title (e.g. the stage). */\n  stage?: string;\n  /** Extra pills (e.g. Locked, Validated, Draft). */\n  badges?: WorkbenchBadge[];\n  /** Small monospace id shown on the right (e.g. deal / application id). */\n  idLabel?: string;\n  onBack?: () => void;\n  onRefresh?: () => void;\n  /** Optional cross-link rendered in the ribbon (e.g. \"View Credit Analysis \u2192\"). */\n  crossLink?: { label: string; onClick: () => void };\n  /** Collapsible content revealed by the \"Details\" toggle. */\n  details?: ReactNode;\n  /** Colour-coded tabs. Omit to render `children` directly under the ribbon. */\n  tabs?: WorkbenchTab[];\n  defaultTabId?: string;\n  /** Content rendered under the ribbon when `tabs` is not supplied (ribbon-only\n   *  adoption for pages not yet tab-converted). */\n  children?: ReactNode;\n}\n\nexport function WorkbenchShell({\n  title, stage, badges, idLabel, onBack, onRefresh, crossLink, details, tabs, defaultTabId, children,\n}: WorkbenchShellProps) {\n  const tabList = tabs ?? [];\n  const [activeTab, setActiveTab] = useState(defaultTabId ?? (tabList[0]?.id ?? ''));\n\n  // \u2500\u2500 ANY PANEL CAN ASK FOR A TAB \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // A committee member reaching the decision card from their queue needs the\n  // documents, and has no reason to know they live under another tab. Rather\n  // than lifting this state through every page that uses the shell, a panel\n  // dispatches `workbench:open-tab` with the tab id and the shell answers.\n  //\n  // Ignored if the tab is not on this page, so a panel asking for something\n  // that is not there simply does nothing rather than blanking the view.\n  useEffect(() => {\n    const onOpen = (e: Event) => {\n      const id = (e as CustomEvent<string>).detail;\n      if (id && tabList.some((t) => t.id === id)) setActiveTab(id);\n    };\n    window.addEventListener('workbench:open-tab', onOpen as EventListener);\n    return () => window.removeEventListener('workbench:open-tab', onOpen as EventListener);\n  }, [tabList]);\n  const [detailsOpen, setDetailsOpen] = useState(false);\n  const active = tabList.find((t) => t.id === activeTab) ?? tabList[0];\n\n  return (\n    <div>\n      {/* Coloured ribbon \u2014 the clean top landing. */}\n      <div className=\"mt-1 flex flex-wrap items-center justify-between gap-3 rounded-t-lg bg-gradient-to-r from-[#0082BB] to-[#005B82] px-6 py-3.5 text-white shadow-sm\">\n        <div className=\"flex flex-wrap items-center gap-2.5\">\n          {onBack && (\n            <button onClick={onBack}\n              className=\"rounded border border-white/40 px-2 py-0.5 text-xs font-medium hover:bg-white/10\">\u2190 Back</button>\n          )}\n          <h2 className=\"text-base font-semibold\">{title || '\u2014'}</h2>\n          {stage && <span className=\"rounded-full bg-white/20 px-2 py-0.5 text-xs\">{stage}</span>}\n          {(badges ?? []).map((b) => (\n            <span key={b.label} className=\"rounded-full bg-white/20 px-2 py-0.5 text-xs\">{b.label}</span>\n          ))}\n          {crossLink && (\n            <button onClick={crossLink.onClick}\n              className=\"text-xs font-medium text-white/90 underline hover:text-white\">{crossLink.label}</button>\n          )}\n        </div>\n        <div className=\"flex items-center gap-3\">\n          {idLabel && <span className=\"font-mono text-xs text-white/70\">{idLabel}</span>}\n          {onRefresh && (\n            <button onClick={onRefresh}\n              className=\"rounded border border-white/40 px-2 py-0.5 text-xs font-medium hover:bg-white/10\">Refresh</button>\n          )}\n          {details != null && (\n            <button onClick={() => setDetailsOpen((v) => !v)}\n              className=\"rounded border border-white/40 px-2 py-0.5 text-xs font-medium hover:bg-white/10\">\n              {detailsOpen ? 'Hide details \u25b4' : 'Details \u25be'}\n            </button>\n          )}\n        </div>\n      </div>\n\n      {details != null && detailsOpen && <div className=\"mt-4\">{details}</div>}\n\n      {tabList.length > 0 ? (\n        <div className=\"mt-3\">\n          <div className=\"flex flex-wrap gap-1 rounded-t-lg border-b border-gray-200 bg-[#EAF4FA] px-2 pt-1.5 text-sm\">\n            {tabList.map((t) => {\n              const isActive = active?.id === t.id;\n              return (\n                <button key={t.id} onClick={() => setActiveTab(t.id)}\n                  style={isActive ? { color: t.color, borderTopColor: t.color, borderTopWidth: 2 } : { color: t.color }}\n                  className={`-mb-px rounded-t-md px-3 py-2 font-medium transition-colors ${\n                    isActive ? 'bg-white font-semibold shadow-sm' : 'opacity-60 hover:bg-white/60 hover:opacity-100'}`}>\n                  {t.label}\n                </button>\n              );\n            })}\n          </div>\n          <div className=\"pt-4\">{active?.content}</div>\n        </div>\n      ) : (\n        <div className=\"mt-4 space-y-4\">{children}</div>\n      )}\n    </div>\n  );\n}\n",
 "frontend/web/src/lib/api.ts": "// v10.500 Phase 1 Batch 3a \u2014 Typed API client.\n// v10.510 Phase 4 Batch \u03b21 \u2014 extended with pipeline fetchers.\n// v10.511 Phase 4 Batch \u03b22 \u2014 extended with postJson + pipeline mutations.\n// v10.512 Phase 4 Batch \u03b23 \u2014 extended with create + refer mutations.\n// v10.513 Phase 4 Batch \u03b24 \u2014 extended with manager queues + validate +\n//                              cancel-approve mutations.\n//\n// Single source for talking to the FastAPI backend. The Vite dev proxy\n// (vite.config.ts) transparently forwards /api/* to localhost:8502 in\n// dev; production deployment should put React behind the same origin.\n//\n// Auth integration (Batch 3a):\n//   - AuthProvider calls setCurrentToken(token) on every token-state\n//     change. getJson reads from the module-level holder and attaches\n//     `Authorization: Bearer <token>` when the token is non-null.\n//   - AuthProvider also calls setOn401Callback(fn) on mount. When any\n//     authenticated fetch returns 401, getJson invokes the callback\n//     before throwing \u2014 this is how a server-side expired or invalidated\n//     token propagates back into React auth state.\n//\n// CSRF is intentionally NOT addressed here. The architecture is\n// Bearer-header JWT, not cookie-auth, so CSRF is not the threat model\n// for Phase 1. CSRF reconsideration is deferred to a future Phase 2\n// security arc tied to any httpOnly-cookie migration. See REVIVAL_LEDGER\n// Batch 3a doctrine note.\n\nimport type { Branding } from '@/types/branding';\nimport type { UserIdentity, RoleRegistry } from '@/types/role';\nimport type {\n  PipelineDealsListResponse, PipelineDealDetailResponse,\n  PipelineDealsQuery,\n  PipelineConfig,\n  AdvanceDealRequest, AdvanceDealResponse,\n  RequestCancelRequest, RequestCancelResponse,\n  CreateDealRequest, CreateDealResponse,\n  ReferDealRequest, ReferDealResponse,\n  ValidationQueueResponse, CancellationQueueResponse,\n  ValidateDealRequest, ValidateDealResponse,\n  ApproveCancelRequest, ApproveCancelResponse,\n  CreditChecklistResponse, SubmitToCreditResponse,\n  PipelineAnalyticsResponse,\n  PipelineDrillResponse,\n  FunnelDrillResponse,\n  DealCategoryConfig,\n} from '@/types/pipeline';\nimport type {\n  CreditAnalyticsResponse,\n  CreditDrillResponse,\n} from '@/types/creditAnalytics';\nimport type { ExceptionsResponse } from '@/types/exceptions';\n\nconst API_BASE = '/api';\n\n\n// \u2500\u2500 Auth integration (module-level holders) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// AuthProvider is the only writer; getJson is the only reader. Keeping\n// these at module scope (instead of in a React context) lets api.ts stay\n// callable from non-React code paths (e.g. future service workers,\n// background sync) without forcing every fetch site to become a hook.\n\nlet _currentToken:  string | null              = null;\nlet _on401Callback: (() => void) | null        = null;\n\n/**\n * Update the JWT used for subsequent authenticated requests. Called by\n * AuthProvider whenever its token state changes (login, logout, expiry).\n * Pass null to clear.\n */\nlet _blobTokenRef: string | null = null;\nexport function getCurrentTokenForBlob(): string | null { return _blobTokenRef; }\nexport function setCurrentToken(token: string | null): void {\n  _currentToken = token;\n  _blobTokenRef = token;\n}\n\n/**\n * Register a callback fired when any authenticated request returns 401.\n * Called once by AuthProvider on mount; passes null on unmount.\n */\nexport function setOn401Callback(callback: (() => void) | null): void {\n  _on401Callback = callback;\n}\n\n\n// \u2500\u2500 Typed error for auth-expiry detection at fetch sites \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Distinct from generic Error so callers (e.g. RoleProvider) can decide\n// whether to treat the failure as transient or as auth-state change.\n\nexport class AuthExpiredError extends Error {\n  constructor(public readonly path: string) {\n    super(`Authentication expired or invalid (path: ${path})`);\n    this.name = 'AuthExpiredError';\n  }\n}\n\n\n// \u2500\u2500 Central JSON fetch wrapper \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Attaches Authorization header when a token is registered. Invokes the\n// 401 callback before throwing so AuthProvider state flips synchronously\n// with the failure. Other non-OK responses throw a generic Error.\n\nexport interface PortfolioAccount { account_number: string; cif: string; account_type_name: string; current_balance: number; available_balance: number; account_status: string; dormancy_status: string; npl_status: string; branch_code: string; introducer_code?: string; relationship_manager_code?: string; managed_by_code?: string; managed_by_name?: string; }\nexport interface PortfolioSummary { accounts: number; customers: number; total_balance: number; deposits: number; loans: number; dormant_accounts: number; dormant_pct: number; npl_accounts: number; by_type: { type: string; count: number; balance: number }[]; deposit_movement: { baseline: number; current: number; delta: number; pct: number | null } | null; baseline_date: string | null; pipeline_deposits: number; pipeline_loans: number; pipeline_value: number; }\nexport interface PortfolioTeamMember { staff_code: string; name: string; }\nexport interface PortfolioResponse { rm_code: string; accounts: PortfolioAccount[]; summary: PortfolioSummary; introduced?: { accounts: PortfolioAccount[]; summary: PortfolioSummary } | null; team: PortfolioTeamMember[]; view: string; selected: string; is_manager: boolean; branch_unallocated?: { accounts: number; deposits: number; loans: number; branch_codes: string[] } | null; }\nexport async function fetchMyPortfolio(staffCode = ''): Promise<PortfolioResponse> {\n  const q = staffCode ? `?staff_code=${encodeURIComponent(staffCode)}` : '';\n  return getJson<PortfolioResponse>(`/cbs/portfolio${q}`);\n}\n\nexport async function getJson<T>(path: string): Promise<T> {\n  const headers: Record<string, string> = {};\n  if (_currentToken) {\n    headers['Authorization'] = `Bearer ${_currentToken}`;\n  }\n  const res = await fetch(`${API_BASE}${path}`, { headers });\n\n  if (res.status === 401) {\n    // Notify AuthProvider BEFORE throwing \u2014 synchronous invocation\n    // ensures the React state transition (authenticated \u2192 expired) is\n    // queued in the same task as the failed request.\n    if (_on401Callback) _on401Callback();\n    throw new AuthExpiredError(path);\n  }\n  if (!res.ok) {\n    throw new Error(\n      `API ${path} failed: ${res.status} ${res.statusText}`,\n    );\n  }\n  return res.json() as Promise<T>;\n}\n\n\n// \u2500\u2500 Authenticated binary download (xlsx / pdf / pptx exports) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Mirrors getJson's auth-header + 401 handling, but streams the response as\n// a Blob and triggers a browser download with the server-provided filename.\nexport async function downloadFile(path: string, fallbackName: string): Promise<void> {\n  const headers: Record<string, string> = {};\n  if (_currentToken) headers['Authorization'] = `Bearer ${_currentToken}`;\n  const res = await fetch(`${API_BASE}${path}`, { headers });\n  if (res.status === 401) {\n    if (_on401Callback) _on401Callback();\n    throw new AuthExpiredError(path);\n  }\n  if (!res.ok) throw new Error(`Export ${path} failed: ${res.status} ${res.statusText}`);\n\n  // Prefer the filename from Content-Disposition when present.\n  let filename = fallbackName;\n  const cd = res.headers.get('Content-Disposition') || '';\n  const m = /filename=\"?([^\"]+)\"?/.exec(cd);\n  if (m && m[1]) filename = m[1];\n\n  const blob = await res.blob();\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url;\n  a.download = filename;\n  document.body.appendChild(a);\n  a.click();\n  a.remove();\n  URL.revokeObjectURL(url);\n}\n\n\n// \u2500\u2500 Central JSON POST/PUT wrapper (v10.511 Phase 4 Batch \u03b22) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Mirrors getJson semantics \u2014 same auth header injection, same 401\n// callback dispatch \u2014 but for write operations. Body is JSON-serialized\n// from the second argument. The method defaults to POST; pass 'PUT' for\n// update operations.\n//\n// Error handling shape:\n//   - 401: dispatch on401, throw AuthExpiredError (same as getJson)\n//   - 400 with JSON body containing `detail`: throw Error with the\n//     server's detail message (so the UI can show \"Reason too short\"\n//     rather than a generic \"Bad Request\")\n//   - 403/404/5xx: throw Error with status code + statusText\n//\n// The 400-with-detail handling is load-bearing for \u03b22's UX. The\n// FastAPI HTTPException machinery returns {\"detail\": \"...\"} on\n// validation failure; surfacing that detail to the user is what\n// makes the form interactions feel responsive.\n\nexport class ApiValidationError extends Error {\n  constructor(public readonly detail: string, public readonly status: number) {\n    super(detail);\n    this.name = 'ApiValidationError';\n  }\n}\n\nasync function postJson<TResponse, TBody = unknown>(\n  path: string,\n  body: TBody,\n  method: 'POST' | 'PUT' | 'PATCH' | 'DELETE' = 'POST',\n): Promise<TResponse> {\n  const headers: Record<string, string> = {\n    'Content-Type': 'application/json',\n  };\n  if (_currentToken) {\n    headers['Authorization'] = `Bearer ${_currentToken}`;\n  }\n  const res = await fetch(`${API_BASE}${path}`, {\n    method,\n    headers,\n    body: JSON.stringify(body),\n  });\n\n  if (res.status === 401) {\n    if (_on401Callback) _on401Callback();\n    throw new AuthExpiredError(path);\n  }\n\n  if (res.status === 400 || res.status === 422) {\n    // Try to extract the server's detail message\n    let detail = `Validation failed (${res.status})`;\n    try {\n      const errBody = await res.json();\n      if (errBody && typeof errBody.detail === 'string') {\n        detail = errBody.detail;\n      } else if (errBody && Array.isArray(errBody.detail)) {\n        // Pydantic 422 errors come as array of {loc, msg, type}\n        const first = errBody.detail[0];\n        if (first && first.msg) detail = String(first.msg);\n      }\n    } catch { /* keep default */ }\n    throw new ApiValidationError(detail, res.status);\n  }\n\n  if (!res.ok) {\n    throw new Error(\n      `API ${path} failed: ${res.status} ${res.statusText}`,\n    );\n  }\n\n  return res.json() as Promise<TResponse>;\n}\n\n\n// \u2500\u2500 Public endpoint fetchers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n/**\n * Fetch tenant branding from /api/branding.\n *\n * Auth: NOT required (endpoint is public per utils/api_branding.py:11 \u2014\n * the login page needs branding before authentication). Returns bank\n * name, app name, brand colors, regulator name, and the IP notice text.\n * Called once on app mount by BrandingProvider.\n */\nexport async function fetchBranding(): Promise<Branding> {\n  return getJson<Branding>('/branding');\n}\n\n\n// \u2500\u2500 Authenticated endpoint fetchers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n/**\n * Fetch the caller's detailed identity from /api/auth/whoami-detailed.\n *\n * Auth: REQUIRED (Depends(get_current_user) at utils/api.py:328). The\n * Authorization: Bearer header is attached automatically from the\n * current token registered by AuthProvider.\n *\n * Returns the full UserIdentity shape: identity fields (username,\n * staff_code, full_name, department, email), role classification (tier,\n * sbu, branch_scope, can_be_tagged), capability flags (is_admin,\n * can_view_all), Streamlit RBAC modules, and token expiry.\n *\n * Called by RoleProvider once auth.status === 'authenticated'.\n */\nexport async function fetchWhoamiDetailed(): Promise<UserIdentity> {\n  return getJson<UserIdentity>('/auth/whoami-detailed');\n}\n\n\n/**\n * Fetch the canonical role registry from /api/roles/registry.\n *\n * Auth: REQUIRED (Depends(get_current_user) at utils/api_roles.py:51).\n * Returns system-wide role schema: enum constants (tiers/sbus/scopes)\n * plus the array of explicit role classifications. The registry is\n * system schema, not per-user data \u2014 every authenticated user receives\n * the same response.\n *\n * Called by RoleProvider in parallel with fetchWhoamiDetailed once\n * auth.status === 'authenticated'.\n */\nexport async function fetchRoleRegistry(): Promise<RoleRegistry> {\n  return getJson<RoleRegistry>('/roles/registry');\n}\n\n\n// \u2500\u2500 Pipeline endpoint fetchers (v10.510 Phase 4 Batch \u03b21) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n//\n// Consumes the FastAPI pipeline domain surface built in Arc \u03b1 (\u03b11-\u03b17).\n// Cascade scoping is applied server-side; each deal carries a per-caller\n// permissions object that the React UI uses to decide button rendering.\n// No client-side authorization logic \u2014 the API tells us what's allowed.\n\n\n/**\n * Fetch the cascade-scoped list of pipeline deals from /api/pipeline/deals.\n *\n * Auth: REQUIRED. Server applies the caller's cascade visibility \u2014 a\n * teller sees only own deals; a branch manager sees branch deals; an\n * admin sees everything. (\u03b12 / G395.)\n *\n * Each returned deal carries a `permissions` object (\u03b17 / G400) with\n * 6 booleans the React UI reads to decide which actions to render.\n *\n * Filter params (all optional):\n *   stage    \u2014 exact-match filter on deal.stage\n *   category \u2014 pipeline category (Loans / Accounts / Deposits)\n *   unit     \u2014 organizational unit filter\n *   offset, limit \u2014 server-side pagination\n */\nexport async function fetchPipelineDeals(\n  query: PipelineDealsQuery = {},\n): Promise<PipelineDealsListResponse> {\n  const params = new URLSearchParams();\n  if (query.stage)    params.set('stage',    query.stage);\n  if (query.category) params.set('category', query.category);\n  if (query.unit)     params.set('unit',     query.unit);\n  if (query.offset !== undefined) params.set('offset', String(query.offset));\n  if (query.limit  !== undefined) params.set('limit',  String(query.limit));\n  const qs = params.toString();\n  const path = qs ? `/pipeline/deals?${qs}` : '/pipeline/deals';\n  return getJson<PipelineDealsListResponse>(path);\n}\n\n\n/**\n * Fetch the admin-configured pipeline config (categories, stages, sectors,\n * decision levels) from /api/pipeline/stages. Single source for the filter\n * + create-form dropdowns so the UI matches the bank's configured workflow.\n */\nexport async function fetchPipelineConfig(): Promise<PipelineConfig> {\n  return getJson<PipelineConfig>('/pipeline/stages');\n}\n\n/** Editable reference-config slice returned by the admin write endpoint. */\nexport interface AdminConfigPatch {\n  segment_labels?:     Record<string, string>;\n  customer_segments?:  Record<string, string[]>;\n  client_types?:       { key: string; label: string; field: 'mou' | 'sector' }[];\n  product_catalogue?:  Record<string, string[]>;\n  individual_mous?:    { id: string; title: string; partner_name?: string; active?: boolean }[];\n  business_sectors?:   string[];\n  sectors?:            string[];\n  required_fields?:    string[];\n  allow_other_sector?: boolean;\n  allow_other_mou?:    boolean;\n  deal_categories?:    DealCategoryConfig[];\n}\nexport interface AdminConfigResponse {\n  status: 'saved' | 'noop';\n  applied: string[];\n  config: AdminConfigPatch;\n}\n\n/** PATCH reference config (CEO/MD only \u2014 gated server-side by require_config_admin). */\nexport async function updatePipelineConfig(patch: AdminConfigPatch): Promise<AdminConfigResponse> {\n  return postJson<AdminConfigResponse, AdminConfigPatch>('/admin/pipeline-config', patch);\n}\n\n/** SW-1 \u2014 admin branches / regions panel. */\nexport interface AdminBranch {\n  id?: string; name: string; region?: string; area_name?: string;\n  branch_code?: string; active?: boolean;\n}\nexport async function getAdminBranches(): Promise<{ branches: AdminBranch[]; regions: string[]; areas: string[] }> {\n  return getJson<{ branches: AdminBranch[]; regions: string[]; areas: string[] }>('/admin/branches');\n}\nexport async function saveAdminBranches(branches: AdminBranch[]): Promise<{ status: string; added: number; updated: number; branches: AdminBranch[] }> {\n  return postJson<{ status: string; added: number; updated: number; branches: AdminBranch[] }, { branches: AdminBranch[] }>('/admin/branches', { branches });\n}\n\n/** Add / edit / deactivate a single MOU in the partnership register\n * (CEO/MD only). Add: pass partner_name (+ optional mou_type/department) with no\n * id. Deactivate: pass the id with status 'Inactive'. Writes the file the deal\n * picker reads, so a newly added partner is immediately selectable. */\nexport interface MouUpsertInput {\n  id?: string;\n  partner_name?: string;\n  mou_type?: string;\n  department?: string;\n  status?: 'Active' | 'Inactive';\n}\nexport interface MouUpsertResponse {\n  status: 'saved';\n  mou: { id: string; title: string; partner_name: string; status: string };\n  active_count: number;\n  total: number;\n}\nexport async function upsertMou(input: MouUpsertInput): Promise<MouUpsertResponse> {\n  return postJson<MouUpsertResponse, MouUpsertInput>('/admin/mous', input);\n}\n\n/** Author one product's process flow (CEO/MD only). Pass `product` plus its\n * ordered `stages` (each {stage, target_days}) and the `client_types` that offer\n * it (empty = all). Pass `delete: true` with a `product` to revert it to its\n * class flow. Writes pipeline_settings.product_flows; the deal form picks it up. */\nexport interface ProductFlowStageInput { stage: string; target_days: number; }\nexport interface ProductFlowUpsertInput {\n  product: string;\n  stages?: ProductFlowStageInput[];\n  client_types?: string[];\n  required_documents?: string[];\n  documents_required_at_stage?: string;\n  committee_journey?: string[];\n  delete?: boolean;\n}\nexport interface ProductFlowUpsertResponse {\n  status: 'saved';\n  product?: string;\n  flow?: { client_types: string[]; stages: ProductFlowStageInput[] };\n  deleted?: string;\n  total: number;\n}\nexport async function upsertProductFlow(\n  input: ProductFlowUpsertInput,\n): Promise<ProductFlowUpsertResponse> {\n  return postJson<ProductFlowUpsertResponse, ProductFlowUpsertInput>('/admin/product-flows', input);\n}\n\n\n// \u2500\u2500 Role registry (admin) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// The full role-definition registry (kpi_library.json -> role_kpis): every\n// role with its KPI count, resolved pillar mix, and capabilities. Distinct\n// from `RoleRegistry` in types/role.ts, which is the RBAC tier registry.\n\nexport interface AdminRoleRow {\n  role: string;\n  kpi_count: number;\n  pillars: Record<string, number>;\n  can_disburse: boolean;\n}\n\nexport interface AdminRolesResponse {\n  roles: AdminRoleRow[];\n  count: number;\n  disbursement_roles: string[];\n}\n\nexport interface AdminRoleKpi {\n  ref: string | number;\n  id?: string;\n  name?: string;\n  pillar?: string;\n  weight?: number;\n  mapped: boolean;\n}\n\nexport interface AdminRoleDetailResponse {\n  role: string;\n  kpis: AdminRoleKpi[];\n  kpi_count: number;\n  unmapped: number;\n  can_disburse: boolean;\n}\n\nexport interface RoleCapabilityResponse {\n  role: string;\n  can_disburse: boolean;\n  disbursement_roles: string[];\n}\n\n/** Full role registry \u2014 config-admin only (server-gated). */\nexport async function fetchAdminRoles(): Promise<AdminRolesResponse> {\n  return getJson<AdminRolesResponse>('/admin/roles');\n}\n\n/** One role's resolved KPI breakdown + capabilities. */\nexport async function fetchAdminRoleDetail(role: string): Promise<AdminRoleDetailResponse> {\n  return getJson<AdminRoleDetailResponse>(`/admin/role-detail?role=${encodeURIComponent(role)}`);\n}\n\n/** Grant/revoke a role's disbursement capability. */\nexport async function setRoleCapability(\n  role: string, canDisburse: boolean,\n): Promise<RoleCapabilityResponse> {\n  return postJson<RoleCapabilityResponse, { role: string; can_disburse: boolean }>(\n    '/admin/roles/capabilities', { role, can_disburse: canDisburse });\n}\n\n\n// \u2500\u2500 Referral inbox / lifecycle (refer-existing-deal flow) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Distinct from referPipelineDeal above (the legacy create-referral-deal\n// endpoint). These drive the Incoming / Returned / Following inbox.\n\nexport interface ReferralView {\n  id: string;\n  client_name?: string;\n  deal_value?: number;\n  amount_kes?: number;   // KES-equivalent; display this, not native deal_value\n  product_type?: string;\n  stage?: string;\n  segment?: string;\n  referral_status?: string;\n  referred_to?: string;\n  referred_to_code?: string;\n  referred_by_name?: string;\n  referred_by_code?: string;\n  referral_note?: string;\n  decline_reason?: string;\n  referred_at?: string;\n  accepted_at?: string;\n  declined_at?: string;\n  referral_tier?: 'B2B' | 'S2B';\n  cross_unit?: boolean;\n  referrer_department?: string | null;\n  recipient_department?: string | null;\n  referral_chain?: Array<{\n    seq: number; from_code?: string; from_name?: string; from_dept?: string;\n    to_code?: string; to_name?: string; to_dept?: string; note?: string;\n    at?: string; status?: string; resolved_at?: string; decline_reason?: string;\n  }>;\n  credit_stage?: { key: string; label: string; status: string; declined: boolean } | null;\n}\n\nexport interface ReferralListResponse {\n  deals: ReferralView[];\n  count: number;\n}\n\n/** Pending referrals addressed to the caller (accept / decline). */\nexport async function fetchIncomingReferrals(): Promise<ReferralListResponse> {\n  return getJson<ReferralListResponse>('/pipeline/referrals/incoming');\n}\n\n/** Declined referrals the caller made (reassign pool). */\nexport async function fetchReturnedReferrals(): Promise<ReferralListResponse> {\n  return getJson<ReferralListResponse>('/pipeline/referrals/returned');\n}\n\n/** Live referrals the caller made \u2014 pending + accepted (follow progress). */\nexport async function fetchOutgoingReferrals(): Promise<ReferralListResponse> {\n  return getJson<ReferralListResponse>('/pipeline/referrals/outgoing');\n}\n\nexport interface ReferralAlert {\n  id?: string;\n  client_name?: string;\n  referred_to?: string;\n  kind: string;\n  days?: number;\n  message: string;\n}\n\nexport interface OutgoingReferralAnalytics {\n  total: number;\n  by_status: { pending: number; accepted: number; declined: number };\n  by_stage: Record<string, number>;\n  closed: { won: number; lost: number };\n  alerts: ReferralAlert[];\n  alert_count: number;\n}\n\nexport async function fetchOutgoingReferralAnalytics(): Promise<OutgoingReferralAnalytics> {\n  return getJson<OutgoingReferralAnalytics>('/pipeline/referrals/outgoing/analytics');\n}\n\nexport interface ReferralDepartmentRow {\n  department: string;\n  total: number;\n  by_status: { pending: number; accepted: number; declined: number };\n  closed: { won: number; lost: number };\n}\n\nexport interface ReferralLeaderRow {\n  code: string; referrer: string; count: number; value: number; accepted: number; won: number;\n}\nexport interface ReferralRvoSide { referred: { count: number; value: number }; originated: { count: number; value: number }; }\nexport interface ReferralRecentRow {\n  id: string; client_name?: string; product?: string;\n  referred_by_name?: string; referred_by_code?: string; referred_to?: string;\n  referral_status?: string; referral_tier?: 'B2B' | 'S2B' | null;\n  stage?: string; value?: number; referred_at?: string;\n}\nexport interface ReferralsByDepartment {\n  departments: ReferralDepartmentRow[];\n  total: number;\n  department_count: number;\n  scope?: string;\n  scope_tier?: 'bank' | 'department' | 'unit';\n  totals?: {\n    total: number; accepted: number; pending: number; declined: number;\n    won: number; lost: number; value_influenced: number; conversion_rate: number;\n  };\n  by_referrer?: ReferralLeaderRow[];\n  referral_vs_originated?: { open: ReferralRvoSide; closed: ReferralRvoSide };\n  referral_branch_split?: { in_branch: number; cross_branch: number };\n  recent?: ReferralRecentRow[];\n}\n\nexport async function fetchReferralsByDepartment(): Promise<ReferralsByDepartment> {\n  return getJson<ReferralsByDepartment>('/pipeline/referrals/analytics/by-department');\n}\n\nexport interface TeamReferralsResponse {\n  deals: ReferralView[];\n  count: number;\n  summary: {\n    total: number;\n    by_status: { pending: number; accepted: number; declined: number };\n    by_tier: { B2B: number; S2B: number };\n    closed: { won: number; lost: number };\n  };\n}\n\nexport async function fetchTeamReferrals(): Promise<TeamReferralsResponse> {\n  return getJson<TeamReferralsResponse>('/pipeline/referrals/team');\n}\n\n// \u2500\u2500 SLA (Phase 4 S1/S2) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface SlaStep { key: string; label: string; owner_role: string; target_days: number; }\nexport interface SlaTier { after_days: number; escalate_to: string; }\nexport interface SlaConfig {\n  steps: SlaStep[];\n  escalation_ladder: SlaTier[];\n  product_promise: Record<string, number>;\n  due_soon_days?: number;\n  stage_step_map?: Record<string, string>;\n}\nexport async function fetchSlaConfig(): Promise<{ sla_config: SlaConfig; is_default: boolean }> {\n  return getJson<{ sla_config: SlaConfig; is_default: boolean }>('/admin/sla-config');\n}\nexport async function saveSlaConfig(cfg: SlaConfig): Promise<{ status: string; sla_config: SlaConfig }> {\n  return postJson<{ status: string; sla_config: SlaConfig }, { sla_config: SlaConfig }>(\n    '/admin/sla-config', { sla_config: cfg });\n}\n\nexport interface SlaCommitment {\n  reason: string;\n  committed_date: string;\n  recorded_by?: string;\n  recorded_by_name?: string;\n  recorded_at?: string;\n}\nexport interface SlaViolation {\n  deal_id: string;\n  client_name?: string;\n  product_type?: string | null;\n  stage?: string;\n  owner_code?: string;\n  clock: 'step' | 'age';\n  step?: string | null;\n  elapsed_business_days: number;\n  target_days: number;\n  remaining_business_days?: number;\n  overdue_business_days: number;\n  breached: boolean;\n  state?: 'on_track' | 'due_soon' | 'breached';\n  escalate_to?: string | null;\n  commitment?: SlaCommitment | null;\n  commitment_status?: 'active' | 'unfulfilled' | null;\n}\nexport interface SlaViolations {\n  violations: SlaViolation[];\n  count: number;\n  open_deals: number;\n  by_escalation: Record<string, number>;\n  by_clock: { step: number; age: number };\n  by_step?: Record<string, number>;\n  by_state?: { on_track: number; due_soon: number; breached: number };\n}\nexport async function fetchSlaViolations(): Promise<SlaViolations> {\n  return getJson<SlaViolations>('/pipeline/sla/violations');\n}\nexport async function fetchDealSla(dealId: string): Promise<{ deal_id: string; sla: SlaViolation | null }> {\n  return getJson<{ deal_id: string; sla: SlaViolation | null }>(`/pipeline/deals/${dealId}/sla`);\n}\nexport async function recordSlaCommitment(\n  dealId: string, reason: string, committedDate: string,\n): Promise<{ deal_id: string; step: string; commitment: SlaCommitment }> {\n  return postJson<\n    { deal_id: string; step: string; commitment: SlaCommitment },\n    { reason: string; committed_date: string }\n  >(`/pipeline/deals/${dealId}/sla/commitment`, { reason, committed_date: committedDate });\n}\n\n// \u2500\u2500 Referral bench (both directions, with the escalation clock) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface ReferralClock {\n  status: 'due' | 'overdue' | 'decided';\n  state: string; sent_at: string; due_at: string;\n  hours_left: number; overdue_hours: number;\n  escalate_to: { level: string; code: string; name: string; role: string }[];\n}\nexport interface ReferralBenchRow {\n  deal_id: string; client: string; product: string; value: number;\n  from_code: string; from_name: string; to_code: string; to_name: string;\n  sent_at: string; clock: ReferralClock;\n}\nexport interface ReferralBench {\n  incoming: ReferralBenchRow[];\n  outgoing: ReferralBenchRow[];\n  incoming_overdue: number;\n  outgoing_overdue: number;\n}\nexport async function fetchReferralBench(): Promise<ReferralBench> {\n  return getJson<ReferralBench>('/pipeline/referrals/bench');\n}\n\nexport async function acceptReferral(dealId: string): Promise<{ status?: string }> {\n  return postJson<{ status?: string }, Record<string, never>>(\n    `/pipeline/deals/${dealId}/referral/accept`, {});\n}\n\nexport async function reReferReferral(dealId: string, referredToCode: string, referredTo: string, note?: string): Promise<{ referral_status?: string }> {\n  return postJson<{ referral_status?: string }, { referred_to_code: string; referred_to: string; note?: string }>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/referral/re-refer`,\n    { referred_to_code: referredToCode, referred_to: referredTo, note });\n}\nexport async function declineReferral(dealId: string, reason: string): Promise<{ status?: string }> {\n  return postJson<{ status?: string }, { reason: string }>(\n    `/pipeline/deals/${dealId}/referral/decline`, { reason });\n}\n\n// \u2500\u2500 Phase V: line-manager validation requests (reopen / hold) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface ValidationRequest {\n  id: string;\n  kind: 'reopen' | 'hold';\n  requested_by?: string;\n  requested_by_name?: string;\n  reason?: string;\n  at?: string;\n  status: 'pending' | 'approved' | 'rejected';\n  validator_code?: string | null;\n  validator_name?: string | null;\n  validator_role?: string | null;\n  admin_fallback?: boolean;\n  validated_by?: string | null;\n  validated_by_name?: string | null;\n  validated_at?: string | null;\n  note?: string | null;\n}\n\nexport async function createValidationRequest(\n  dealId: string, kind: 'reopen' | 'hold', reason: string,\n): Promise<ValidationRequest> {\n  return postJson<ValidationRequest, { kind: string; reason: string }>(\n    `/pipeline/deals/${dealId}/validation-requests`, { kind, reason });\n}\n\nexport async function resolveValidationRequest(\n  dealId: string, reqId: string, decision: 'approved' | 'rejected', note: string,\n): Promise<ValidationRequest> {\n  return postJson<ValidationRequest, { decision: string; note: string }>(\n    `/pipeline/deals/${dealId}/validation-requests/${reqId}/resolve`, { decision, note });\n}\n\nexport async function liftDealHold(dealId: string, note: string): Promise<{ deal_id: string; on_hold: boolean }> {\n  return postJson<{ deal_id: string; on_hold: boolean }, { note: string }>(\n    `/pipeline/deals/${dealId}/unhold`, { note });\n}\n\nexport async function fetchDealJourney(dealId: string): Promise<{ journey: LoanAppHistoryEvent[]; linked_application_id: string | null }> {\n  return getJson<{ journey: LoanAppHistoryEvent[]; linked_application_id: string | null }>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/journey`);\n}\n\n// \u2500\u2500 Daily Branch Log \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface BranchLogField { key: string; label: string; type: string; unit: string; bsc_kpi: string | null; weight?: number; auto?: boolean; }\nexport interface BranchLogEntry {\n  id: string; log_date: string; staff_code: string; staff_name: string; unit: string; role: string;\n  submitted_at?: string; updated_at?: string; validated?: boolean; rejected?: boolean;\n  validated_by?: string; validated_at?: string; manager_note?: string; remarks?: string;\n  [metric: string]: unknown;\n}\n// Calendar context for today (Kenya work calendar: weekends, half-day Saturdays,\n// gazetted holidays). Counts include today.\nexport interface DayContext {\n  date: string; weekday: string;\n  day_of_year: number; days_in_year: number; days_remaining: number;\n  working_days_remaining: number; working_hours_remaining: number;\n  working: boolean; half_day: boolean; weight: number; hours_today: number;\n  holiday: boolean; holiday_label: string; next_working_day: string;\n  staff_name?: string; staff_code?: string;\n}\nexport async function fetchDayContext(): Promise<DayContext> {\n  return getJson<DayContext>('/branch-log/day-context');\n}\n\nexport async function fetchBranchLogFields(): Promise<{ fields: BranchLogField[] }> {\n  return getJson<{ fields: BranchLogField[] }>('/branch-log/fields');\n}\n\nexport interface BranchLogActivity { at: string; time: string; kind: string; detail: string; }\nexport async function fetchBranchLogAutoActivities(): Promise<{ activities: BranchLogActivity[]; date: string }> {\n  return getJson<{ activities: BranchLogActivity[]; date: string }>('/branch-log/auto-activities');\n}\n\nexport interface BranchLogConfig {\n  activity_weights: Record<string, number>;\n  daily_index_target: number;\n  fields: BranchLogField[];\n  activity_sets?: Record<string, string[]>;\n  unit_activity_weights?: Record<string, Record<string, number>>;\n  units?: string[];\n  unit_labels?: Record<string, string>;\n}\nexport async function fetchBranchLogConfig(): Promise<BranchLogConfig> {\n  return getJson<BranchLogConfig>('/branch-log/config');\n}\nexport async function saveBranchLogConfig(activity_weights: Record<string, number>, daily_index_target: number): Promise<{ status: string }> {\n  return postJson<{ status: string }, { activity_weights: Record<string, number>; daily_index_target: number }>(\n    '/branch-log/config', { activity_weights, daily_index_target });\n}\n// Per-unit sets and weights (AS1-AS3). Sent on their own, so saving one unit\n// never rewrites the bank-wide weights as a side effect.\nexport interface UnitConfigPayload {\n  activity_sets?: Record<string, string[]>;\n  unit_activity_weights?: Record<string, Record<string, number>>;\n}\nexport async function saveBranchLogUnitConfig(\n  body: UnitConfigPayload,\n): Promise<{ status: string }> {\n  return postJson<{ status: string }, UnitConfigPayload>('/branch-log/config', body);\n}\nexport interface ExtraActivity { key: string; label: string; type: string; unit: string; weight: number; roles: string[]; }\nexport async function fetchBranchLogActivities(): Promise<{ base: BranchLogField[]; extra: ExtraActivity[] }> {\n  return getJson<{ base: BranchLogField[]; extra: ExtraActivity[] }>('/branch-log/activities');\n}\nexport async function saveBranchLogActivities(extra_activities: ExtraActivity[]): Promise<{ status: string }> {\n  return postJson<{ status: string }, { extra_activities: ExtraActivity[] }>('/branch-log/activities', { extra_activities });\n}\nexport interface BranchLogRankRow { rank: number; staff_code: string; staff_name: string; unit: string; index: number; days: number; avg_per_day: number; target: number; }\n// \u2500\u2500 Pipeline validation (same tier structure as the Daily Log) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface PipelineQueueRow {\n  deal_id: string; staff_code: string; staff_name: string; role: string;\n  branch: string; client: string; product: string; stage: string;\n  deal_value: number; validated: boolean; validated_by: string; can_act: boolean;\n}\nexport interface PipelineQueue {\n  rows: PipelineQueueRow[]; date: string; working_day: boolean; label: string;\n  pending: number; branch?: string; mode: string;\n}\nexport interface PipelineDayRow {\n  branch: string; deals: number; validated: number; pending: number; value: number;\n  status: string; submitted_by_name: string; validated_by_name: string;\n  return_note: string;\n}\nexport interface PipelineDays {\n  rows: PipelineDayRow[]; date: string; working_day?: boolean; label?: string;\n  top_of_house: boolean; can_return?: boolean;\n}\nexport async function fetchPipelineValidationQueue(\n  date = '', branch = '',\n): Promise<PipelineQueue> {\n  const q = new URLSearchParams();\n  if (date) q.set('date', date);\n  if (branch) q.set('branch', branch);\n  const s = q.toString();\n  return getJson<PipelineQueue>(`/pipeline-validation/queue${s ? `?${s}` : ''}`);\n}\nexport async function fetchPipelineValidationDays(date = ''): Promise<PipelineDays> {\n  return getJson<PipelineDays>(\n    `/pipeline-validation/days${date ? `?date=${encodeURIComponent(date)}` : ''}`);\n}\nexport async function submitPipelineDay(\n  branch: string, date: string,\n): Promise<{ pipeline_day: Record<string, unknown> }> {\n  return postJson<{ pipeline_day: Record<string, unknown> },\n                  { branch: string; date: string }>(\n    '/pipeline-validation/days/submit', { branch, date });\n}\nexport async function decidePipelineDay(\n  branch: string, date: string, approved: boolean, note = '',\n): Promise<{ pipeline_day: Record<string, unknown> }> {\n  return postJson<{ pipeline_day: Record<string, unknown> },\n                  { branch: string; date: string; approved: boolean; note: string }>(\n    '/pipeline-validation/days/validate', { branch, date, approved, note });\n}\n\n// \u2500\u2500 Defined funnel (journey from admin config + credit side layer) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface DefinedStep {\n  stage: string; count: number; value: number; probability: number;\n}\nexport interface BucketHealth {\n  status: 'green' | 'amber' | 'red' | 'idle';\n  avg_days: number; target_days: number; oldest_days: number; at_risk: number;\n}\nexport interface DefinedBucket {\n  key: string; label: string; weight: number;\n  count: number; value: number; probability: number;\n  steps: DefinedStep[];\n  health: BucketHealth;\n}\nexport interface DefinedFlow {\n  flow: string; buckets: DefinedBucket[];\n  deals: number; value: number; weighted: number;\n}\nexport interface DefinedFunnel {\n  flows: DefinedFlow[];\n  total_deals: number;\n  unplaced_deals: number;\n}\nexport interface PipelineLeaderboardRow {\n  key: string; rank: number; name: string;\n  staff_code: string; role: string; branch: string;\n  deals: number; value: number; weighted: number;\n  won: number; lost: number; referred: number; win_rate: number;\n  label?: string;\n}\nexport interface PipelineLeaderboard {\n  level: string; origin: string; start: string; end: string;\n  rows: PipelineLeaderboardRow[];\n  total_deals: number; total_value: number; total_weighted: number;\n  branches: string[];\n  // Built from config, so a new origin appears without a frontend change.\n  origins?: { key: string; label: string; credits_party: boolean }[];\n}\nexport async function fetchPipelineLeaderboard(opts: {\n  days?: number; start?: string; end?: string;\n  level?: string; origin?: string; branch?: string; unit?: string;\n} = {}): Promise<PipelineLeaderboard> {\n  const q = new URLSearchParams();\n  if (opts.days) q.set('days', String(opts.days));\n  if (opts.start) q.set('start', opts.start);\n  if (opts.end) q.set('end', opts.end);\n  if (opts.level) q.set('level', opts.level);\n  if (opts.origin) q.set('origin', opts.origin);\n  if (opts.branch) q.set('branch', opts.branch);\n  if (opts.unit) q.set('unit', opts.unit);\n  return getJson<PipelineLeaderboard>(`/pipeline/leaderboard?${q.toString()}`);\n}\n\nexport interface DealOrigin {\n  key: string; label: string; credits_party: boolean;\n  party_label?: string; active?: boolean; note?: string;\n}\nexport interface PipelineOriginSplit {\n  origin: string; label?: string; credits_party?: boolean;\n  count: number; value: number; won: number;\n}\nexport interface OriginChannel {\n  key: string; label: string; origin: string; store: string;\n  supports_roi: boolean; party_label: string; note: string;\n}\nexport interface ChannelRecord {\n  id: string; channel: string; name: string; party: string;\n  owner_type: string; owner: string; branch: string; category: string;\n  start_date: string; end_date: string; status: string;\n  budget_kes: number | null; spent_kes: number | null;\n  target_leads: number | null; target_accounts: number | null;\n  target_value_kes: number | null;\n  leads: number; accounts: number; won_value: number;\n  roi_pct: number | null; supports_roi: boolean;\n}\nexport interface ChannelDeal {\n  id: string; client: string; product: string; value: number;\n  stage: string; gate: string; position: number;\n  closed: boolean; won: boolean;\n  owner: string; branch: string; source_id: string; opened: string;\n}\nexport async function fetchChannelDeals(\n  key: string, recordId = '',\n): Promise<{ channel: string; record_id: string; deals: ChannelDeal[]; total_value: number }> {\n  const q = new URLSearchParams(recordId ? { record_id: recordId } : {});\n  const qs = q.toString();\n  return getJson<{ channel: string; record_id: string; deals: ChannelDeal[]; total_value: number }>(\n    `/channels/${encodeURIComponent(key)}/deals${qs ? `?${qs}` : ''}`);\n}\nexport interface ChannelAnalytics {\n  channel: OriginChannel;\n  totals: {\n    records: number; spent: number; leads: number; accounts: number;\n    value: number; conversion_pct: number | null;\n    cost_per_account: number | null; roi_pct: number | null;\n    supports_roi: boolean;\n  };\n  by_owner: { owner: string; records: number; spent: number; leads: number;\n              accounts: number; value: number }[];\n  by_stage: { stage: string; count: number }[];\n  best: { id: string; name: string; owner: string; spent: number;\n          leads: number; accounts: number; value: number;\n          cost_per_account: number | null }[];\n  no_conversions: { id: string; name: string; leads: number }[];\n  untagged: { id: string; name: string }[];\n}\nexport async function fetchChannelAnalytics(key: string): Promise<ChannelAnalytics> {\n  return getJson<ChannelAnalytics>(`/channels/${encodeURIComponent(key)}/analytics`);\n}\nexport interface ChannelOwners {\n  units: { value: string; label: string }[];\n  branches: { value: string; label: string }[];\n  mine: { unit: string; branch: string };\n  is_admin: boolean;\n}\nexport async function fetchChannelOwners(): Promise<ChannelOwners> {\n  return getJson<ChannelOwners>('/channels/owners');\n}\n// \u2500\u2500 Deals Warehouse \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface WarehouseProspect {\n  id: string; name: string; sector: string; town: string; status: string;\n  estimated_value: number; source_event: string; notes: string;\n  created_by_name: string; created_at: string;\n  claimed_by_name: string; claimed_at: string; deal_id: string;\n  mine: boolean; contacts_visible: boolean;\n  score?: number; validated?: boolean; missing_count?: number;\n  contact_name?: string; contact_phone?: string; contact_email?: string;\n}\nexport interface ProspectFact {\n  id: string; kind: string; title: string; detail: string;\n  source: string; url: string; occurred_on: string;\n  added_by: string; added_at: string;\n}\nexport interface ProspectDetail {\n  prospect: WarehouseProspect;\n  card: { items: ProspectFact[]; counts: Record<string, number>; total: number };\n  completeness: Completeness;\n}\nexport async function fetchProspect(id: string): Promise<ProspectDetail> {\n  return getJson<ProspectDetail>(`/warehouse/prospects/${encodeURIComponent(id)}`);\n}\nexport async function addProspectFact(\n  id: string, body: Record<string, unknown>,\n): Promise<{ item: ProspectFact }> {\n  return postJson<{ item: ProspectFact }, Record<string, unknown>>(\n    `/warehouse/prospects/${encodeURIComponent(id)}/enrichment`, body);\n}\nexport interface WarehouseMine {\n  listed: WarehouseProspect[]; claimed: WarehouseProspect[];\n  stale: WarehouseProspect[];\n  counts: { listed: number; claimed: number; stale: number };\n}\nexport interface CompletenessField {\n  key: string; label: string; weight: number; why: string;\n}\nexport interface Completeness {\n  prospect_id: string; score: number; complete: boolean;\n  fully_complete: boolean; threshold: number;\n  have: string[]; missing: CompletenessField[];\n  answered: number; of: number;\n  validated: boolean; validated_by: string; validated_at: string;\n  stale_validation: boolean;\n}\nexport interface WarehouseCut {\n  label: string; total: number; validated: number; ready: number; average_score: number;\n}\nexport interface WarehouseAnalytics {\n  totals: { prospects: number; validated: number; ready_to_validate: number;\n            under_validation: number; average_score: number; claimed: number;\n            converted: number };\n  by_sector: WarehouseCut[]; by_segment: WarehouseCut[];\n  by_county: WarehouseCut[]; by_source: WarehouseCut[];\n  bands: { band: string; count: number }[];\n  gaps: { key: string; label: string; missing: number }[];\n}\nexport async function fetchWarehouseAnalytics(): Promise<WarehouseAnalytics> {\n  return getJson<WarehouseAnalytics>('/warehouse/analytics');\n}\nexport async function fetchCompletenessMatrix(): Promise<{\n  fields: CompletenessField[];\n  summary: { total: number; average_score: number; complete: number;\n             validated: number; worst_gaps: { key: string; label: string; missing: number }[] };\n  segments: string[]; sectors: string[]; counties: string[];\n}> {\n  return getJson('/warehouse/completeness');\n}\nexport async function updateProspect(\n  id: string, changes: Record<string, unknown>, password = '',\n): Promise<{ prospect: Record<string, unknown> }> {\n  return postJson<{ prospect: Record<string, unknown> }, Record<string, unknown>>(\n    `/warehouse/prospects/${encodeURIComponent(id)}`,\n    password ? { ...changes, password } : changes, 'PATCH');\n}\nexport async function validateProspect(id: string): Promise<{ completeness: Completeness }> {\n  return postJson<{ completeness: Completeness }, Record<string, never>>(\n    `/warehouse/prospects/${encodeURIComponent(id)}/validate`,\n    {} as Record<string, never>);\n}\nexport async function fetchWarehouseTaxonomy(): Promise<{ sectors: string[]; towns: string[] }> {\n  return getJson<{ sectors: string[]; towns: string[] }>('/warehouse/taxonomy');\n}\nexport async function fetchWarehouseShelves(\n  opts: { town?: string; sector?: string; q?: string } = {},\n): Promise<{ shelves: Record<string, WarehouseProspect[]>; total: number }> {\n  const qs = new URLSearchParams();\n  if (opts.town) qs.set('town', opts.town);\n  if (opts.sector) qs.set('sector', opts.sector);\n  if (opts.q) qs.set('q', opts.q);\n  const s = qs.toString();\n  return getJson<{ shelves: Record<string, WarehouseProspect[]>; total: number }>(\n    `/warehouse/shelves${s ? `?${s}` : ''}`);\n}\nexport async function fetchWarehouseMine(): Promise<WarehouseMine> {\n  return getJson<WarehouseMine>('/warehouse/mine');\n}\nexport async function createProspect(\n  body: Record<string, unknown>,\n): Promise<{ prospect: WarehouseProspect }> {\n  return postJson<{ prospect: WarehouseProspect }, Record<string, unknown>>(\n    '/warehouse/prospects', body);\n}\nexport async function claimProspect(\n  id: string,\n): Promise<{ prospect: WarehouseProspect; referrer_code: string; referrer_name: string }> {\n  return postJson<{ prospect: WarehouseProspect; referrer_code: string; referrer_name: string },\n                  Record<string, never>>(\n    `/warehouse/prospects/${encodeURIComponent(id)}/claim`, {} as Record<string, never>);\n}\nexport async function deleteProspect(\n  id: string, password = '',\n): Promise<{ deleted: string }> {\n  // Uses the existing postJson-with-method pattern rather than a new helper -\n  // one way of issuing a DELETE is enough.\n  const q = password ? `?password=${encodeURIComponent(password)}` : '';\n  return postJson<{ deleted: string }, Record<string, never>>(\n    `/warehouse/prospects/${encodeURIComponent(id)}${q}`,\n    {} as Record<string, never>, 'DELETE');\n}\nexport async function archiveProspect(\n  id: string, reason: string,\n): Promise<{ prospect: WarehouseProspect }> {\n  return postJson<{ prospect: WarehouseProspect }, { reason: string }>(\n    `/warehouse/prospects/${encodeURIComponent(id)}/archive`, { reason });\n}\nexport async function fetchChannels(): Promise<{ channels: OriginChannel[] }> {\n  return getJson<{ channels: OriginChannel[] }>('/channels');\n}\nexport async function fetchChannelRecords(\n  key: string, activeOnly = false, mine = false,\n): Promise<{ channel: OriginChannel; records: ChannelRecord[]; tagged_deals: number }> {\n  const q = new URLSearchParams({ active_only: String(activeOnly), mine: String(mine) });\n  return getJson<{ channel: OriginChannel; records: ChannelRecord[]; tagged_deals: number }>(\n    `/channels/${encodeURIComponent(key)}/records?${q.toString()}`);\n}\nexport async function createChannelRecord(\n  key: string, body: Record<string, unknown>,\n): Promise<{ record: ChannelRecord }> {\n  return postJson<{ record: ChannelRecord }, Record<string, unknown>>(\n    `/channels/${encodeURIComponent(key)}/records`, body);\n}\nexport interface PipelineEvent {\n  id: string; name: string; partner: string; branch: string;\n  department: string; category: string;\n  start_date: string; end_date: string; status: string;\n  budget_kes: number; spent_kes: number;\n  target_leads: number | null; target_accounts: number | null;\n  stored_leads: number | null; stored_accounts: number | null;\n  derived_leads: number; derived_accounts: number; derived_value: number;\n  derived_roi_pct: number | null; stored_roi_pct: number | null;\n}\nexport async function fetchPipelineEvents(\n  activeOnly = false,\n): Promise<{ events: PipelineEvent[]; tagged_deals: number; total_deals: number }> {\n  const q = new URLSearchParams({ active_only: String(activeOnly) });\n  return getJson<{ events: PipelineEvent[]; tagged_deals: number; total_deals: number }>(\n    `/pipeline/events?${q.toString()}`);\n}\nexport interface OriginSourceOption { id: string; label: string; sub: string }\nexport async function fetchOriginSources(\n  origin: string, activeOnly = true,\n): Promise<{ origin: string; field: string; options: OriginSourceOption[] }> {\n  const q = new URLSearchParams({ origin, active_only: String(activeOnly) });\n  return getJson<{ origin: string; field: string; options: OriginSourceOption[] }>(\n    `/pipeline/origin-sources?${q.toString()}`);\n}\nexport async function fetchDealOrigins(): Promise<{ origins: DealOrigin[]; default: string }> {\n  return getJson<{ origins: DealOrigin[]; default: string }>('/pipeline/origins');\n}\nexport interface PipelineJourneyFlow {\n  flow: string; deals: number; buckets: DefinedBucket[];\n}\nexport interface PipelineAnalyticsSummary {\n  start: string; end: string; days: number;\n  totals: {\n    deals: number; open: number; won: number; lost: number;\n    open_value: number; won_value: number; weighted: number; win_rate: number;\n  };\n  journey: PipelineJourneyFlow[];\n  origin: PipelineOriginSplit[];\n}\nexport async function fetchPipelineAnalyticsSummary(\n  days = 30, start = '', end = '',\n): Promise<PipelineAnalyticsSummary> {\n  const q = new URLSearchParams();\n  if (days) q.set('days', String(days));\n  if (start) q.set('start', start);\n  if (end) q.set('end', end);\n  return getJson<PipelineAnalyticsSummary>(`/pipeline/analytics/summary?${q.toString()}`);\n}\n\nexport async function fetchPipelineDefinedFunnel(\n  opts: { unit?: string; segment?: string } = {},\n): Promise<DefinedFunnel> {\n  const q = new URLSearchParams();\n  if (opts.unit) q.set('unit', opts.unit);\n  if (opts.segment) q.set('segment', opts.segment);\n  const qs = q.toString();\n  return getJson<DefinedFunnel>(`/pipeline/funnel${qs ? `?${qs}` : ''}`);\n}\n\n// \u2500\u2500 Cumulative leaderboard (staff / role / branch / unit) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface LeaderboardRow {\n  rank?: number;\n  name?: string;                       // role / branch / unit rows\n  staff_code?: string; staff_name?: string; role?: string; branch?: string; unit?: string;\n  index: number; target: number; achievement?: number;\n  headcount?: number; index_per_head?: number;\n  days_filed: number; validated: number; cf_variance?: number;\n  met_days?: number; scored_days?: number; met_rate?: number;\n  segment?: string;\n  label?: string;            // readable department name; `name` stays the key\n  avg_index?: number; avg_target?: number;   // per ON-DUTY day\n}\nexport interface Leaderboard {\n  level: string; days: number; rows: LeaderboardRow[];\n  total_index: number; total_headcount: number;\n  met_days?: number; scored_days?: number; met_rate?: number;\n  filters: { role: string; branch: string; unit: string };\n  roles: string[]; branches: string[]; units: string[]; segments?: string[];\n  unit_labels?: Record<string, string>;\n  // Segment level only: people held back because they bear the branch.\n  bears_branch?: { headcount: number; index: number } | null;\n}\nexport async function fetchBranchLogLeaderboard(opts: {\n  days?: number; level?: string; role?: string; branch?: string; unit?: string;\n  segment?: string; start?: string; end?: string;\n} = {}): Promise<Leaderboard> {\n  const q = new URLSearchParams();\n  if (opts.days) q.set('days', String(opts.days));\n  if (opts.start) q.set('start', opts.start);\n  if (opts.end) q.set('end', opts.end);\n  if (opts.level) q.set('level', opts.level);\n  if (opts.role) q.set('role', opts.role);\n  if (opts.branch) q.set('branch', opts.branch);\n  if (opts.unit) q.set('unit', opts.unit);\n  if (opts.segment) q.set('segment', opts.segment);\n  const s = q.toString();\n  return getJson<Leaderboard>(`/branch-log/leaderboard${s ? `?${s}` : ''}`);\n}\n\nexport async function fetchBranchLogRanking(days = 30): Promise<{ ranking: BranchLogRankRow[]; days: number; daily_index_target: number }> {\n  return getJson<{ ranking: BranchLogRankRow[]; days: number; daily_index_target: number }>(`/branch-log/ranking?days=${days}`);\n}\nexport async function fetchMyBranchLogs(days = 14): Promise<{ logs: BranchLogEntry[]; identity: Record<string, string> }> {\n  return getJson<{ logs: BranchLogEntry[]; identity: Record<string, string> }>(`/branch-log/mine?days=${days}`);\n}\nexport async function fetchPendingBranchLogs(): Promise<{ logs: BranchLogEntry[] }> {\n  return getJson<{ logs: BranchLogEntry[] }>('/branch-log/pending');\n}\nexport async function submitBranchLog(values: Record<string, number | string>): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, { values: Record<string, number | string> }>('/branch-log', { values });\n}\n\n// \u2500\u2500 Day-planner hourly model \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface HourMeeting { label: string; tier: string; span: number; source?: string; }\nexport interface HourBlock { counts: Record<string, number>; meetings: HourMeeting[]; note?: string; }\nexport type HourlyMap = Record<string, HourBlock>;\n\n// submit/draft carrying an hourly map (the planner path). Day totals are derived server-side.\nexport async function submitBranchLogHourly(hourly: HourlyMap, remarks?: string): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, { values: Record<string, unknown> }>(\n    '/branch-log', { values: { hourly, remarks: remarks ?? '' } });\n}\nexport async function saveBranchLogHourlyDraft(hourly: HourlyMap, remarks?: string): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, { values: Record<string, unknown> }>(\n    '/branch-log/draft', { values: { hourly, remarks: remarks ?? '' } });\n}\n\n// \u2500\u2500 Analytics (impact pie + validation split + totals) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface ImpactBreakdown {\n  high: number; medium: number; low: number; total: number; high_pct: number;\n  by_activity: Record<string, { tier: string; index: number }>;\n}\nexport interface BranchLogAnalytics {\n  days: number; scope_tier: string; impact: ImpactBreakdown; high_impact_keys: string[];\n  totals: { logs: number; submitters: number; validated: number; auto_submitted: number;\n            returned: number; pending: number; validation_rate: number };\n}\nexport async function fetchBranchLogAnalytics(\n  days = 30, unit = '', start = '', end = '',\n): Promise<BranchLogAnalytics> {\n  const p = new URLSearchParams();\n  if (days) p.set('days', String(days));\n  if (unit) p.set('unit', unit);\n  if (start) p.set('start', start);   // calendar window (quarter / YTD)\n  if (end) p.set('end', end);\n  const q = `?${p.toString()}`;\n  return getJson<BranchLogAnalytics>(`/branch-log/analytics${q}`);\n}\n\n// \u2500\u2500 History grid (one row per staff per day, with carried-forward variance) \u2500\nexport interface HistoryGridColumn { key: string; label: string; unit: string; type: string; tier: string; }\nexport interface HistoryGridRow {\n  log_date: string; staff_code: string; staff_name: string; role: string; unit: string;\n  status: string; validated: boolean; auto_submitted: boolean;\n  index: number; target: number; variance: number; cf_variance: number;\n  working_day?: boolean;   // false on Sundays / gazetted holidays (no target, no deficit)\n  remarks?: string; manager_note?: string;\n  department?: string; branch?: string;   // canonical, joined from the roster\n  [metric: string]: unknown;\n}\nexport interface HistoryGrid {\n  rows: HistoryGridRow[]; columns: HistoryGridColumn[]; days: number;\n  scope_tier: string; deadline_time: string;\n}\n// Daily-log validation queue: one day, the staff this manager may validate.\nexport interface ValidationQueueRow {\n  log_id: string; log_date: string;\n  staff_code: string; staff_name: string; role: string;\n  department: string; branch: string;\n  status: string; validated: boolean; auto_submitted: boolean;\n  index: number; target: number;\n  remarks: string; manager_note: string; validated_by?: string;\n  can_act: boolean;\n  [metric: string]: unknown;\n}\nexport interface ValidationQueue {\n  rows: ValidationQueueRow[]; columns: HistoryGridColumn[];\n  date: string; working_day: boolean; label: string;\n  mode: string; pending: number;\n  branch?: string;\n  staff_totals?: Record<string, number>;\n  control_totals?: Record<string, number>;\n  // ReconBranchDay/ReconMetric are declared further down this file with the\n  // other reconciliation types \u2014 reuse them rather than restating the shape.\n  reconciliation?: Partial<ReconBranchDay>;\n  branch_index?: number;\n  validated_count?: number;\n  filed_count?: number;\n}\nexport async function saveBranchControlTotals(\n  branch: string, date: string, totals: Record<string, number>,\n): Promise<{ status: string; totals: Record<string, number> }> {\n  return postJson<{ status: string; totals: Record<string, number> },\n                  { branch: string; date: string; totals: Record<string, number> }>(\n    '/branch-log/control-totals', { branch, date, totals });\n}\nexport async function fetchBranchLogValidationQueue(\n  date = '', branch = '', unit = '',\n): Promise<ValidationQueue> {\n  const q = new URLSearchParams();\n  if (date) q.set('date', date);\n  if (branch) q.set('branch', branch);      // tier-2 read-only inspection\n  if (unit) q.set('unit', unit);            // Head Office unit, read-only\n  const s = q.toString();\n  return getJson<ValidationQueue>(`/branch-log/validation-queue${s ? `?${s}` : ''}`);\n}\n\n// \u2500\u2500 Tier 2: branch-day countersign \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface BranchDayRow {\n  branch: string;\n  expected: number; filed: number; validated: number; pending: number; not_filed: number;\n  status: string;               // draft | submitted | validated | returned\n  branch_index: number;\n  submitted_by_name: string; submitted_at: string;\n  return_note: string; validated_by_name: string;\n  over_reported: number;\n}\nexport interface BranchDays {\n  rows: BranchDayRow[]; date: string; mode: string;\n  all_view: boolean; working_day: boolean; label?: string;\n}\nexport interface NonSubmitterRow {\n  staff_code: string; staff_name: string; role: string;\n  branch: string; department: string;\n  days_outstanding: number;\n  exception: string; exception_note: string;\n}\nexport interface NonSubmitters {\n  rows: NonSubmitterRow[]; date: string; total: number; working_day?: boolean;\n  bank_wide?: boolean;\n}\nexport async function fetchNonSubmitters(date = ''): Promise<NonSubmitters> {\n  return getJson<NonSubmitters>(\n    `/branch-log/non-submitters${date ? `?date=${encodeURIComponent(date)}` : ''}`);\n}\nexport interface UnitRow {\n  key: string; name: string; kind: string;            // branch | unit | rollup\n  expected: number; filed: number; validated: number; not_filed: number;\n  status: string; index: number; owner: string; over_reported: number;\n  can_countersign?: boolean;\n  count?: number; countersigned?: number;             // rollup only\n  children?: UnitRow[];\n}\nexport interface UnitDays {\n  branches: UnitRow | null; units: UnitRow[];\n  date: string; working_day?: boolean; label?: string;\n  top_of_house: boolean; can_return?: boolean;\n}\nexport async function fetchUnitDays(date = ''): Promise<UnitDays> {\n  return getJson<UnitDays>(\n    `/branch-log/unit-days${date ? `?date=${encodeURIComponent(date)}` : ''}`);\n}\nexport async function fetchBranchDays(date = ''): Promise<BranchDays> {\n  return getJson<BranchDays>(\n    `/branch-log/branch-days${date ? `?date=${encodeURIComponent(date)}` : ''}`);\n}\nexport async function submitBranchDay(\n  branch: string, date: string, branchIndex: number,\n  staffTotals: Record<string, number>, controlTotals: Record<string, number>,\n  counts: Record<string, number>,\n): Promise<{ branch_day: Record<string, unknown> }> {\n  return postJson<{ branch_day: Record<string, unknown> }, Record<string, unknown>>(\n    '/branch-log/branch-days/submit',\n    { branch, date, branch_index: branchIndex, staff_totals: staffTotals,\n      control_totals: controlTotals, counts });\n}\nexport async function decideBranchDay(\n  branch: string, date: string, approved: boolean, note = '',\n): Promise<{ branch_day: Record<string, unknown> }> {\n  return postJson<{ branch_day: Record<string, unknown> },\n                  { branch: string; date: string; approved: boolean; note: string }>(\n    '/branch-log/branch-days/validate', { branch, date, approved, note });\n}\n\nexport async function fetchBranchLogHistoryGrid(days = 30, unit = ''): Promise<HistoryGrid> {\n  const q = unit ? `?days=${days}&unit=${encodeURIComponent(unit)}` : `?days=${days}`;\n  return getJson<HistoryGrid>(`/branch-log/history-grid${q}`);\n}\n\n// \u2500\u2500 Impact matrix (80/20) \u2014 admin \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface ImpactTiersResponse {\n  impact_tiers: Record<string, string>;\n  activities: { key: string; label: string; unit: string }[];\n}\nexport async function fetchBranchLogImpactTiers(): Promise<ImpactTiersResponse> {\n  return getJson<ImpactTiersResponse>('/branch-log/impact-tiers');\n}\nexport async function saveBranchLogImpactTiers(tiers: Record<string, string>): Promise<{ status: string; impact_tiers: Record<string, string> }> {\n  return postJson<{ status: string; impact_tiers: Record<string, string> }, { tiers: Record<string, string> }>(\n    '/branch-log/impact-tiers', { tiers });\n}\n\n// \u2500\u2500 Lifecycle actions (manager return, admin unlock, admin cf-reset) \u2500\u2500\u2500\u2500\u2500\u2500\nexport async function returnBranchLog(logId: string, note: string): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, { note: string }>(`/branch-log/${encodeURIComponent(logId)}/return`, { note });\n}\nexport async function unlockBranchLog(logId: string): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, Record<string, never>>(`/branch-log/${encodeURIComponent(logId)}/unlock`, {});\n}\nexport async function resetBranchLogCarryForward(date?: string): Promise<{ status: string }> {\n  return postJson<{ status: string }, { date?: string }>('/branch-log/cf-reset', date ? { date } : {});\n}\n\n// \u2500\u2500 Reconciliation (branch over-reporting) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface ReconContributor { staff_code: string; staff_name: string; reported: number; }\nexport interface ReconMetric {\n  reported_sum: number; control_total: number; over_by: number; anomaly: boolean;\n  contributors: ReconContributor[];\n}\nexport interface ReconBranchDay {\n  branch: string; date: string; metrics: Record<string, ReconMetric>;\n  anomaly_count: number; log_count: number;\n}\nexport interface ReconciliationResponse {\n  reconciliations: ReconBranchDay[]; anomaly_total?: number; days?: number; scope_tier: string;\n}\nexport async function fetchBranchLogReconciliation(days = 7): Promise<ReconciliationResponse> {\n  return getJson<ReconciliationResponse>(`/branch-log/reconciliation?days=${days}`);\n}\nexport async function setBranchControlTotals(branch: string, date: string, totals: Record<string, number>): Promise<{ status: string; totals: Record<string, number> }> {\n  return postJson<{ status: string; totals: Record<string, number> }, { branch: string; date: string; totals: Record<string, number> }>(\n    '/branch-log/control-totals', { branch, date, totals });\n}\n// Item 3: save the daily log as a private DRAFT (not submitted for validation).\nexport async function saveBranchLogDraft(values: Record<string, number | string>): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, { values: Record<string, number | string> }>('/branch-log/draft', { values });\n}\n// Item 3: fetch today's log (draft or submitted) to re-hydrate the form.\nexport async function fetchBranchLogDraft(): Promise<{ log: BranchLogEntry | null }> {\n  return getJson<{ log: BranchLogEntry | null }>('/branch-log/draft');\n}\nexport async function validateBranchLog(logId: string, approved: boolean, note: string): Promise<{ log: BranchLogEntry }> {\n  return postJson<{ log: BranchLogEntry }, { approved: boolean; note: string }>(\n    `/branch-log/${encodeURIComponent(logId)}/validate`, { approved, note });\n}\n\n\nexport async function reassignReferral(\n  dealId: string, code: string, name: string, note: string,\n): Promise<{ status?: string }> {\n  return postJson<{ status?: string },\n    { referred_to_code: string; referred_to_name: string; referral_note: string }>(\n    `/pipeline/deals/${dealId}/referral/reassign`,\n    { referred_to_code: code, referred_to_name: name, referral_note: note });\n}\n\n\n// \u2500\u2500 Staff picker (referral recipient) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport interface StaffMember {\n  staff_code: string;\n  name: string;\n  role?: string;\n  unit?: string;\n  region?: string;\n  segment?: string;\n}\n\nexport interface StaffSearchResponse {\n  staff: StaffMember[];\n  count: number;\n}\n\nexport interface StaffSegment {\n  segment: string;\n  count: number;\n}\n\nexport interface StaffSegmentsResponse {\n  segments: StaffSegment[];\n  count: number;\n}\n\n/** Distinct staff segments (Department) for the picker's first step. */\nexport async function fetchStaffSegments(): Promise<StaffSegmentsResponse> {\n  return getJson<StaffSegmentsResponse>('/staff/segments');\n}\n\n/** Search the roster, optionally within one segment. */\nexport async function searchStaff(q: string, segment: string, branch?: string): Promise<StaffSearchResponse> {\n  const params = new URLSearchParams();\n  if (q) params.set('q', q);\n  if (segment) params.set('segment', segment);\n  if (branch) params.set('branch', branch);\n  const qs = params.toString();\n  return getJson<StaffSearchResponse>(`/staff/search${qs ? `?${qs}` : ''}`);\n}\n\nexport interface ReferExistingResponse {\n  status?: string;\n  referred_to?: string;\n  referred_to_code?: string;\n}\n\n/** Refer an EXISTING deal to a chosen recipient (-> pending). */\nexport async function referExistingDeal(\n  dealId: string,\n  body: { referred_to_code: string; referred_to_name: string; referral_note: string },\n): Promise<ReferExistingResponse> {\n  return postJson<ReferExistingResponse,\n    { referred_to_code: string; referred_to_name: string; referral_note: string }>(\n    `/pipeline/deals/${dealId}/refer`, body);\n}\n\n\n// \u2500\u2500 CBS portfolio owner (mapped relationship manager) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport interface CustomerPortfolioOwner {\n  cif: string;\n  customer_name: string;\n  is_mapped: boolean;\n  portfolio_owner_code: string | null;\n  portfolio_owner_name: string | null;\n  owner_in_roster: boolean;\n  relationship_manager_code: string;\n}\n\n/** Resolve the portfolio owner (relationship manager) mapped to a CIF. */\nexport async function fetchCustomerPortfolioOwner(cif: string): Promise<CustomerPortfolioOwner> {\n  return getJson<CustomerPortfolioOwner>(\n    `/cbs/customers/${encodeURIComponent(cif)}/portfolio-owner`);\n}\n\n\n/**\n * Fetch pipeline analytics from /api/pipeline/analytics \u2014 validated/pending\n * value split, per-class buckets (asset/liability/insurance/other), the\n * validated funnel, and the scope-aware pending-validation count.\n */\nexport async function fetchPipelineAnalytics(\n  opts: { unit?: string; segment?: string } = {},\n): Promise<PipelineAnalyticsResponse> {\n  const q = new URLSearchParams();\n  if (opts.unit) q.set('unit', opts.unit);\n  if (opts.segment) q.set('segment', opts.segment);\n  const qs = q.toString();\n  return getJson<PipelineAnalyticsResponse>(`/pipeline/analytics${qs ? `?${qs}` : ''}`);\n}\n\nexport async function fetchPipelineDrill(\n  unit?: string, rm?: string,\n): Promise<PipelineDrillResponse> {\n  const p = new URLSearchParams();\n  if (unit) p.set('unit', unit);\n  if (rm) p.set('rm', rm);\n  const qs = p.toString();\n  return getJson<PipelineDrillResponse>(`/pipeline/drill${qs ? `?${qs}` : ''}`);\n}\n\nexport async function fetchFunnelDrill(\n  cls: string, stage: string,\n): Promise<FunnelDrillResponse> {\n  const p = new URLSearchParams();\n  p.set('cls', cls || 'all');\n  if (stage) p.set('stage', stage);\n  return getJson<FunnelDrillResponse>(`/pipeline/funnel/drill?${p.toString()}`);\n}\n\nexport async function fetchCreditAnalytics(): Promise<CreditAnalyticsResponse> {\n  return getJson<CreditAnalyticsResponse>('/credit/analytics');\n}\n\nexport async function fetchDashboardExceptions(): Promise<ExceptionsResponse> {\n  return getJson<ExceptionsResponse>('/dashboard/exceptions');\n}\n\nexport async function fetchCreditDrill(\n  region?: string, branch?: string, rm?: string,\n): Promise<CreditDrillResponse> {\n  const p = new URLSearchParams();\n  if (region) p.set('region', region);\n  if (branch) p.set('branch', branch);\n  if (rm) p.set('rm', rm);\n  const qs = p.toString();\n  return getJson<CreditDrillResponse>(`/credit/drill${qs ? `?${qs}` : ''}`);\n}\n\n\n/**\n * Fetch a single deal by id from /api/pipeline/deals/{deal_id}.\n *\n * Auth: REQUIRED. Returns 404 (not 403) when the deal exists but is\n * outside the caller's cascade scope \u2014 deliberate to avoid leaking\n * deal existence (\u03b17 / G400 design decision).\n *\n * Response shape differs from the list: the deal is at `response.deal`\n * and permissions live at `response.permissions` (not embedded in deal).\n */\nexport async function fetchPipelineDealDetail(\n  dealId: string,\n): Promise<PipelineDealDetailResponse> {\n  return getJson<PipelineDealDetailResponse>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}`,\n  );\n}\n\n\n/**\n * Fetch the credit-submission checklist for a deal\n * (GET /api/pipeline/deals/{id}/credit-checklist).\n *\n * Returns the required documents (from lms_config's tiered checklist),\n * which are already provided, which are still missing, whether the deal\n * has already been submitted, and whether the caller may submit it.\n */\nexport interface NextStep {\n  deal_id: string; current_stage: string; next_stage: string;\n  submit_label: string; flow: string[];\n  documents: { name: string; attached_by: string; mandatory: boolean }[];\n  by_attacher: { attacher: string; have: string[]; outstanding: string[] }[];\n  owner_outstanding: string[]; blocking: string[]; can_submit: boolean;\n  attachers: { key: string; label: string }[];\n}\nexport async function fetchNextStep(dealId: string): Promise<NextStep> {\n  return getJson<NextStep>(`/pipeline/deals/${encodeURIComponent(dealId)}/next-step`);\n}\nexport interface CommitteeQueueCase {\n  /** Whether THIS member has already voted on every committee still pending\n   *  for this case. Without it the list said \"Review\" beside cases somebody\n   *  had already dealt with, and they could not tell which. */\n  you_voted?: boolean;\n  your_vote?: string;\n  deal_id: string; client_name: string; product: string;\n  deal_value?: number; currency?: string; branch?: string; stage?: string;\n  owner?: string; awaiting: string[]; awaiting_names: string[];\n  submitted_at?: string;\n}\nexport interface CommitteeQueueResponse {\n  committees: { code: string; name: string; members: number }[];\n  cases: CommitteeQueueCase[];\n  total: number;\n}\nexport async function fetchCommitteeQueue(): Promise<CommitteeQueueResponse> {\n  return getJson<CommitteeQueueResponse>('/pipeline/queues/committee');\n}\nexport async function fetchCreditChecklist(\n  dealId: string,\n): Promise<CreditChecklistResponse> {\n  return getJson<CreditChecklistResponse>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/credit-checklist`,\n  );\n}\n\n\n/**\n * Submit a deal to credit analysis\n * (POST /api/pipeline/deals/{id}/submit-to-credit).\n *\n * Auth: REQUIRED. Owner or admin only. Throws ApiValidationError (400)\n * when required documents are missing \u2014 the message lists them. On\n * success the deal is linked to a new loan application.\n */\nexport async function submitDealToCredit(\n  dealId: string,\n  documentsProvided: string[],\n): Promise<SubmitToCreditResponse> {\n  return postJson<SubmitToCreditResponse, { documents_provided: string[] }>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/submit-to-credit`,\n    { documents_provided: documentsProvided },\n  );\n}\n\n\n// \u2500\u2500 Pipeline mutation fetchers (v10.511 Phase 4 Batch \u03b22) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n//\n// Wraps the \u03b13 advance + \u03b16 cancel-request endpoints. Server enforces\n// the load-bearing rules (authorization, scope, stage transitions,\n// minimum reason length); these fetchers just shape the request/\n// response.\n\n\n/**\n * Advance a deal to a new stage via POST /api/pipeline/deals/{id}/advance.\n *\n * Auth: REQUIRED. Server enforces \u03b13 + \u03b14 logic \u2014 only valid stage\n * transitions allowed, LMS handoff triggered automatically when\n * advancing into Compliance, scope check applied (caller must own\n * the deal, back it up, or be a manager-in-scope).\n *\n * Throws ApiValidationError (400) on:\n *   - invalid target stage\n *   - terminal-stage deal (cannot advance Closed Won/Lost)\n *   - scope violation\n *\n * Response includes the updated deal + LMS handoff metadata when\n * the advance crossed into a credit-stage.\n */\nexport async function advancePipelineDeal(\n  dealId: string,\n  body: AdvanceDealRequest,\n): Promise<AdvanceDealResponse> {\n  return postJson<AdvanceDealResponse, AdvanceDealRequest>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/advance`,\n    body,\n  );\n}\n\n\n/**\n * Request cancellation of a deal via POST /api/pipeline/deals/{id}/cancel/request.\n *\n * Auth: REQUIRED. Any authenticated user with scope access \u2014 the\n * asymmetric authorization model from \u03b16 (anyone can request, only\n * managers can approve). Reason must be \u2265 MIN_CANCEL_REASON_LEN (5)\n * chars per server validation.\n *\n * Throws ApiValidationError (400) on:\n *   - missing or too-short reason\n *   - terminal-stage deal\n *   - already-pending cancel request\n *\n * After success, the deal carries `cancel_requested: true` and\n * `awaiting_manager: true` \u2014 surfaces in the manager's cancellation\n * queue (\u03b16) for approve/reject decision.\n */\nexport async function requestPipelineDealCancel(\n  dealId: string,\n  body: RequestCancelRequest,\n): Promise<RequestCancelResponse> {\n  return postJson<RequestCancelResponse, RequestCancelRequest>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/cancel/request`,\n    body,\n  );\n}\n\n\n// \u2500\u2500 Pipeline create + refer fetchers (v10.512 Phase 4 Batch \u03b23) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n//\n// The two creation paths. Server enforces the load-bearing rules:\n//   - REQUIRED_CREATE_FIELDS presence + non-empty\n//   - deal_value non-negative number\n//   - stage in ALLOWED_ADVANCE_STAGES (LMS stages rejected)\n//   - is_override_semantics \u2192 manager_override_note required (>=10 chars)\n//   - REQUIRED_REFER_FIELDS presence + non-empty\n//   - refer: staff_code != portfolio_owner_code (no self-referral)\n\n\n/**\n * Create a new pipeline deal via POST /api/pipeline/deals.\n *\n * Auth: REQUIRED. Server validates payload via validate_create_payload\n * in utils/api_pipeline_mutations.py.\n *\n * Conflict resolution (\u03b15):\n *   - \"Seek permission\" path:    bsc_credit_to = portfolio_owner_name (or unset)\n *                                NO manager_override_note required\n *   - \"Override\" path:           bsc_credit_to = caller's own name\n *                                manager_override_note REQUIRED, \u226510 chars\n *\n * Throws ApiValidationError on:\n *   - Missing required fields\n *   - deal_value negative or not numeric\n *   - Stage not in allowlist\n *   - Override semantics detected without sufficient note\n */\nexport async function createPipelineDeal(\n  body: CreateDealRequest,\n): Promise<CreateDealResponse> {\n  return postJson<CreateDealResponse, CreateDealRequest>(\n    '/pipeline/deals',\n    body,\n  );\n}\n\n// \u2500\u2500\u2500 Initiatives authoring (Phase 1) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface CreateInitiativeBody {\n  name: string; objective: string; category: string;\n  workstream: string; io: string; sub_workstream?: string;\n}\nexport async function createInitiative(\n  body: CreateInitiativeBody,\n): Promise<{ status: string; id?: string }> {\n  return postJson<{ status: string; id?: string }, CreateInitiativeBody>(\n    '/initiatives', body,\n  );\n}\n\nexport interface AddMilestoneBody {\n  name: string; owner: string; due_date: string;\n  type?: string; start_date?: string; description?: string;\n}\nexport async function addMilestone(\n  initiativeId: string, body: AddMilestoneBody,\n): Promise<{ status: string; milestone_id?: string }> {\n  return postJson<{ status: string; milestone_id?: string }, AddMilestoneBody>(\n    `/initiatives/${encodeURIComponent(initiativeId)}/milestones`, body,\n  );\n}\n\nexport interface MilestoneStatusBody {\n  status: string; note?: string; started?: boolean;\n}\nexport async function setMilestoneStatus(\n  initiativeId: string, msId: string, body: MilestoneStatusBody,\n): Promise<{ status: string }> {\n  return postJson<{ status: string }, MilestoneStatusBody>(\n    `/initiatives/${encodeURIComponent(initiativeId)}/milestones/${encodeURIComponent(msId)}/status`,\n    body, 'PATCH',\n  );\n}\n\n\n/**\n * Refer a deal to its portfolio owner via POST /api/pipeline/deals/refer.\n *\n * Auth: REQUIRED. Server validates via validate_refer_payload.\n * Server auto-sets: is_referral=true, product_type=\"Referral\",\n * stage=\"Lead\", deal_value=0, probability=0.05.\n *\n * Throws ApiValidationError on:\n *   - Missing required fields (REQUIRED_REFER_FIELDS)\n *   - staff_code === portfolio_owner_code (cannot refer to self)\n */\nexport async function referPipelineDeal(\n  body: ReferDealRequest,\n): Promise<ReferDealResponse> {\n  return postJson<ReferDealResponse, ReferDealRequest>(\n    '/pipeline/deals/refer',\n    body,\n  );\n}\n\n\n// \u2500\u2500 Manager queue + action fetchers (v10.513 Phase 4 Batch \u03b24) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n//\n// Wraps the \u03b16 manager-only endpoints. Server enforces is_manager()\n// authorization via utils/api_pipeline_manager_actions.py \u2014 non-managers\n// get 403 (not 401). The React UI uses lib/role.ts::isManager to avoid\n// surfacing these endpoints to non-managers in the first place, but the\n// server is the security boundary.\n\n\n/**\n * Fetch the validation queue from /api/pipeline/queues/validation.\n *\n * Auth: REQUIRED + manager-only. Returns deals past Lead stage that\n * haven't been validated yet (and aren't pending cancellation), scoped\n * to the caller's cascade.\n *\n * 403 here means the caller isn't a manager. The page handles this\n * gracefully by checking isManager(user) before fetch.\n */\nexport async function fetchValidationQueue(): Promise<ValidationQueueResponse> {\n  return getJson<ValidationQueueResponse>('/pipeline/queues/validation');\n}\n\n\n/**\n * Fetch the cancellation queue from /api/pipeline/queues/cancellation.\n *\n * Auth: REQUIRED + manager-only. Returns deals with pending cancellation\n * requests awaiting manager decision, scoped to caller's cascade.\n */\nexport async function fetchCancellationQueue(): Promise<CancellationQueueResponse> {\n  return getJson<CancellationQueueResponse>('/pipeline/queues/cancellation');\n}\n\n\n/**\n * Validate or query a deal via POST /api/pipeline/deals/{id}/validate.\n *\n * Auth: REQUIRED + manager-only + deal must be in caller's cascade scope.\n *\n * Two outcomes based on body.approved:\n *   true  \u2192 DEAL_VALIDATED, deal joins forecast (manager_validated:true)\n *   false \u2192 DEAL_QUERIED, deal returns to owner with note (still\n *           manager_validated:false; the note is visible to owner)\n *\n * Throws ApiValidationError on validation failure (rare \u2014 server\n * accepts any boolean+note).\n */\nexport async function validatePipelineDeal(\n  dealId: string,\n  body: ValidateDealRequest,\n): Promise<ValidateDealResponse> {\n  return postJson<ValidateDealResponse, ValidateDealRequest>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/validate`,\n    body,\n  );\n}\n\n\n/**\n * Approve or reject a cancellation request via\n * POST /api/pipeline/deals/{id}/cancel/approve.\n *\n * Auth: REQUIRED + manager-only + deal must have pending cancel_requested.\n *\n * Two outcomes based on body.approve:\n *   true  \u2192 CANCEL_APPROVED, deal transitions to Closed Lost\n *   false \u2192 CANCEL_REJECTED, deal continues, cancel_requested cleared\n *\n * Throws ApiValidationError if the deal has no pending cancel request\n * (server rejects with 400).\n */\nexport async function approvePipelineDealCancel(\n  dealId: string,\n  body: ApproveCancelRequest,\n): Promise<ApproveCancelResponse> {\n  return postJson<ApproveCancelResponse, ApproveCancelRequest>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/cancel/approve`,\n    body,\n  );\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// LMS (Loan Application Management System) fetchers\n// \u03b25 Phase 4 \u2014 consumes \u03b18 backend (utils/api_lms_routes.py)\n//\n// 5 endpoints under /api/lms/applications. All require Bearer JWT.\n// Cascade-scoped (rm_code + analyst-override). Audit emission per \u03b18.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  LoanApplicationsResponse,\n  LoanApplicationDetailResponse,\n  LoanAppMutationResponse,\n  AssignAnalystRequest,\n  LoanAppUpdateRequest,\n  RecordDecisionRequest,\n  RequestInfoRequest,\n  ProvideInfoRequest,\n  SignOfferRequest,\n  ValidateOfferRequest,\n  ConfirmToCreditAdminRequest,\n  CommitteeVoteRequest,\n  ResolveCommitteeRequest,\n  AppSla,\n  LoanAppHistoryEvent,\n} from '@/types/lms';\n\n\n/**\n * Fetch the cascade-scoped list of loan applications.\n *\n * Auth: REQUIRED. Server filters by caller's visible_codes (cascade\n * walk) PLUS analyst-override (caller's staff_code matches\n * application.analyst.code). Admins see everything.\n *\n * Returns: { applications: [], count: N, source: 'loan_application_manager' }\n */\nexport async function fetchLmsApplications(): Promise<LoanApplicationsResponse> {\n  return getJson<LoanApplicationsResponse>('/lms/applications');\n}\n\n// Pipeline-origin credit flow grouped by workflow stage \u2014 the live credit\n// workload (NOT the loan book / NPL view, which is deferred to Phase-2 Credit\n// Monitoring). Scoped to the caller's cascade.\nexport interface CreditFlowStage {\n  key: string;\n  label: string;\n  count: number;\n  value: number;\n}\nexport interface CreditFlowByStageResponse {\n  stages: CreditFlowStage[];\n  totals: {\n    count: number;\n    value: number;\n    in_flight_count: number;\n    in_flight_value: number;\n  };\n  source: string;\n}\nexport async function fetchCreditFlowByStage(): Promise<CreditFlowByStageResponse> {\n  return getJson<CreditFlowByStageResponse>('/lms/flow-by-stage');\n}\n\n// Troops (Treasury Back Office) disbursement flow grouped by stage \u2014 the live\n// disbursement workload (cleared \u2192 booked \u2192 value-dated \u2192 disbursed). Bank-wide,\n// role-gated to Treasury Back Office.\nexport interface TroopsFlowStage {\n  key: string;\n  label: string;\n  count: number;\n  value: number;\n}\nexport interface TroopsFlowByStageResponse {\n  stages: TroopsFlowStage[];\n  totals: {\n    count: number;\n    value: number;\n    pending_count: number;\n    pending_value: number;\n  };\n  source: string;\n}\nexport async function fetchTroopsFlowByStage(): Promise<TroopsFlowByStageResponse> {\n  return getJson<TroopsFlowByStageResponse>('/credit-admin/troops/flow-by-stage');\n}\n\n\n/**\n * Fetch a single application by id.\n *\n * Auth: REQUIRED. Returns 404 if not found, 403 if out-of-scope.\n * Response includes per-caller permissions object that React uses\n * to decide which action buttons to enable.\n */\nexport async function fetchLmsApplicationDetail(\n  appId: string,\n): Promise<LoanApplicationDetailResponse> {\n  return getJson<LoanApplicationDetailResponse>(\n    `/lms/applications/${encodeURIComponent(appId)}`,\n  );\n}\n\n\n/**\n * Assign a credit analyst to a submitted application. Manager-tier only.\n *\n * Throws ApiValidationError (400) on:\n *   - Missing analyst_code or analyst_name\n *   - Application status != 'submitted' (re-assignment not allowed)\n * Server returns 403 if caller is not manager-tier.\n */\nexport async function assignLmsAnalyst(\n  appId: string,\n  body: AssignAnalystRequest,\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, AssignAnalystRequest>(\n    `/lms/applications/${encodeURIComponent(appId)}/assign`,\n    body,\n  );\n}\n\n/**\n * Self-pick: an analyst pulls an unallocated case to themselves (no manager\n * assignment). Gated server-side by can_self_pick.\n */\nexport async function pickLmsApplication(\n  appId: string,\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, Record<string, never>>(\n    `/lms/applications/${encodeURIComponent(appId)}/pick`,\n    {},\n  );\n}\n\n/**\n * Department Analyst: voice support + submit the case to the Department Credit\n * Committee. Records opinion + PEP confirmation and refers onward. Gated\n * server-side by can_submit_to_dcc; enforces the completeness gate (required\n * attachments + PEP) with a 400 on failure.\n */\nexport async function submitLmsToDcc(\n  appId: string,\n  body: { opinion: string; pep_confirmed: boolean },\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { opinion: string; pep_confirmed: boolean }>(\n    `/lms/applications/${encodeURIComponent(appId)}/submit-to-dcc`,\n    body,\n  );\n}\n\n// Department Credit Committee (P4b) \u2014 self-contained, distinct from the\n// authority-tier charter. Roster + votes live on the application.\nexport interface DccMember { id?: string; member_id?: string; name?: string; role?: string }\nexport interface DccVote { member_id: string; vote: string; rationale?: string; by?: string; at?: string }\nexport interface DccOutcome {\n  recommendation: string;\n  tally: { yes: number; no: number; abstain: number };\n  by?: string; by_name?: string; at?: string; note?: string;\n}\nexport interface DccRosterResponse {\n  enabled: boolean; name: string; is_dcc_case: boolean;\n  members: DccMember[]; votes: DccVote[]; outcome?: DccOutcome | null;\n}\nexport async function getDccRoster(appId: string): Promise<DccRosterResponse> {\n  return getJson<DccRosterResponse>(\n    `/lms/applications/${encodeURIComponent(appId)}/dcc/roster`);\n}\nexport async function recordDccVote(\n  appId: string,\n  body: { member_id: string; vote: string; rationale: string },\n): Promise<{ dcc_votes: DccVote[] }> {\n  return postJson<{ dcc_votes: DccVote[] }, { member_id: string; vote: string; rationale: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/dcc/vote`,\n    body,\n  );\n}\nexport async function resolveDcc(\n  appId: string,\n  body: { note?: string },\n): Promise<{ dcc_outcome: DccOutcome }> {\n  return postJson<{ dcc_outcome: DccOutcome }, { note?: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/dcc/resolve`,\n    body,\n  );\n}\n/** The rework is done - send the case back to the analyst who returned it.\n *  Not into the pool: they have the context, and re-queueing turns a two-hour\n *  correction into a two-day one. */\nexport async function resubmitAfterRework(\n  appId: string,\n  body: { note?: string } = {},\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse>(\n    `/lms/applications/${encodeURIComponent(appId)}/resubmit-after-rework`, body);\n}\n\nexport async function handToCreditAnalyst(appId: string): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, Record<string, never>>(\n    `/lms/applications/${encodeURIComponent(appId)}/hand-to-credit-analyst`,\n    {},\n  );\n}\nexport async function uploadCallbackMemo(\n  appId: string,\n  body: { filename: string; content_b64: string },\n): Promise<{ document_files: Record<string, unknown> }> {\n  return postJson<{ document_files: Record<string, unknown> }, { filename: string; content_b64: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/callback-memo`,\n    body,\n  );\n}\n\n\n/**\n * Partial update to application fields.\n *\n * Throws ApiValidationError (400) on:\n *   - Status not in {submitted, assigned} (no edits after decision)\n *   - completeness_score out of 0..100 range\n *   - No updatable fields provided (empty body)\n * Server returns 403 if caller has no stake (not owner/analyst/manager).\n *\n * Uses PUT method via postJson's 3rd arg.\n */\nexport async function updateLmsApplication(\n  appId: string,\n  body: LoanAppUpdateRequest,\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, LoanAppUpdateRequest>(\n    `/lms/applications/${encodeURIComponent(appId)}`,\n    body,\n    'PUT',\n  );\n}\n\n\n/**\n * Record approve/decline/return decision. Manager-tier only.\n *\n * Throws ApiValidationError (400) on:\n *   - Missing verdict or authority\n *   - verdict not in {approve, approved, decline, declined, return, returned}\n *   - Status not in {submitted, assigned}\n * Server returns 403 if caller not manager-tier.\n *\n * Verdict normalized server-side to canonical {approved|declined|returned}.\n */\nexport async function recordLmsDecision(\n  appId: string,\n  body: RecordDecisionRequest,\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, RecordDecisionRequest>(\n    `/lms/applications/${encodeURIComponent(appId)}/decision`,\n    body,\n  );\n}\n\n// \u2500\u2500 Credit workflow fetchers (v10.587) \u2500\u2500\nconst lmsAction = (appId: string, action: string) =>\n  `/lms/applications/${encodeURIComponent(appId)}/${action}`;\n\nexport async function requestLmsInfo(appId: string, body: RequestInfoRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, RequestInfoRequest>(lmsAction(appId, 'request-info'), body);\n}\nexport async function provideLmsInfo(appId: string, body: ProvideInfoRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, ProvideInfoRequest>(lmsAction(appId, 'provide-info'), body);\n}\nexport async function escalateLmsApplication(appId: string, body: { reason: string; to_manager?: string }): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { reason: string; to_manager?: string }>(lmsAction(appId, 'escalate'), body);\n}\nexport async function addLmsManagerView(appId: string, body: { view: string }): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { view: string }>(lmsAction(appId, 'manager-view'), body);\n}\nexport interface LmsAttachment {\n  id: string; kind: string; filename?: string; ref?: string;\n  added_by?: string; added_at?: string; meta?: Record<string, unknown>;\n}\nexport async function listLmsAttachments(appId: string): Promise<{ attachments: LmsAttachment[]; bcc?: Record<string, unknown> | null }> {\n  return getJson<{ attachments: LmsAttachment[]; bcc?: Record<string, unknown> | null }>(`/lms/applications/${appId}/attachments`);\n}\nexport async function addLmsAttachment(appId: string, body: { kind: string; filename?: string; ref?: string }): Promise<{ attachment: LmsAttachment; attachments: LmsAttachment[] }> {\n  return postJson<{ attachment: LmsAttachment; attachments: LmsAttachment[] }, typeof body>(lmsAction(appId, 'attachments'), body);\n}\nexport async function recordLmsBcc(appId: string, body: { verdict: string; branch?: string; chaired_by?: string; attendees?: string[]; minutes?: string; filename?: string; ref?: string }): Promise<Record<string, unknown>> {\n  return postJson<Record<string, unknown>, typeof body>(lmsAction(appId, 'bcc'), body);\n}\nexport interface CrField { key: string; label: string; source: 'auto' | 'cbs' | 'rm'; required?: boolean; type?: 'table'; }\nexport interface CrSection { key: string; title: string; fields: CrField[]; }\nexport interface CrView {\n  template: { sections: CrSection[] };\n  values: Record<string, unknown>;\n  auto_values: Record<string, unknown>;\n  saved_values: Record<string, unknown>;\n  cbs_available: boolean;\n  completed: boolean;\n  updated_by?: string | null;\n  updated_at?: string | null;\n}\nexport async function getLmsCr(appId: string): Promise<{ cr: CrView }> {\n  return getJson<{ cr: CrView }>(`/lms/applications/${appId}/cr`);\n}\nexport async function saveLmsCr(appId: string, body: { values: Record<string, unknown>; completed?: boolean }): Promise<{ cr: CrView }> {\n  return postJson<{ cr: CrView }, typeof body>(lmsAction(appId, 'cr'), body);\n}\nexport interface CommitteeMember { member_id: string; name: string; role: string; is_independent: boolean; }\nexport interface CommitteeCharter {\n  committee_id: string; name: string; members: CommitteeMember[];\n  voting_rule: string; min_quorum_count: number; independent_member_min: number;\n  authority_limit_kes: number; escalation_target: string;\n}\nexport async function getCommitteeCharter(): Promise<CommitteeCharter> {\n  return getJson<CommitteeCharter>('/lms/committee/charter');\n}\nexport async function signLmsOffer(appId: string, body: SignOfferRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, SignOfferRequest>(lmsAction(appId, 'sign-offer'), body);\n}\nexport async function validateLmsOffer(appId: string, body: ValidateOfferRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, ValidateOfferRequest>(lmsAction(appId, 'validate-offer'), body);\n}\nexport async function confirmLmsToCreditAdmin(appId: string, body: ConfirmToCreditAdminRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, ConfirmToCreditAdminRequest>(lmsAction(appId, 'confirm-to-credit-admin'), body);\n}\nexport async function referLmsCommittee(appId: string, entryTier?: number): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { entry_tier?: number }>(lmsAction(appId, 'committee/refer'),\n    entryTier != null ? { entry_tier: entryTier } : {});\n}\nexport interface CommitteeTier { tier: number; key: string; name: string; authority_limit_kes: number | null; can_be_entry: boolean; }\nexport async function getCommitteeTiers(): Promise<{ tiers: CommitteeTier[] }> {\n  return getJson<{ tiers: CommitteeTier[] }>('/lms/committee/tiers');\n}\nexport async function saveCommitteeTiers(tiers: CommitteeTier[]): Promise<{ tiers: CommitteeTier[] }> {\n  return postJson<{ tiers: CommitteeTier[] }, { tiers: CommitteeTier[] }>('/lms/committee/tiers', { tiers });\n}\nexport async function submitCommitteeUpward(appId: string, note?: string): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { note?: string }>(lmsAction(appId, 'committee/submit-upward'), { note: note || '' });\n}\nexport async function voteLmsCommittee(appId: string, body: CommitteeVoteRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, CommitteeVoteRequest>(lmsAction(appId, 'committee/vote'), body);\n}\nexport async function resolveLmsCommittee(appId: string, body: ResolveCommitteeRequest): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, ResolveCommitteeRequest>(lmsAction(appId, 'committee/resolve'), body);\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Credit Admin (CALMS) fetchers\n// \u03b26 Phase 4 \u2014 consumes \u03b19 backend (utils/api_credit_admin_routes.py)\n//\n// 4 endpoints under /api/credit-admin/cases. All require Bearer JWT.\n// Cascade-scoped (rm_code-based). Audit emission per \u03b19.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  CreditAdminCasesResponse,\n  CreditAdminCaseDetailResponse,\n  CreditAdminMutationResponse,\n  FulfillConditionRequest,\n  DisburseCaseRequest,\n  RequestAuthorizationRequest,\n  AuthorizeRequest,\n} from '@/types/creditAdmin';\n\n\n/**\n * Fetch cascade-scoped list of credit-admin cases.\n *\n * Auth: REQUIRED. Server filters by caller's visible_codes against\n * case.rm_code. No analyst-override layer (per Section 19.3) \u2014 credit\n * admin officers typically have department-level role widening.\n */\nexport async function fetchCreditAdminCases(): Promise<CreditAdminCasesResponse> {\n  return getJson<CreditAdminCasesResponse>('/credit-admin/cases');\n}\n\n\n/**\n * Fetch single case detail + permissions.\n *\n * Auth: REQUIRED. 404 if not found, 403 if out-of-scope.\n */\nexport async function fetchCreditAdminCaseDetail(\n  caseId: string,\n): Promise<CreditAdminCaseDetailResponse> {\n  return getJson<CreditAdminCaseDetailResponse>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}`,\n  );\n}\n\n\n/**\n * Mark a condition fulfilled on a case. Anyone in scope, case not disbursed.\n *\n * Throws ApiValidationError (400) on:\n *   - condition_type or officer_name missing\n *   - Case is already disbursed\n *   - Condition with given type doesn't exist on the case\n * Server returns 403 if caller out-of-scope.\n */\nexport async function fulfillCreditAdminCondition(\n  caseId: string,\n  body: FulfillConditionRequest,\n): Promise<CreditAdminMutationResponse> {\n  return postJson<CreditAdminMutationResponse, FulfillConditionRequest>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/conditions/fulfill`,\n    body,\n  );\n}\n\n\n/**\n * Clear case for disbursement. Manager-tier only; requires all conditions met.\n *\n * Calls cam.clear_for_disbursement() under the hood \u2014 sets\n * ready_for_disbursement=True. The actual fund transfer (disbursed=True)\n * is OUT OF SCOPE (finance system handles it).\n *\n * Throws ApiValidationError (400) on:\n *   - Missing authority\n *   - all_conditions_met is False (returns list of unmet)\n *   - Case is already disbursed\n * Server returns 403 if caller not manager-tier.\n */\nexport async function disburseCreditAdminCase(\n  caseId: string,\n  body: DisburseCaseRequest,\n): Promise<CreditAdminMutationResponse> {\n  return postJson<CreditAdminMutationResponse, DisburseCaseRequest>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/disburse`,\n    body,\n  );\n}\n\n// \u2500\u2500 Two-layer authorization fetchers (v10.585 / B20) \u2500\u2500\nexport async function requestCreditAdminAuthorization(\n  caseId: string,\n  body: RequestAuthorizationRequest,\n): Promise<CreditAdminMutationResponse> {\n  return postJson<CreditAdminMutationResponse, RequestAuthorizationRequest>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/request-authorization`,\n    body,\n  );\n}\n\nexport async function authorizeCreditAdminCase(\n  caseId: string,\n  body: AuthorizeRequest,\n): Promise<CreditAdminMutationResponse> {\n  return postJson<CreditAdminMutationResponse, AuthorizeRequest>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/authorize`,\n    body,\n  );\n}\n\n// \u2500\u2500 P4 secured-lending fetchers \u2500\u2500\nimport type {\n  ClassifyConditionRequest, ClassifyFacilityRequest, LinkCollateralRequest,\n  LegalAssignRequest, LegalCommentRequest, LegalOutcomeRequest,\n  AddPerfectionRequest, UpdatePerfectionRequest, AddInsuranceRequest,\n  OverrideRequestBody, DisbursementGate,\n} from '@/types/creditAdmin';\n\nconst caPost = <B,>(caseId: string, path: string, body: B) =>\n  postJson<CreditAdminMutationResponse, B>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/${path}`, body);\n\nexport const classifyCondition = (id: string, b: ClassifyConditionRequest) => caPost(id, 'conditions/classify', b);\nexport const classifyFacility  = (id: string, b: ClassifyFacilityRequest)  => caPost(id, 'classify-facility', b);\nexport const linkCollateral    = (id: string, b: LinkCollateralRequest)    => caPost(id, 'collateral/link', b);\nexport const unlinkCollateral  = (id: string, collateral_id: string)       => caPost(id, 'collateral/unlink', { collateral_id });\nexport const legalAssign       = (id: string, b: LegalAssignRequest)       => caPost(id, 'legal/assign', b);\nexport const legalComment      = (id: string, b: LegalCommentRequest)      => caPost(id, 'legal/comment', b);\nexport const legalOutcome      = (id: string, b: LegalOutcomeRequest)      => caPost(id, 'legal/outcome', b);\nexport const addPerfection     = (id: string, b: AddPerfectionRequest)     => caPost(id, 'perfection', b);\nexport const updatePerfection  = (id: string, pid: string, b: UpdatePerfectionRequest) => caPost(id, `perfection/${encodeURIComponent(pid)}/update`, b);\nexport const addInsurance      = (id: string, b: AddInsuranceRequest)      => caPost(id, 'insurance', b);\nexport const updateInsurance   = (id: string, iid: string, b: Record<string, unknown>) => caPost(id, `insurance/${encodeURIComponent(iid)}/update`, b);\nexport const requestOverride   = (id: string, b: OverrideRequestBody)      => caPost(id, 'perfection-override/request', b);\nexport const approveOverride   = (id: string)                             => caPost(id, 'perfection-override/approve', {});\n\nexport async function fetchDisbursementGate(caseId: string): Promise<DisbursementGate> {\n  return getJson<DisbursementGate>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/disbursement-gate`);\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// CBS (Core Banking System) lookup fetchers\n// \u03b32 Phase 5 \u2014 consumes \u03b31 backend (utils/api_cbs_routes.py)\n//\n// 5 endpoints under /api/cbs. All require Bearer JWT. Bank-wide scope\n// (no cascade filter). Read-only.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  CbsCustomerSearchResponse,\n  CbsCustomerResponse,\n  CbsAccountsResponse,\n  CbsBranchesResponse,\n  CbsAggregatesResponse,\n  CbsAccountDetailResponse,\n  CbsAccount360Response,\n} from '@/types/cbs';\n\n\n/**\n * Search customers by name substring (min 3 chars activates server-side).\n * Empty query returns empty list (debounce safety).\n */\nexport async function searchCbsCustomers(\n  query: string,\n  limit: number = 10,\n): Promise<CbsCustomerSearchResponse> {\n  const params = new URLSearchParams();\n  params.set('q',     query);\n  params.set('limit', String(limit));\n  return getJson<CbsCustomerSearchResponse>(`/cbs/customers?${params.toString()}`);\n}\n\n\n/**\n * Exact CIF lookup. 404 if not found.\n * Server emits CBS_CUSTOMER_LOOKUP audit event.\n */\nexport async function fetchCbsCustomer(cif: string): Promise<CbsCustomerResponse> {\n  return getJson<CbsCustomerResponse>(`/cbs/customers/${encodeURIComponent(cif)}`);\n}\n\n\n/**\n * All accounts for a CIF. 404 if CIF not found. Empty array if customer\n * has zero accounts (rare but possible). Server emits CBS_ACCOUNTS_LOOKUP.\n */\nexport async function fetchCbsCustomerAccounts(cif: string): Promise<CbsAccountsResponse> {\n  return getJson<CbsAccountsResponse>(`/cbs/customers/${encodeURIComponent(cif)}/accounts`);\n}\n\n\n/** 35-branch reference. Not audited. */\nexport async function fetchCbsBranches(): Promise<CbsBranchesResponse> {\n  return getJson<CbsBranchesResponse>('/cbs/branches');\n}\n\n\n/** Bundled bank-level aggregates. Not audited. */\nexport async function fetchCbsAggregates(): Promise<CbsAggregatesResponse> {\n  return getJson<CbsAggregatesResponse>('/cbs/aggregates');\n}\n\n\n/**\n * Exact account-number lookup.\n * Live: CUSTOMERACCOUNTDETAILS via FlexCube script API.\n * Fallback: CSV when FLEXCUBE_SCRIPTS_URL is not configured on the server.\n * Audited (CBS_ACCOUNT_LOOKUP). 404 if not found.\n */\nexport async function fetchCbsAccountByNumber(\n  accountNumber: string,\n): Promise<CbsAccountDetailResponse> {\n  return getJson<CbsAccountDetailResponse>(\n    `/cbs/accounts/${encodeURIComponent(accountNumber)}`,\n  );\n}\n\n\n/**\n * Combined account + active loans payload.\n * Calls CUSTOMERACCOUNTDETAILS then CUSTOMERACTIVELOANS on the server.\n * Audited (CBS_ACCOUNT_360_LOOKUP). 404 if account not found.\n */\nexport async function fetchCbsAccount360(\n  accountNumber: string,\n): Promise<CbsAccount360Response> {\n  return getJson<CbsAccount360Response>(\n    `/cbs/accounts/${encodeURIComponent(accountNumber)}/360`,\n  );\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Target Cascade fetchers\n// \u03b33b Phase 5 \u2014 consumes \u03b33a backend (utils/api_cascade_routes.py)\n//\n// 4 endpoints under /api/cascade. Read-only. All require Bearer JWT.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  BankTargetsResponse,\n  MyAllocationsResponse,\n  GivenToMeResponse,\n  CoverageResponse,\n} from '@/types/cascade';\n\n\nexport async function fetchBankTargets(period: string = '2026'): Promise<BankTargetsResponse> {\n  return getJson<BankTargetsResponse>(`/cascade/bank-targets?period=${encodeURIComponent(period)}`);\n}\n\n\nexport async function fetchMyCascadeAllocations(period: string = '2026'): Promise<MyAllocationsResponse> {\n  return getJson<MyAllocationsResponse>(`/cascade/my-allocations?period=${encodeURIComponent(period)}`);\n}\n\n\nexport async function fetchGivenToMe(period: string = '2026'): Promise<GivenToMeResponse> {\n  return getJson<GivenToMeResponse>(`/cascade/given-to-me?period=${encodeURIComponent(period)}`);\n}\n\n\nexport async function fetchCascadeCoverage(\n  fromCode: string,\n  kpi: string,\n  period: string = '2026',\n): Promise<CoverageResponse> {\n  const params = new URLSearchParams();\n  params.set('from_code', fromCode);\n  params.set('kpi',       kpi);\n  params.set('period',    period);\n  return getJson<CoverageResponse>(`/cascade/coverage?${params.toString()}`);\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Target Cascade WRITE fetchers (\u03b35a)\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  SetBankTargetRequest,\n  SetBankTargetResponse,\n  SetAllocationRequest,\n  SetAllocationResponse,\n} from '@/types/cascade';\n\n\nexport async function setBankTarget(req: SetBankTargetRequest): Promise<SetBankTargetResponse> {\n  return postJson<SetBankTargetResponse, SetBankTargetRequest>(\n    '/cascade/bank-targets',\n    req,\n    'PUT',\n  );\n}\n\n\nexport async function setCascadeAllocations(req: SetAllocationRequest): Promise<SetAllocationResponse> {\n  return postJson<SetAllocationResponse, SetAllocationRequest>(\n    '/cascade/allocations',\n    req,\n    'PUT',\n  );\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Strategic Initiatives fetchers (\u03b34b)\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  PortfolioSummaryResponse,\n  InitiativeDetailResponse,\n} from '@/types/initiatives';\n\n\nexport async function fetchPortfolioSummary(): Promise<PortfolioSummaryResponse> {\n  return getJson<PortfolioSummaryResponse>('/initiatives/portfolio-summary');\n}\n\n\nexport async function fetchInitiativeDetail(initiativeId: string): Promise<InitiativeDetailResponse> {\n  return getJson<InitiativeDetailResponse>(`/initiatives/${encodeURIComponent(initiativeId)}`);\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// MD / CEO Dashboard fetcher (P4)\n// Consumes /api/dashboard/md (utils/api.py::md_dashboard) \u2014 the single\n// executive aggregate (bsc + pipeline + credit + aml + org). Cached\n// server-side. Any authenticated user; bank-wide (not cascade-scoped).\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type { MdDashboardResponse } from '@/types/dashboard';\n\nexport async function fetchMdDashboard(): Promise<MdDashboardResponse> {\n  return getJson<MdDashboardResponse>('/dashboard/md');\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// Credit cockpit fetcher (P5)\n// Consumes /api/cockpit/credit/open-work \u2014 bank-wide applications-by-lane +\n// IFRS9 stage distribution + NPL%. Feeds the dashboard Credit Risk panel.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type { CreditOpenWork } from '@/types/cockpit';\n\nexport async function fetchCreditOpenWork(): Promise<CreditOpenWork> {\n  return getJson<CreditOpenWork>('/cockpit/credit/open-work');\n}\n\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// FX rates (P4-1c) \u2014 operational FX rate table. List/resolve for any authed\n// user (dashboards need the LCY/FCY rate); upsert is admin-only server-side.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nimport type {\n  FxRatesResponse,\n  FxResolveResponse,\n  FxRateUpsertRequest,\n  FxRateUpsertResponse,\n} from '@/types/fx';\n\nexport async function fetchFxRates(\n  currency?: string,\n  activeOnly = false,\n): Promise<FxRatesResponse> {\n  const qs = new URLSearchParams();\n  if (currency) qs.set('currency', currency);\n  if (activeOnly) qs.set('active_only', 'true');\n  const suffix = qs.toString() ? `?${qs.toString()}` : '';\n  return getJson<FxRatesResponse>(`/fx/rates${suffix}`);\n}\n\nexport async function resolveFxRate(\n  currency: string,\n  asOf?: string,\n  rateType: 'mid' | 'buy' | 'sell' = 'mid',\n): Promise<FxResolveResponse> {\n  const qs = new URLSearchParams({ currency, rate_type: rateType });\n  if (asOf) qs.set('as_of', asOf);\n  return getJson<FxResolveResponse>(`/fx/resolve?${qs.toString()}`);\n}\n\nexport async function upsertFxRate(\n  body: FxRateUpsertRequest,\n): Promise<FxRateUpsertResponse> {\n  return postJson<FxRateUpsertResponse, FxRateUpsertRequest>('/fx/rates', body);\n}\n\n\n// \u2500\u2500 Staff administration (Postgres users table) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface StaffRow {\n  display_name?: string; analytics_name?: string; preferred_name?: string;\n  accessible_modules?: string[];\n  username: string;\n  staff_code: string | null;\n  full_name: string | null;\n  role: string | null;\n  department: string | null;\n  unit: string | null;\n  email: string;\n  active: boolean;\n  is_admin: boolean;\n  can_view_all: boolean;\n  must_change_password: boolean;\n  last_login: string | null;\n  reports_to?: string | null;\n  managed_staff_codes?: string[];\n  managed_units?: string[];\n  managed_roles?: string[];\n  region?: string | null;\n}\n\nexport interface StaffListResponse { staff: StaffRow[]; count: number; }\n\nexport interface StaffCreateInput {\n  username?: string; staff_code?: string; password: string; full_name: string;\n  email?: string; role?: string; department?: string; unit?: string;\n  band?: string; gender?: string; can_view_all?: boolean; is_admin?: boolean;\n}\n\nexport interface StaffPatchInput {\n  accessible_modules?: string[];\n  full_name?: string; preferred_name?: string; email?: string; role?: string;\n  department?: string; unit?: string; staff_code?: string; band?: string;\n  gender?: string; can_view_all?: boolean; is_admin?: boolean; active?: boolean;\n}\n\nexport async function fetchAdminStaff(): Promise<StaffListResponse> {\n  return getJson<StaffListResponse>('/admin/staff');\n}\nexport async function createAdminStaff(\n  input: StaffCreateInput,\n): Promise<{ status: string; username: string; staff_code: string }> {\n  return postJson('/admin/staff', input, 'POST');\n}\nexport async function updateAdminStaff(\n  username: string, patch: StaffPatchInput,\n): Promise<{ status: string; username: string }> {\n  return postJson(`/admin/staff/${encodeURIComponent(username)}`, patch, 'PATCH');\n}\nexport async function deactivateAdminStaff(\n  username: string,\n): Promise<{ status: string; username: string }> {\n  return postJson(`/admin/staff/${encodeURIComponent(username)}/deactivate`, {}, 'POST');\n}\nexport async function reactivateAdminStaff(\n  username: string,\n): Promise<{ status: string; username: string }> {\n  return postJson(`/admin/staff/${encodeURIComponent(username)}/reactivate`, {}, 'POST');\n}\n\n// staff module-access (module-level RBAC)\nexport interface AccessModule { key: string; label: string; min: string; }\nexport async function fetchAccessModules(): Promise<AccessModule[]> {\n  const res = await getJson<{ modules: AccessModule[] }>('/admin/modules');\n  return res.modules ?? [];\n}\n\n// staff Excel upload (preview + apply)\nexport interface StaffUploadPreview {\n  ok: boolean;\n  errors: string[];\n  summary: {\n    total: number;\n    root: { code: string; name: string; role: string } | null;\n    reporting_to_md: { code: string; name: string; role: string }[];\n    staff_per_branch: Record<string, number>;\n    roles: Record<string, number>;\n  } | null;\n}\nexport interface StaffUploadResult {\n  ok: boolean; applied: number; before: number; after: number; preserved: string[];\n}\nexport async function previewStaffUpload(contentB64: string): Promise<StaffUploadPreview> {\n  return postJson<StaffUploadPreview, { content_b64: string }>(\n    '/admin/staff/upload/preview', { content_b64: contentB64 });\n}\nexport async function applyStaffUpload(contentB64: string, keep: string[]): Promise<StaffUploadResult> {\n  return postJson<StaffUploadResult, { content_b64: string; keep: string[] }>(\n    '/admin/staff/upload/apply', { content_b64: contentB64, keep });\n}\n\n// reporting hierarchy (role -> parent roles)\nexport interface HierarchyResponse {\n  roles: string[];\n  hierarchy: Record<string, string[]>;\n  functional_hierarchy?: Record<string, string[]>;\n  top: string[];\n}\nexport async function fetchHierarchy(): Promise<HierarchyResponse> {\n  return getJson<HierarchyResponse>('/admin/hierarchy');\n}\n\nexport interface DataSourceStatus {\n  users: {\n    authoritative_source: string;\n    postgres_ready: boolean;\n    total_in_postgres: number;\n    total_in_staff_register_xlsx: number | null;\n    total_registrable_in_postgres: number;\n    in_sync: boolean | null;\n  };\n  hierarchy: {\n    role_hierarchy: {\n      source: string;\n      editable_at: string | null;\n      roles_with_parents_set: number;\n      used_by_scope_engine: boolean;\n    };\n    person_hierarchy: {\n      source: string;\n      editable_at: string | null;\n      staff_with_reports_to: number;\n      total_staff: number;\n      used_by_scope_engine: boolean;\n    };\n  };\n}\nexport async function fetchDataSourceStatus(): Promise<DataSourceStatus> {\n  return getJson<DataSourceStatus>('/admin/data-source-status');\n}\nexport async function syncDataSource(): Promise<{ status: string; staff_register_rows: number }> {\n  return postJson<{ status: string; staff_register_rows: number }, Record<string, never>>(\n    '/admin/data-source-status/sync', {});\n}\nexport async function saveHierarchy(\n  body: { action: string; role?: string; parents?: string[]; new_name?: string },\n): Promise<{ status: string; hierarchy: Record<string, string[]> }> {\n  return postJson<{ status: string; hierarchy: Record<string, string[]> }, typeof body>(\n    '/admin/hierarchy', body);\n}\n\n// document catalog (master list for per-product required documents)\nexport async function fetchDocumentCatalog(): Promise<string[]> {\n  const res = await getJson<{ documents: string[] }>('/admin/document-catalog');\n  return res.documents ?? [];\n}\n\n// admin: add a new document type to the global master catalog\nexport async function addDocumentType(name: string): Promise<string[]> {\n  const res = await postJson<{ documents: string[] }>('/admin/document-catalog', { name });\n  return res.documents ?? [];\n}\n\n// deal document upload/attach (Batch 3)\nexport interface DealDocumentMeta {\n  filename: string; path: string; sha256: string; size: number;\n  uploaded_by: string; uploaded_at: string;\n}\nexport interface DealDocumentsResponse {\n  files: Record<string, DealDocumentMeta>;\n  required: string[];\n  provided: string[];\n}\nexport async function listDealDocuments(dealId: string): Promise<DealDocumentsResponse> {\n  return getJson<DealDocumentsResponse>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/documents`);\n}\nexport async function uploadDealDocument(\n  dealId: string, docName: string, filename: string, contentB64: string,\n): Promise<{ status: string; doc_name: string; meta: DealDocumentMeta }> {\n  return postJson<{ status: string; doc_name: string; meta: DealDocumentMeta },\n    { doc_name: string; filename: string; content_b64: string }>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/documents`,\n    { doc_name: docName, filename, content_b64: contentB64 });\n}\nexport async function deleteDealDocument(dealId: string, docName: string): Promise<{ status: string }> {\n  return postJson<{ status: string }, Record<string, never>>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/documents/${encodeURIComponent(docName)}`,\n    {}, 'DELETE');\n}\nexport async function downloadDealDocument(dealId: string, docName: string): Promise<Blob> {\n  const headers: Record<string, string> = {};\n  const tok = getCurrentTokenForBlob();\n  if (tok) headers['Authorization'] = `Bearer ${tok}`;\n  const res = await fetch(\n    `/api/pipeline/deals/${encodeURIComponent(dealId)}/documents/${encodeURIComponent(docName)}`,\n    { headers });\n  if (!res.ok) throw new Error(`Download failed (${res.status})`);\n  return res.blob();\n}\n\n// LMS-side document access: the documents that TRAVELLED with the case from the\n// pipeline deal, served under LMS view permission (the credit side has no deal\n// scope). Used by the analyst / DCC / BCC / Chief Credit to read every file.\nexport interface LmsDocumentsResponse {\n  files: Record<string, DealDocumentMeta>;\n  provided: string[];\n  /** Documents an analyst has asked for on THIS case - separate from the\n   *  product's required list, which is an admin setting for every case of\n   *  its kind. */\n  requested?: { name: string; note?: string; requested_by?: string;\n                requested_role?: string; requested_at?: string }[];\n}\nexport async function listLmsDocuments(appId: string): Promise<LmsDocumentsResponse> {\n  return getJson<LmsDocumentsResponse>(\n    `/lms/applications/${encodeURIComponent(appId)}/documents`);\n}\nexport async function requestLmsDocument(\n  appId: string, docName: string, note = '',\n): Promise<{ ok: boolean; documents_requested: { name: string; note?: string }[] }> {\n  return postJson<{ ok: boolean; documents_requested: { name: string; note?: string }[] },\n                  { doc_name: string; note: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/documents/request`,\n    { doc_name: docName, note });\n}\nexport async function uploadLmsDocument(\n  appId: string, docName: string, filename: string, contentB64: string,\n): Promise<{ ok: boolean; doc_name: string; documents_provided: string[] }> {\n  return postJson<{ ok: boolean; doc_name: string; documents_provided: string[] },\n                  { doc_name: string; filename: string; content_b64: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/documents`,\n    { doc_name: docName, filename, content_b64: contentB64 });\n}\nexport async function downloadLmsDocument(appId: string, docName: string): Promise<Blob> {\n  const headers: Record<string, string> = {};\n  const tok = getCurrentTokenForBlob();\n  if (tok) headers['Authorization'] = `Bearer ${tok}`;\n  const res = await fetch(\n    `/api/lms/applications/${encodeURIComponent(appId)}/documents/${encodeURIComponent(docName)}`,\n    { headers });\n  if (!res.ok) throw new Error(`Download failed (${res.status})`);\n  return res.blob();\n}\n\n// credit committee palette (4b-1)\nexport interface CommitteeMemberDef { name: string; role: string; staff_code?: string; full_funnel?: boolean; }\nexport interface CommitteeDef {\n  code: string;\n  name: string;\n  kind?: string;\n  branch?: string;\n  chaired_by?: string;\n  recording_mode: string;\n  voting_rule: string;\n  amount_threshold_kes: number;\n  members: CommitteeMemberDef[];\n}\nexport interface CommitteePaletteResponse {\n  committees: CommitteeDef[];\n  recording_modes: string[];\n  voting_rules: string[];\n}\nexport async function fetchCommitteePalette(): Promise<CommitteePaletteResponse> {\n  return getJson<CommitteePaletteResponse>('/admin/committee-palette');\n}\nexport async function upsertCommittee(committee: CommitteeDef): Promise<{ status: string; committees: CommitteeDef[] }> {\n  return postJson<{ status: string; committees: CommitteeDef[] }, { committee: CommitteeDef }>(\n    '/admin/committee-palette', { committee });\n}\nexport async function deleteCommittee(code: string): Promise<{ status: string; committees: CommitteeDef[] }> {\n  return postJson<{ status: string; committees: CommitteeDef[] }, { delete: string }>(\n    '/admin/committee-palette', { delete: code });\n}\nexport async function seedCommitteePalette(): Promise<{ status: string; committees: CommitteeDef[] }> {\n  return postJson<{ status: string; committees: CommitteeDef[] }, Record<string, never>>(\n    '/admin/committee-palette/seed', {});\n}\n\nexport async function generateBranchCommittees(): Promise<{ status: string; created: string[]; count: number; committees: CommitteeDef[] }> {\n  return postJson<{ status: string; created: string[]; count: number; committees: CommitteeDef[] }, Record<string, never>>(\n    '/admin/committee-palette/generate-branch', {});\n}\n\n// deal-level CR (4b-3): the CR originates at the branch on the deal.\nexport async function getDealCr(dealId: string): Promise<CrView> {\n  return getJson<CrView>(`/pipeline/deals/${encodeURIComponent(dealId)}/cr`);\n}\nexport async function saveDealCr(\n  dealId: string, body: { values: Record<string, unknown>; completed?: boolean },\n): Promise<CrView> {\n  return postJson<CrView, typeof body>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/cr`, body);\n}\n\n// committee decision capture on the deal (4b-4)\nexport interface CommitteeVote { name: string; role: string; vote: string; documents_validated?: boolean; comment?: string; }\nexport interface CommitteeRecord {\n  outcome: string; mode: string; votes: CommitteeVote[];\n  note?: string; recorded_by?: string; recorded_at?: string;\n}\nexport interface CommitteeGate {\n  code: string; name: string; recording_mode: string; voting_rule: string;\n  members: { name: string; role: string }[];\n  record: CommitteeRecord | null;\n  /** Progress BEFORE a decision exists. Without these a member cannot tell\n   *  whether the committee is waiting on them or on somebody else, which is\n   *  the question they opened the case to answer. */\n  /** Whether THIS viewer may vote on this gate. canEdit means owner or\n   *  admin, which a committee member is not - they were shown a read-only\n   *  panel with nothing to vote with. The server answers from the roster. */\n  can_vote?: boolean;\n  votes_cast?: number;\n  quorum?: number;\n  awaiting?: string[];\n}\nexport interface CommitteeRecordsResponse { gates: CommitteeGate[]; cr_only: boolean; }\nexport async function getDealCommitteeRecords(dealId: string): Promise<CommitteeRecordsResponse> {\n  return getJson<CommitteeRecordsResponse>(`/pipeline/deals/${encodeURIComponent(dealId)}/committee-records`);\n}\nexport interface CommitteeVoteResult {\n  status: string; committee: string; your_vote: string;\n  votes_cast: number; quorum: number; decided: boolean; outcome: string;\n  tally: { name?: string; role?: string; vote?: string; at?: string }[];\n  awaiting: string[];\n}\n/** ONE MEMBER, ONE VOTE, from their own login. recordDealCommitteeDecision\n *  posts every member's vote at once, which is how a single member closed a\n *  case: one vote, below quorum, DEFERRED, done. */\nexport async function castCommitteeVote(\n  dealId: string, code: string,\n  body: { vote: string; documents_validated?: boolean; comment?: string; note?: string },\n): Promise<CommitteeVoteResult> {\n  return postJson<CommitteeVoteResult>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/committee/${encodeURIComponent(code)}/vote`,\n    body);\n}\n\nexport async function recordDealCommitteeDecision(\n  dealId: string,\n  body: { code: string; outcome?: string; votes?: CommitteeVote[]; note?: string },\n): Promise<{ status: string; code: string; record: CommitteeRecord }> {\n  return postJson<{ status: string; code: string; record: CommitteeRecord }, typeof body>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/committee-records`, body);\n}\n\n// reject -> owner fallback (4b-6)\nexport async function appealCommitteeDecision(\n  dealId: string, code: string, reason: string,\n): Promise<{ status: string; message: string }> {\n  return postJson<{ status: string; message: string }, { code: string; reason: string }>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/committee-appeal`, { code, reason });\n}\nexport async function closeDealAsLost(dealId: string, reason: string): Promise<{ status: string }> {\n  return postJson<{ status: string }, { reason: string }>(\n    `/pipeline/deals/${encodeURIComponent(dealId)}/close-lost`, { reason });\n}\n\n// analyst read-only view of branch committee decisions (4b-7b)\nexport interface LmsCommitteeRecordsResponse {\n  committee_records: Record<string, {\n    outcome: string; mode: string;\n    votes: { name: string; role: string; vote: string }[];\n    note?: string; recorded_by?: string; recorded_at?: string;\n  }>;\n  committee_appeals: { code: string; reason: string; outcome: string; by: string; at: string }[];\n  cr_origin: string;\n}\nexport async function getLmsCommitteeRecords(appId: string): Promise<LmsCommitteeRecordsResponse> {\n  return getJson<LmsCommitteeRecordsResponse>(`/lms/applications/${appId}/committee-records`);\n}\n\n// assignable analysts for the current manager (assign-analyst dropdown)\nexport interface AssignableAnalyst { staff_code: string; name: string; role: string; unit: string; }\nexport async function fetchMyAnalysts(): Promise<{ analysts: AssignableAnalyst[]; count: number }> {\n  return getJson<{ analysts: AssignableAnalyst[]; count: number }>('/lms/my-analysts');\n}\n\n\n// B2: assignment requests (analyst pull + manager resolve)\nexport interface AssignmentRequestCase {\n  id: string; client_name?: string; product?: string; amount?: number;\n  rm_name?: string; status?: string;\n  requests: { by_code: string; by_name: string; at: string; note?: string }[];\n}\nexport async function requestLmsAssignment(\n  appId: string, note?: string,\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { note?: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/request-assignment`, { note });\n}\nexport async function fetchAssignmentRequests(): Promise<{ cases: AssignmentRequestCase[]; count: number }> {\n  return getJson<{ cases: AssignmentRequestCase[]; count: number }>(\n    '/lms/applications/assignment-requests');\n}\n\n// C1: committee routing suggestion (Chief routes by limit)\nexport interface CommitteeRouting {\n  tiers: CommitteeTier[];\n  amount: number;\n  suggested_tier: number | null;\n  suggested_name: string | null;\n  entry_tier?: number | null;\n  entry_name?: string | null;\n  final_tier?: number | null;\n  final_name?: string | null;\n  require_mcc?: boolean;\n  must_climb?: boolean;\n  can_refer: boolean;\n  current_status: string;\n}\nexport async function fetchCommitteeRouting(appId: string): Promise<CommitteeRouting> {\n  return getJson<CommitteeRouting>(`/lms/applications/${encodeURIComponent(appId)}/committee-routing`);\n}\n\n// C1b: require-MCC-before-higher admin toggle\nexport async function setRequireMcc(enabled: boolean): Promise<{ status: string; require_mcc_before_higher: boolean }> {\n  return postJson<{ status: string; require_mcc_before_higher: boolean }, { enabled: boolean }>(\n    '/lms/committee/require-mcc', { enabled });\n}\n\n// C2: correctness-staging readiness (ready for committee / return for rework)\nexport async function setCommitteeReadiness(\n  appId: string, decision: 'ready' | 'rework', opinion?: string, reasons?: string[],\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { decision: string; opinion?: string; reasons?: string[] }>(\n    `/lms/applications/${encodeURIComponent(appId)}/committee-readiness`,\n    { decision, opinion, reasons });\n}\n\n// C2: the configured rework reason codes (lms_config -> rework_reasons)\nexport async function fetchReworkReasons(): Promise<string[]> {\n  const r = await getJson<{ rework_reasons: string[] }>('/lms/rework-reasons');\n  return r.rework_reasons ?? [];\n}\n\n// Decline appeal: file (originator) + review (manager grant/uphold)\nexport async function appealDecline(appId: string, reason: string): Promise<{ status: string }> {\n  return postJson<{ status: string }, { reason: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/appeal`, { reason });\n}\nexport async function decideAppeal(appId: string, outcome: 'grant' | 'uphold', note?: string): Promise<{ status: string; reopened: boolean }> {\n  return postJson<{ status: string; reopened: boolean }, { outcome: string; note?: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/appeal-decision`, { outcome, note });\n}\n\n// C3b: committee pre-read (member non-binding view)\nexport interface CommitteePreRead {\n  by_code: string; by_name: string; view: 'leaning_approve' | 'leaning_decline' | 'questions';\n  note?: string; at: string; tier?: number | null;\n}\nexport interface CommitteePreReadsResponse {\n  pre_reads: CommitteePreRead[]; all: CommitteePreRead[];\n  tally: Record<string, number>; current_tier: number | null;\n}\nexport async function recordCommitteePreRead(\n  appId: string, view: 'leaning_approve' | 'leaning_decline' | 'questions', note?: string,\n): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, { view: string; note?: string }>(\n    `/lms/applications/${encodeURIComponent(appId)}/committee/pre-read`, { view, note });\n}\nexport async function fetchCommitteePreReads(appId: string): Promise<CommitteePreReadsResponse> {\n  return getJson<CommitteePreReadsResponse>(\n    `/lms/applications/${encodeURIComponent(appId)}/committee/pre-reads`);\n}\n\n// C4: MD convening queue\nexport interface ConveningCase {\n  id: string; client_name?: string; product?: string; amount?: number;\n  pre_read_count: number; pre_read_tally: Record<string, number>;\n  convened: boolean; sla?: AppSla | null;\n}\nexport interface ConveningTier { tier: number | null; name: string | null; count: number; cases: ConveningCase[]; }\nexport interface ConveningQueueResponse { tiers: ConveningTier[]; total: number; awaiting: number; }\nexport async function fetchConveningQueue(): Promise<ConveningQueueResponse> {\n  return getJson<ConveningQueueResponse>('/lms/committee/convening-queue');\n}\nexport async function convokeCommittee(appId: string): Promise<LoanAppMutationResponse> {\n  return postJson<LoanAppMutationResponse, Record<string, never>>(\n    `/lms/applications/${encodeURIComponent(appId)}/committee/convene`, {});\n}\n\n// CA1: Troops disbursement queue + the 3 actions (book -> value-date -> disburse)\nexport interface TroopsQueueCase {\n  case_id: string; application_id?: string; client_name?: string; amount?: number;\n  rm_code?: string; troops_status: string; cbs_account_no?: string | null;\n  value_date?: string | null; disbursed: boolean; disbursement_date?: string | null;\n}\nexport interface TroopsQueueResponse { cases: TroopsQueueCase[]; count: number; source: string; }\nexport async function fetchTroopsQueue(): Promise<TroopsQueueResponse> {\n  return getJson<TroopsQueueResponse>('/credit-admin/troops/queue');\n}\nexport async function troopsBook(caseId: string, cbsAccountNo?: string): Promise<{ troops_status: string }> {\n  return postJson<{ troops_status: string }, { cbs_account_no?: string }>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/troops/book`, { cbs_account_no: cbsAccountNo });\n}\nexport async function troopsValueDate(caseId: string, valueDate: string): Promise<{ troops_status: string }> {\n  return postJson<{ troops_status: string }, { value_date: string }>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/troops/value-date`, { value_date: valueDate });\n}\nexport async function troopsDisburse(caseId: string, glReference?: string): Promise<{ troops_status: string }> {\n  return postJson<{ troops_status: string }, { gl_reference?: string }>(\n    `/credit-admin/cases/${encodeURIComponent(caseId)}/troops/disburse`, { gl_reference: glReference });\n}\n\n// CA2: submit-to-legal-for-charging + Legal Chief queue + officer pool\nexport const submitForCharging = (id: string, note?: string) =>\n  caPost(id, 'legal/submit-for-charging', { note: note ?? '' });\nexport interface ChargingQueueCase {\n  case_id: string; client_name?: string; amount?: number;\n  submitted_at?: string; submitted_by?: string;\n  assigned_officer_code?: string | null; assigned_officer_name?: string | null;\n}\nexport interface ChargingQueueResponse { cases: ChargingQueueCase[]; count: number; }\nexport async function fetchChargingQueue(): Promise<ChargingQueueResponse> {\n  return getJson<ChargingQueueResponse>('/credit-admin/legal/charging-queue');\n}\nexport interface LegalOfficer { staff_code: string; name: string; role: string; unit: string; }\nexport interface LegalOfficersResponse { officers: LegalOfficer[]; count: number; }\nexport async function fetchMyLegalOfficers(): Promise<LegalOfficersResponse> {\n  return getJson<LegalOfficersResponse>('/credit-admin/my-legal-officers');\n}\n\n\n// \u2500\u2500 Credit Analyst Workbench (P1/P2/P3) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface WorkbenchPull { data_source: string; recorded?: boolean; decision?: string; }\nexport interface WorkbenchSummary {\n  found: boolean; session_id?: string; state?: string;\n  customer_id?: string; loan_application_id?: string;\n  data_pulls_count?: number; sources_pulled?: string[]; sources_missing?: string[];\n  notes_count?: number; notes_by_category?: Record<string, number>;\n}\nexport interface WorkbenchConflict { decision: string; sources: string[]; pull_count: number; }\nexport interface WorkbenchConflictReport {\n  session_id: string; total_pulls: number; distinct_decisions: number;\n  conflict_count: number; conflicts: WorkbenchConflict[];\n}\nexport interface WorkbenchRoleLens {\n  cr: { completed: boolean | null };\n  credit_admin: {\n    linked: boolean; conditions_total: number | null; conditions_met: number | null;\n    all_conditions_met: boolean | null; cleared: boolean | null; disbursed: boolean | null;\n  };\n}\nexport interface WorkbenchView {\n  session_id: string; summary: WorkbenchSummary;\n  conflict_report: WorkbenchConflictReport; states: string[];\n  role_lens?: WorkbenchRoleLens;\n}\nexport async function getApplicationWorkbench(appId: string): Promise<WorkbenchView> {\n  return getJson<WorkbenchView>(`/lms/applications/${encodeURIComponent(appId)}/workbench`);\n}\nexport async function refreshWorkbench(appId: string): Promise<{ refreshed: WorkbenchPull[]; summary: WorkbenchSummary; conflict_report: WorkbenchConflictReport; }> {\n  return postJson(`/lms/applications/${encodeURIComponent(appId)}/workbench/refresh`, {});\n}\nexport async function addWorkbenchNote(appId: string, category: string, body: string): Promise<{ note_id: string; summary: WorkbenchSummary; }> {\n  return postJson(`/lms/applications/${encodeURIComponent(appId)}/workbench/note`, { category, body });\n}\nexport async function transitionWorkbench(appId: string, new_state: string, reason?: string): Promise<{ summary: WorkbenchSummary; states: string[]; }> {\n  return postJson(`/lms/applications/${encodeURIComponent(appId)}/workbench/transition`, { new_state, reason });\n}\n\n\n// \u2500\u2500 Affordability appraisal (multi-source, deterministic, no AI) \u2500\u2500\u2500\u2500\u2500\u2500\nexport interface SourceAffordability {\n  dsr_limit_pct?: number; dsr_is_override?: boolean; dsr_default_pct?: number;\n  basis?: number; months_in_basis?: number; months_window?: number | null;\n  months_excluded?: { month: string; reason: string }[];\n  anomaly_hints?: string[]; affordable_installment?: number; verdict?: string;\n}\nexport interface SourceLine {\n  label?: string; ok?: boolean; months?: number;\n  summary?: { avg_monthly_credit?: number; avg_monthly_debit?: number; avg_monthly_net?: number };\n  affordability?: SourceAffordability;\n}\nexport interface MultiSourceResult {\n  sources: SourceLine[];\n  consolidation: { method: string; total_affordable_installment: number; source_count: number; source_labels: string[] };\n}\nexport interface AmortizationResult {\n  amount: number; monthly_rate_pct: number; tenor_months: number;\n  monthly_instalment: number; total_repayable: number; total_interest: number;\n}\nexport interface MultiSourceInput {\n  label: string; cif?: string; transactions?: { txn_date: string; amount: number; dr_cr: string }[];\n  dsr_pct?: number; months_window?: number; excluded_months?: { month: string; reason: string }[];\n}\nexport async function analyzeMultiSource(sources: MultiSourceInput[], scenarioName?: string): Promise<MultiSourceResult> {\n  return postJson('/credit/analyze-multi-source', { sources, ...(scenarioName ? { scenario_name: scenarioName } : {}) });\n}\nexport async function computeAmortization(body: { amount: number; monthly_rate_pct?: number; annual_rate_pct?: number; tenor_months: number }): Promise<AmortizationResult> {\n  return postJson('/credit/amortization', body);\n}\n\n\n// \u2500\u2500 Appraisal persistence \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nexport interface SavedAppraisal {\n  sources?: unknown[]; scenarios?: unknown[]; custom_sections?: unknown[];\n  updated_by?: string; updated_at?: string;\n}\nexport async function getDealAppraisal(dealId: string): Promise<SavedAppraisal> {\n  return getJson(`/pipeline/deals/${encodeURIComponent(dealId)}/appraisal`);\n}\nexport async function saveDealAppraisal(dealId: string, body: SavedAppraisal): Promise<SavedAppraisal> {\n  return postJson(`/pipeline/deals/${encodeURIComponent(dealId)}/appraisal`, body);\n}\nexport async function getAppAppraisal(appId: string): Promise<SavedAppraisal> {\n  return getJson(`/lms/applications/${encodeURIComponent(appId)}/appraisal`);\n}\nexport async function saveAppAppraisal(appId: string, body: SavedAppraisal): Promise<SavedAppraisal> {\n  return postJson(`/lms/applications/${encodeURIComponent(appId)}/appraisal`, body);\n}\n\n\nexport interface QualifyingResult {\n  affordable_installment: number; monthly_rate_pct: number; tenor_months: number; qualifying_amount: number;\n}\nexport async function computeQualifyingAmount(body: { affordable_installment: number; monthly_rate_pct?: number; annual_rate_pct?: number; tenor_months: number }): Promise<QualifyingResult> {\n  return postJson('/credit/qualifying-amount', body);\n}\n",
 "frontend/web/src/pages/BranchLog.tsx": "import { useCallback, useEffect, useRef, useState } from 'react';\nimport { PageHeader } from '@/components/PageHeader';\nimport { CommitteeQueue } from '@/components/CommitteeQueue';\nimport { Card } from '@/components/Card';\nimport { Button } from '@/components/Button';\nimport { useToast } from '@/components/Toast';\nimport { useRole } from '@/hooks/useRole';\nimport DayPlanner from '@/components/DayPlanner';\nimport HistoryGrid from '@/components/HistoryGrid';\nimport Leaderboard from '@/components/Leaderboard';\nimport {\n  fetchBranchLogFields, fetchBranchLogAutoActivities, fetchMyBranchLogs, fetchPendingBranchLogs,\n  submitBranchLogHourly, saveBranchLogHourlyDraft, fetchBranchLogDraft, validateBranchLog, fetchBranchLogConfig, saveBranchLogConfig, fetchBranchLogRanking,\n  fetchBranchLogActivities, saveBranchLogActivities,\n  fetchDayContext, fetchBranchLogHistoryGrid,\n  type BranchLogField, type BranchLogEntry, type BranchLogActivity, type ExtraActivity,\n  type HourlyMap, type DayContext, type HistoryGrid as HistoryGridData,\n} from '@/lib/api';\nimport { displayName } from '@/lib/names';\n\ntype Tab = 'entry' | 'history' | 'review' | 'ranking' | 'setup';\n\n// Per-tab accent. `text` colours the label when the tab is active (white pill on\n// the blue ribbon); `dot` keeps the colour legible while the tab is inactive.\nconst TAB_TONE: Record<Tab, { text: string; dot: string }> = {\n  entry:   { text: 'text-[#0082BB]', dot: 'bg-[#0082BB]' },\n  history: { text: 'text-[#005B82]', dot: 'bg-[#005B82]' },\n  review:  { text: 'text-[#854F0B]', dot: 'bg-[#E0A02B]' },\n  ranking: { text: 'text-[#3B6D11]', dot: 'bg-[#BED600]' },\n  setup:   { text: 'text-[#464646]', dot: 'bg-[#979797]' },\n};\n\n// True when the planner holds anything worth persisting. Module scope on purpose:\n// the submit/draft callbacks must stay dependency-free to keep a stable identity.\nfunction hasEntryContent(h: HourlyMap, r: string): boolean {\n  if (r.trim().length > 0) return true;\n  return Object.values(h).some(\n    (b) => Object.keys(b.counts || {}).length > 0 || (b.meetings?.length ?? 0) > 0 || !!b.note,\n  );\n}\n\nexport default function BranchLog() {\n  const { toast } = useToast();\n  const { user, isAdmin } = useRole();\n  const [tab, setTab] = useState<Tab>('entry');\n  const [fields, setFields] = useState<BranchLogField[]>([]);\n  // Phase 2c: the day planner is the entry surface. `hourly` is the source of\n  // truth; day totals are derived server-side (utils/branch_log.derive_from_hourly).\n  const [hourly, setHourly] = useState<HourlyMap>({});\n  const [remarks, setRemarks] = useState('');\n  const [lastSaved, setLastSaved] = useState<Date | null>(null);\n  const [dayCtx, setDayCtx] = useState<DayContext | null>(null);\n  const [grid, setGrid] = useState<HistoryGridData | null>(null);\n  // 7 by default: the grid is now roster-complete (every scoped staff member\n  // for every working day), so 30 days is ~9,500 rows before filtering.\n  const [gridDays, setGridDays] = useState(7);\n  const [gridLoading, setGridLoading] = useState(false);\n  const [mine, setMine] = useState<BranchLogEntry[]>([]);\n  const [pending, setPending] = useState<BranchLogEntry[]>([]);\n  const [notes, setNotes] = useState<Record<string, string>>({});\n  const [busy, setBusy] = useState(false);\n  // Item 3/4: track unsaved edits so we can auto-save a draft on leave.\n  const [dirty, setDirty] = useState(false);\n  const [savingDraft, setSavingDraft] = useState(false);\n  const [autoActs, setAutoActs] = useState<BranchLogActivity[]>([]);\n  const [indexTarget, setIndexTarget] = useState(0);\n  const [weightDraft, setWeightDraft] = useState<Record<string, string>>({});\n  const [targetDraft, setTargetDraft] = useState('');\n  const [extraActs, setExtraActs] = useState<ExtraActivity[]>([]);\n  const [newAct, setNewAct] = useState<{ key: string; label: string; unit: string; weight: string; roles: string }>({ key: '', label: '', unit: '', weight: '', roles: '' });\n\n  const canReview = isAdmin || /manager|head|supervisor/i.test(String(user?.role ?? ''));\n  const metricFields = fields.filter((f) => f.type !== 'text');\n  const today = new Date().toISOString().slice(0, 10);\n\n  const loadFields = useCallback(async () => {\n    try { const r = await fetchBranchLogFields(); setFields(r.fields); } catch { /* ignore */ }\n  }, []);\n  const loadMine = useCallback(async () => {\n    try { const r = await fetchMyBranchLogs(14); setMine(r.logs); } catch { /* ignore */ }\n  }, []);\n  const loadPending = useCallback(async () => {\n    try { const r = await fetchPendingBranchLogs(); setPending(r.logs); } catch { /* ignore */ }\n  }, []);\n  const loadAuto = useCallback(async () => {\n    try { const r = await fetchBranchLogAutoActivities(); setAutoActs(r.activities); } catch { /* ignore */ }\n  }, []);\n  const loadCfg = useCallback(async () => {\n    try {\n      const r = await fetchBranchLogConfig();\n      setIndexTarget(r.daily_index_target || 0);\n      setTargetDraft(String(r.daily_index_target || 0));\n      const wd: Record<string, string> = {};\n      for (const [k, v] of Object.entries(r.activity_weights || {})) wd[k] = String(v);\n      setWeightDraft(wd);\n    } catch { /* ignore */ }\n  }, []);\n  const loadRanking = useCallback(async () => {\n    // The Leaderboard component owns the ranking now; this call survives only to\n    // pick up the daily index target, which the Day Planner header needs.\n    try { const r = await fetchBranchLogRanking(30); setIndexTarget(r.daily_index_target || 0); } catch { /* ignore */ }\n  }, []);\n  const loadActs = useCallback(async () => {\n    try { const r = await fetchBranchLogActivities(); setExtraActs(r.extra); } catch { /* ignore */ }\n  }, []);\n  // Calendar context for the header. Failure is silent: a missing work calendar\n  // must not stop anyone logging their day.\n  const loadDayCtx = useCallback(async () => {\n    try { setDayCtx(await fetchDayContext()); } catch { /* header falls back */ }\n  }, []);\n  // Phase 3: the wide history grid. Loads on demand (History tab) and on\n  // range change, not on mount - it is the heaviest call on the page.\n  const loadGrid = useCallback(async (days: number) => {\n    setGridLoading(true);\n    try { setGrid(await fetchBranchLogHistoryGrid(days)); }\n    catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not load history.' }); }\n    finally { setGridLoading(false); }\n  }, [toast]);\n\n  useEffect(() => { void loadFields(); void loadMine(); void loadAuto(); void loadCfg(); void loadDayCtx(); }, [loadFields, loadMine, loadAuto, loadCfg, loadDayCtx]);\n  useEffect(() => { if (tab === 'ranking') void loadRanking(); }, [tab, loadRanking]);\n  useEffect(() => { if (tab === 'setup') void loadActs(); }, [tab, loadActs]);\n  useEffect(() => { if (tab === 'review' && canReview) void loadPending(); }, [tab, canReview, loadPending]);\n\n  const todaysLog = mine.find((l) => l.log_date === today);\n\n  // Phase 2c: submit/draft read the entry from a ref so the callbacks keep a\n  // stable identity. The 30s timer and the unmount handler must not be re-armed\n  // on every keystroke (that previously fired a draft POST per edit).\n  const entryRef = useRef<{ hourly: HourlyMap; remarks: string }>({ hourly: {}, remarks: '' });\n  useEffect(() => { entryRef.current = { hourly, remarks }; }, [hourly, remarks]);\n\n  const submit = async () => {\n    const { hourly: h, remarks: r } = entryRef.current;\n    // Guard: an empty planner would derive all-zero day totals and wipe a\n    // pre-existing entry for today. Make the user log something first.\n    if (!hasEntryContent(h, r)) {\n      toast({ tone: 'danger', message: 'Log at least one activity or a remark before submitting.' });\n      return;\n    }\n    setBusy(true);\n    try {\n      await submitBranchLogHourly(h, r);\n      toast({ tone: 'success', message: 'Daily log submitted for validation.' });\n      setDirty(false); setLastSaved(new Date()); void loadMine();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Submit failed.' });\n    } finally { setBusy(false); }\n  };\n\n  // Item 3 (Phase 2c): save the planner as a private draft (not submitted).\n  const saveDraft = useCallback(async (silent = false) => {\n    const { hourly: h, remarks: r } = entryRef.current;\n    if (!hasEntryContent(h, r)) return;\n    setSavingDraft(true);\n    try {\n      await saveBranchLogHourlyDraft(h, r);\n      setDirty(false);\n      setLastSaved(new Date());\n      if (!silent) toast({ tone: 'success', message: 'Draft saved. You can submit later today.' });\n    } catch (e) {\n      if (!silent) toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Could not save draft.' });\n    } finally { setSavingDraft(false); }\n  }, [toast]);\n\n  // Item 3 (Phase 2c): re-hydrate today's hourly map (draft or submitted) on load.\n  // Legacy flat entries carry no `hourly` \u2014 those open as an empty planner.\n  const loadDraft = useCallback(async () => {\n    try {\n      const r = await fetchBranchLogDraft();\n      const log = r.log;\n      if (!log) return;\n      const raw = (log as { hourly?: unknown }).hourly;\n      if (raw && typeof raw === 'object' && Object.keys(raw as object).length > 0) {\n        setHourly((prev) => (Object.keys(prev).length ? prev : (raw as HourlyMap)));\n      }\n      if (typeof log.remarks === 'string' && log.remarks) {\n        setRemarks((prev) => (prev ? prev : (log.remarks as string)));\n      }\n    } catch { /* no entry today \u2014 start blank */ }\n  }, []);\n\n  // Item 3: load today's saved entry once, on mount (after loadDraft exists).\n  useEffect(() => { void loadDraft(); }, [loadDraft]);\n  useEffect(() => { if (tab === 'history') void loadGrid(gridDays); }, [tab, gridDays, loadGrid]);\n\n  // Item 4: auto-save a draft when leaving with unsaved edits. The unmount\n  // handler runs on logout and in-app navigation (React unmounts the page) and\n  // uses the normal authenticated saveDraft. A beforeunload warning covers the\n  // browser-close/refresh case (sendBeacon can't carry the JWT, so we warn).\n  const dirtyRef = useRef(false); useEffect(() => { dirtyRef.current = dirty; }, [dirty]);\n  useEffect(() => {\n    const warn = (e: BeforeUnloadEvent) => {\n      if (dirtyRef.current) { e.preventDefault(); e.returnValue = ''; }\n    };\n    window.addEventListener('beforeunload', warn);\n    return () => {\n      window.removeEventListener('beforeunload', warn);\n      if (dirtyRef.current) void saveDraft(true);\n    };\n  }, [saveDraft]);\n\n  // Phase 2c: autosave the planner every 30 seconds while edits are pending.\n  // saveDraft is ref-backed and stable, so the timer is armed once per mount.\n  useEffect(() => {\n    const id = window.setInterval(() => {\n      if (dirtyRef.current) void saveDraft(true);\n    }, 30_000);\n    return () => window.clearInterval(id);\n  }, [saveDraft]);\n\n  const review = async (id: string, approved: boolean) => {\n    setBusy(true);\n    try {\n      await validateBranchLog(id, approved, (notes[id] ?? '').trim());\n      toast({ tone: 'success', message: approved ? 'Log validated.' : 'Log returned.' });\n      void loadPending();\n    } catch (e) {\n      toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Action failed.' });\n    } finally { setBusy(false); }\n  };\n\n  const fmt = (v: unknown) => (typeof v === 'number' ? v.toLocaleString() : String(v ?? ''));\n  const metricSummary = (l: BranchLogEntry) =>\n    metricFields.filter((f) => Number(l[f.key]) > 0).map((f) => (\n      <span key={f.key}>{f.label}: <b>{fmt(l[f.key])}</b></span>\n    ));\n\n  const tabs: [Tab, string][] = [\n    ['entry', 'Daily Log Entry'],\n    ['history', 'Log History'],\n    ...(canReview ? ([['review', 'Supervisor Review']] as [Tab, string][]) : []),\n    ['ranking', 'Ranking'],\n    ...(isAdmin ? ([['setup', 'Index Setup']] as [Tab, string][]) : []),\n  ];\n  // DayPlanner renders the live day index itself (sum of count x weight over hours).\n  const dateLabel = new Date().toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long' });\n  // Greeting name: prefer the server-resolved staff name, fall back to the JWT\n  // identity, and render an impersonal greeting rather than \"Dear ,\" if neither.\n  const firstName = displayName(dayCtx?.staff_name || user?.full_name || '');\n\n  return (\n    <div>\n      <PageHeader\n        ribbon\n        sticky\n        title=\"Daily Log\"\n        subtitle={dateLabel}\n        actions={\n          <div className=\"flex flex-wrap items-center justify-end gap-1.5\">\n            {tabs.map(([id, lbl]) => (\n              <button key={id} onClick={() => setTab(id)}\n                className={'flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors '\n                  + (tab === id ? `bg-white shadow-sm ${TAB_TONE[id].text}` : 'text-white/80 hover:bg-white/15')}>\n                <span className={'h-1.5 w-1.5 rounded-full ' + (tab === id ? TAB_TONE[id].dot : 'bg-white/50')} />\n                {lbl}{id === 'review' && pending.length ? ` (${pending.length})` : ''}\n              </button>\n            ))}\n          </div>\n        }\n      />\n\n      <div className=\"mx-auto max-w-7xl px-4 py-6 2xl:max-w-[1680px]\">\n\n      {tab === 'entry' && (\n        <Card>\n          <Card.Header>\n            <div className=\"flex flex-wrap items-center justify-between gap-3\">\n              <div className=\"min-w-0\">\n                <h2 className=\"text-base font-semibold text-gray-900\">\n                  {firstName ? `Dear ${firstName}, the day is all yours \u2014 make every activity count.`\n                             : 'The day is all yours \u2014 make every activity count.'}\n                </h2>\n                <p className=\"mt-0.5 text-xs text-gray-500\">\n                  {dayCtx\n                    ? `${dayCtx.weekday} \u00b7 day ${dayCtx.day_of_year} of ${dayCtx.days_in_year}`\n                    : 'Today\\u2019s activity'}\n                </p>\n              </div>\n              {dayCtx && (\n                <div className=\"flex flex-wrap items-center gap-1.5 text-[11px]\">\n                  {dayCtx.holiday && (\n                    <span className=\"rounded-full bg-[#FAEEDA] px-2.5 py-1 font-medium text-[#854F0B]\">\n                      {dayCtx.holiday_label || 'Public holiday'}\n                    </span>\n                  )}\n                  {!dayCtx.holiday && dayCtx.half_day && (\n                    <span className=\"rounded-full bg-[#EAF3DE] px-2.5 py-1 font-medium text-[#3B6D11]\">\n                      Half day \u00b7 {dayCtx.hours_today}h\n                    </span>\n                  )}\n                  {!dayCtx.working && !dayCtx.holiday && (\n                    <span className=\"rounded-full bg-gray-100 px-2.5 py-1 font-medium text-gray-500\">\n                      Rest day\n                    </span>\n                  )}\n                  <span className=\"rounded-full bg-[#E6F1FB] px-2.5 py-1 text-[#0C447C]\">\n                    {dayCtx.days_remaining.toLocaleString()} days left in {dayCtx.date.slice(0, 4)}\n                  </span>\n                  <span className=\"rounded-full bg-[#E6F1FB] px-2.5 py-1 text-[#0C447C]\">\n                    {dayCtx.working_days_remaining.toLocaleString()} working days\n                  </span>\n                  <span className=\"rounded-full bg-[#E6F1FB] px-2.5 py-1 text-[#0C447C]\">\n                    {dayCtx.working_hours_remaining.toLocaleString()} working hours\n                  </span>\n                </div>\n              )}\n            </div>\n          </Card.Header>\n          <Card.Body>\n            {todaysLog && (\n              <div className=\"mb-3 rounded border border-blue-100 bg-blue-50 p-2 text-sm text-blue-800\">\n                You already submitted today\n                {todaysLog.validated ? ' (validated)' : todaysLog.rejected ? ' (returned \u2014 please correct)' : ' (awaiting validation)'}.\n                {' '}Re-submitting updates it.\n              </div>\n            )}\n            <div className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1fr)_20rem]\">\n              <DayPlanner\n                fields={metricFields}\n                hourly={hourly}\n                onChange={(next) => { setDirty(true); setHourly(next); }}\n                target={indexTarget}\n              />\n\n              {/* Context in, actions out. Keeps Save/Submit beside the timeline\n                  rather than below it, so they stay above the fold. */}\n              <aside className=\"flex flex-col gap-4\">\n                {autoActs.length > 0 && (\n                  <div className=\"rounded-md border border-gray-200 bg-gray-50 p-3\">\n                    <div className=\"text-sm font-semibold text-gray-800\">Tracked automatically today</div>\n                    <p className=\"mb-2 text-xs text-gray-400\">Pulled from your pipeline actions \u2014 no need to key these.</p>\n                    <ol className=\"max-h-40 space-y-1 overflow-y-auto\">\n                      {autoActs.map((a, i) => (\n                        <li key={i} className=\"flex items-start gap-2 text-sm\">\n                          <span className=\"tabular-nums text-gray-400\">{a.time}</span>\n                          <span className=\"rounded border border-gray-200 bg-white px-1.5 py-0.5 text-xs text-gray-600\">{a.kind}</span>\n                          <span className=\"text-gray-700\">{a.detail}</span>\n                        </li>\n                      ))}\n                    </ol>\n                  </div>\n                )}\n\n                <label className=\"block text-sm\">\n                  <span className=\"mb-1 block text-gray-700\">Remarks / challenges</span>\n                  <textarea rows={4} className=\"w-full rounded border px-2 py-1.5 text-sm\"\n                    placeholder=\"Blockers, escalations, anything the hours don't say.\"\n                    value={remarks} onChange={(e) => { setDirty(true); setRemarks(e.target.value); }} />\n                </label>\n\n                <div className=\"mt-auto border-t border-gray-100 pt-3\">\n                  <div className=\"mb-2 text-xs text-gray-400\">\n                    {savingDraft\n                      ? 'Saving\u2026'\n                      : dirty\n                        ? 'Unsaved changes \u2014 autosaves every 30 seconds.'\n                        : lastSaved\n                          ? `All changes saved ${lastSaved.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`\n                          : 'Autosaves every 30 seconds.'}\n                  </div>\n                  <div className=\"flex flex-col gap-2\">\n                    <Button fullWidth onClick={() => void submit()} disabled={busy}>Submit daily log</Button>\n                    <Button fullWidth variant=\"ghost\" onClick={() => void saveDraft()} disabled={busy || savingDraft}>\n                      {savingDraft ? 'Saving\u2026' : 'Save draft'}\n                    </Button>\n                  </div>\n                </div>\n              </aside>\n            </div>\n          </Card.Body>\n        </Card>\n      )}\n\n      {tab === 'ranking' && <Leaderboard />}\n\n      {tab === 'setup' && isAdmin && (\n        <Card>\n          <Card.Header><h2 className=\"text-base font-semibold text-gray-900\">Activity weights &amp; daily index target</h2></Card.Header>\n          <Card.Body>\n            <label className=\"mb-4 block text-sm\">\n              <span className=\"mb-1 block text-gray-700\">Daily index target</span>\n              <input type=\"number\" min={0} className=\"w-40 rounded border px-2 py-1.5 text-sm\"\n                value={targetDraft} onChange={(e) => setTargetDraft(e.target.value)} />\n            </label>\n            <p className=\"mb-2 text-sm font-medium text-gray-700\">Points per activity</p>\n            <div className=\"grid grid-cols-1 gap-3 sm:grid-cols-2\">\n              {metricFields.map((f) => (\n                <label key={f.key} className=\"flex items-center justify-between gap-2 text-sm\">\n                  <span className=\"text-gray-700\">{f.label}</span>\n                  <input type=\"number\" step=\"any\" className=\"w-24 rounded border px-2 py-1 text-sm\"\n                    value={weightDraft[f.key] ?? ''} onChange={(e) => setWeightDraft((p) => ({ ...p, [f.key]: e.target.value }))} />\n                </label>\n              ))}\n            </div>\n            <div className=\"mt-4 flex justify-end\">\n              <Button disabled={busy} onClick={async () => {\n                setBusy(true);\n                try {\n                  const w: Record<string, number> = {};\n                  for (const [k, v] of Object.entries(weightDraft)) w[k] = Number(v) || 0;\n                  await saveBranchLogConfig(w, Number(targetDraft) || 0);\n                  toast({ tone: 'success', message: 'Weights & target saved.' });\n                  await loadFields(); await loadCfg();\n                } catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Save failed' }); }\n                finally { setBusy(false); }\n              }}>Save weights &amp; target</Button>\n            </div>\n\n            <div className=\"mt-6 border-t border-gray-100 pt-4\">\n              <h3 className=\"mb-1 text-sm font-semibold text-gray-800\">Extra activities (head office / role-specific)</h3>\n              <p className=\"mb-3 text-xs text-gray-400\">These appear only for the roles you list (comma-separated). Leave roles blank to show for everyone.</p>\n              {extraActs.length > 0 && (\n                <div className=\"mb-3 space-y-1\">\n                  {extraActs.map((a, i) => (\n                    <div key={a.key} className=\"flex items-center justify-between rounded border border-gray-200 bg-gray-50 px-2 py-1 text-sm\">\n                      <div>\n                        <span className=\"font-medium text-gray-800\">{a.label}</span>\n                        <span className=\"ml-2 text-xs text-gray-500\">{a.unit || 'count'} \u00b7 wt {a.weight}{a.roles.length ? ` \u00b7 ${a.roles.join(', ')}` : ' \u00b7 all roles'}</span>\n                      </div>\n                      <button className=\"text-xs text-gray-400 hover:text-red-600\"\n                        onClick={() => setExtraActs((p) => p.filter((_, j) => j !== i))}>Remove</button>\n                    </div>\n                  ))}\n                </div>\n              )}\n              <div className=\"grid grid-cols-1 gap-2 sm:grid-cols-5\">\n                <input className={'rounded border px-2 py-1 text-sm'} placeholder=\"key (e.g. credit_apps)\" value={newAct.key} onChange={(e) => setNewAct((p) => ({ ...p, key: e.target.value }))} />\n                <input className={'rounded border px-2 py-1 text-sm'} placeholder=\"Label\" value={newAct.label} onChange={(e) => setNewAct((p) => ({ ...p, label: e.target.value }))} />\n                <input className={'rounded border px-2 py-1 text-sm'} placeholder=\"unit\" value={newAct.unit} onChange={(e) => setNewAct((p) => ({ ...p, unit: e.target.value }))} />\n                <input className={'rounded border px-2 py-1 text-sm'} type=\"number\" step=\"any\" placeholder=\"weight\" value={newAct.weight} onChange={(e) => setNewAct((p) => ({ ...p, weight: e.target.value }))} />\n                <input className={'rounded border px-2 py-1 text-sm'} placeholder=\"roles (comma-sep)\" value={newAct.roles} onChange={(e) => setNewAct((p) => ({ ...p, roles: e.target.value }))} />\n              </div>\n              <div className=\"mt-2 flex gap-2\">\n                <Button variant=\"ghost\" onClick={() => {\n                  const k = newAct.key.trim(); if (!k || !newAct.label.trim()) { toast({ tone: 'danger', message: 'Key and label required.' }); return; }\n                  setExtraActs((p) => [...p.filter((x) => x.key !== k), { key: k, label: newAct.label.trim(), type: 'int', unit: newAct.unit.trim(), weight: Number(newAct.weight) || 0, roles: newAct.roles.split(',').map((s) => s.trim()).filter(Boolean) }]);\n                  setNewAct({ key: '', label: '', unit: '', weight: '', roles: '' });\n                }}>Add activity</Button>\n                <Button disabled={busy} onClick={async () => {\n                  setBusy(true);\n                  try { await saveBranchLogActivities(extraActs); toast({ tone: 'success', message: 'Activities saved.' }); await loadFields(); await loadActs(); }\n                  catch (e) { toast({ tone: 'danger', message: e instanceof Error ? e.message : 'Save failed' }); }\n                  finally { setBusy(false); }\n                }}>Save activities</Button>\n              </div>\n            </div>\n          </Card.Body>\n        </Card>\n      )}\n\n      {/* A committee member who is not a manager never opens Manager\n\n          Queues, so the same list appears here. It renders nothing at\n\n          all for somebody on no committee. */}\n\n      <CommitteeQueue compact />\n\n\n      {tab === 'history' && (\n        <Card>\n          <Card.Header>\n            <div className=\"flex flex-wrap items-center justify-between gap-2\">\n              <h2 className=\"text-base font-semibold text-gray-900\">Log history</h2>\n              <span className=\"text-xs text-gray-400\">\n                Index vs target per day, with the running carried-forward balance.\n              </span>\n            </div>\n          </Card.Header>\n          <Card.Body>\n            <HistoryGrid grid={grid} loading={gridLoading} days={gridDays} onDaysChange={setGridDays} />\n          </Card.Body>\n        </Card>\n      )}\n\n      {tab === 'review' && canReview && (\n        <Card>\n          <Card.Header><h2 className=\"text-base font-semibold text-gray-900\">Awaiting validation</h2></Card.Header>\n          <Card.Body>\n            {pending.length === 0 ? <p className=\"text-sm text-gray-400\">Nothing pending in your unit.</p> : (\n              <div className=\"space-y-3\">\n                {pending.map((l) => (\n                  <div key={l.id} className=\"rounded border border-amber-200 bg-amber-50 p-3\">\n                    <div className=\"flex items-center justify-between\">\n                      <span className=\"font-medium text-gray-900\">{l.staff_name} <span className=\"text-gray-400\">({l.role}, {l.unit})</span></span>\n                      <span className=\"text-xs text-gray-500\">{l.log_date}</span>\n                    </div>\n                    <div className=\"mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-600\">{metricSummary(l)}</div>\n                    {l.remarks ? <p className=\"mt-1 text-xs text-gray-500\">{l.remarks}</p> : null}\n                    <input className=\"mt-2 w-full rounded border px-2 py-1 text-xs\" placeholder=\"Note (optional)\"\n                      value={notes[l.id] ?? ''} onChange={(e) => setNotes((p) => ({ ...p, [l.id]: e.target.value }))} />\n                    <div className=\"mt-2 flex gap-2\">\n                      <Button size=\"sm\" onClick={() => void review(l.id, true)} disabled={busy}>Validate</Button>\n                      <Button size=\"sm\" variant=\"ghost\" onClick={() => void review(l.id, false)} disabled={busy}>Return</Button>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            )}\n          </Card.Body>\n        </Card>\n      )}\n      </div>\n    </div>\n  );\n}\n"
}''')



# What must survive in each file. A whole-file patch has to prove it takes
# nothing away, because one of these once carried a menu entry to the pilot
# that was not meant to travel.
KEEP = {
    "frontend/web/src/pages/LmsApplicationDetail.tsx":
        ["CorrectnessPanel", "DccVotePanel", "SubmitToDccPanel",
         "LmsTravelledDocuments", "CommitteePreReadPanel"],
    "frontend/web/src/pages/Lms.tsx": ["My cases", "Pool", "applications"],
    "frontend/web/src/pages/PipelineDealDetail.tsx":
        ["CreditSubmissionPanel", "CaseJourneyTab", "castCommitteeVote"],
    "frontend/web/src/pages/PipelineManagerQueues.tsx":
        ["CommitteeQueue", "Pipeline validation"],
    "frontend/web/src/pages/Pipeline.tsx": ["DefinedFunnel", "segmentGroups"],
    "frontend/web/src/components/Sidebar.tsx":
        ["Credit Analysis", "Manager Queues", "Daily Log", "Portfolio"],
    "frontend/web/src/lib/api.ts":
        ["castCommitteeVote", "fetchCommitteeQueue",
         "fetchPipelineAnalytics", "fetchPipelineDefinedFunnel"],
}

# Markers that prove the work is present after applying.
EXPECT = {
    "frontend/web/src/pages/LmsApplicationDetail.tsx":
        ["label: 'Department Review'", "label: 'Department Credit Committee'",
         "Recommend to committee", "still to be attached",
         "Rework done \u2014 send it back"],
    "frontend/web/src/pages/Lms.tsx": ["Reviewed \u00b7 recommended", "doPick"],
    "frontend/web/src/components/CommitteeQueue.tsx": ["you_voted"],
    "frontend/web/src/components/Sidebar.tsx": ["label: 'Department Review'"],
    # THE REWORK LOOP NOW CLOSES. RB1 sends a case back to the branch with what
    # needs fixing; "Rework done - send it back" sends it on again, to the
    # analyst who returned it. It shows to WHOEVER opens a returned case -
    # owner or analyst - because a case waiting on "who is allowed to press
    # this" is a case not moving.
    "frontend/web/src/lib/api.ts":
        ["can_vote?", "castCommitteeVote", "resubmitAfterRework"],
}


def main():
    apply = "--apply" in sys.argv

    missing = [f for f in FILES if not os.path.isfile(_p(f))]
    if missing:
        print("ABORT: not found: %s" % ", ".join(missing[:3]))
        return 1

    # EVERY file must already carry it, not just one. These files overlap -
    # an earlier patch in the chain can leave one of them looking finished
    # while the rest are untouched - and stopping on the first match is how a
    # patch reports "already applied" over work that is mostly missing.
    already = [f for f in EXPECT
               if all(m in open(_p(f), encoding="utf-8").read() for m in EXPECT[f])]
    if len(already) == len(EXPECT):
        print("ABORT: UI1 looks applied - every file already carries it.")
        return 1
    if already:
        print("  note: %d of %d file(s) already carry part of this; the rest"
              % (len(already), len(EXPECT)))
        print("        will be brought up to the same state.")

    for f, new in FILES.items():
        cur = open(_p(f), encoding="utf-8").read()
        for m in KEEP.get(f, []):
            if cur.count(m) and not new.count(m):
                print("ABORT: %r is in %s and NOT in this patch." % (m, os.path.basename(f)))
                return 1
    print("  ok  nothing present in any file would be removed")

    bar = "frontend/web/src/components/Sidebar.tsx"
    cur_bar = open(_p(bar), encoding="utf-8").read()
    if FILES[bar].count("Deals Warehouse") > cur_bar.count("Deals Warehouse"):
        print("ABORT: this would add a Deals Warehouse menu entry to the pilot.")
        print("       That happened once before and must not again.")
        return 1
    print("  ok  no menu entry travels that should not")

    for f, marks in EXPECT.items():
        for m in marks:
            if m not in FILES[f]:
                print("ABORT: %r is missing from %s - the patch is incomplete."
                      % (m, os.path.basename(f)))
                return 1
    for f, new in FILES.items():
        for op, cl in (("{", "}"), ("(", ")")):
            if new.count(op) != new.count(cl):
                print("ABORT: %s unbalanced %s%s." % (os.path.basename(f), op, cl))
                return 1
    print("  ok  post-checks: %d file(s), all markers present, brackets balanced"
          % len(FILES))

    if not apply:
        print("\nDRY RUN - nothing written. Re-run with --apply.")
        return 0

    for f, new in FILES.items():
        shutil.copy2(_p(f), _p(f) + BACKUP_SUFFIX)
        open(_p(f), "w", encoding="utf-8", newline="").write(new)
        print("APPLIED %s" % f)
    print("\nNext: pushd frontend\\web && pnpm install && pnpm tsc --noEmit && pnpm build && popd")
    return 0


if __name__ == "__main__":
    sys.exit(main())
